-- Lock A: strip English from banda 2–3 copy (titlu / materiale / pasi / gata_cand / tema).
-- Live ids are sN-b23-… ; seed ids sN-2-3-… remap via docs/IMPORT-BANDA-2-3-ID-MAP.md.
-- ONLY banda='2-3'. Does not touch banda 1–2 or ids without b23.
-- Do not apply to Familie/production from this PR; Cristina QA pe preview.
update public.activities as a
set
  titlu = v.titlu,
  materiale = v.materiale,
  pasi = v.pasi,
  gata_cand = v.gata_cand,
  tema_saptamana = v.tema_saptamana
from (values
  ('s1-b23-z1-mental', 'Trei locuri din casă', ARRAY['ușă', 'fereastră', 'scaun (sau 3 locuri vizibile)']::text[], ARRAY['Arătați trei locuri: „Ușă. Fereastră. Scaun.”', 'Întrebați blând: „Unde e ușa?” și așteptați arătarea.', 'Dacă vrea: spuneți o dată: „Casă.” și arătați camera.']::text[], 'A auzit și a privit cele trei locuri.', 'Casa și curtea'),
  ('s1-b23-z1-social', 'Salut spațiului: bună, casă', '{}'::text[], ARRAY['La intrare, bateți ușor în ușă și spuneți: „Bună, casă!”', 'Zâmbiți și așteptați dacă vrea să imite gestul.', 'Dacă vrea: adăugați: „Ușă.” când atingeți clanța.']::text[], 'A participat la salutul spațiului (privire, gest sau cuvânt).', 'Casa și curtea'),
  ('s1-b23-z2-mental', 'Unde e curtea?', ARRAY['fereastră sau ușă cu vedere']::text[], ARRAY['Stați la fereastră/ușă: „Unde e curtea?”', 'Arătați și spuneți: „Curte.”', 'Dacă vrea: comparați: „În casă e cald. Afară e curtea.”']::text[], 'A privit spre curte când ați arătat.', 'Casa și curtea'),
  ('s1-b23-z5-mental', 'Hartă scurtă: trei cuvinte', '{}'::text[], ARRAY['Spuneți: „Casă. Ușă. Curte.” arătând fiecare.', 'Cereți: „Arată casa” — așteptați gestul.', 'Dacă vrea: includeți: „Casă.” lângă camera principală.']::text[], 'A asociat cel puțin un loc cu gestul.', 'Casa și curtea'),
  ('s1-b23-z7-social', 'Ritual: bună seara, casă', ARRAY['lumină mică opțională']::text[], ARRAY['Șoptiți: „Bună seara, casă.”', 'Îmbrățișați-vă doar dacă vrea; fără forțare.', 'Dacă vrea: adăugați: „Curte — la revedere până mâine.”']::text[], 'Ați închis ziua cu ritualul blând.', 'Casa și curtea'),
  ('s2-b23-z1-mental', 'Apa curge — etichete bogate', ARRAY['robinet', 'vas']::text[], ARRAY['Deschideți un fir subțire: „Apă. Curge. Rece.”', 'Spuneți: „Apă.” și arătați firul.', 'Dacă vrea: întrebați: „Unde se duce apa?” și arătați scurgerea.']::text[], 'A observat apa curgând și a auzit etichetele.', 'Apa în casă și afară'),
  ('s2-b23-z3-mental', 'Ud sau uscat?', ARRAY['cârpă udă', 'cârpă uscată']::text[], ARRAY['Atingeți ambele: „Ud. Uscat.”', 'Spuneți: „Ud.” pe cârpa udă.', 'Dacă vrea: ascundeți una și întrebați: „Unde e cea udă?”']::text[], 'A comparat ud și uscat.', 'Apa în casă și afară'),
  ('s2-b23-z7-mental', 'Carte sau imagine cu apă', ARRAY['carte cu apă / baie / ploaie, sau orice carte']::text[], ARRAY['Răsfoiți împreună; el întoarce pagina dacă vrea.', 'Când vedeți apă: „Apă.”', 'Dacă vrea: spuneți: „Apă.” pe pagina aleasă.']::text[], 'Ați răsfoit scurt și ați denumit apa dacă a apărut.', 'Apa în casă și afară'),
  ('s3-b23-z1-mental', 'Aproape și departe', ARRAY['jucărie care face sunet sau bătăi din palme']::text[], ARRAY['Faceți un sunet aproape: „Aproape.”', 'Un sunet mai departe: „Departe.”', 'Dacă vrea: spuneți: „Ascultăm. Ascultă.” înainte de al doilea sunet.']::text[], 'A auzit diferența aproape / departe.', 'Sunete și liniște'),
  ('s3-b23-z2-mental', 'Numește două sunete', '{}'::text[], ARRAY['Ascultați în casă: numiți două sunete (voce, apă, ușă).', 'Arătați sursa fiecăruia.', 'Dacă vrea: adăugați: „Tare.” pe sunetul mai puternic.']::text[], 'Ați denumit două sunete.', 'Sunete și liniște'),
  ('s3-b23-z3-mental', 'Voce tare, voce încet', '{}'::text[], ARRAY['Spuneți același cuvânt tare, apoi încet: „Tare. Încet.”', 'Spuneți: „Liniște.” pe varianta încet.', 'Dacă vrea: el alege: „Spunem tare sau încet?”']::text[], 'A auzit tare și încet.', 'Sunete și liniște'),
  ('s4-b23-z1-mental', 'Numește degete și acțiuni', '{}'::text[], ARRAY['Arătați: „Mână. Deget.” Atingeți-i palma blând.', 'Spuneți: „Mână.” pe palma voastră.', 'Dacă vrea: numiți un deget: „Acesta e degetul mare.”']::text[], 'A auzit etichetele mână / deget.', 'Mâini și degete'),
  ('s4-b23-z2-mental', 'Ce face mâna? Apasă, trage', ARRAY['sertar sau ușă ușoară']::text[], ARRAY['Arătați: „Apăs.” pe un buton sau întrerupător cu adult.', '„Trag.” pe un sertar ușor.', 'Dacă vrea: spuneți: „Deschis.” când deschideți sertarul.']::text[], 'A văzut două acțiuni ale mâinii.', 'Mâini și degete'),
  ('s4-b23-z3-mental', 'Degetul mare și celelalte', '{}'::text[], ARRAY['Arătați degetul mare: „Deget mare.”', 'Arătați celelalte: „Degete.”', 'Dacă vrea: spuneți: „Deget.” pe un deget arătat.']::text[], 'A diferențiat degetul mare de celelalte.', 'Mâini și degete'),
  ('s4-b23-z5-mental', 'Mâna stângă, mâna dreaptă', '{}'::text[], ARRAY['Arătați: „Mâna asta. Mâna cealaltă.” (fără a forța etichete stânga/dreapta).', 'Puneți un obiect pe o mână: „Pe mâna aceasta.”', 'Dacă vrea: spuneți: „Mână.” pe ambele pe rând.']::text[], 'A diferențiat cele două mâini pe scurt.', 'Mâini și degete'),
  ('s4-b23-z7-fizic', 'Joaca favorită cu mâinile', ARRAY['materialul sau unealta preferată din săptămână']::text[], ARRAY['Reluați pe scurt jocul cu mâinile care i-a plăcut.', 'El dictează ritmul; voi urmăriți.', 'Dacă vrea: alegeți între două favorita ale săptămânii.']::text[], 'Ați reluat jocul favorit cu mâinile.', 'Mâini și degete'),
  ('s4-b23-z7-social', 'Ritual: mână pe mână, noapte bună', '{}'::text[], ARRAY['Atingeți palmele scurt dacă vrea: „Mână pe mână.”', '„Noapte bună.” Calm.', 'Dacă vrea: spuneți: „Deschis” pe palmă, apoi odihnă.']::text[], 'Ați închis săptămâna cu ritualul blând.', 'Mâini și degete'),
  ('s5-b23-z1-mental', 'Aceeași culoare de două ori', ARRAY['2 obiecte de aceeași culoare', '1 obiect de altă culoare']::text[], ARRAY['Arătați două obiecte: „La fel. Aceeași culoare.”', 'Arătați al treilea: „Altă culoare.” Întrebați: „Care sunt la fel?”', 'Dacă vrea: spuneți o dată: „Roșu.” sau „Albastru.” pe obiectul potrivit.']::text[], 'A privit perechea de aceeași culoare.', 'Culori pe care le vedem'),
  ('s5-b23-z1-social', 'Arătăm culoarea favorită', ARRAY['1–2 obiecte colorate']::text[], ARRAY['Invitați-l să arate cu degetul culoarea care îi place.', 'Spuneți: „Uite ce arată el!” și numiți culoarea.', 'Dacă vrea: adăugați: „Uite. Privește.” când arătați împreună.']::text[], 'A arătat o culoare adultului (gest sau cuvânt).', 'Culori pe care le vedem'),
  ('s5-b23-z2-mental', 'Roșu sau albastru?', ARRAY['1 obiect roșu', '1 obiect albastru']::text[], ARRAY['Arătați: „Roșu.” pe obiectul roșu.', 'Arătați: „Albastru.” pe cel albastru. Întrebați: „Unde e roșu?”', 'Dacă vrea: lăsați-l să atingă culoarea pe care o numiți.']::text[], 'A auzit și a privit roșu / albastru.', 'Culori pe care le vedem'),
  ('s5-b23-z3-social', 'Privește cu al meu', '{}'::text[], ARRAY['Apropiați-vă de un obiect colorat: „Uite. Privește.”', 'Stați 10 secunde și numiți culoarea.', 'Dacă vrea: el alege următorul lucru de privit.']::text[], 'Ați privit împreună un lucru colorat.', 'Culori pe care le vedem'),
  ('s5-b23-z4-mental', 'Numește culoarea pe care o atingi', ARRAY['2–3 obiecte colorate']::text[], ARRAY['Atingeți un obiect: „Albastru.”', 'Atingeți altul: „Roșu.” Așteptați dacă imită.', 'Dacă vrea: spuneți: „Albastru.” doar pe unul.']::text[], 'A auzit numele a două culori pe obiecte.', 'Culori pe care le vedem'),
  ('s5-b23-z6-mental', 'Trei culori pe masă', ARRAY['3 obiecte de culori diferite']::text[], ARRAY['Așezați trei: „Una. Două. Trei.” Numiți fiecare culoare.', 'Întrebați blând: „Unde e albastru?”', 'Dacă vrea: adăugați: „Uite. Privește.” înainte de a arăta.']::text[], 'A auzit trei culori și a privit cel puțin una.', 'Culori pe care le vedem'),
  ('s5-b23-z7-mental', 'Culoarea favorită a săptămânii', ARRAY['2–3 obiecte colorate din săptămână']::text[], ARRAY['Întrebați: „Care ți-a plăcut?” — arătați 2–3 opțiuni.', 'Stați un moment și numiți culoarea aleasă.', 'Dacă vrea: spuneți: „Roșu” sau „Albastru” doar pe favorită.']::text[], 'A ales sau a privit culoarea favorită.', 'Culori pe care le vedem'),
  ('s5-b23-z7-social', 'Ritual: bună seara, culori', '{}'::text[], ARRAY['Șoptiți: „Bună seara.” Arătați o culoare din cameră.', '„Noapte bună.” Calm, fără forțare.', 'Dacă vrea: „Uite. Privește” — o ultimă culoare, apoi odihnă.']::text[], 'Ați închis săptămâna culorilor cu ritual blând.', 'Culori pe care le vedem'),
  ('s6-b23-z1-mental', 'Sus și jos pe corp', '{}'::text[], ARRAY['Atingeți capul: „Sus. Cap.”', 'Atingeți picioarele: „Jos. Picioare.”', 'Dacă vrea: spuneți: „Sus.” pe cap, „Jos.” pe picioare.']::text[], 'A auzit sus / jos pe corp.', 'Sus și jos'),
  ('s6-b23-z2-mental', 'Obiect sus, obiect jos', ARRAY['1 jucărie', 'scaun sau masă joasă']::text[], ARRAY['Puneți jucăria pe scaun: „Sus.”', 'Puneți-o pe jos: „Jos.” Întrebați: „Unde e acum?”', 'Dacă vrea: adăugați: „Sus” când e pe scaun, „Jos” pe jos.']::text[], 'A văzut același obiect sus și jos.', 'Sus și jos'),
  ('s6-b23-z4-mental', 'Mingea sus, mingea jos', ARRAY['minge ușoară']::text[], ARRAY['Țineți mingea sus: „Sus.”', 'Lăsați-o jos (sau puneți-o): „Jos.”', 'Dacă vrea: el spune sau arată unde e mingea.']::text[], 'A urmărit mingea sus și jos.', 'Sus și jos'),
  ('s6-b23-z7-mental', 'Favoritul: sus sau jos?', ARRAY['jucărie pe masă și pe jos ca opțiuni']::text[], ARRAY['Întrebați: „Îți place sus sau jos?” — arătați ambele.', 'Stați un moment la alegerea lui.', 'Dacă vrea: „Sus” sau „Jos” pe alegere.']::text[], 'A ales sau a privit favoritul sus/jos.', 'Sus și jos'),
  ('s6-b23-z7-social', 'Ritual: mână sus, mână jos, noapte bună', '{}'::text[], ARRAY['Ridicați mâna scurt: „Sus.” Coborâți: „Jos.”', '„Noapte bună.” Calm.', 'Dacă vrea: „Sus… Jos…” șoptit, apoi odihnă.']::text[], 'Ați închis săptămâna cu ritualul sus/jos.', 'Sus și jos'),
  ('s7-b23-z2-fizic', 'Din casă afară și înapoi', ARRAY['ușă', 'pantofi dacă e nevoie']::text[], ARRAY['Ieșiți câțiva pași: „Afară.”', 'Intrați înapoi: „Înăuntru.”', 'Dacă vrea: el alege ritmul pe traseul scurt.']::text[], 'A ieșit și a intrat pe scurt cu adultul.', 'Înăuntru și afară'),
  ('s7-b23-z3-mental', 'Ce e înăuntru, ce e afară', ARRAY['fereastră sau ușă deschisă']::text[], ARRAY['Arătați în casă: „Înăuntru.”', 'Arătați afară: „Afară.”', 'Dacă vrea: întrebați: „Unde e pomul / holul?”']::text[], 'A privit înăuntru și afară pe rând.', 'Înăuntru și afară'),
  ('s7-b23-z5-mental', 'Unde suntem acum?', '{}'::text[], ARRAY['La fiecare oprire: „Suntem înăuntru” sau „Suntem afară.”', 'Așteptați dacă arată sau repetă.', 'Dacă vrea: „Înăuntru” / „Afară” pe locul unde sunteți.']::text[], 'A auzit eticheta locului actual.', 'Înăuntru și afară'),
  ('s7-b23-z7-mental', 'Locul favorit: înăuntru sau afară', '{}'::text[], ARRAY['Întrebați: „Unde ți-a plăcut?” — arătați înăuntru și afară.', 'Stați un moment acolo.', 'Dacă vrea: „Înăuntru” sau „Afară” pe favorit.']::text[], 'A ales sau a privit locul favorit.', 'Înăuntru și afară'),
  ('s8-b23-z1-fizic', 'Strângem frunze blând', ARRAY['frunze afară sau aduse', 'mâini sau găleată mică']::text[], ARRAY['Strângeți 2–3 frunze împreună, fără grabă.', '„Frunză.” pe una pe rest.', 'Dacă vrea: întrebați: „De ce e diferită?” pe două frunze.']::text[], 'A strâns frunze pe scurt cu adultul.', 'Frunze și pământ'),
  ('s8-b23-z1-mental', 'Două tipuri: frunză și pământ', ARRAY['frunză', 'puțin pământ/nisip într-un vas']::text[], ARRAY['Atingeți: „Frunză.” Apoi: „Pământ.”', '„Uscat / moale” — ce simțiți, pe scurt.', 'Dacă vrea: sortați încă o frunză lângă frunze.']::text[], 'A atins și a auzit frunză / pământ.', 'Frunze și pământ'),
  ('s8-b23-z1-social', 'Împărțim o frunză', ARRAY['1–2 frunze']::text[], ARRAY['Oferiți-i o frunză: „Pentru tine.”', 'Voi țineți una: „Pentru al meu.”', 'Dacă vrea: schimbați frunzele o dată.']::text[], 'Ați împărțit frunze pe scurt.', 'Frunze și pământ'),
  ('s8-b23-z2-fizic', 'Pământ controlat — degete pe vas', ARRAY['vas cu puțin pământ/nisip', 'prosop']::text[], ARRAY['Lăsați-l să atingă pământul din vas (nu împrăștia).', '„Pământ.” Ștergeți degetele: „Gata.”', 'Dacă vrea: comparați cu o frunză uscată pe lângă.']::text[], 'A atins pământul controlat din vas.', 'Frunze și pământ'),
  ('s8-b23-z2-mental', 'Sortăm: frunză mare, frunză mică', ARRAY['2–4 frunze de mărimi diferite']::text[], ARRAY['Arătați: „Mare.” „Mică.”', 'Puneți-le în două grupe.', 'Dacă vrea: „De ce e diferit?” — o frază scurtă de la voi.']::text[], 'A văzut sortarea mare / mică pe frunze.', 'Frunze și pământ'),
  ('s8-b23-z2-social', 'Arătăm frunza adultului', ARRAY['1 frunză']::text[], ARRAY['Invitați-l să arate frunza cuiva drag.', '„Uite frunza!”', 'Dacă vrea: spuneți: „Frunză.” când arată.']::text[], 'A arătat frunza cuiva.', 'Frunze și pământ'),
  ('s8-b23-z4-fizic', 'Frunza cade — urmărim', ARRAY['1–2 frunze']::text[], ARRAY['Lăsați o frunză să cadă de la înălțimea pieptului: „Toamnă. Cade.”', 'Ridicați-o: „Jos pe jos. Frunză.”', 'Dacă vrea: el dă drumul frunzei (voi prindeți sau lăsați pe jos).']::text[], 'A urmărit frunza care cade.', 'Frunze și pământ'),
  ('s8-b23-z5-mental', 'Unde e frunza, unde e pământul?', ARRAY['frunză', 'vas cu pământ']::text[], ARRAY['„Unde e frunza?” Așteptați arătarea.', '„Unde e pământul?”', 'Dacă vrea: „Frunză” / „Pământ” pe fiecare, o dată.']::text[], 'A arătat sau a privit frunza și pământul.', 'Frunze și pământ'),
  ('s8-b23-z5-social', 'Privim împreună frunza pe geam sau pe jos', ARRAY['frunză']::text[], ARRAY['Stați umăr lângă umăr: „Uite — frunză.” ().', '„Frunză.” o dată.', 'Dacă vrea: el alege unde o puneți să o priviți.']::text[], 'Ați privit împreună frunza.', 'Frunze și pământ'),
  ('s8-b23-z7-fizic', 'Strâns liber — frunza favorită', ARRAY['frunze']::text[], ARRAY['El alege ritmul: strânge sau doar ține o frunză.', 'Voi numiți, fără grabă.', 'Dacă vrea: lăsați frunza să cadă o dată: „Toamnă. Cade.”']::text[], 'A manipulat frunza liber, pe scurt.', 'Frunze și pământ'),
  ('s8-b23-z7-social', 'Ritual: bună seara, frunză', ARRAY['1 frunză opțională']::text[], ARRAY['Șoptiți: „Bună seara.” Atingeți frunza sau cutia.', '„Noapte bună.”', 'Dacă vrea: „Frunză — la revedere până mâine.”']::text[], 'Ați închis săptămâna frunzelor cu ritual blând.', 'Frunze și pământ'),
  ('s9-b23-z1-mental', 'Unde simți aerul?', '{}'::text[], ARRAY['Atingeți ușor fața lui cu aerul de la mână (sau vânt): „Pe față.”', 'Apoi pe mână: „Pe mână. Unde simți aerul?”', 'Dacă vrea: spuneți o dată: „Aer.” pe locul unde simte.']::text[], 'A auzit și a simțit aerul pe o parte a corpului.', 'Vânt și aer'),
  ('s9-b23-z1-social', 'Arătăm vântul împreună', ARRAY['eșarfă sau frunză ușoară (opțional)']::text[], ARRAY['Țineți eșarfa împreună și lăsați-o să se miște: „Uite vântul!”', 'Spuneți: „Împreună.” și priviți mișcarea.', 'Dacă vrea: adăugați: „Vânt.” când eșarfa se mișcă.']::text[], 'Ați privit împreună mișcarea eșarfei / aerului.', 'Vânt și aer'),
  ('s9-b23-z2-mental', 'Vânt sau liniște?', ARRAY['fereastră / ușă']::text[], ARRAY['Deschideți puțin: „Vânt.” — simțiți aerul.', 'Închideți: „Liniște. Fără vânt.” Întrebați: „Unde e vântul?”', 'Dacă vrea: el arată fereastra sau gestul „afară”.']::text[], 'A comparat vânt și liniște.', 'Vânt și aer'),
  ('s9-b23-z2-social', 'Rândul la suflat blând', ARRAY['hârtie ușoară sau fulg de bumbac']::text[], ARRAY['Voi suflați blând: „Acum eu. Suflăm. Suflu.”', 'Apoi: „Acum tu” — așteptați suflul lui (sau gest).', 'Dacă vrea: încă un schimb de rând, apoi gata.']::text[], 'Ați făcut un schimb de rând la suflat blând.', 'Vânt și aer'),
  ('s9-b23-z3-mental', 'Două locuri: aer pe față, aer pe mână', '{}'::text[], ARRAY['Arătați fața: „Aer aici.”', 'Arătați mâna: „Aer aici.” Întrebați: „Unde simți?”', 'Dacă vrea: spuneți: „Aer” pe locul pe care îl alege.']::text[], 'A legat aerul de două părți ale corpului.', 'Vânt și aer'),
  ('s9-b23-z4-fizic', 'Învârtire blândă — aer pe corp', ARRAY['podea liberă']::text[], ARRAY['Învârtiți-vă foarte încet ținându-l: „Aer pe corp.”', 'Opriți-vă: „Gata. Stăm.”', 'Dacă vrea: arătați pe față și pe spate: „Aici.”']::text[], 'A simțit aerul pe corp într-o învârtire blândă.', 'Vânt și aer'),
  ('s9-b23-z4-mental', 'Suflăm — Suflăm', ARRAY['hârtie ușoară']::text[], ARRAY['Suflați pe hârtie: „Suflăm. Suflu.”', 'Priviți cum se mișcă: „Se mișcă.”', 'Dacă vrea: el suflă sau apropiați hârtia de gura lui fără forțare.']::text[], 'A văzut efectul suflatului pe hârtie.', 'Vânt și aer'),
  ('s9-b23-z4-social', 'Eu suflu, tu privești', ARRAY['hârtie ușoară']::text[], ARRAY['Voi suflați: „Acum eu.” El privește.', 'Schimbați: „Acum tu” — el suflă sau gesticulează.', 'Dacă vrea: spuneți împreună: „Vânt!” când hârtia se mișcă.']::text[], 'Ați schimbat rolul la suflat / privit.', 'Vânt și aer'),
  ('s9-b23-z6-mental', 'Trei cuvinte: vânt, aer, suflu', ARRAY['eșarfă opțională']::text[], ARRAY['Spuneți: „Vânt.” Apoi: „Aer.” Apoi: „Suflu.”', 'Atingeți eșarfa sau aerul la fiecare cuvânt.', 'Dacă vrea: adăugați: „Vânt. Aer. Suflăm.” pe rând, cu gest.']::text[], 'A auzit trei cuvinte legate de aer.', 'Vânt și aer'),
  ('s9-b23-z7-mental', 'Favoritul: vânt sau liniște?', '{}'::text[], ARRAY['Întrebați: „Îți place vântul sau liniștea?” — arătați ambele (fereastră deschisă / închisă).', 'Stați un moment pe alegerea lui.', 'Dacă vrea: spuneți: „Vânt” sau „Aer” doar pe favorit.']::text[], 'A ales sau a privit favorita săptămânii.', 'Vânt și aer'),
  ('s9-b23-z7-social', 'Ritual: bună seara, aer blând', '{}'::text[], ARRAY['Șoptiți: „Bună seara.” Suflați foarte blând pe o mână.', '„Noapte bună.” Calm, fără forțare.', 'Dacă vrea: „Aer” — un ultim suflu mic, apoi odihnă.']::text[], 'Ați închis săptămâna vântului cu ritual blând.', 'Vânt și aer'),
  ('s10-b23-z1-mental', 'Sortăm pe un criteriu', ARRAY['4 obiecte: 2 de un tip, 2 de alt tip']::text[], ARRAY['Arătați: „La fel aici.” — grămadă 1.', '„Altul aici.” — grămadă 2. Spuneți: „Sortăm.”', 'Dacă vrea: el mută un obiect în grămada potrivită.']::text[], 'A văzut două grămezi sortate pe un criteriu.', 'Colectăm și sortăm'),
  ('s10-b23-z1-social', 'Rândul la pus în cutie', ARRAY['cutie', '2 obiecte']::text[], ARRAY['Voi puneți unul: „Acum eu. În cutie.”', 'Apoi: „Acum tu” — așteptați gestul lui.', 'Dacă vrea: adăugați: „Cutie.” când puneți.']::text[], 'Ați făcut un schimb de rând la pus în cutie.', 'Colectăm și sortăm'),
  ('s10-b23-z2-fizic', 'Cărăm de pe jos pe masă', ARRAY['2 obiecte pe jos', 'masă sau scaun']::text[], ARRAY['Ridicați de pe jos: „Alege. Luăm.”', 'Cărați pe masă: „Aici.”', 'Dacă vrea: el alege care obiect urcă primul.']::text[], 'A cărat obiecte de pe jos pe masă.', 'Colectăm și sortăm'),
  ('s10-b23-z2-mental', 'Două grămezi: culoare', ARRAY['2 obiecte de o culoare', '2 de altă culoare']::text[], ARRAY['Sortați: „Roșu aici. Albastru aici.”', 'Spuneți: „Sortăm după culoare.”', 'Dacă vrea: el alege unde merge un obiect nou.']::text[], 'A sortat (sau a privit sortarea) pe culoare.', 'Colectăm și sortăm'),
  ('s10-b23-z3-mental', 'Mare și mic — sortăm', ARRAY['2 obiecte mari', '2 mici']::text[], ARRAY['Arătați: „Mare aici. Mic aici.”', '„Sortăm după mărime.”', 'Dacă vrea: combinați: un obiect „mare și roșu” — arătați ambele criterii.']::text[], 'A văzut sortarea pe mărime.', 'Colectăm și sortăm'),
  ('s10-b23-z4-resurse', 'Alege ce intră în cutie — unul din două', ARRAY['2 obiecte', 'cutie']::text[], ARRAY['„Acesta sau acesta în cutie?”', 'El alege; celălalt la loc pe masă: „La loc.”', 'Dacă vrea: spuneți: „Alege. Alegem.” pe obiectul ales.']::text[], 'Un obiect e în cutie; celălalt e la loc.', 'Colectăm și sortăm'),
  ('s10-b23-z5-mental', 'Sortăm culoare și mărime', ARRAY['obiecte pe 2 culori și 2 mărimi']::text[], ARRAY['Faceți o grămadă: „Roșu și mic.”', 'Arătați alta: „Albastru și mare.” Spuneți: „Sortăm.”', 'Dacă vrea: el alege unde merge un obiect după ambele criterii.']::text[], 'A văzut sortarea pe culoare și mărime (extensie schiță).', 'Colectăm și sortăm'),
  ('s10-b23-z6-fizic', 'Colectăm afară sau lângă fereastră', ARRAY['curte / balcon sau cameră', '2–3 obiecte sigure']::text[], ARRAY['Colectați 2–3 lucruri sigure (frunză, piatră mică, jucărie).', 'Cărați-le la cutie: „În cutie. În cutie.”', 'Dacă vrea: încă un obiect, sau opriți-vă.']::text[], 'A colectat și a cărat 2–3 obiecte.', 'Colectăm și sortăm'),
  ('s10-b23-z7-mental', 'Favoritul: sortăm sau cărat?', ARRAY['cutie', 'câteva obiecte']::text[], ARRAY['Întrebați: „Îți place să sortezi sau să cari?” — arătați ambele.', 'Stați un moment pe alegerea lui.', 'Dacă vrea: spuneți: „Sortăm” sau „Alege” pe favorită.']::text[], 'A ales sau a privit favorita săptămânii.', 'Colectăm și sortăm'),
  ('s10-b23-z7-social', 'Ritual: bună seara, cutie', ARRAY['cutie']::text[], ARRAY['Șoptiți: „Bună seara.” Atingeți cutia blând.', '„Noapte bună.”', 'Dacă vrea: „Cutie — la revedere până mâine.”']::text[], 'Ați închis săptămâna colectatului cu ritual blând.', 'Colectăm și sortăm'),
  ('s11-b23-z1-fizic', 'Mutăm corpul: lumină și umbră', ARRAY['loc luminos', 'loc cu umbră (perete / perdea)']::text[], ARRAY['Stați în lumină: „Lumină.”', 'Mutați-vă în umbră: „Umbră.” Faceți o dată dus-întors.', 'Dacă vrea: mutați un obiect din lumină în umbră.']::text[], 'A mutat corpul din lumină în umbră.', 'Lumină și umbră'),
  ('s11-b23-z1-resurse', 'Stinge și aprinde — gata', ARRAY['lampă sau întrerupător (doar adultul)']::text[], ARRAY['Adultul stinge blând: „Întuneric.”', 'Aprinde: „Lumină. Gata.” O dată e destul.', 'Dacă vrea: el cere „iar” sau „gata” — voi respectați.']::text[], 'Ați stins și aprins o dată; jocul e închis.', 'Lumină și umbră'),
  ('s11-b23-z1-social', 'Arătăm umbra celuilalt', ARRAY['perete luminat']::text[], ARRAY['Stați astfel încât umbra voastră să se vadă: „Uite umbra mea.”', 'Ajutați-l să-și vadă umbra: „Uite umbra ta!”', 'Dacă vrea: adăugați: „Umbră.” pe umbra lui.']::text[], 'Ați arătat umbra unul altuia.', 'Lumină și umbră'),
  ('s11-b23-z2-mental', 'Lumină sau întuneric?', ARRAY['lampă (adult)']::text[], ARRAY['Aprindeți: „Lumină.”', 'Stingeți puțin: „Întuneric.” Întrebați: „Unde e lumină?”', 'Dacă vrea: el arată lampa sau fereastra.']::text[], 'A comparat lumină și întuneric.', 'Lumină și umbră'),
  ('s11-b23-z3-mental', 'Umbra mâinii pe perete', ARRAY['lampă sau soare pe perete']::text[], ARRAY['Puneți mâna între lumină și perete: „Umbră.”', 'Mișcați degetele: „Se mișcă umbra.”', 'Dacă vrea: mutați un obiect mic — umbra obiectului.']::text[], 'A văzut umbra mâinii (sau a unui obiect).', 'Lumină și umbră'),
  ('s11-b23-z3-social', 'Umbra ta pe al meu — joc blând', ARRAY['perete luminat']::text[], ARRAY['Apropiați umbrele pe perete: „Uite — umbrele se întâlnesc.”', 'Priviți împreună 10 secunde.', 'Dacă vrea: el mută umbra spre a voastră.']::text[], 'Ați întâlnit umbrele pe perete.', 'Lumină și umbră'),
  ('s11-b23-z4-mental', 'Obiect în lumină, obiect în umbră', ARRAY['2 obiecte', 'zonă lumină și umbră']::text[], ARRAY['Puneți unul în lumină: „Lumină.”', 'Puneți celălalt în umbră: „Umbră.” Întrebați: „Care e în lumină?”', 'Dacă vrea: schimbați locurile obiectelor.']::text[], 'A văzut același tip de obiect în lumină și în umbră.', 'Lumină și umbră'),
  ('s11-b23-z4-resurse', 'Stins — ajunge pentru azi', ARRAY['lampă (adult)']::text[], ARRAY['Stingeți o dată: „Întuneric.”', 'Aprindeți: „Lumină. Ajunge. Gata.”', 'Dacă vrea: lăsați o lumină mică de noapte aprinsă.']::text[], 'Ciclu stins/aprins închis cu „ajunge”.', 'Lumină și umbră'),
  ('s11-b23-z5-mental', 'Unde e mai întuneric?', ARRAY['2 colțuri ale camerei']::text[], ARRAY['Arătați un colț: „Mai luminos.”', 'Arătați altul: „Mai întuneric.”', 'Dacă vrea: el alege unde stă 10 secunde.']::text[], 'A comparat două niveluri de lumină.', 'Lumină și umbră'),
  ('s11-b23-z5-social', 'Umbra mea, umbra ta', ARRAY['perete luminat']::text[], ARRAY['Arătați: „A mea.” Apoi: „A ta.”', 'Mișcați pe rând o mână.', 'Dacă vrea: spuneți: „Umbră” pe fiecare umbră.']::text[], 'Ați numit umbra mea / umbra ta.', 'Lumină și umbră'),
  ('s11-b23-z6-mental', 'Trei cuvinte: lumină, întuneric, umbră', ARRAY['lampă / perete']::text[], ARRAY['Spuneți: „Lumină.” „Întuneric.” „Umbră.” cu gest pe fiecare.', 'Repetați o dată pe obiecte / locuri.', 'Dacă vrea: „Lumină. Întuneric. Umbră.” pe rând, cu gest.']::text[], 'A auzit trei cuvinte despre lumină.', 'Lumină și umbră'),
  ('s11-b23-z7-mental', 'Favoritul: lumină sau umbră?', '{}'::text[], ARRAY['Întrebați: „Îți place lumina sau umbra?” — arătați ambele.', 'Stați un moment pe alegerea lui.', 'Dacă vrea: „Lumină” sau „Umbră” pe favorită.']::text[], 'A ales sau a privit favorita săptămânii.', 'Lumină și umbră'),
  ('s11-b23-z7-social', 'Ritual: bună seara, umbră blândă', ARRAY['lampă slabă opțională']::text[], ARRAY['Șoptiți: „Bună seara.” Arătați o umbră mică pe perete.', '„Noapte bună.”', 'Dacă vrea: „Întuneric — odihnă.” apoi lumină mică.']::text[], 'Ați închis săptămâna luminii cu ritual blând.', 'Lumină și umbră'),
  ('s12-b23-z1-fizic', 'Alegem loc cald sau rece pe corp', ARRAY['mână pe obraz / pe geam / pe cană călduță (sigură)']::text[], ARRAY['Atingeți un loc călduț pe corp: „Cald.”', 'Atingeți ceva mai rece (geam, podea): „Rece.”', 'Dacă vrea: el alege care loc îi place și spune (sau arată) de ce — o frază.']::text[], 'A simțit un loc cald și unul rece pe corp / obiect.', 'Cald și rece'),
  ('s12-b23-z1-mental', 'Compară două temperaturi', ARRAY['2 obiecte: unul călduț, unul rece (sigure)']::text[], ARRAY['Arătați: „Acesta e cald.”', '„Acesta e rece.” Întrebați: „Care e cald?”', 'Dacă vrea: adăugați: „Fierbinte” doar pe cel foarte cald (nu arzător) sau „Cald” pe călduț.']::text[], 'A comparat două temperaturi.', 'Cald și rece'),
  ('s12-b23-z1-social', 'Împărtășim senzația', ARRAY['obiect călduț sau rece sigur']::text[], ARRAY['Atingeți și spuneți: „Eu simt cald.”', 'Oferiți-i să atingă: „Tu?” — așteptați gestul.', 'Dacă vrea: spuneți împreună: „Cald” sau „Rece” pe senzație.']::text[], 'Ați împărtășit o senzație de temperatură.', 'Cald și rece'),
  ('s12-b23-z2-fizic', 'Mâini pe geam — rece', ARRAY['geam (sigur)']::text[], ARRAY['Puneți mâinile pe geam: „Rece.”', 'Apoi pe obrazul vostru: „Cald.”', 'Dacă vrea: el alege cât stă pe geam.']::text[], 'A simțit rece pe geam și cald pe corp.', 'Cald și rece'),
  ('s12-b23-z2-mental', 'Cald, călduț, rece', ARRAY['3 zone / obiecte sigure']::text[], ARRAY['Arătați: „Fierbinte / foarte cald” (doar dacă e sigur — altfel „cald”).', '„Cald. Călduț.” „Rece.”', 'Dacă vrea: el arată zona pe care o numiți.']::text[], 'A auzit trei niveluri de temperatură.', 'Cald și rece'),
  ('s12-b23-z4-fizic', 'Înfășurare blândă — cald pe corp', ARRAY['pătură ușoară']::text[], ARRAY['Înveliți-l blând: „Cald.”', 'Descoperiți puțin: „Mai puțin cald.”', 'Dacă vrea: el alege pătură pe sau pătură jos.']::text[], 'A simțit cald cu pătură pe corp.', 'Cald și rece'),
  ('s12-b23-z4-mental', 'Rece pe mână, cald pe obraz', '{}'::text[], ARRAY['Atingeți mâna cu ceva rece (sau aer de la geam): „Rece.”', 'Atingeți obrazul: „Cald.”', 'Dacă vrea: întrebați: „Unde e cald pe tine?”']::text[], 'A legat cald / rece de părți ale corpului.', 'Cald și rece'),
  ('s12-b23-z4-social', 'Ținem împreună ceva călduț', ARRAY['sticlă călduță sau pernă ținută la piept']::text[], ARRAY['Țineți împreună: „Cald. Împreună.”', 'Coborâți: „Gata.”', 'Dacă vrea: încă o dată, el alege ritmul.']::text[], 'Ați ținut împreună ceva călduț.', 'Cald și rece'),
  ('s12-b23-z5-mental', 'Fierbinte, rece, cald — pe obiecte', ARRAY['3 obiecte / zone sigure']::text[], ARRAY['Arătați: „Fierbinte” (sau „cald” dacă nu e fierbinte).', '„Rece.” „Cald. Călduț.”', 'Dacă vrea: el atinge doar zona pe care o alege.']::text[], 'A auzit fierbinte / rece / cald pe obiecte sigure.', 'Cald și rece'),
  ('s12-b23-z6-fizic', 'Afară scurt: aer mai rece, casă mai caldă', ARRAY['ușă / balcon']::text[], ARRAY['Ieșiți 20–30 de secunde: „Rece afară.”', 'Intrați: „Cald în casă.”', 'Dacă vrea: încă un dus-întors scurt.']::text[], 'A simțit contrastul afară / în casă.', 'Cald și rece'),
  ('s12-b23-z7-mental', 'Favoritul: cald sau rece?', '{}'::text[], ARRAY['Întrebați: „Îți place cald sau rece?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Cald” sau „Rece” pe favorită — și un „de ce” blând.']::text[], 'A ales sau a privit favorita săptămânii.', 'Cald și rece'),
  ('s12-b23-z7-social', 'Ritual: bună seara, cald blând', ARRAY['pătură sau lumină călduță']::text[], ARRAY['Șoptiți: „Bună seara.” Atingeți pătură: „Cald.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Rece” pe geam, apoi înapoi la cald și odihnă.']::text[], 'Ați închis săptămâna cald/rece cu ritual blând.', 'Cald și rece'),
  ('s13-b23-z1-fizic', 'Îmbrăcat asistat pe scurt — haina', ARRAY['haină ușoară sau jachetă']::text[], ARRAY['Luați haina împreună: „Haină.”', 'Puneți-o pe umeri 10–20 de secunde, asistat, fără forțare.', 'Dacă vrea: spuneți de ce — „Pentru că e frig / e vremea.”']::text[], 'A simțit haina pe umeri câteva secunde.', 'Haine pe vreme'),
  ('s13-b23-z2-fizic', 'Pălăria pe cap — scurt', ARRAY['pălărie sau căciulă']::text[], ARRAY['Luați pălăria: „Pălărie.”', 'Puneți-o pe cap 10–15 de secunde, apoi jos blând.', 'Dacă vrea: încă o dată, el alege pe sau jos.']::text[], 'A simțit pălăria pe cap scurt.', 'Haine pe vreme'),
  ('s13-b23-z2-mental', 'Haină sau pălărie — după vreme', ARRAY['haină', 'pălărie']::text[], ARRAY['Arătați ambele: „Haină. Pălărie.”', 'Întrebați: „Ce punem dacă e frig afară?”', 'Dacă vrea: el alege și arată motivul (geam / gest frig).']::text[], 'A ales un articol legat de vreme.', 'Haine pe vreme'),
  ('s13-b23-z3-mental', 'Rece — de ce haina?', ARRAY['haină', 'fereastră']::text[], ARRAY['Atingeți geamul sau aerul de la ușă: „Rece.”', 'Arătați haina: „De aceea haina.”', 'Dacă vrea: el repetă „rece” sau arată haina.']::text[], 'A legat recele de nevoie de haină.', 'Haine pe vreme'),
  ('s13-b23-z4-fizic', 'Pași cu haina pe umeri', ARRAY['haină ușoară', 'spațiu liber']::text[], ARRAY['Puneți haina pe umeri și faceți 5–8 pași: „Haină. Mergem.”', 'Opriți-vă: „Gata.”', 'Dacă vrea: el alege direcția următorilor pași.']::text[], 'A mers scurt cu haina pe umeri.', 'Haine pe vreme'),
  ('s13-b23-z4-social', 'Eu țin pălăria, tu haina', ARRAY['haină', 'pălărie']::text[], ARRAY['Dați-i haina: „A ta.” Luați pălăria: „A mea.”', 'Schimbați o dată: „Acum invers.”', 'Dacă vrea: spuneți împreună „Haină” și „Pălărie” pe obiecte.']::text[], 'Ați împărțit rolurile pe două articole.', 'Haine pe vreme'),
  ('s13-b23-z5-mental', 'Haină, pălărie, rece — pe obiecte', ARRAY['haină', 'pălărie', 'fereastră / aer rece']::text[], ARRAY['Arătați: „Haină.” „Pălărie.”', 'Apoi aerul: „Rece.”', 'Dacă vrea: el atinge doar obiectul pe care îl numiți.']::text[], 'A auzit haină / pălărie / rece pe obiecte reale.', 'Haine pe vreme'),
  ('s13-b23-z6-fizic', 'Afară scurt cu haina — înapoi', ARRAY['haină', 'ușă / balcon']::text[], ARRAY['Îmbrăcați, ieșiți 20–30 de secunde: „Rece afară.”', 'Intrați și scoateți: „În casă. Haina jos.”', 'Dacă vrea: încă un dus-întors scurt.']::text[], 'A simțit contrastul afară cu haină / în casă fără.', 'Haine pe vreme'),
  ('s13-b23-z6-social', 'Joacă paralel: eu cu haina, tu cu pălăria', ARRAY['haină', 'pălărie']::text[], ARRAY['Voi cu haina; el cu pălăria (sau invers).', 'Comentați: „Eu haină. Tu pălărie.”', 'Dacă vrea: schimbați o dată.']::text[], 'Ați jucat paralel cu două articole.', 'Haine pe vreme'),
  ('s13-b23-z7-mental', 'Favoritul: haina sau pălăria?', ARRAY['haină', 'pălărie']::text[], ARRAY['Întrebați: „Îți place haina sau pălăria?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Haină” sau „Pălărie” pe favorită — și un „de ce” blând.']::text[], 'A ales sau a privit favorita săptămânii.', 'Haine pe vreme'),
  ('s13-b23-z7-social', 'Ritual: bună seara, haină la loc', ARRAY['haină sau pălărie']::text[], ARRAY['Șoptiți: „Bună seara.” Agățați blând: „La loc.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Rece” pe geam, apoi înapoi la calm.']::text[], 'Ați închis săptămâna hainelor cu ritual blând.', 'Haine pe vreme'),
  ('s14-b23-z1-fizic', 'Plimbare scurtă până la un reper', ARRAY['hol / curte / cameră cu un reper vizibil']::text[], ARRAY['Alegeți un reper (ușă, scaun, pom): „Mergem până acolo.”', 'Mergeți împreună: „Mergem.”', 'Dacă vrea: denumiți reperul — „Ușa. / Scaunul.”']::text[], 'A ajuns la reperul ales pe jos.', 'Pași pe drumul scurt'),
  ('s14-b23-z1-resurse', 'Întoarcere acasă — gata', ARRAY['reper → punct de pornim']::text[], ARRAY['Spuneți: „Ne întoarcem. Gata drumul.”', 'Ajungeți la pornim: „Acasă. Ajunge.”', 'Dacă vrea: el alege dacă vă întoarceți pe același traseu.']::text[], 'V-ați întors; drumul e închis.', 'Pași pe drumul scurt'),
  ('s14-b23-z1-social', 'Mergeți împreună — așteaptă', '{}'::text[], ARRAY['Luați-l de mână sau mergeți umăr la umăr: „Împreună.”', 'Opriți-vă o clipă: „Așteptăm.” apoi: „Hai. Mergem.”', 'Dacă vrea: el dă semnalul de plecare (gest sau cuvânt).']::text[], 'A mers împreună și a așteptat o oprire.', 'Pași pe drumul scurt'),
  ('s14-b23-z2-fizic', 'Mergem și oprim pe hol', ARRAY['hol sau cameră liberă']::text[], ARRAY['Mergeți: „Mergem.”', 'Opriți-vă: „Oprim. Stăm.” — 2–3 runde.', 'Dacă vrea: el alege când oprim (bătăi din palme sau gest).']::text[], 'A alternat mers și oprire.', 'Pași pe drumul scurt'),
  ('s14-b23-z2-resurse', 'Drumul se oprește aici', ARRAY['punct clar de oprire']::text[], ARRAY['La punct: „Oprim. Gata.”', '„Ajunge pentru azi pe drum.”', 'Dacă vrea: alegeți un obiect mic de „închis” (cheie / pantof la loc).']::text[], 'Drumul e închis la punctul ales.', 'Pași pe drumul scurt'),
  ('s14-b23-z2-social', 'Rândul la mers înainte', '{}'::text[], ARRAY['Voi faceți 2 pași: „Acum eu. Hai.”', 'Apoi: „Acum tu” — așteptați pașii lui.', 'Dacă vrea: încă un schimb, apoi oprim împreună.']::text[], 'Ați schimbat rândul la pași înainte.', 'Pași pe drumul scurt'),
  ('s14-b23-z3-fizic', 'Dus-întors scurt pe același drum', ARRAY['reper la 5–10 pași']::text[], ARRAY['Mergeți la reper: „Hai. Mergem.”', 'Întoarceți-vă: „Înapoi. Acasă.”', 'Dacă vrea: denumiți un reper la dus și unul la întors.']::text[], 'A făcut un dus-întors pe jos.', 'Pași pe drumul scurt'),
  ('s14-b23-z4-fizic', 'Pași mari, pași mici pe drum', ARRAY['spațiu liber']::text[], ARRAY['Faceți 3 pași mari: „Mari.”', 'Apoi 3 pași mici: „Mici. Mergem.”', 'Dacă vrea: el alege următorul tip — mari sau mici.']::text[], 'A făcut pași mari și pași mici.', 'Pași pe drumul scurt'),
  ('s14-b23-z4-mental', 'Unde ne oprim? — Oprim', ARRAY['2 repere']::text[], ARRAY['Arătați: „Oprim aici? Sau aici?”', 'Alegeți unul și opriți-vă: „Oprim. Stăm.”', 'Dacă vrea: el motivează de ce acel reper (aproape / departe).']::text[], 'A ales un loc de oprire pe drum.', 'Pași pe drumul scurt'),
  ('s14-b23-z4-resurse', 'Alege drumul — unul din două', ARRAY['2 direcții / 2 repere']::text[], ARRAY['„Astăzi: pe aici sau pe aici?”', 'El alege; mergeți scurt: „Hai. Ajunge la reper.”', 'Dacă vrea: spuneți de ce ați alege voi celălalt drum, scurt.']::text[], 'A ales un drum din două.', 'Pași pe drumul scurt'),
  ('s14-b23-z4-social', 'Eu merg, tu aștepți — apoi invers', '{}'::text[], ARRAY['Voi mergeți 3 pași; el așteaptă.', 'Schimbați: „Acum tu. Hai.”', 'Dacă vrea: la final spuneți împreună „Oprim!”']::text[], 'Ați alternat mers și așteptare.', 'Pași pe drumul scurt'),
  ('s14-b23-z5-fizic', 'Traseu cu trei repere', ARRAY['3 repere pe un drum scurt']::text[], ARRAY['Parcurgeți: reper 1 → 2 → 3, denumind fiecare.', '„Mergem… Oprim” la fiecare reper o clipă.', 'Dacă vrea: el denumește unul dintre repere singur.']::text[], 'A trecut pe la trei repere pe jos.', 'Pași pe drumul scurt'),
  ('s14-b23-z5-mental', 'Pași, oprim, hai — pe drum', '{}'::text[], ARRAY['Spuneți: „Mergem” și mergeți.', '„Oprim” — stați. „Hai” — plecați din nou.', 'Dacă vrea: el dă unul din cele trei cuvinte (sau gest).']::text[], 'A auzit pași / oprim / hai în mișcare.', 'Pași pe drumul scurt'),
  ('s14-b23-z5-resurse', 'Întoarcerea e gata — ajunge', ARRAY['punct de pornim']::text[], ARRAY['Înapoi la pornim: „Acasă. Gata.”', '„Ajunge drumul de azi.”', 'Dacă vrea: un obiect de pe drum la loc înainte de pauză.']::text[], 'Întoarcerea a închis drumul.', 'Pași pe drumul scurt'),
  ('s14-b23-z5-social', 'Drumul meu, drumul tău — paralel', ARRAY['2 linii / 2 părți de hol']::text[], ARRAY['Voi pe o parte; el pe cealaltă: „Mergem împreună.”', 'La capăt: „Oprim. Împreună.”', 'Dacă vrea: schimbați părțile o dată.']::text[], 'Ați mers paralel pe același drum scurt.', 'Pași pe drumul scurt'),
  ('s14-b23-z6-fizic', 'Plimbare liberă scurtă afară sau la ușă', ARRAY['curte / balcon / hol spre ușă']::text[], ARRAY['Mergeți liber 30–60 de secunde: „Mergem.”', 'Alegeți un reper și opriți: „Oprim.”', 'Dacă vrea: denumiți două lucruri văzute pe drum.']::text[], 'A făcut o plimbare liberă scurtă cu o oprire.', 'Pași pe drumul scurt'),
  ('s14-b23-z7-mental', 'Favoritul: mergem sau oprim?', '{}'::text[], ARRAY['Întrebați: „Îți place să mergi sau să stai?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Mergem” sau „Oprim” pe favorită — și un „de ce” blând.']::text[], 'A ales sau a privit favorita săptămânii.', 'Pași pe drumul scurt'),
  ('s14-b23-z7-social', 'Ritual: bună seara, drumul s-a oprit', '{}'::text[], ARRAY['Șoptiți: „Bună seara. Oprim. Drumul e gata.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Hai” pe degete (mers pe genunchi), apoi calm.']::text[], 'Ați închis săptămâna drumului cu ritual blând.', 'Pași pe drumul scurt'),
  ('s15-b23-z1-fizic', 'Gustare: stai și mestecă', ARRAY['gustare mică sigură', 'scaun / masă']::text[], ARRAY['Stați la masă: „Stăm. Mâncăm.”', 'O bucată mică: mestecați împreună, fără grabă.', 'Dacă vrea: rol — voi oferiți, el mulțumește (sau invers).']::text[], 'A stat și a mestecat o bucată cu adultul.', 'Mâncare împreună'),
  ('s15-b23-z1-mental', 'Numește — miros și gust mic', ARRAY['1 aliment cunoscut (fruct / pâine)']::text[], ARRAY['Mirosiți: „Miros.” Apoi o mușcătură mică: „Gust.”', 'Numiți: „Fruct.” sau numele alimentului.', 'Dacă vrea: el spune „dulce / acru” sau arată dacă îi place.']::text[], 'A mirosit și a gustat pe scurt cu etichetă.', 'Mâncare împreună'),
  ('s15-b23-z1-social', 'Mulțumesc — oferă o bucată', ARRAY['2 bucăți mici']::text[], ARRAY['Oferiți-i una: „Pentru tine.”', 'El poate oferi una înapoi sau vouă: „Mulțumesc.”', 'Dacă vrea: schimbați rolurile — el oferă primul.']::text[], 'Ați oferit și ați mulțumit pe o bucată.', 'Mâncare împreună'),
  ('s15-b23-z2-fizic', 'Mestecăm încet — aceeași ritm', ARRAY['gustare moale']::text[], ARRAY['Luați o bucată: „Mâncăm. Încet.”', 'Mestecați de câteva ori împreună, pe ritm blând.', 'Dacă vrea: el alege ritmul — mai rar sau mai des.']::text[], 'A mestecat încet alături de adult.', 'Mâncare împreună'),
  ('s15-b23-z2-mental', 'Ce e pe farfurie?', ARRAY['1–2 alimente vizibile']::text[], ARRAY['Arătați: „Ce e asta?” — numiți clar.', 'Miros scurt: „Miros de…”', 'Dacă vrea: „Fruct” pe fruct, dacă e cazul.']::text[], 'A numit sau a privit alimentul de pe farfurie.', 'Mâncare împreună'),
  ('s15-b23-z2-social', 'Rândul la oferit', ARRAY['bol comun cu bucăți mici']::text[], ARRAY['Voi oferiți: „Acum eu.”', 'Apoi: „Acum tu” — așteptați gestul lui.', 'Dacă vrea: „Mulțumesc” după fiecare oferire.']::text[], 'Ați schimbat rândul la oferit.', 'Mâncare împreună'),
  ('s15-b23-z3-social', 'Oferă o bucată altcuiva', ARRAY['1 bucată', 'persoană dragă']::text[], ARRAY['Mergeți împreună și oferiți: „Pentru tine.”', 'Modelați: „Mulțumesc.” când primesc.', 'Dacă vrea: el ține bucata și o oferă singur.']::text[], 'A oferit o bucată cuiva.', 'Mâncare împreună'),
  ('s15-b23-z4-fizic', 'Bea o înghițitură, apoi mestecă', ARRAY['pahar cu apă', 'bucată mică']::text[], ARRAY['Înghițitură de apă: „Apă.”', 'Apoi bucata: „Mâncăm.”', 'Dacă vrea: el alege ordinea — întâi apă sau întâi mâncare.']::text[], 'A legat o înghițitură de apă de o mestecare.', 'Mâncare împreună'),
  ('s15-b23-z4-mental', 'Fruct — unde e fructul?', ARRAY['1 fruct', '1 alt aliment']::text[], ARRAY['Arătați: „Fruct.” pe fruct.', 'Arătați celălalt: „Nu e fruct.” Întrebați: „Unde e fructul?”', 'Dacă vrea: el atinge sau aduce fructul.']::text[], 'A găsit fructul dintre două.', 'Mâncare împreună'),
  ('s15-b23-z4-social', 'Eu mulțumesc, tu oferi', ARRAY['1 bucată']::text[], ARRAY['El oferă (asistat); voi: „Mulțumesc.”', 'Schimbați: voi oferiți; așteptați mulțumirea lui (gest sau cuvânt).', 'Dacă vrea: încă un schimb scurt.']::text[], 'Ați jucat rolul ofer / mulțumesc.', 'Mâncare împreună'),
  ('s15-b23-z5-fizic', 'Masă scurtă: stai, mestecă, gata', ARRAY['masă / scaun', 'porție mică']::text[], ARRAY['Secvență: „Stăm. Mâncăm. Gata.”', 'O porție mică, fără grabă.', 'Dacă vrea: el anunță „gata” când termină gura.']::text[], 'A parcurs stai–mestecă–gata la masă.', 'Mâncare împreună'),
  ('s15-b23-z5-mental', 'Mâncăm, fruct, mulțumesc — la masă', ARRAY['fruct sau aliment', 'bucată de oferit']::text[], ARRAY['„Mâncăm” pe mestecare. „Fruct” pe fruct (dacă e).', 'Oferiți: „Mulțumesc” când primește.', 'Dacă vrea: el spune unul din cele trei (sau gest).']::text[], 'A auzit mâncăm / fruct / mulțumesc la masă.', 'Mâncare împreună'),
  ('s15-b23-z5-social', 'Masă împreună — mulțumim', ARRAY['masă']::text[], ARRAY['La final: „Mulțumesc pentru masă.” împreună.', '„Mulțumesc.” pe rând, blând.', 'Dacă vrea: el mulțumește primului adult de la masă.']::text[], 'Ați mulțumit împreună la final de masă.', 'Mâncare împreună'),
  ('s15-b23-z6-social', 'Joacă de rol: magazin de fructe', ARRAY['1–2 fructe sau jucării-fruct']::text[], ARRAY['Voi „vindeți”: „Fruct?” El „cumpără” (ia).', '„Mulțumesc!” la schimb.', 'Dacă vrea: schimbați rolurile.']::text[], 'Ați jucat un schimb scurt cu fruct.', 'Mâncare împreună'),
  ('s15-b23-z7-mental', 'Favoritul: ce am mâncat?', ARRAY['2 amintiri / 2 opțiuni arătate']::text[], ARRAY['Întrebați: „Ce ți-a plăcut?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Fruct” sau „Mâncăm” pe favorită — și un „de ce” blând.']::text[], 'A ales sau a privit favorita săptămânii.', 'Mâncare împreună'),
  ('s15-b23-z7-social', 'Ritual: bună seara, mulțumim pentru masă', '{}'::text[], ARRAY['Șoptiți: „Bună seara. Mulțumesc pentru masă.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Mâncăm” pe gest (mână la gură), apoi odihnă.']::text[], 'Ați închis săptămâna mesei cu ritual blând.', 'Mâncare împreună'),
  ('s16-b23-z1-fizic', 'Turnat scurt cu adult', ARRAY['pahar / cană mică', 'recipient cu puțină apă', 'prosop']::text[], ARRAY['Țineți mâna lui pe cană: „Apă. Turnăm.”', 'Turnați puțin într-un pahar — scurt, cu control.', 'Dacă vrea: comparați două locuri — paharul sau planta (unde turnăm).']::text[], 'A turnat puțină apă cu adultul.', 'Apă și sete'),
  ('s16-b23-z1-mental', 'Ud sau uscat?', ARRAY['prosop uscat', 'prosop / mână ușor udă']::text[], ARRAY['Atingeți uscat: „Uscat.”', 'Atingeți ud: „Ud.” Întrebați: „Unde e ud?”', 'Dacă vrea: el arată din nou locul ud.']::text[], 'A comparat ud și uscat.', 'Apă și sete'),
  ('s16-b23-z2-fizic', 'Udat — degete în apă scurt', ARRAY['bol cu puțină apă', 'prosop']::text[], ARRAY['Atingeți apa: „Ud.”', 'Scoateți și ștergeți: „Uscat.”', 'Dacă vrea: încă o dată, el alege ud sau uscat întâi.']::text[], 'A trecut de la ud la uscat pe degete.', 'Apă și sete'),
  ('s16-b23-z2-mental', 'Unde e apa?', ARRAY['pahar', 'bol', 'sau chiuvetă vizibilă']::text[], ARRAY['Întrebați: „Unde e apă? Apa?”', 'Arătați locul: „Aici.”', 'Dacă vrea: comparați — „Aici e apă. Aici e uscat.”']::text[], 'A găsit locul cu apă.', 'Apă și sete'),
  ('s16-b23-z2-social', 'Rândul la turnat o picătură', ARRAY['cană', 'pahar', 'prosop']::text[], ARRAY['Voi turnați o picătură: „Acum eu.”', 'Apoi: „Acum tu” — asistat.', 'Dacă vrea: spuneți „Apă” la fiecare picătură.']::text[], 'Ați schimbat rândul la turnat.', 'Apă și sete'),
  ('s16-b23-z3-fizic', 'Cărăm paharul cu grijă', ARRAY['pahar cu foarte puțină apă', '2–4 pași']::text[], ARRAY['Cărați împreună paharul până la masă.', 'Puneți-l: „Gata. Apă pe masă.”', 'Dacă vrea: el alege traseul scurt până la masă.']::text[], 'A cărat paharul pe o distanță scurtă.', 'Apă și sete'),
  ('s16-b23-z4-fizic', 'Udăm planta — scurt', ARRAY['plantă', 'cană mică', 'prosop']::text[], ARRAY['Turnați puțin la rădăcină: „Apă pentru plantă.”', 'Opriți: „Ajunge. Gata.”', 'Dacă vrea: comparați pământul — „Ud aici. Uscat acolo.”']::text[], 'A udat planta pe scurt cu adultul.', 'Apă și sete'),
  ('s16-b23-z4-mental', 'Ud și uscat pe două locuri', ARRAY['2 zone: chiuvetă / prosop uscat sau pământ ud / uscat']::text[], ARRAY['Arătați: „Ud.” pe unul.', '„Uscat.” pe celălalt. „Unde e ud?”', 'Dacă vrea: el merge și atinge locul pe care îl numiți.']::text[], 'A legat ud / uscat de două locuri.', 'Apă și sete'),
  ('s16-b23-z4-social', 'Eu ud, tu ștergi — apoi invers', ARRAY['picătură pe masă', 'prosop']::text[], ARRAY['Voi „udați” o picătură; el șterge: „Uscat.”', 'Schimbați rolurile.', 'Dacă vrea: încă o rundă scurtă.']::text[], 'Ați schimbat rolurile ud / șters.', 'Apă și sete'),
  ('s16-b23-z5-fizic', 'Traseu: pahar gol → apă → pahar pe masă', ARRAY['pahar', 'chiuvetă / cană', 'masă']::text[], ARRAY['Luați paharul gol, turnați puțin, duceți la masă.', 'Numiți: „Gol. Apă. Pe masă.”', 'Dacă vrea: el compară — „Aici e apa” (chiuvetă) și „Aici bem” (masă).']::text[], 'A parcurs traseul pahar–apă–masă.', 'Apă și sete'),
  ('s16-b23-z5-mental', 'Apă, ud, uscat — pe obiecte', ARRAY['pahar cu apă', 'prosop ud', 'prosop uscat']::text[], ARRAY['„Apă” pe pahar. „Ud” pe prosopul ud. „Uscat” pe cel uscat.', 'Întrebați: „Unde e uscat?”', 'Dacă vrea: el atinge doar obiectul numit.']::text[], 'A auzit apă / ud / uscat pe obiecte.', 'Apă și sete'),
  ('s16-b23-z5-social', 'Apa mea, apa ta', ARRAY['2 pahare cu foarte puțină apă']::text[], ARRAY['Dați-i unul: „Al tău.” Luați-l pe al vostru: „Al meu.”', 'Beți pe rând sau doar atingeți.', 'Dacă vrea: spuneți „Apă” pe fiecare pahar.']::text[], 'Ați împărțit două pahare pe rând.', 'Apă și sete'),
  ('s16-b23-z6-fizic', 'Joacă cu apă — limită vas', ARRAY['vas/bol mic', 'prosop', 'spațiu protejat']::text[], ARRAY['Turnați în vas: „Apă în vas. Ajunge aici.”', 'Fără risipă forțată — vasul e limita.', 'Dacă vrea: comparați vasul și paharul — două locuri cu apă.']::text[], 'A jucat cu apă în limita vasului.', 'Apă și sete'),
  ('s16-b23-z6-mental', 'De ce e ud aici?', ARRAY['zonă udă sigură']::text[], ARRAY['Arătați: „E ud.”', 'Întrebați: „De ce?” — oferiți: „Pentru că am turnat apă.”', 'Dacă vrea: el repetă o parte din motiv.']::text[], 'A legat udul de o cauză simplă.', 'Apă și sete'),
  ('s16-b23-z6-resurse', 'Prosopul și vasul — la loc', ARRAY['prosop', 'vas']::text[], ARRAY['Ștergeți: „Uscat. La loc.”', '„Gata. Ajunge.”', 'Dacă vrea: alegeți ce puneți primul — prosopul sau vasul.']::text[], 'Materialele de apă sunt la loc.', 'Apă și sete'),
  ('s16-b23-z6-social', 'Udați planta împreună', ARRAY['plantă', 'cană']::text[], ARRAY['Țineți cana împreună: „Împreună. Apă.”', 'Turnați puțin: „Gata.”', 'Dacă vrea: el spune „ajunge” când e destul.']::text[], 'Ați udat planta împreună.', 'Apă și sete'),
  ('s16-b23-z7-mental', 'Favoritul: ud sau uscat?', ARRAY['prosop ud', 'prosop uscat']::text[], ARRAY['Întrebați: „Îți place ud sau uscat?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Ud” sau „Uscat” pe favorită — și un „de ce” blând.']::text[], 'A ales sau a privit favorita săptămânii.', 'Apă și sete'),
  ('s16-b23-z7-resurse', 'Totul uscat și la loc înainte de calm', ARRAY['prosop', 'pahar / vas']::text[], ARRAY['Ștergeți: „Uscat. La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: paharul favorit rămâne la vedere (gol).']::text[], 'Totul e uscat și la loc înainte de calm.', 'Apă și sete'),
  ('s16-b23-z7-social', 'Ritual: bună seara, o înghițitură de apă', ARRAY['pahar cu puțină apă']::text[], ARRAY['Șoptiți: „Bună seara.” O înghițitură: „Apă.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Uscat” pe buze șterse, apoi odihnă.']::text[], 'Ați închis săptămâna apei cu ritual blând.', 'Apă și sete'),
  ('s17-b23-z1-fizic', 'Ascultăm afară 2–3 minute', ARRAY['ușă / balcon / curte']::text[], ARRAY['Ieșiți împreună 2–3 minute. Stați pe loc: „Urechi. Ascultăm.”', 'Arătați spre sunet dacă apare: „Uite. Acolo.”', 'Dacă vrea: întrebați blând — „Ce face?” — și așteptați gest sau sunet.']::text[], 'A staționar afară pe scurt și a ascultat.', 'Animale pe care le auzim'),
  ('s17-b23-z1-mental', 'Sunet → animal — unde?', ARRAY['fereastră / ușă / curte']::text[], ARRAY['Când auziți ceva clar: „Sunet. Unde?”', 'Arătați direcția: „Acolo. Uite.”', 'Dacă vrea: „Ce face animalul?” — oferiți un gest simplu (zbor / lătrat).']::text[], 'A legat un sunet de o direcție.', 'Animale pe care le auzim'),
  ('s17-b23-z1-social', 'Arată-mi ce auzi', '{}'::text[], ARRAY['Stați umăr la umăr: „Împreună. Ascultăm.”', 'Când aude ceva: „Arată-mi.” — mulțumiți gestului.', 'Dacă vrea: el arată din nou și voi spuneți „Uite”.']::text[], 'A arătat adultului ceva auzit.', 'Animale pe care le auzim'),
  ('s17-b23-z2-fizic', 'Pași de câine pe scurt', ARRAY['spațiu liber pe jos']::text[], ARRAY['Mergeți în patru labe 5–8 pași dacă vrea: „Câine.”', 'Opriți-vă: „Gata. Stăm.”', 'Dacă vrea: „Ce face câinele?” — lătrat blând sau gest cu mâna.']::text[], 'A încercat pașii de câine sau a privit.', 'Animale pe care le auzim'),
  ('s17-b23-z2-mental', 'Câine — ham-ham', ARRAY['jucărie câine sau imagine']::text[], ARRAY['Arătați: „Câine.”', 'Spuneți blând: „Ham-ham.”', 'Dacă vrea: „Ce face?” — el repetă sunetul sau arată jucăria.']::text[], 'A legat câinele de sunetul ham-ham.', 'Animale pe care le auzim'),
  ('s17-b23-z2-social', 'Arată-i altcuiva câinele', ARRAY['pluș / imagine câine']::text[], ARRAY['Mergeți la o persoană dragă cu obiectul.', 'Modelați: „Uite. Câine.”', 'Dacă vrea: el ține și arată singur.']::text[], 'A împărtășit câinele cu cineva.', 'Animale pe care le auzim'),
  ('s17-b23-z3-fizic', 'Brațe ca aripile — pasăre', ARRAY['spațiu liber']::text[], ARRAY['Ridicați brațele și mișcați ușor: „Pasăre.”', 'Faceți 5–10 „bătăi” de aripi, apoi jos: „Gata.”', 'Dacă vrea: „Ce face pasărea?” — zburați încă o rundă scurtă.']::text[], 'A mișcat brațele ca aripile pe scurt.', 'Animale pe care le auzim'),
  ('s17-b23-z3-mental', 'Pasăre — ciripit', ARRAY['imagine pasăre / pluș / fereastră']::text[], ARRAY['Arătați: „Pasăre.”', 'Ciripiți blând: „Cip-cip.”', 'Dacă vrea: „Ce face?” — el arată cerul / geamul / aripile.']::text[], 'A legat pasărea de ciripit sau zbor.', 'Animale pe care le auzim'),
  ('s17-b23-z3-social', 'Rândul la arătat pasărea', ARRAY['pluș / imagine pasăre']::text[], ARRAY['Voi arătați: „Acum eu. Uite. Pasăre.”', 'Apoi: „Acum tu” — așteptați gestul.', 'Dacă vrea: încă un schimb, apoi la loc.']::text[], 'Ați schimbat rândul la arătat pasărea.', 'Animale pe care le auzim'),
  ('s17-b23-z4-fizic', 'Urechi la geam — privim afară', ARRAY['fereastră']::text[], ARRAY['Stați la geam 30–60 de secunde: „Uite. Privim.”', 'Atingeți urechea: „Ascultăm.”', 'Dacă vrea: „Ce face?” pe ceva văzut sau auzit afară.']::text[], 'A privit și a ascultat la geam pe scurt.', 'Animale pe care le auzim'),
  ('s17-b23-z4-mental', 'Câine sau pasăre — care sunet?', ARRAY['2 jucării / imagini: câine + pasăre']::text[], ARRAY['Faceți ham-ham: „Care? Câine?”', 'Ciripiți: „Care? Pasăre?”', 'Dacă vrea: el alege obiectul după sunet și spune „ce face”.']::text[], 'A legat un sunet de un animal din două.', 'Animale pe care le auzim'),
  ('s17-b23-z4-resurse', 'Două animale — la loc pe rând', ARRAY['pluș câine', 'pluș pasăre', 'raft / cutie']::text[], ARRAY['Puneți întâi unul: „Una. La loc.”', 'Apoi al doilea: „Două. Ajunge.”', 'Dacă vrea: el alege ordinea — câine sau pasăre întâi.']::text[], 'Ambele jucării-animal sunt la loc.', 'Animale pe care le auzim'),
  ('s17-b23-z4-social', 'Eu ascult, tu arăți', '{}'::text[], ARRAY['Voi închideți ochii o clipă: „Eu ascult.”', 'El arată: „Tu — Uite.”', 'Dacă vrea: schimbați rolurile o dată.']::text[], 'Ați împărțit rolurile ascult / arată.', 'Animale pe care le auzim'),
  ('s17-b23-z5-fizic', 'Traseu: urechi → uite → gata', ARRAY['ușă / geam / loc de calm']::text[], ARRAY['La ușă: „Urechi.” La geam: „Uite.” Înapoi: „Gata.”', 'Parcurgeți traseul o dată, fără grabă.', 'Dacă vrea: pe un sunet întrebați „Ce face?”']::text[], 'A parcurs traseul urechi–uite–gata.', 'Animale pe care le auzim'),
  ('s17-b23-z5-mental', 'Pasăre, câine, uite — pe obiecte', ARRAY['pluș pasăre', 'pluș câine', 'fereastră']::text[], ARRAY['Arătați: „Pasăre.” „Câine.”', 'Apoi geamul: „Uite. Privim.”', 'Dacă vrea: el atinge doar obiectul pe care îl numiți.']::text[], 'A auzit pasăre / câine / uite pe obiecte reale.', 'Animale pe care le auzim'),
  ('s17-b23-z5-social', 'Ajutor: adu câinele', ARRAY['pluș câine pe scaun / masă joasă']::text[], ARRAY['Cereți: „Adu câinele, te rog.”', 'Când îl aduce (sau îl atinge): „Mulțumesc! Uite. Câine.”', 'Dacă vrea: el cere vouă același ajutor cu pasărea.']::text[], 'A ajutat sau a fost ajutat cu plușul.', 'Animale pe care le auzim'),
  ('s17-b23-z6-fizic', 'Afară scurt — ascultăm, înapoi', ARRAY['ușă / balcon']::text[], ARRAY['Ieșiți 20–40 de secunde: „Uite. Ascultăm.”', 'Intrați: „În casă. Gata.”', 'Dacă vrea: încă un dus-întors; pe un sunet — „Ce face?”']::text[], 'A ieșit scurt să asculte și s-a întors.', 'Animale pe care le auzim'),
  ('s17-b23-z6-mental', 'Ce animal am auzit?', ARRAY['amintire de afară sau 2 plușuri']::text[], ARRAY['Întrebați blând: „Pasăre? Câine? Altceva?”', 'Oferiți gesturi: aripi / lătrat.', 'Dacă vrea: „Ce face?” pe animalul ales.']::text[], 'A ales sau a arătat un animal auzit.', 'Animale pe care le auzim'),
  ('s17-b23-z6-social', 'Joacă paralel: eu câine, tu pasăre', ARRAY['pluș câine', 'pluș pasăre']::text[], ARRAY['Voi cu câinele; el cu pasărea (sau invers).', 'Comentați: „Eu câine. Tu pasăre.”', 'Dacă vrea: schimbați o dată.']::text[], 'Ați jucat paralel cu două animale.', 'Animale pe care le auzim'),
  ('s17-b23-z7-fizic', 'Mișcare liberă — aripi sau lăbuțe', ARRAY['spațiu liber']::text[], ARRAY['El alege: brațe-aripi (pasăre) sau pași de câine (câine); voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: stați 20 de secunde și spuneți ce alege — „Pasăre” sau „Câine”.']::text[], 'A ales liber tipul de mișcare.', 'Animale pe care le auzim'),
  ('s17-b23-z7-mental', 'Favoritul: pasăre sau câine?', ARRAY['pluș pasăre', 'pluș câine']::text[], ARRAY['Întrebați: „Îți place pasărea sau câinele?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Pasăre” sau „Câine” pe favorită — și „Ce face?”']::text[], 'A ales sau a privit favorita săptămânii.', 'Animale pe care le auzim'),
  ('s17-b23-z7-social', 'Ritual: bună seara, uite la geam', ARRAY['fereastră']::text[], ARRAY['Șoptiți: „Bună seara.” Priviți o clipă: „Uite.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Pasăre” sau „Câine” pe amintire, apoi calm.']::text[], 'Ați închis săptămâna animalelor cu ritual blând.', 'Animale pe care le auzim'),
  ('s18-b23-z1-fizic', 'Mingea pe scurt — aruncat blând', ARRAY['minge ușoară', 'spațiu liber']::text[], ARRAY['Luați mingea: „Minge.”', 'Aruncați blând între voi 2–3 schimburi, fără forțare.', 'Dacă vrea: inventați o regulă scurtă — „Doar pe jos” sau „Doar cu două mâini.”']::text[], 'A atins sau a aruncat mingea pe scurt.', 'Joacă de-a rândul'),
  ('s18-b23-z1-mental', 'Rândul tău — trei schimburi', ARRAY['minge']::text[], ARRAY['Spuneți: „Rândul meu.” — aruncați voi.', 'Apoi: „Rând. Rândul tău.” — așteptați 3 schimburi în total.', 'Dacă vrea: regula — „Trei aruncări, apoi gata.”']::text[], 'A auzit rândul pe trei schimburi cu mingea.', 'Joacă de-a rândul'),
  ('s18-b23-z1-social', 'Trei schimburi sociale cu mingea', ARRAY['minge']::text[], ARRAY['Schimbați mingea de trei ori: „Rând… Rând… Rând.”', 'Mulțumiți la final: „Mulțumesc. Împreună.”', 'Dacă vrea: regula — „Cine ține mingea așteaptă.”']::text[], 'Ați făcut trei schimburi pe rând.', 'Joacă de-a rândul'),
  ('s18-b23-z2-fizic', 'Rostogolim mingea pe jos', ARRAY['minge', 'podea liberă']::text[], ARRAY['Așezați-vă pe jos: „Minge.”', 'Rostogoliți blând unul spre celălalt 2–4 ori.', 'Dacă vrea: regula — „Doar rostogolim, nu aruncăm sus.”']::text[], 'A rostogolit sau a oprit mingea pe jos.', 'Joacă de-a rândul'),
  ('s18-b23-z2-mental', 'Rândul meu / rând — pe minge', ARRAY['minge']::text[], ARRAY['Țineți mingea: „Rândul meu.”', 'Dați-i-o: „Rând. Acum tu.”', 'Dacă vrea: el spune „rând” sau face gestul de rând.']::text[], 'A legat cuvintele de rând de ținerea mingii.', 'Joacă de-a rândul'),
  ('s18-b23-z2-social', 'Rândul la ținut mingea', ARRAY['minge']::text[], ARRAY['Voi țineți: „Rândul meu.”', 'Apoi: „Rând” — așteptați să țină sau să atingă.', 'Dacă vrea: încă un schimb, apoi la loc.']::text[], 'Ați schimbat rândul la ținut mingea.', 'Joacă de-a rândul'),
  ('s18-b23-z3-fizic', 'Pași cu mingea pe braț', ARRAY['minge ușoară', '5–8 pași liberi']::text[], ARRAY['Țineți mingea pe braț și faceți câțiva pași: „Minge. Mergem.”', 'Opriți-vă: „Gata.”', 'Dacă vrea: regula — „Pași mici cu mingea.”']::text[], 'A mers scurt ținând mingea.', 'Joacă de-a rândul'),
  ('s18-b23-z3-mental', 'Cine e la rând?', ARRAY['minge', '2 persoane']::text[], ARRAY['Arătați: „Rândul meu?” pe voi, apoi pe el: „Rând?”', 'Faceți un schimb clar.', 'Dacă vrea: regula inventată — „Bătăi din palme înainte de rând.”']::text[], 'A recunoscut cine ține rândul.', 'Joacă de-a rândul'),
  ('s18-b23-z3-social', 'Eu arunc, tu prinzi — apoi invers', ARRAY['minge ușoară']::text[], ARRAY['Aruncați blând: „Rândul meu.”', 'Apoi: „Rând” — el încearcă; schimbați o dată.', 'Dacă vrea: regula — „Doi pași înapoi înainte.”']::text[], 'Ați împărțit rolurile arunc / prind pe rând.', 'Joacă de-a rândul'),
  ('s18-b23-z4-fizic', 'Mingea între genunchi — stăm', ARRAY['minge']::text[], ARRAY['Stați pe jos cu mingea între genunchi 10–15 secunde: „Minge. Stăm.”', 'Apoi dați-i-o: „Rând.”', 'Dacă vrea: regula — „Numărăm până la trei, apoi rând.”']::text[], 'A ținut mingea pe scurt în poziție calmă.', 'Joacă de-a rândul'),
  ('s18-b23-z4-mental', 'Trei turnuri — numărăm', ARRAY['minge']::text[], ARRAY['Schimbați: „Unu — rând. Doi — rând. Trei — rând.”', '„Gata. Trei.”', 'Dacă vrea: regula — „După trei, mingea la loc.”']::text[], 'A auzit trei rânduri numărate.', 'Joacă de-a rândul'),
  ('s18-b23-z4-social', 'Arată-i altcuiva rândul', ARRAY['minge']::text[], ARRAY['Mergeți la o persoană dragă cu mingea.', 'Modelați: „Rândul meu… Rând — acum tu.”', 'Dacă vrea: regula scurtă spusă și celuilalt — „Trei, apoi gata.”']::text[], 'A împărtășit jocul de rând cu cineva.', 'Joacă de-a rândul'),
  ('s18-b23-z5-fizic', 'Traseu: minge → rând → la loc', ARRAY['minge', 'coș la 4–6 pași']::text[], ARRAY['Țineți mingea, faceți câțiva pași, dați-o pe rând, apoi în coș.', 'Numiți: „Minge. Rând. La loc.”', 'Dacă vrea: regula — „Nu alergăm cu mingea.”']::text[], 'A parcurs traseul minge–rând–la loc.', 'Joacă de-a rândul'),
  ('s18-b23-z5-mental', 'Minge, rând, rândul meu — pe minge', ARRAY['minge']::text[], ARRAY['Arătați mingea: „Minge.”', 'Țineți: „Rândul meu.” Dați: „Rând.”', 'Dacă vrea: el atinge mingea doar când e „rând”.']::text[], 'A auzit minge / rând / rândul meu pe minge reală.', 'Joacă de-a rândul'),
  ('s18-b23-z5-social', 'Ajutor: adu mingea', ARRAY['minge pe scaun / jos']::text[], ARRAY['Cereți: „Adu mingea, te rog.”', 'Când o aduce: „Mulțumesc! Minge.”', 'Dacă vrea: el cere vouă același ajutor — apoi rând.']::text[], 'A ajutat sau a fost ajutat cu mingea.', 'Joacă de-a rândul'),
  ('s18-b23-z6-fizic', 'Joacă liberă scurtă cu mingea', ARRAY['minge', 'spațiu liber']::text[], ARRAY['Jucați liber 30–60 de secunde: „Minge.”', 'Închideți: „Gata. Turnuri gata.”', 'Dacă vrea: o regulă inventată de el (gest sau cuvânt).']::text[], 'A jucat liber scurt cu mingea.', 'Joacă de-a rândul'),
  ('s18-b23-z6-social', 'Joacă paralel: eu cu mingea, tu cu…', ARRAY['minge', 'altă jucărie rotundă / cub']::text[], ARRAY['Voi cu mingea; el cu cealaltă (sau invers).', 'Comentați: „Eu minge. Tu — rândul tău pe a ta.”', 'Dacă vrea: schimbați o dată — rând.']::text[], 'Ați jucat paralel cu două obiecte pe rând.', 'Joacă de-a rândul'),
  ('s18-b23-z7-fizic', 'Mișcare liberă — cu sau fără minge', ARRAY['minge la îndemână']::text[], ARRAY['El alege: cu mingea pe braț sau fără; voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: un singur rând blând, apoi gata.']::text[], 'A ales liber cum ține mingea.', 'Joacă de-a rândul'),
  ('s18-b23-z7-mental', 'Favoritul: mingea sau rândul?', ARRAY['minge']::text[], ARRAY['Întrebați: „Îți place mingea sau să dai pe rând?” — gesturi clare.', 'Stați pe alegerea lui.', 'Dacă vrea: „Minge” sau „Rând” pe favorită.']::text[], 'A ales sau a privit favorita săptămânii.', 'Joacă de-a rândul'),
  ('s18-b23-z7-social', 'Ritual: bună seara, rândul meu blând', ARRAY['minge']::text[], ARRAY['Șoptiți: „Bună seara.” Țineți mingea o clipă: „Rândul meu” — apoi lui: „Rând.”', '„La loc. Noapte bună.”', 'Dacă vrea: un ultim „Minge” pe coș, apoi odihnă.']::text[], 'Ați închis săptămâna rândului cu ritual blând.', 'Joacă de-a rândul'),
  ('s19-b23-z1-fizic', 'Cartea pe genunchi — ritual seară', ARRAY['carte cartonată', 'loc pe canapea / pat']::text[], ARRAY['Așezați-vă: puneți cartea pe genunchi: „Carte.”', 'Stați 30–60 de secunde, fără grabă.', 'Dacă vrea: răsfoiți o pagină — „Ce urmează pe pagină?”']::text[], 'A ținut cartea pe genunchi pe scurt.', 'Cartea de seară'),
  ('s19-b23-z1-mental', 'Întoarcem pagina', ARRAY['carte cu pagini groase']::text[], ARRAY['Arătați: „Pagină.”', 'Întoarceți împreună o pagină: „Uite.”', 'Dacă vrea: „Ce urmează pe pagină?” — așteptați gest sau cuvânt.']::text[], 'A participat la întorsul unei pagini.', 'Cartea de seară'),
  ('s19-b23-z2-fizic', 'Deschide și închide cartea', ARRAY['carte cartonată']::text[], ARRAY['Deschideți: „Carte. Deschis.”', 'Închideți: „Închis. Gata.” — 2–3 runde blânde.', 'Dacă vrea: pe deschis — „Ce urmează pe pagină?”']::text[], 'A deschis sau închis cartea pe scurt.', 'Cartea de seară'),
  ('s19-b23-z2-mental', 'Pagină — unde e poza?', ARRAY['carte cu imagini clare']::text[], ARRAY['Arătați o poză: „Pagină. Uite.”', 'Întoarceți: „Altă pagină.”', 'Dacă vrea: „Ce urmează pe pagină?” — el arată ceva din imagine.']::text[], 'A legat pagina de o imagine.', 'Cartea de seară'),
  ('s19-b23-z2-social', 'Rândul la întors pagina', ARRAY['carte']::text[], ARRAY['Voi întoarceți: „Acum eu. Pagină.”', 'Apoi: „Acum tu” — așteptați gestul.', 'Dacă vrea: „Ce urmează?” pe pagina lui.']::text[], 'Ați schimbat rândul la întors pagina.', 'Cartea de seară'),
  ('s19-b23-z3-fizic', 'Cartea pe genunchi — noapte', ARRAY['carte', 'lumină blândă / lampă']::text[], ARRAY['Stingeți sau reduceți lumina blând: „Noapte. Seară.”', 'Cartea pe genunchi: „Carte.”', 'Dacă vrea: o pagină — „Ce urmează pe pagină?”']::text[], 'A simțit ritualul carte + seară pe genunchi.', 'Cartea de seară'),
  ('s19-b23-z3-mental', 'Previzionăm — ce urmează?', ARRAY['carte cunoscută']::text[], ARRAY['Înainte de a întoarce: „Ce crezi că urmează?”', 'Întoarceți: „Pagină. Uite.”', 'Dacă vrea: încă o previziune pe pagina următoare.']::text[], 'A auzit o previziune înainte de pagină.', 'Cartea de seară'),
  ('s19-b23-z3-social', 'Arată-i altcuiva poza din carte', ARRAY['carte deschisă pe o pagină']::text[], ARRAY['Mergeți la o persoană dragă cu cartea.', 'Modelați: „Pagină. Uite poza.”', 'Dacă vrea: el ține cartea și arată; „Ce urmează?”']::text[], 'A împărtășit o pagină cu cineva.', 'Cartea de seară'),
  ('s19-b23-z4-fizic', 'Pași până la raft — aducem cartea', ARRAY['raft cu cărți', 'loc de citit']::text[], ARRAY['Mergeți la raft: „Carte.”', 'Aduceți o carte pe genunchi / pe locul de citit.', 'Dacă vrea: pe drum — „Noapte? Mergem să citim.”']::text[], 'A adus sau a ajutat să aducă o carte.', 'Cartea de seară'),
  ('s19-b23-z4-mental', 'Carte, pagină, noapte — pe obiecte', ARRAY['carte', 'fereastră / lampă (semn de seară)']::text[], ARRAY['Arătați: „Carte.” Întoarceți: „Pagină.”', 'Gest seară: „Noapte / seară.”', 'Dacă vrea: el atinge doar obiectul pe care îl numiți.']::text[], 'A auzit carte / pagină / noapte pe obiecte reale.', 'Cartea de seară'),
  ('s19-b23-z4-social', 'Eu citesc, tu întorci — apoi invers', ARRAY['carte']::text[], ARRAY['Voi spuneți 1–2 cuvinte pe pagină; el întoarce: „Pagină.”', 'Schimbați o dată: „Acum tu spui, eu întorc.”', 'Dacă vrea: „Ce urmează pe pagină?” înainte de invertire.']::text[], 'Ați împărțit rolurile citit / întors.', 'Cartea de seară'),
  ('s19-b23-z5-fizic', 'Traseu: raft → genunchi → raft', ARRAY['carte', 'raft', 'loc pe genunchi']::text[], ARRAY['Luați cartea, pe genunchi 20–30 de secunde, înapoi pe raft.', 'Numiți: „Carte. Genunchi. La loc.”', 'Dacă vrea: pe genunchi — o pagină și „Ce urmează?”']::text[], 'A parcurs traseul raft–genunchi–raft.', 'Cartea de seară'),
  ('s19-b23-z5-mental', 'Aceeași pagină de două ori', ARRAY['carte']::text[], ARRAY['Arătați o pagină: „Pagină.”', 'Închideți, redeschideți la aceeași: „Tot aici.”', 'Dacă vrea: „Ce urmează pe pagina de după?”']::text[], 'A recunoscut aceeași pagină de două ori.', 'Cartea de seară'),
  ('s19-b23-z5-social', 'Ajutor: adu cartea', ARRAY['carte pe masă / raft jos']::text[], ARRAY['Cereți: „Adu cartea, te rog.”', 'Când o aduce: „Mulțumesc! Carte.”', 'Dacă vrea: el cere vouă același ajutor — apoi o pagină.']::text[], 'A ajutat sau a fost ajutat cu cartea.', 'Cartea de seară'),
  ('s19-b23-z6-fizic', 'Seară scurtă — carte pe genunchi liber', ARRAY['carte', 'loc calm']::text[], ARRAY['Așezați-vă: „Noapte. Carte.”', 'El răsfoiește liber 30–60 de secunde; voi stați aproape.', 'Dacă vrea: pe o pagină — „Ce urmează?”']::text[], 'A ținut cartea pe genunchi în ritm liber.', 'Cartea de seară'),
  ('s19-b23-z6-social', 'Joacă paralel: eu cu o carte, tu cu alta', ARRAY['2 cărți']::text[], ARRAY['Fiecare cu câte o carte pe genunchi.', 'Comentați: „Eu carte. Tu carte.”', 'Dacă vrea: schimbați cărțile o dată — pagină pe fiecare.']::text[], 'Ați citit paralel pe scurt cu două cărți.', 'Cartea de seară'),
  ('s19-b23-z7-fizic', 'Mișcare liberă — carte pe genunchi sau pe braț', ARRAY['carte ușoară']::text[], ARRAY['El alege: carte pe genunchi sau pe braț; voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: un „Noapte” șoptit, apoi liniște.']::text[], 'A ales liber cum ține cartea.', 'Cartea de seară'),
  ('s19-b23-z7-mental', 'Favorita: care carte?', ARRAY['2–3 cărți']::text[], ARRAY['Întrebați: „Care carte îți place?” — arătați-le.', 'Stați pe alegerea lui.', 'Dacă vrea: „Carte” pe favorită, o pagină, apoi „Ce urmează?”']::text[], 'A ales sau a privit cartea favorită.', 'Cartea de seară'),
  ('s19-b23-z7-social', 'Ritual: bună seara, carte, noapte', ARRAY['1 carte']::text[], ARRAY['Șoptiți: „Bună seara. Carte.” O clipă pe genunchi.', '„Noapte bună.” Pe raft: „La loc.”', 'Dacă vrea: un ultim „Pagină” pe copertă, apoi odihnă.']::text[], 'Ați închis săptămâna cărții cu ritual blând.', 'Cartea de seară'),
  ('s20-b23-z1-fizic', 'Trei lucruri cărate la loc', ARRAY['3 obiecte mici pe jos', 'locurile lor']::text[], ARRAY['Arătați trei: „La loc. La loc.”', 'Cărați împreună unul câte unul până la loc.', 'Dacă vrea: pe două — „Al meu / al tău” (al meu / al tău).']::text[], 'A cărat sau a ajutat la trei lucruri la loc.', 'Ordine mică în cameră'),
  ('s20-b23-z1-mental', 'De ce aici? — categorie', ARRAY['2–3 obiecte', '2 locuri (raft / cutie)']::text[], ARRAY['Puneți un obiect: „De ce aici?” — oferiți: „Pentru că e jucărie / haină.”', 'Al doilea la celălalt loc.', 'Dacă vrea: pe două obiecte — „Al meu. Al tău.”']::text[], 'A auzit un motiv simplu pentru un loc.', 'Ordine mică în cameră'),
  ('s20-b23-z1-resurse', 'Al meu — la loc', ARRAY['1 obiect al copilului', 'locul lui']::text[], ARRAY['Arătați: „Al meu. Al meu.”', '„La loc. Ajunge.”', 'Dacă vrea: comparați cu unul al vostru — „Al tău / al tău” pe al vostru greșit corectat blând la „al meu (adult)”.']::text[], 'Obiectul lui e la loc.', 'Ordine mică în cameră'),
  ('s20-b23-z1-social', 'Ajutor la strâns împreună', ARRAY['2–3 obiecte pe jos']::text[], ARRAY['Cereți: „Ajută-mă să strângem.”', 'Mulțumiți: „Mulțumesc. La loc. Împreună.”', 'Dacă vrea: „Acesta al meu, acesta al tău” pe două obiecte.']::text[], 'A ajutat la strâns împreună.', 'Ordine mică în cameră'),
  ('s20-b23-z2-fizic', 'Cărăm cuburile în cutie', ARRAY['3–5 cuburi', 'cutie']::text[], ARRAY['Luați cuburile: „La loc.”', 'Puneți în cutie unul câte unul: „La loc.”', 'Dacă vrea: două cuburi — „Al meu” / „Al tău” pe cine le pune.']::text[], 'A pus cuburi în cutie pe scurt.', 'Ordine mică în cameră'),
  ('s20-b23-z2-mental', 'Unde stau cuburile?', ARRAY['cuburi', 'cutie']::text[], ARRAY['Întrebați: „Unde?” — arătați cutia: „Aici.”', '„De ce aici? Pentru că e cutia cuburilor.”', 'Dacă vrea: „Al meu / al tău” pe două cuburi înainte de cutie.']::text[], 'A legat cuburile de cutia lor.', 'Ordine mică în cameră'),
  ('s20-b23-z2-social', 'Rândul la pus în cutie', ARRAY['cuburi', 'cutie']::text[], ARRAY['Voi puneți unul: „Acum eu.”', 'Apoi: „Acum tu” — așteptați.', 'Dacă vrea: pe două — „Al meu” (al vostru pus) / „Al tău” (al lui).']::text[], 'Ați schimbat rândul la pus în cutie.', 'Ordine mică în cameră'),
  ('s20-b23-z3-fizic', 'Haine mici pe scaun — la loc', ARRAY['1–2 haine mici pe jos', 'scaun / cui']::text[], ARRAY['Luați haina: „La loc.”', 'Pe scaun sau cui: „La loc.”', 'Dacă vrea: „Al meu” pe haina lui, „Al tău” pe una a adultului.']::text[], 'A ajutat haina mică la loc.', 'Ordine mică în cameră'),
  ('s20-b23-z3-mental', 'De ce pe cui / pe scaun?', ARRAY['haină', 'cui sau scaun']::text[], ARRAY['Arătați: „De ce aici?”', 'Oferiți: „Ca să nu fie pe jos. La loc.”', 'Dacă vrea: pe două articole — al meu / al tău.']::text[], 'A auzit de ce haina are un loc.', 'Ordine mică în cameră'),
  ('s20-b23-z3-resurse', 'Alege: pe cui sau pe scaun — unul', ARRAY['1 haină', 'cui', 'scaun']::text[], ARRAY['„Astăzi alegem un loc.” Arătați ambele.', 'El alege; „La loc. Ajunge.”', 'Dacă vrea: „Al meu pe cui, al tău pe scaun” — sau invers, pe două obiecte.']::text[], 'Haina e la locul ales.', 'Ordine mică în cameră'),
  ('s20-b23-z3-social', 'Eu strâng una, tu pe cealaltă', ARRAY['2 obiecte pe jos']::text[], ARRAY['Dați-i unul: „Al tău — al tău la loc.”', 'Luați-l pe al vostru: „Al meu — al meu.”', 'Dacă vrea: schimbați obiectele o dată.']::text[], 'Ați strâns câte unul pe al meu / al tău.', 'Ordine mică în cameră'),
  ('s20-b23-z4-fizic', 'Pași cu un obiect până la loc', ARRAY['1 obiect', 'locul lui la 5–8 pași']::text[], ARRAY['Țineți obiectul și mergeți: „La loc. Mergem la loc.”', 'Puneți: „Gata.”', 'Dacă vrea: încă un obiect — „Al meu” / „Al tău” pe cele două.']::text[], 'A dus un obiect la loc pe jos.', 'Ordine mică în cameră'),
  ('s20-b23-z4-mental', 'Al meu și al tău — pe două obiecte', ARRAY['2 obiecte: unul al copilului, unul al adultului']::text[], ARRAY['Arătați: „Al meu. Al meu.” pe al vostru.', '„Al tău. Al tău.” pe al lui.', 'Dacă vrea: el pune fiecare la locul potrivit și spune de ce.']::text[], 'A legat al meu / al tău de două obiecte reale.', 'Ordine mică în cameră'),
  ('s20-b23-z4-resurse', 'Două obiecte — la loc pe rând', ARRAY['2 obiecte', '2 locuri']::text[], ARRAY['Puneți întâi unul: „Una. La loc.”', 'Apoi al doilea: „Două. Ajunge.”', 'Dacă vrea: el alege ordinea — al meu sau al tău întâi.']::text[], 'Ambele obiecte sunt la loc.', 'Ordine mică în cameră'),
  ('s20-b23-z4-social', 'Arată-i altcuiva: al meu, al tău', ARRAY['2 obiecte']::text[], ARRAY['Mergeți la o persoană dragă cu cele două.', 'Modelați: „Al meu. Al tău.”', 'Dacă vrea: el arată singur care e al lui.']::text[], 'A împărtășit al meu / al tău cu cineva.', 'Ordine mică în cameră'),
  ('s20-b23-z5-fizic', 'Traseu: jos → la loc → la loc', ARRAY['3 obiecte pe jos', 'locurile lor']::text[], ARRAY['Parcurgeți: ridicați, spuneți „La loc”, puneți la loc — de trei ori.', '„Gata. Cameră mai liberă.”', 'Dacă vrea: pe ultimele două — al meu / al tău.']::text[], 'A parcurs traseul jos–la loc–la loc pe trei obiecte.', 'Ordine mică în cameră'),
  ('s20-b23-z5-mental', 'La loc, al meu, al tău — pe obiecte', ARRAY['2 obiecte', '1 cutie / raft']::text[], ARRAY['Gest strâns: „La loc.”', 'Pe obiecte: „Al meu. Al tău.”', 'Dacă vrea: el atinge doar obiectul pe care îl numiți.']::text[], 'A auzit la loc / al meu / al tău pe obiecte reale.', 'Ordine mică în cameră'),
  ('s20-b23-z5-social', 'Ajutor: adu al tău la loc', ARRAY['1 obiect al copilului pe jos']::text[], ARRAY['Cereți: „Adu al tău, te rog. Al tău.”', 'Când îl aduce: „Mulțumesc! La loc.”', 'Dacă vrea: el cere vouă — „Adu al tău (al meu).”']::text[], 'A ajutat sau a fost ajutat cu obiectul lui.', 'Ordine mică în cameră'),
  ('s20-b23-z6-fizic', 'Strâns liber scurt în cameră', ARRAY['câteva obiecte pe jos']::text[], ARRAY['El alege 1–3 obiecte de cărat: „La loc.”', 'Voi urmați ritmul lui, fără listă lungă.', 'Dacă vrea: pe două — al meu / al tău.']::text[], 'A strâns liber pe scurt în cameră.', 'Ordine mică în cameră'),
  ('s20-b23-z6-mental', 'De ce am pus aici?', ARRAY['1 obiect tocmai pus la loc']::text[], ARRAY['Arătați locul: „Am pus aici.”', '„De ce?” — oferiți un motiv simplu.', 'Dacă vrea: comparați cu un al doilea — al meu / al tău.']::text[], 'A legat un obiect de un motiv de loc.', 'Ordine mică în cameră'),
  ('s20-b23-z6-social', 'Joacă paralel: eu strâng, tu strângi', ARRAY['2 zone mici / 2 obiecte']::text[], ARRAY['Voi într-un colț; el în altul.', 'Comentați: „Eu la loc — al meu. Tu la loc — al tău.”', 'Dacă vrea: schimbați zonele o dată.']::text[], 'Ați strâns paralel pe scurt.', 'Ordine mică în cameră'),
  ('s20-b23-z7-fizic', 'Mișcare liberă — un obiect la loc sau pe braț', ARRAY['1 obiect la îndemână']::text[], ARRAY['El alege: obiectul la loc sau pe braț o clipă; voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: spuneți „La loc” doar dacă el alege la loc.']::text[], 'A ales liber ce face cu obiectul.', 'Ordine mică în cameră'),
  ('s20-b23-z7-mental', 'Favoritul: care obiect la loc?', ARRAY['2 obiecte']::text[], ARRAY['Întrebați: „Care îl pui tu la loc?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Al meu / al tău” pe cele două, apoi la loc pe ales.']::text[], 'A ales sau a privit obiectul favorit de strâns.', 'Ordine mică în cameră'),
  ('s20-b23-z7-resurse', 'Camera gata — înainte de calm', ARRAY['ultimele 1–2 obiecte']::text[], ARRAY['Strângeți: „La loc. La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: obiectul favorit rămâne la vedere pe raft.']::text[], 'Camera e gata înainte de calm.', 'Ordine mică în cameră'),
  ('s20-b23-z7-social', 'Ritual: bună seara, la loc blând', ARRAY['1 obiect']::text[], ARRAY['Șoptiți: „Bună seara.” Puneți blând: „La loc. La loc.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Al meu” / „Al tău” pe două obiecte, apoi odihnă.']::text[], 'Ați închis săptămâna ordinii cu ritual blând.', 'Ordine mică în cameră'),
  ('s21-b23-z1-fizic', 'Privim la geam + întindere scurtă', ARRAY['fereastră / pervaz']::text[], ARRAY['Mergeți la geam. Stați pe loc: „Geam.”', 'Brațele sus 3–5 secunde, apoi jos: „Sus… jos. Ne întindem.”', 'Dacă vrea: comparați blând cu ieri — „Ieri tot rece? Sau altfel?”']::text[], 'A privit la geam și s-a întins pe scurt.', 'Iarna pe pervaz'),
  ('s21-b23-z1-mental', 'Două detalii de vreme', ARRAY['fereastră']::text[], ARRAY['Priviți afară: „Ce vezi? Unu…” — numiți un detaliu.', '„Doi…” — al doilea (rece / ploaie / nori / soare).', 'Dacă vrea: „Ieri era la fel?” — așteptați gest sau cuvânt.']::text[], 'A numit sau auziți două detalii de vreme.', 'Iarna pe pervaz'),
  ('s21-b23-z1-resurse', 'Înăuntru e cald — alegem unde stăm', ARRAY['2 locuri: lângă geam / mai înăuntru']::text[], ARRAY['Arătați geamul: „Afară — rece.”', 'Arătați camera: „Înăuntru — cald. Alegem unul.”', 'Dacă vrea: comparați cu unde ați stat ieri (dacă își amintește).']::text[], 'A ales un loc cald sau a privit alegerea.', 'Iarna pe pervaz'),
  ('s21-b23-z1-social', 'Descrie vremea adultului', ARRAY['fereastră']::text[], ARRAY['Stați umăr la umăr la geam: „Geam.”', 'Modelați: „Rece.” — apoi: „Spune-i mamei / tatei.”', 'Dacă vrea: el arată ieri / azi cu gest (același / altfel).']::text[], 'A împărtășit ceva despre vreme cu adultul.', 'Iarna pe pervaz'),
  ('s21-b23-z2-fizic', 'Mâna pe geam — rece pe scurt', ARRAY['fereastră curată']::text[], ARRAY['Atingeți sticla pe scurt: „Geam. Rece.”', 'Luați mâna: „Gata. Cald în palmă.”', 'Dacă vrea: „Ieri tot rece pe geam?” — gest da / nu.']::text[], 'A atins geamul rece sau a privit.', 'Iarna pe pervaz'),
  ('s21-b23-z2-mental', 'Rece — ce e rece?', ARRAY['geam / pervaz']::text[], ARRAY['Arătați geamul: „Rece.”', 'Arătați mâna sau un obiect cald din casă: „Nu rece. Cald.”', 'Dacă vrea: comparație cu ieri — același rece sau altul.']::text[], 'A legat rece de ceva rece din casă.', 'Iarna pe pervaz'),
  ('s21-b23-z2-social', 'Arată-i altcuiva geam', ARRAY['fereastră']::text[], ARRAY['Mergeți cu el la geam lângă o persoană dragă.', 'Modelați: „Geam. Rece. Geam.”', 'Dacă vrea: el arată singur și spune rece / ploaie.']::text[], 'A arătat geamul cuiva din casă.', 'Iarna pe pervaz'),
  ('s21-b23-z3-fizic', 'Ploaie pe geam — degetul urmărește', ARRAY['fereastră (ploaie sau imagine / sunet de ploaie)']::text[], ARRAY['Dacă plouă (sau mimați): „Ploaie.” Degetul pe sticlă.', 'Câteva linii blânde, apoi oprire: „Gata.”', 'Dacă vrea: „Ieri a plouat?” — gest sau cuvânt.']::text[], 'A urmărit ploaie pe geam sau a mimat.', 'Iarna pe pervaz'),
  ('s21-b23-z3-mental', 'Ploaie sau rece — care e azi?', ARRAY['fereastră']::text[], ARRAY['Întrebați: „Azi ploaie?” — arătați afară.', '„Azi rece?” — gest pe brațe.', 'Dacă vrea: „Ieri care era?” — așteptați alegerea.']::text[], 'A ales sau auziți ploaie / rece pentru azi.', 'Iarna pe pervaz'),
  ('s21-b23-z3-social', 'Rândul la arătat ploaie', ARRAY['fereastră']::text[], ARRAY['Voi arătați: „Acum eu. Ploaie.”', 'Apoi: „Acum tu” — așteptați gestul spre geam.', 'Dacă vrea: încă un schimb, apoi comparați cu ieri.']::text[], 'Ați schimbat rândul la arătat ploaia / geamul.', 'Iarna pe pervaz'),
  ('s21-b23-z4-fizic', 'Întindere la geam — brațe și genunchi', ARRAY['spațiu lângă geam']::text[], ARRAY['La geam: brațele sus — „Geam.” — apoi genunchi ușor îndoiți.', '2–3 repetări: „Sus… jos.”', 'Dacă vrea: „Ieri am făcut la fel?” — da / nu cu capul.']::text[], 'A făcut întindere scurtă lângă geam.', 'Iarna pe pervaz'),
  ('s21-b23-z4-mental', 'Rece, ploaie, geam — pe obiecte', ARRAY['fereastră', 'opțional: imagine ploaie']::text[], ARRAY['Arătați geamul: „Geam.”', '„Rece.” pe sticlă; „Ploaie” dacă e / pe imagine.', 'Dacă vrea: el alege un cuvânt și îl spune pe geam.']::text[], 'A legat cele trei cuvinte de geam / vreme.', 'Iarna pe pervaz'),
  ('s21-b23-z4-social', 'Eu spun rece, tu arăți geam', ARRAY['fereastră']::text[], ARRAY['Voi: „Rece.” El arată geamul: „Geam.”', 'Schimbați o dată: el spune / voi arătați.', 'Dacă vrea: adăugați ploaie dacă e vizibil.']::text[], 'Ați legat cuvântul de arătat împreună.', 'Iarna pe pervaz'),
  ('s21-b23-z5-fizic', 'Traseu: cameră → geam → întindere → gata', ARRAY['cale scurtă până la geam']::text[], ARRAY['Din cameră: „Mergem la geam.”', 'La geam întindere scurtă, apoi: „Gata. Înapoi.”', 'Dacă vrea: comparați traseul cu ieri (dacă ați făcut).']::text[], 'A făcut traseul scurt până la geam.', 'Iarna pe pervaz'),
  ('s21-b23-z5-mental', 'Ce e diferit azi la geam?', ARRAY['fereastră']::text[], ARRAY['Priviți: „Azi… rece? Ploaie?”', 'Numiți un detaliu nou sau același.', 'Dacă vrea: „Ieri era X. Azi?” — așteptați gest.']::text[], 'A observat un detaliu de vreme azi.', 'Iarna pe pervaz'),
  ('s21-b23-z5-social', 'Ajutor: vino la geam', ARRAY['fereastră']::text[], ARRAY['Cereți: „Vino la geam, te rog.”', 'Mulțumiți când vine: „Mulțumesc. Rece.”', 'Dacă vrea: el vă cheamă pe voi la geam.']::text[], 'A venit la geam la cerere sau a chemat.', 'Iarna pe pervaz'),
  ('s21-b23-z6-fizic', 'Privit liber scurt la geam', ARRAY['fereastră']::text[], ARRAY['Stați liber 30–60 de secunde: „Geam.”', 'Fără instrucțiuni multe — doar prezență.', 'Dacă vrea: un rece sau ploaie șoptit, apoi gata.']::text[], 'A privit liber la geam pe scurt.', 'Iarna pe pervaz'),
  ('s21-b23-z6-mental', 'Ce am văzut la geam?', ARRAY['fereastră']::text[], ARRAY['Întoarceți-vă din geam: „Am văzut…” — numiți 1 lucru.', '„Rece? Ploaie?” — așteptați.', 'Dacă vrea: „Ieri am văzut altceva?”']::text[], 'A legat privitul de un cuvânt / detaliu.', 'Iarna pe pervaz'),
  ('s21-b23-z6-social', 'Joacă paralel: eu la un geam, tu la altul', ARRAY['1–2 ferestre / un geam împărțit']::text[], ARRAY['Fiecare privește o clipă din locul lui.', 'Comentați: „Eu — geam. Tu — geam.”', 'Dacă vrea: schimbați locurile o dată.']::text[], 'Ați privit paralel pe scurt.', 'Iarna pe pervaz'),
  ('s21-b23-z7-fizic', 'Mișcare liberă — geam sau întindere', ARRAY['spațiu liber / geam']::text[], ARRAY['El alege: la geam (geam) sau întindere pe loc; voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: spuneți cuvântul ales — „Geam” sau „Rece”.']::text[], 'A ales liber tipul de mișcare / loc.', 'Iarna pe pervaz'),
  ('s21-b23-z7-mental', 'Favoritul: rece, ploaie sau geam?', ARRAY['fereastră']::text[], ARRAY['Întrebați: „Îți place rece, ploaie sau geam?” — gesturi clare.', 'Stați pe alegerea lui.', 'Dacă vrea: „Ieri tot ăsta?” — un da / nu blând.']::text[], 'A ales sau a privit favoritul de vreme / geam.', 'Iarna pe pervaz'),
  ('s21-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['perdea / obiecte de pe pervaz']::text[], ARRAY['Strângeți: „La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: o ultimă privire geam, apoi închideți.']::text[], 'Pervazul e gata înainte de calm.', 'Iarna pe pervaz'),
  ('s21-b23-z7-social', 'Ritual: bună seara, geam blând', ARRAY['fereastră']::text[], ARRAY['Șoptiți: „Bună seara.” O privire: „Geam.”', '„Noapte bună. Rece afară — cald aici.”', 'Dacă vrea: un ultim ploaie / rece pe amintire, apoi odihnă.']::text[], 'Ați închis săptămâna pervazului cu ritual blând.', 'Iarna pe pervaz'),
  ('s22-b23-z1-fizic', 'Sărituri mici sau pași pe loc', ARRAY['spațiu liber pe jos']::text[], ARRAY['Arătați: „Sărim. Săritură.” — 2–4 sărituri mici (sau pe loc).', '„Oprim. Stăm.”', 'Dacă vrea: el alege — încă sărim sau oprim acum.']::text[], 'A sărit pe scurt sau a privit, apoi oprim.', 'Corp care se mișcă în casă'),
  ('s22-b23-z1-mental', 'Secvență: sărim → oprim', ARRAY['spațiu liber']::text[], ARRAY['Spuneți: „Întâi sărim. Apoi oprim.”', 'Faceți împreună o dată.', 'Dacă vrea: el alege ordinea — oprim întâi sau sărim întâi.']::text[], 'A urmat sau auziți secvența de 2 mișcări.', 'Corp care se mișcă în casă'),
  ('s22-b23-z1-social', 'Mișcare împreună — o rundă', ARRAY['spațiu liber']::text[], ARRAY['„Împreună. Sărim.” — apoi „Oprim.”', 'O singură rundă scurtă.', 'Dacă vrea: el alege următoarea mișcare din rundă.']::text[], 'Ați făcut o rundă de mișcare împreună.', 'Corp care se mișcă în casă'),
  ('s22-b23-z2-fizic', 'Alergăm pe scurt în casă — apoi oprim', ARRAY['coridor / cameră liberă']::text[], ARRAY['Pași repezi pe scurt: „Alergăm.” — 5–8 pași.', '„Oprim.” — înghețați pe loc.', 'Dacă vrea: el alege unde e oprim-ul (prag / covor).']::text[], 'A alergat pe scurt și s-a oprit.', 'Corp care se mișcă în casă'),
  ('s22-b23-z2-mental', 'Alergăm sau sărim — care?', '{}'::text[], ARRAY['Arătați: „Alergăm?” — pași repezi pe loc.', '„Sărim?” — săritură mică.', 'Dacă vrea: el alege secvența — alergăm apoi sărim, sau invers.']::text[], 'A ales sau auziți alergăm / sărim.', 'Corp care se mișcă în casă'),
  ('s22-b23-z2-resurse', 'După alergăm — paharul la loc', ARRAY['pahar', 'masă / chiuvetă']::text[], ARRAY['După pauza de apă: „La loc.”', '„Ajunge. Gata.”', 'Dacă vrea: el alege raftul sau masa.']::text[], 'Paharul e la loc după mișcare.', 'Corp care se mișcă în casă'),
  ('s22-b23-z2-social', 'Eu alerg, tu stai — apoi invers', ARRAY['spațiu liber']::text[], ARRAY['Voi: „Alergăm” pe loc; el: „Oprim.”', 'Schimbați: el alergăm, voi oprim.', 'Dacă vrea: el inventează ordinea rundei.']::text[], 'Ați schimbat rolurile alergăm / oprim.', 'Corp care se mișcă în casă'),
  ('s22-b23-z3-fizic', 'Târâit sau mers pe genunchi — traseu scurt', ARRAY['covor / spațiu pe jos']::text[], ARRAY['Traseu de 4–6 „pași” pe genunchi sau târâit: „Mergem.”', 'La final: „Oprim.”', 'Dacă vrea: el alege traseul — spre ușă sau spre canapea.']::text[], 'A făcut traseul pe jos pe scurt.', 'Corp care se mișcă în casă'),
  ('s22-b23-z3-mental', 'Secvență de 3: alergăm → sărim → oprim', ARRAY['spațiu liber']::text[], ARRAY['Spuneți: „Unu — alergăm. Doi — sărim. Trei — oprim.”', 'Faceți o dată împreună, lent.', 'Dacă vrea: el alege o altă ordine a celor trei.']::text[], 'A auzit / făcut o secvență de 3 mișcări.', 'Corp care se mișcă în casă'),
  ('s22-b23-z3-social', 'Rândul la sărim', ARRAY['spațiu liber']::text[], ARRAY['Voi: „Acum eu. Sărim.”', '„Acum tu.” — așteptați săritura sau gestul.', 'Dacă vrea: încă un schimb, apoi oprim împreună.']::text[], 'Ați schimbat rândul la săritură.', 'Corp care se mișcă în casă'),
  ('s22-b23-z4-fizic', 'Dans scurt — oprim când spunem', ARRAY['spațiu liber', 'opțional: muzică blândă adult']::text[], ARRAY['Mișcare liberă 15–20 de secunde: „Dans.”', '„Oprim.” — înghețați, zâmbiți.', 'Dacă vrea: el spune oprim când vrea el.']::text[], 'A dansat pe scurt și s-a oprit la oprim.', 'Corp care se mișcă în casă'),
  ('s22-b23-z4-mental', 'Sărim, alergăm, oprim — pe corp', '{}'::text[], ARRAY['Arătați pe corp: „Sărim” (genunchi), „Alergăm” (picioare), „Oprim” (palmă).', 'El repetă gestul sau cuvântul.', 'Dacă vrea: el alege secvența de gesturi.']::text[], 'A legat cele trei cuvinte de gesturi pe corp.', 'Corp care se mișcă în casă'),
  ('s22-b23-z4-social', 'Arată-i altcuiva sărim', '{}'::text[], ARRAY['Mergeți la o persoană dragă.', 'Modelați: „Sărim!” — o săritură mică.', 'Dacă vrea: el alege să arate alergăm sau oprim în loc.']::text[], 'A împărtășit o mișcare cu cineva.', 'Corp care se mișcă în casă'),
  ('s22-b23-z5-fizic', 'Traseu: alergăm → sărim → oprim → apă', ARRAY['cale scurtă în casă', 'pahar']::text[], ARRAY['„Alergăm” până la reper, „Sărim” o dată, „Oprim.”', 'Apoi: „Apă. Gata.”', 'Dacă vrea: el alege ordinea reperelor pe traseu.']::text[], 'A făcut traseul de mișcare până la apă.', 'Corp care se mișcă în casă'),
  ('s22-b23-z5-mental', 'Ce mișcare urmează?', '{}'::text[], ARRAY['Faceți sărim: „Ce urmează?” — oferiți oprim sau alergăm.', 'Așteptați alegerea lui.', 'Dacă vrea: el inventează toată secvența de 2–3.']::text[], 'A ales următoarea mișcare din secvență.', 'Corp care se mișcă în casă'),
  ('s22-b23-z5-resurse', 'Ajunge — o rundă de mișcare', ARRAY['spațiu liber']::text[], ARRAY['„Una. O rundă.” — sărim / alergăm / oprim scurt.', '„Ajunge. Gata.” — pauză apă.', 'Dacă vrea: el alege dacă mai e o rundă mică.']::text[], 'Runda e închisă cu ajunge.', 'Corp care se mișcă în casă'),
  ('s22-b23-z5-social', 'Ajutor: vino să facem oprim', '{}'::text[], ARRAY['Cereți: „Vino, facem oprim împreună.”', 'Înghețați amândoi: „Oprim. Bravo.”', 'Dacă vrea: el vă cheamă pe voi la sărim.']::text[], 'A venit la mișcarea comună.', 'Corp care se mișcă în casă'),
  ('s22-b23-z6-fizic', 'Mișcare liberă scurtă în casă', ARRAY['spațiu liber']::text[], ARRAY['30–60 de secunde liber: sărim / alergăm / târâit — ce vrea.', 'Voi: „Oprim” blând la final.', 'Dacă vrea: el alege când oprim.']::text[], 'A mișcat liber pe scurt în casă.', 'Corp care se mișcă în casă'),
  ('s22-b23-z6-mental', 'Ce mișcare am făcut?', '{}'::text[], ARRAY['Amintiți: „Am făcut sărim? Alergăm?”', 'El arată sau spune.', 'Dacă vrea: ordonează 2 mișcări — care întâi.']::text[], 'A denumit o mișcare din joacă.', 'Corp care se mișcă în casă'),
  ('s22-b23-z6-social', 'Joacă paralel: eu sărim, tu alergi', ARRAY['spațiu liber']::text[], ARRAY['Voi săriți pe loc; el aleargă pe loc (sau invers).', 'Comentați: „Eu sărim. Tu alergi.”', 'Dacă vrea: oprim împreună, apoi schimbați.']::text[], 'Ați mișcat paralel pe scurt.', 'Corp care se mișcă în casă'),
  ('s22-b23-z7-fizic', 'Mișcare liberă — sărim, alergăm sau oprim', ARRAY['spațiu liber']::text[], ARRAY['El alege: sărim, alergăm pe loc sau doar oprim-stat; voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: el alege o secvență scurtă de 2.']::text[], 'A ales liber tipul de mișcare.', 'Corp care se mișcă în casă'),
  ('s22-b23-z7-mental', 'Favoritul: sărim, alergăm sau oprim?', '{}'::text[], ARRAY['Întrebați: „Îți place sărim, alergăm sau oprim?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: faceți o dată doar favoritul lui.']::text[], 'A ales sau a privit mișcarea favorită.', 'Corp care se mișcă în casă'),
  ('s22-b23-z7-social', 'Ritual: bună seara, oprim blând', '{}'::text[], ARRAY['Șoptiți: „Bună seara.” O clipă pe loc: „Oprim.”', '„Noapte bună.”', 'Dacă vrea: un ultim sărim mic pe pernă, apoi odihnă.']::text[], 'Ați închis săptămâna mișcării cu ritual blând.', 'Corp care se mișcă în casă'),
  ('s23-b23-z1-fizic', 'Două mirosuri sigure în casă', ARRAY['săpun', 'pâine / ceai răcit / fruct']::text[], ARRAY['Apropiați nasul de primul: „Miros.” — săpun / pâine.', 'Al doilea la fel, pe scurt.', 'Dacă vrea: numiți cele două — „Săpun și pâine.”']::text[], 'A mirosit două lucruri sigure pe scurt.', 'Mirosuri din casă'),
  ('s23-b23-z1-mental', 'Care e care? — săpun sau pâine', ARRAY['săpun', 'pâine']::text[], ARRAY['Mirosiți unul cu ochii închiși blând: „Care? Săpun?”', 'Apoi celălalt: „Pâine?”', 'Dacă vrea: el numește ambele mirosuri cu gest sau cuvânt.']::text[], 'A deosebit două mirosuri.', 'Mirosuri din casă'),
  ('s23-b23-z1-resurse', 'Săpunul / pâinea la loc', ARRAY['săpun', 'pâine', 'raft / coș / masă']::text[], ARRAY['După miros: „La loc.” — întâi unul.', 'Apoi al doilea: „Ajunge.”', 'Dacă vrea: alegeți ordinea — săpun sau pâine întâi.']::text[], 'Obiectele de miros sunt la loc.', 'Mirosuri din casă'),
  ('s23-b23-z1-social', 'Împărtășește mirosul', ARRAY['1 obiect cu miros sigur']::text[], ARRAY['Țineți obiectul: „Miros. Hai împreună.”', 'El miroase; voi: „Mmm. Săpun / pâine.”', 'Dacă vrea: numiți al doilea miros pe care l-ați avut azi.']::text[], 'A împărtășit un miros cu adultul.', 'Mirosuri din casă'),
  ('s23-b23-z2-fizic', 'Nas aproape de săpun pe scurt', ARRAY['săpun (neascuțit / blând)']::text[], ARRAY['Apropiați: „Săpun. Miros.”', '10–15 secunde, apoi: „Gata.”', 'Dacă vrea: numiți săpun și încă un miros din casă.']::text[], 'A mirosit săpunul pe scurt.', 'Mirosuri din casă'),
  ('s23-b23-z2-mental', 'Săpun — cum miroase?', ARRAY['săpun']::text[], ARRAY['„Săpun. Miros.” — oferiți un cuvânt: „Curat / blând.”', 'El repetă săpun sau arată.', 'Dacă vrea: comparați cu pâine — „Alt miros.”']::text[], 'A legat săpun de miros.', 'Mirosuri din casă'),
  ('s23-b23-z2-social', 'Arată-i altcuiva săpun', ARRAY['săpun']::text[], ARRAY['Mergeți la o persoană dragă cu săpunul.', 'Modelați: „Miros. Săpun.”', 'Dacă vrea: el ține și spune săpun / miros.']::text[], 'A împărtășit mirosul de săpun.', 'Mirosuri din casă'),
  ('s23-b23-z3-fizic', 'Nas aproape de pâine pe scurt', ARRAY['pâine / cozonac rece / toast rece']::text[], ARRAY['Apropiați: „Pâine. Miros.”', '10–15 secunde, fără a forța gustul.', 'Dacă vrea: numiți pâine și săpun — două mirosuri.']::text[], 'A mirosit pâinea pe scurt.', 'Mirosuri din casă'),
  ('s23-b23-z3-mental', 'Pâine — miros de casă', ARRAY['pâine']::text[], ARRAY['„Pâine. Miros.”', '„E ca acasă.” — gest spre masă / bucătărie.', 'Dacă vrea: el numește pâine și încă un miros.']::text[], 'A legat pâine de mirosul din casă.', 'Mirosuri din casă'),
  ('s23-b23-z3-social', 'Rândul la mirosit pâine', ARRAY['pâine']::text[], ARRAY['Voi: „Acum eu. Miros. Pâine.”', '„Acum tu.” — așteptați.', 'Dacă vrea: numiți și săpun ca al doilea miros al zilei.']::text[], 'Ați schimbat rândul la mirosit pâinea.', 'Mirosuri din casă'),
  ('s23-b23-z4-fizic', 'Traseu mirosuri: săpun → pâine', ARRAY['săpun la chiuvetă', 'pâine la masă']::text[], ARRAY['La chiuvetă: „Săpun. Miros.”', 'La masă: „Pâine. Miros.” — apoi „Gata.”', 'Dacă vrea: el numește cele două pe drum înapoi.']::text[], 'A făcut traseul scurt între două mirosuri.', 'Mirosuri din casă'),
  ('s23-b23-z4-mental', 'Miros, săpun, pâine — pe obiecte', ARRAY['săpun', 'pâine']::text[], ARRAY['Arătați: „Miros” (nas). „Săpun.” „Pâine.”', 'El potrivește obiectul la cuvânt.', 'Dacă vrea: spune ambele mirosuri fără să privească.']::text[], 'A legat cele trei cuvinte de obiecte.', 'Mirosuri din casă'),
  ('s23-b23-z4-resurse', 'Două obiecte — la loc pe rând', ARRAY['săpun', 'pâine']::text[], ARRAY['„Una. Săpun la loc.”', '„Două. Pâine la loc. Ajunge.”', 'Dacă vrea: el alege care e primul.']::text[], 'Ambele sunt la loc.', 'Mirosuri din casă'),
  ('s23-b23-z4-social', 'Eu miros săpun, tu pâine — apoi invers', ARRAY['săpun', 'pâine']::text[], ARRAY['Voi cu săpun; el cu pâine (sau invers).', '„Miros.” pe rând.', 'Dacă vrea: fiecare numește mirosul celuilalt.']::text[], 'Ați împărțit cele două mirosuri pe roluri.', 'Mirosuri din casă'),
  ('s23-b23-z5-fizic', 'Miros scurt la ceai / fruct — al treilea sigur', ARRAY['ceai răcit / fruct spălat', 'opțional săpun sau pâine']::text[], ARRAY['Un miros nou blând: „Miros.”', 'Comparați cu săpun sau pâine pe scurt.', 'Dacă vrea: numiți două din cele mirosite azi.']::text[], 'A mirosit un al treilea lucru sigur pe scurt.', 'Mirosuri din casă'),
  ('s23-b23-z5-mental', 'Care miros e săpun?', ARRAY['săpun', 'pâine sau alt obiect']::text[], ARRAY['Apropiați ambele (sau pe rând): „Care e săpun?”', 'El arată.', 'Dacă vrea: „Și care e pâine?” — numește ambele.']::text[], 'A identificat săpun dintre mirosuri.', 'Mirosuri din casă'),
  ('s23-b23-z5-resurse', 'Ajunge — un miros, apoi la loc', ARRAY['1 obiect cu miros']::text[], ARRAY['„Una. Miros.” — scurt.', '„La loc. Ajunge.”', 'Dacă vrea: alegeți săpun sau pâine pentru „una”.']::text[], 'Un singur miros, apoi obiectul la loc.', 'Mirosuri din casă'),
  ('s23-b23-z5-social', 'Ajutor: adu săpun / pâine', ARRAY['săpun sau pâine la vedere']::text[], ARRAY['Cereți: „Adu săpun, te rog.” (sau pâine).', 'Mulțumiți: „Miros împreună.”', 'Dacă vrea: el cere obiectul celălalt.']::text[], 'A adus obiectul de miros la cerere.', 'Mirosuri din casă'),
  ('s23-b23-z6-fizic', 'Miros liber scurt — ce alege el', ARRAY['2–3 obiecte sigure cu miros']::text[], ARRAY['El alege un obiect: „Miros.”', '10–20 de secunde, fără listă lungă.', 'Dacă vrea: numiți două mirosuri din cele de pe masă.']::text[], 'A ales și a mirosit liber pe scurt.', 'Mirosuri din casă'),
  ('s23-b23-z6-mental', 'Ce am mirosit?', '{}'::text[], ARRAY['„Am mirosit săpun? Pâine?”', 'El arată sau spune.', 'Dacă vrea: spune ambele pe care le ține minte.']::text[], 'A denumit cel puțin un miros din joacă.', 'Mirosuri din casă'),
  ('s23-b23-z6-social', 'Joacă paralel: eu săpun, tu pâine', ARRAY['săpun', 'pâine']::text[], ARRAY['Fiecare cu obiectul lui: „Miros.”', 'Comentați blând fără a lua obiectul celuilalt.', 'Dacă vrea: schimbați obiectele o dată.']::text[], 'Ați mirosit paralel pe scurt.', 'Mirosuri din casă'),
  ('s23-b23-z7-fizic', 'Mișcare liberă — un miros la final', ARRAY['1 obiect cu miros', 'spațiu liber']::text[], ARRAY['El alege mișcare liberă scurtă; la final un miros blând.', 'Fără forțare.', 'Dacă vrea: alege săpun sau pâine pentru final.']::text[], 'A mișcat liber și a închis cu un miros.', 'Mirosuri din casă'),
  ('s23-b23-z7-mental', 'Favoritul: săpun sau pâine?', ARRAY['săpun', 'pâine']::text[], ARRAY['Întrebați: „Îți place săpun sau pâine?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: numiți ambele, apoi stați pe favorit.']::text[], 'A ales sau a privit mirosul favorit.', 'Mirosuri din casă'),
  ('s23-b23-z7-resurse', 'Mirosurile la loc înainte de calm', ARRAY['săpun / pâine']::text[], ARRAY['Strângeți: „La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un ultim miros pe favorit, apoi la loc.']::text[], 'Mirosurile sunt la loc înainte de calm.', 'Mirosuri din casă'),
  ('s23-b23-z7-social', 'Ritual: bună seara, miros blând', ARRAY['opțional: săpun departe / aer curat']::text[], ARRAY['Șoptiți: „Bună seara.” O inspirare: „Miros.”', '„Noapte bună.”', 'Dacă vrea: șoptiți săpun sau pâine pe amintire, apoi odihnă.']::text[], 'Ați închis săptămâna mirosurilor cu ritual blând.', 'Mirosuri din casă'),
  ('s24-b23-z1-fizic', 'Pregătim spațiul — un obiect', ARRAY['1 pernă / scaun / jucărie']::text[], ARRAY['Alegeți un obiect: „Pentru oaspete / prieten.”', 'Cărați-l împreună la locul pregătit.', 'Dacă vrea: o întrebare blândă — „Vrei să pui tu perna?” — poate refuza.']::text[], 'A cărat un obiect pentru spațiul de oaspete.', 'Familia și oaspeții'),
  ('s24-b23-z1-mental', 'Salut + un cuvânt blând', '{}'::text[], ARRAY['Modelați: „Bună.” — undă cu mâna.', 'Adăugați un cuvânt: „Prieten” sau „Bun venit.”', 'Dacă vrea: „Vrei să spui bună?” — poate refuza, fără presiune.']::text[], 'A auzit / încercat salutul blând.', 'Familia și oaspeții'),
  ('s24-b23-z1-resurse', 'Loc pentru oaspete — scaunul', ARRAY['scaun / pernă']::text[], ARRAY['Arătați: „Aici stă oaspetele / prieten.”', '„Ajunge. Locul e gata.”', 'Dacă vrea: alegeți scaunul sau perna (1 din 2).']::text[], 'Locul pentru oaspete e marcat.', 'Familia și oaspeții'),
  ('s24-b23-z1-social', 'Bună fără forțare', '{}'::text[], ARRAY['Voi spuneți: „Bună.” — undă.', 'El poate undă, spune sau doar privi — tot e bine.', 'Dacă vrea: o întrebare — „Vrei bună sau doar mâna?” — poate refuza.']::text[], 'Ați practicat salutul fără forțare.', 'Familia și oaspeții'),
  ('s24-b23-z2-fizic', 'Mână ridicată — bună pe scurt', '{}'::text[], ARRAY['Ridicați mâna: „Bună.” — 2–3 unde.', 'Jos: „Gata.”', 'Dacă vrea: „Vrei încă un bună?” — poate refuza.']::text[], 'A unduit sau a privit salutul.', 'Familia și oaspeții'),
  ('s24-b23-z2-mental', 'Bună — ce înseamnă?', '{}'::text[], ARRAY['„Bună înseamnă bună.” — undă.', '„La revedere înseamnă la revedere.” — undă de plecare.', 'Dacă vrea: el alege pe care îl arată acum.']::text[], 'A legat bună / la revedere de gest.', 'Familia și oaspeții'),
  ('s24-b23-z2-resurse', 'Jucăria de salut pe raft', ARRAY['o jucărie „oaspete”', 'raft']::text[], ARRAY['După joacă: „Prieten la loc.”', '„Ajunge. Gata.”', 'Dacă vrea: alegeți raftul sau scaunul pentru jucărie.']::text[], 'Jucăria-oaspete e la loc.', 'Familia și oaspeții'),
  ('s24-b23-z2-social', 'Spunem bună adultului din casă', '{}'::text[], ARRAY['Mergeți la o persoană dragă.', 'Modelați: „Bună!” — undă.', 'Dacă vrea: „Vrei să spui tu?” — poate refuza.']::text[], 'A împărtășit un bună în casă.', 'Familia și oaspeții'),
  ('s24-b23-z3-fizic', 'Așezăm scaunul pentru prieten', ARRAY['scaun ușor / pernă']::text[], ARRAY['Mutați împreună scaunul: „Pentru prieten.”', '„Aici.” — arătați locul.', 'Dacă vrea: „Vrei tu să împingi?” — poate refuza.']::text[], 'A mutat scaunul / perna pe scurt.', 'Familia și oaspeții'),
  ('s24-b23-z3-mental', 'Prieten — cine e?', ARRAY['jucărie sau poză persoană dragă']::text[], ARRAY['Arătați: „Prieten / familie.”', 'Numiți pe cineva drag din casă.', 'Dacă vrea: „Cine e prieten-ul tău?” — poate refuza dacă nu răspunde.']::text[], 'A legat prieten de o persoană / jucărie.', 'Familia și oaspeții'),
  ('s24-b23-z3-resurse', 'Scaunul rămâne locul oaspetelui — gata', ARRAY['scaun']::text[], ARRAY['„Locul e gata. Ajunge.”', 'Nu mai mutați: „Gata.”', 'Dacă vrea: alegeți dacă prieten stă pe scaun sau pe pernă.']::text[], 'Locul oaspetelui e stabilit.', 'Familia și oaspeții'),
  ('s24-b23-z3-social', 'Rândul la bună', '{}'::text[], ARRAY['Voi: „Acum eu. Bună.”', '„Acum tu” — așteptați undă sau cuvânt.', 'Dacă vrea: „Vrei încă un rând?” — poate refuza.']::text[], 'Ați schimbat rândul la salut.', 'Familia și oaspeții'),
  ('s24-b23-z4-fizic', 'La revedere cu mâna — pași spre ușă pe scurt', ARRAY['ușă / prag']::text[], ARRAY['La ușă: „La revedere.” — undă.', '2–3 pași înapoi în casă: „Rămânem.”', 'Dacă vrea: „Vrei la revedere încă o dată?” — poate refuza.']::text[], 'A practicat la revedere la ușă pe scurt.', 'Familia și oaspeții'),
  ('s24-b23-z4-mental', 'Bună, prieten, la revedere — pe gesturi', '{}'::text[], ARRAY['„Bună” — undă venire. „Prieten” — arătați pe cineva / jucăria.', '„La revedere” — undă plecare.', 'Dacă vrea: el alege un gest de arătat.']::text[], 'A legat cele trei cuvinte de gesturi.', 'Familia și oaspeții'),
  ('s24-b23-z4-resurse', 'După la revedere — jucăria prieten la loc', ARRAY['jucărie oaspete', 'raft']::text[], ARRAY['„La revedere, prieten. La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți raftul sau patul jucăriei.']::text[], 'Jucăria prieten e la loc după la revedere.', 'Familia și oaspeții'),
  ('s24-b23-z4-social', 'Eu bună, tu la revedere — apoi invers', '{}'::text[], ARRAY['Voi: „Bună.” El: „La revedere” (sau undă).', 'Schimbați o dată.', 'Dacă vrea: o întrebare — „Care îți place?” — poate refuza.']::text[], 'Ați schimbat rolurile bună / la revedere.', 'Familia și oaspeții'),
  ('s24-b23-z5-fizic', 'Traseu: pregătim → bună → scaun → la revedere', ARRAY['1 obiect', 'scaun']::text[], ARRAY['Cărați obiectul, spuneți bună, arătați scaunul, apoi la revedere.', 'Traseu scurt, o dată.', 'Dacă vrea: el alege unde e bună pe traseu.']::text[], 'A făcut traseul de oaspete pe scurt.', 'Familia și oaspeții'),
  ('s24-b23-z5-mental', 'Cine vine? — prieten', ARRAY['jucărie / poză']::text[], ARRAY['„Vine prieten.” — arătați.', '„Bună, prieten.”', 'Dacă vrea: „Cum îl cheamă?” — poate refuza dacă nu spune.']::text[], 'A legat venirea de prieten / bună.', 'Familia și oaspeții'),
  ('s24-b23-z5-social', 'Ajutor: adu scaunul / perna', ARRAY['scaun ușor / pernă']::text[], ARRAY['Cereți: „Adu perna pentru prieten, te rog.”', 'Mulțumiți: „Bună pe locul ăsta.”', 'Dacă vrea: el cere ajutorul vostru — poate refuza pe roluri.']::text[], 'A ajutat la pregătirea locului.', 'Familia și oaspeții'),
  ('s24-b23-z6-fizic', 'Joacă liberă — bună / la revedere pe scurt', ARRAY['jucărie oaspete opțional']::text[], ARRAY['30–60 de secunde: undă bună sau la revedere când vrea.', 'Voi urmăriți, fără a corecta.', 'Dacă vrea: o întrebare blândă la final — poate refuza.']::text[], 'A jucat liber salutul pe scurt.', 'Familia și oaspeții'),
  ('s24-b23-z6-mental', 'Ce am spus oaspetelui?', '{}'::text[], ARRAY['„Am spus bună? La revedere?”', 'El arată gestul.', 'Dacă vrea: „Și prieten?” — arătați jucăria / persoana.']::text[], 'A denumit un salut din joacă.', 'Familia și oaspeții'),
  ('s24-b23-z6-resurse', 'Scaunul / jucăria la loc după joacă', ARRAY['scaun sau jucărie']::text[], ARRAY['„La loc.” după joaca de oaspeți.', '„Ajunge. Gata.”', 'Dacă vrea: prieten rămâne pe scaun până seara (apoi la loc).']::text[], 'Spațiul e strâns după joacă.', 'Familia și oaspeții'),
  ('s24-b23-z6-social', 'Joacă paralel: eu bună, tu cu prieten', ARRAY['jucărie']::text[], ARRAY['Voi unduiți bună; el ține prieten (sau invers).', 'Fără a lua obiectul celuilalt.', 'Dacă vrea: schimbați, apoi la revedere împreună.']::text[], 'Ați jucat paralel pe tema oaspeților.', 'Familia și oaspeții'),
  ('s24-b23-z7-fizic', 'Mișcare liberă — bună sau la revedere la final', ARRAY['spațiu liber']::text[], ARRAY['El alege mișcare liberă; la final undă bună sau la revedere.', 'Fără forțare.', 'Dacă vrea: „Vrei bună sau la revedere?” — poate refuza pe ambele.']::text[], 'A mișcat liber și a închis cu un salut.', 'Familia și oaspeții'),
  ('s24-b23-z7-mental', 'Favoritul: bună, prieten sau la revedere?', '{}'::text[], ARRAY['Întrebați: „Îți place bună, prieten sau la revedere?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: o singură rundă doar pe favorit — poate refuza.']::text[], 'A ales sau a privit salutul / cuvântul favorit.', 'Familia și oaspeții'),
  ('s24-b23-z7-resurse', 'Locul oaspetelui strâns înainte de calm', ARRAY['scaun / jucărie / pernă']::text[], ARRAY['„La loc. La revedere, prieten.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un ultim bună șoptit, apoi totul la loc.']::text[], 'Spațiul e gata înainte de calm.', 'Familia și oaspeții'),
  ('s24-b23-z7-social', 'Ritual: bună seara, la revedere blând', '{}'::text[], ARRAY['Șoptiți: „Bună seara. La revedere.” — undă mică.', '„Noapte bună, prieten.”', 'Dacă vrea: un bună de noapte bună, apoi odihnă — poate refuza.']::text[], 'Ați închis săptămâna familiei / oaspeților cu ritual blând.', 'Familia și oaspeții'),
  ('s25-b23-z1-fizic', 'Mutăm corpul: lumină și umbră de seară', ARRAY['lampă / lumină de seară', 'spațiu cu umbră']::text[], ARRAY['Stați în lumină: „Lumină.”', 'Mutați-vă în umbră: „Umbră.” O dată dus-întors.', 'Dacă vrea: mutați un obiect din lumină în umbră.']::text[], 'A mutat corpul lumină↔umbră pe scurt.', 'Lumină de seară'),
  ('s25-b23-z1-mental', 'Ce s-a schimbat seara?', ARRAY['lampă', 'perete']::text[], ARRAY['Arătați mâna în lumină, apoi în umbră: „Ce s-a schimbat?”', 'Spuneți: „Aici e lumină. Aici e întuneric.”', 'Dacă vrea: el mută o jucărie lumină↔umbră.']::text[], 'A observat o schimbare lumină / umbră.', 'Lumină de seară'),
  ('s25-b23-z1-resurse', 'Stinge și aprinde — gata', ARRAY['lampă (adultul controlează)']::text[], ARRAY['Adultul stinge blând: „Întuneric.”', 'Aprinde: „Lumină. Gata.” O dată e destul.', 'Dacă vrea: el cere „iar” sau „gata” — voi respectați.']::text[], 'Lampa e stinsă / aprinsă o dată; jocul e închis.', 'Lumină de seară'),
  ('s25-b23-z1-social', 'Arătăm umbra celuilalt', ARRAY['lampă', 'perete']::text[], ARRAY['Stați astfel încât umbra să se vadă: „Umbră. Uite umbra mea.”', 'Ajutați-l să-și vadă umbra: „Uite umbra ta.”', 'Dacă vrea: mutați un obiect pe umbra lui.']::text[], 'A văzut sau a arătat umbra cu adultul.', 'Lumină de seară'),
  ('s25-b23-z2-fizic', 'Pași din umbră în lumină', ARRAY['spațiu cu lampă / lumină de seară']::text[], ARRAY['Din umbră: „Mergem în lumină.” — 3–5 pași.', 'Înapoi în umbră: „Întuneric.” O rundă.', 'Dacă vrea: el mută o jucărie pe același traseu.']::text[], 'A făcut pașii lumină↔umbră.', 'Lumină de seară'),
  ('s25-b23-z2-mental', 'Lumină sau întuneric — care e acum?', ARRAY['lampă']::text[], ARRAY['Arătați camera: „Acum lumină?”', 'Stingeți o clipă (adult): „Întuneric?” — apoi lumină din nou.', 'Dacă vrea: el alege unde stă obiectul — lumină sau întuneric.']::text[], 'A legat lumină / întuneric de starea camerei.', 'Lumină de seară'),
  ('s25-b23-z2-resurse', 'Lampa — gata, nu mai stingem', ARRAY['lampă']::text[], ARRAY['După joc: „Ajunge. Lumină rămâne așa.”', '„Gata.” — nu mai schimbați.', 'Dacă vrea: alegeți lampă mică sau mare (1 din 2).']::text[], 'Lampa e lăsată; gata e clar.', 'Lumină de seară'),
  ('s25-b23-z2-social', 'Rândul la arătat umbră', ARRAY['lampă', 'perete']::text[], ARRAY['Voi: „Acum eu. Umbră.” — arătați umbra.', '„Acum tu” — așteptați gestul spre umbră.', 'Dacă vrea: mutați un obiect pe rând în lumină / umbră.']::text[], 'Ați schimbat rândul la arătat umbra.', 'Lumină de seară'),
  ('s25-b23-z3-fizic', 'Dans scurt în lumină, apoi umbră', ARRAY['lampă', 'spațiu liber']::text[], ARRAY['În lumină: 5–8 secunde mișcare blândă: „Lumină.”', 'Treceți în umbră: „Umbră. Încet.”', 'Dacă vrea: mutați o eșarfă / jucărie lumină↔umbră.']::text[], 'A dansat pe scurt în lumină și umbră.', 'Lumină de seară'),
  ('s25-b23-z3-mental', 'Umbra mâinii pe perete', ARRAY['lampă', 'perete']::text[], ARRAY['Mâna între lampă și perete: „Umbră.”', 'Mișcați degetele: „Ce s-a schimbat?”', 'Dacă vrea: el pune un obiect lângă mână — umbra se schimbă.']::text[], 'A văzut umbra mâinii pe perete.', 'Lumină de seară'),
  ('s25-b23-z3-resurse', 'Perdeaua — alegem deschis sau tras', ARRAY['perdea / draperie']::text[], ARRAY['Arătați 2: „Deschis — lumină. Tras — întuneric.”', 'Alegeți una: „Ajunge așa.”', 'Dacă vrea: mutați un obiect lângă perdea lumină↔umbră.']::text[], 'Perdeaua e aleasă; gata.', 'Lumină de seară'),
  ('s25-b23-z3-social', 'Umbra ta pe al meu — joc blând', ARRAY['lampă']::text[], ARRAY['Stați astfel încât umbra lui să cadă pe voi: „Umbră.”', 'Schimbați: umbra voastră pe el — o clipă.', 'Dacă vrea: un obiect trece lumină↔umbră pe rând.']::text[], 'Ați jucat umbra unul pe celălalt pe scurt.', 'Lumină de seară'),
  ('s25-b23-z4-fizic', 'Traseu: lumină → umbră → lumină', ARRAY['spațiu cu lumină și umbră']::text[], ARRAY['„Lumină… umbră… lumină.” — pași scurți pe traseu.', 'O dată e destul: „Gata.”', 'Dacă vrea: el duce un obiect pe același traseu.']::text[], 'A mers pe traseul lumină–umbră–lumină.', 'Lumină de seară'),
  ('s25-b23-z4-mental', 'Obiect în lumină, obiect în umbră', ARRAY['2 jucării mici', 'lampă']::text[], ARRAY['Puneți una în lumină: „Lumină.”', 'Cealaltă în umbră: „Umbră.”', 'Dacă vrea: el schimbă locurile obiectelor.']::text[], 'A legat două obiecte de lumină / umbră.', 'Lumină de seară'),
  ('s25-b23-z4-resurse', 'Stins — ajunge pentru azi', ARRAY['lampă']::text[], ARRAY['„Întuneric. Stins.” — adultul stinge o dată.', '„Ajunge. Gata pentru seară.”', 'Dacă vrea: alegeți stins total sau lumină mic (1 din 2).']::text[], 'Lumina e reglată; gata e clar.', 'Lumină de seară'),
  ('s25-b23-z4-social', 'Arată umbra unei persoane dragi', ARRAY['lampă', 'persoană dragă (sau foto)']::text[], ARRAY['Arătați umbra adultului: „Umbră. Mama / tata.”', 'El arată sau atinge umbra blând.', 'Dacă vrea: mutați o jucărie pe umbra acelei persoane.']::text[], 'A arătat umbra cuiva drag.', 'Lumină de seară'),
  ('s25-b23-z5-fizic', 'Sărituri mici în lumină, pași lenți în umbră', ARRAY['spațiu cu lumină și umbră']::text[], ARRAY['În lumină: 2–3 sărituri mici: „Lumină.”', 'În umbră: pași lenți: „Umbră.”', 'Dacă vrea: o minge / eșarfă trece lumină↔umbră.']::text[], 'A sărit în lumină și a mers lent în umbră.', 'Lumină de seară'),
  ('s25-b23-z5-mental', 'Unde e mai întuneric?', ARRAY['cameră cu lampă']::text[], ARRAY['Arătați un colț: „Aici întuneric?”', 'Arătați lângă lampă: „Aici lumină.”', 'Dacă vrea: el mută un obiect în locul mai întuneric.']::text[], 'A arătat unde e mai întuneric.', 'Lumină de seară'),
  ('s25-b23-z5-resurse', 'Alege: lumină sau umbră — unde stăm', ARRAY['2 locuri: lângă lampă / în umbră']::text[], ARRAY['„Unde stăm? Lumină sau umbră?” — arătați 2.', 'Stați pe alegerea lui: „Ajunge.”', 'Dacă vrea: mutați perna / jucăria în locul ales.']::text[], 'A ales un loc din două.', 'Lumină de seară'),
  ('s25-b23-z5-social', 'Umbra mea, umbra ta', ARRAY['lampă', 'perete']::text[], ARRAY['„Eu — umbră.” Apoi: „Tu — umbră.”', 'Stați umăr la umăr: umbrele se ating o clipă.', 'Dacă vrea: un obiect trece pe ambele umbre.']::text[], 'Ați comparat umbrele pe scurt.', 'Lumină de seară'),
  ('s25-b23-z6-fizic', 'Lumină la fereastră, umbră în cameră', ARRAY['fereastră de seară', 'cameră']::text[], ARRAY['Lângă geam (dacă e lumină): „Lumină.”', 'Mai înăuntru: „Întuneric / umbră.” Pași scurți.', 'Dacă vrea: mutați o jucărie geam↔cameră.']::text[], 'A simțit lumină la geam și umbră în cameră.', 'Lumină de seară'),
  ('s25-b23-z6-mental', 'Trei cuvinte: lumină, întuneric, umbră', ARRAY['lampă', 'perete']::text[], ARRAY['Arătați: „Lumină.” pe lampă; „Întuneric.” pe colț; „Umbră.” pe perete.', 'Repetați o dată, calm.', 'Dacă vrea: el mută un obiect și spune unde e.']::text[], 'A auzit cele trei cuvinte pe obiecte reale.', 'Lumină de seară'),
  ('s25-b23-z6-resurse', 'Lampa și perdeaua — la loc / gata', ARRAY['lampă', 'perdea']::text[], ARRAY['După joc: „La loc.” — perdeaua / comutatorul cum vreți.', '„Ajunge. Gata.”', 'Dacă vrea: alegeți lumină mic sau întuneric pentru calm.']::text[], 'Spațiul e așezat; gata.', 'Lumină de seară'),
  ('s25-b23-z6-social', 'Joacă paralel: eu în lumină, tu în umbră', ARRAY['lampă']::text[], ARRAY['Voi în lumină: „Eu — lumină.” El în umbră: „Tu — umbră.”', 'Schimbați o dată, fără grabă.', 'Dacă vrea: fiecare mută un obiect în zona lui.']::text[], 'Ați jucat paralel lumină / umbră.', 'Lumină de seară'),
  ('s25-b23-z7-fizic', 'Mișcare liberă — lumină sau umbră', ARRAY['spațiu cu lumină de seară']::text[], ARRAY['El alege zona; voi urmăriți blând.', 'Fără grabă, fără test.', 'Dacă vrea: stați 20 de secunde în zona favorită; mutați un obiect acolo.']::text[], 'A mișcat liber în lumină sau umbră pe scurt.', 'Lumină de seară'),
  ('s25-b23-z7-mental', 'Favoritul: lumină sau umbră?', ARRAY['lampă']::text[], ARRAY['Întrebați: „Îți place lumină sau umbră?” — arătați ambele.', 'Stați un moment pe alegerea lui.', 'Dacă vrea: mutați jucăria favorită în zona aleasă.']::text[], 'A ales lumină sau umbră (gest e destul).', 'Lumină de seară'),
  ('s25-b23-z7-social', 'Ritual: bună seara, umbră blândă', ARRAY['lampă', 'perete']::text[], ARRAY['Șoptiți: „Bună seara.” Arătați o umbră mică: „Umbră.”', '„Noapte bună. Întuneric — odihnă.”', 'Dacă vrea: un obiect mic lângă lampă, apoi lumină mic.']::text[], 'Ați închis seara cu ritual blând.', 'Lumină de seară'),
  ('s26-b23-z1-fizic', 'Reluăm jocul fizic favorita', ARRAY['spațiu liber']::text[], ARRAY['Alegeți un joc pe care l-a iubit (sărituri / plimbare / geam): „Favorita.”', 'Faceți o rundă scurtă: „Din nou.”', 'Dacă vrea: ordonați 2 favorita — întâi… apoi…']::text[], 'A reluat un joc fizic favorit pe scurt.', 'Jumătate de an: favoritele'),
  ('s26-b23-z1-mental', 'Alege favorita — de ce?', ARRAY['2–3 amintiri / gesturi de jocuri']::text[], ARRAY['Arătați 2–3: „Care e favorita?”', '„De ce?” — așteptați gest sau 1 cuvânt.', 'Dacă vrea: ordonați 2 — asta întâi, asta apoi.']::text[], 'A ales o favorită (gest e destul).', 'Jumătate de an: favoritele'),
  ('s26-b23-z1-resurse', 'Alege 1 din 3 favorita', ARRAY['3 obiecte / zone din jocuri iubite']::text[], ARRAY['Arătați trei: „Una. Favorita.”', 'El alege una: „Gata. Ajunge.”', 'Dacă vrea: puneți cele 3 în ordine — 1, 2, 3.']::text[], 'A ales una din trei favorita.', 'Jumătate de an: favoritele'),
  ('s26-b23-z1-social', 'Joacă favorita cu adultul', ARRAY['jocul ales']::text[], ARRAY['„Favorita împreună.” — o rundă scurtă.', '„Gata.” — oprire blândă.', 'Dacă vrea: din nou o dată, apoi gata.']::text[], 'A jucat favorita cu adultul pe scurt.', 'Jumătate de an: favoritele'),
  ('s26-b23-z2-fizic', 'Din nou — aceeași mișcare de două ori', ARRAY['spațiu liber']::text[], ARRAY['O mișcare pe care o știe: „Una.”', '„Din nou.” — a doua oară, la fel.', 'Dacă vrea: alegeți a doua mișcare favorita și ordonați-le.']::text[], 'A repetat mișcarea cu din nou.', 'Jumătate de an: favoritele'),
  ('s26-b23-z2-mental', 'Favorita de la geam sau din casă?', ARRAY['geam', 'cameră']::text[], ARRAY['Arătați geamul și camera: „Care e favorita?”', 'Stați pe alegerea lui o clipă.', 'Dacă vrea: ordonați — întâi geam, apoi casă (sau invers).']::text[], 'A ales între geam și casă.', 'Jumătate de an: favoritele'),
  ('s26-b23-z2-resurse', 'Jucăria favorita — la loc după', ARRAY['1 jucărie favorită']::text[], ARRAY['Joacă scurtă: „Favorita.”', '„Gata. La loc.”', 'Dacă vrea: alegeți între 2 jucării favorita unde stau.']::text[], 'Jucăria favorită e la loc.', 'Jumătate de an: favoritele'),
  ('s26-b23-z2-social', 'Arată-i altcuiva favorita', ARRAY['persoană dragă', 'joc / obiect']::text[], ARRAY['Mergeți la cineva drag: „Favorita. Uite.”', 'El arată sau joacă o clipă.', 'Dacă vrea: din nou pe scurt, apoi gata.']::text[], 'A arătat favorita cuiva din casă.', 'Jumătate de an: favoritele'),
  ('s26-b23-z3-fizic', 'Traseu scurt al favoritelor', ARRAY['2 locuri din jocuri iubite']::text[], ARRAY['„Întâi aici… apoi acolo.” — traseu scurt.', '„Gata.” la final.', 'Dacă vrea: el ordonează cele 2 locuri — care primul.']::text[], 'A mers pe traseul a două favorita.', 'Jumătate de an: favoritele'),
  ('s26-b23-z3-mental', 'Trei favorita — care e unu?', ARRAY['3 gesturi / obiecte']::text[], ARRAY['Arătați trei: „Favorita… favorita… favorita.”', '„Care e unu?” — așteptați alegerea.', 'Dacă vrea: puneți 1–2–3 în ordine cu el.']::text[], 'A ales prima dintre trei favorita.', 'Jumătate de an: favoritele'),
  ('s26-b23-z3-resurse', 'Ajunge — o favorită azi', ARRAY['2–3 opțiuni']::text[], ARRAY['„Azi una. Favorita.” — alegeți împreună.', '„Gata. Ajunge.”', 'Dacă vrea: ordonați restul pentru mâine (gest).']::text[], 'O singură favorită e aleasă pentru azi.', 'Jumătate de an: favoritele'),
  ('s26-b23-z3-social', 'Rândul la favorita', ARRAY['joc scurt']::text[], ARRAY['„Acum eu — favorita.” O rundă.', '„Acum tu.” — așteptați.', 'Dacă vrea: din nou pe rând, apoi gata.']::text[], 'Ați schimbat rândul la jocul favorit.', 'Jumătate de an: favoritele'),
  ('s26-b23-z4-fizic', 'Corp favorit: sărit / întins / pe loc', ARRAY['spațiu liber']::text[], ARRAY['El alege: sărituri, întindere sau pe loc: „Favorita.”', 'O rundă: „Gata.”', 'Dacă vrea: din nou + a doua alegere, în ordine.']::text[], 'A făcut mișcarea corporală aleasă.', 'Jumătate de an: favoritele'),
  ('s26-b23-z4-mental', 'De ce e favorita? — 1 frază / gest', ARRAY['obiectul / jocul ales']::text[], ARRAY['Țineți alegerea: „De ce e favorita?”', 'Modelați o frază scurtă sau acceptați gestul.', 'Dacă vrea: comparați cu a doua favorită — care întâi.']::text[], 'A motivat (gest/cuvânt) favorita.', 'Jumătate de an: favoritele'),
  ('s26-b23-z4-resurse', 'Trei pe masă — alege una', ARRAY['3 obiecte favorita pe masă / jos']::text[], ARRAY['„Trei. Alege favorita.”', 'Celelalte: „La loc. Gata.”', 'Dacă vrea: ordonați cele 3 înainte de a alege.']::text[], 'A ales una; restul la loc.', 'Jumătate de an: favoritele'),
  ('s26-b23-z4-social', 'Eu gata, tu din nou', ARRAY['joc scurt']::text[], ARRAY['Voi: „Gata.” — opriți.', 'El: „Din nou?” — dacă vrea, o rundă; dacă nu, gata.', 'Dacă vrea: el spune gata primul.']::text[], 'Ați folosit gata / din nou împreună.', 'Jumătate de an: favoritele'),
  ('s26-b23-z5-fizic', 'Din nou pe traseul cunoscut', ARRAY['traseu scurt în casă (2–3 puncte)']::text[], ARRAY['Faceți traseul o dată: „Una.”', '„Din nou.” — a doua oară.', 'Dacă vrea: el schimbă ordinea punctelor.']::text[], 'A repetat traseul cu din nou.', 'Jumătate de an: favoritele'),
  ('s26-b23-z5-mental', 'Favorita de iarnă: geam, corp, miros?', ARRAY['3 amintiri: geam / mișcare / miros']::text[], ARRAY['Arătați trei amintiri din săptămânile trecute.', '„Care e favorita?”', 'Dacă vrea: ordonați 2–3 favorita din iarnă.']::text[], 'A ales o amintire favorită de iarnă.', 'Jumătate de an: favoritele'),
  ('s26-b23-z5-resurse', 'Gata — totul la loc după favorita', ARRAY['obiectele din joc']::text[], ARRAY['După joc: „Gata. La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți ce rămâne la vedere (1 din 2).']::text[], 'După favorita, lucrurile sunt la loc.', 'Jumătate de an: favoritele'),
  ('s26-b23-z5-social', 'Împreună: favorita, apoi gata', ARRAY['joc ales']::text[], ARRAY['„Favorita împreună.” — scurt.', 'Împreună: „Gata.”', 'Dacă vrea: din nou o dată dacă amândoi vreți.']::text[], 'Ați închis favorita cu gata împreună.', 'Jumătate de an: favoritele'),
  ('s26-b23-z6-fizic', 'Mișcare liberă — ce e favorita azi', ARRAY['spațiu liber']::text[], ARRAY['El alege mișcarea: „Favorita.”', 'Voi urmăriți blând: „Gata” când se oprește.', 'Dacă vrea: din nou sau treceți la a doua favorită.']::text[], 'A mișcat liber pe alegerea lui.', 'Jumătate de an: favoritele'),
  ('s26-b23-z6-mental', 'Ce am iubit jumătate de an?', ARRAY['spațiu calm']::text[], ARRAY['„Jumătate de an. Favorita…” — numiți 1–2 amintiri.', 'El adaugă gest sau cuvânt.', 'Dacă vrea: ordonați 2–3 pe degete.']::text[], 'Ați numit cel puțin o favorită din an.', 'Jumătate de an: favoritele'),
  ('s26-b23-z6-resurse', 'Alege 1 din 3 — apoi gata', ARRAY['3 zone / obiecte']::text[], ARRAY['„Una din trei. Favorita.”', '„Gata. Ajunge pentru azi.”', 'Dacă vrea: celelalte două în ordine pe loc.']::text[], 'A ales una din trei; gata.', 'Jumătate de an: favoritele'),
  ('s26-b23-z6-social', 'Arătăm favoritele adultului', ARRAY['1–2 obiecte / gesturi']::text[], ARRAY['„Favorita. Uite.” — arătați împreună.', 'Adultul mulțumește blând: „Frumos.”', 'Dacă vrea: din nou pe scurt, apoi gata.']::text[], 'A împărtășit favoritele cu adultul.', 'Jumătate de an: favoritele'),
  ('s26-b23-z7-fizic', 'Mișcare liberă — favorita blândă', ARRAY['spațiu liber']::text[], ARRAY['El alege; voi urmăriți blând.', 'Fără grabă: „Favorita… gata.”', 'Dacă vrea: din nou o dată foarte scurt.']::text[], 'A mișcat liber pe favorita zilei.', 'Jumătate de an: favoritele'),
  ('s26-b23-z7-mental', 'Favoritul săptămânii — din nou sau gata?', ARRAY['amintirea săptămânii']::text[], ARRAY['„Azi favorita e…” — arătați alegerea lui.', '„Din nou sau gata?” — respectați.', 'Dacă vrea: ordonați 2 favorita ale săptămânii.']::text[], 'A închis mental săptămâna pe o favorită.', 'Jumătate de an: favoritele'),
  ('s26-b23-z7-resurse', 'Totul la loc — gata înainte de calm', ARRAY['jucării folosite']::text[], ARRAY['„Gata. La loc.”', '„Acum e liniște.”', 'Dacă vrea: un obiect favorita rămâne la vedere.']::text[], 'Lucrurile sunt la loc; calm.', 'Jumătate de an: favoritele'),
  ('s26-b23-z7-social', 'Ritual: bună seara, favorita blândă', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara. Favorita…” — un gest scurt.', '„Gata. Noapte bună.”', 'Dacă vrea: din nou pe un salut mic, apoi odihnă.']::text[], 'Ați închis seara cu ritual de favorita.', 'Jumătate de an: favoritele'),
  ('s27-b23-z1-fizic', 'Privim la geam + întindere scurtă', ARRAY['fereastră / pervaz']::text[], ARRAY['Mergeți la geam. Stați pe loc: „Geam.”', 'Brațele sus 3–5 secunde, apoi jos: „Sus… jos.”', 'Dacă vrea: comparați blând cu ieri — „Ieri tot rece? Sau ploaie?”']::text[], 'A privit la geam și s-a întins pe scurt.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z1-mental', 'Zăpadă sau ploaie — două detalii', ARRAY['fereastră']::text[], ARRAY['Priviți afară: „Ce vezi? Unu…” — zăpadă / ploaie / nori.', '„Doi…” — rece sau alt detaliu.', 'Dacă vrea: „Ieri era la fel?” — gest sau cuvânt.']::text[], 'A numit sau auziți două detalii de vreme.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z1-resurse', 'Înăuntru e cald — alegem unde stăm', ARRAY['2 locuri: lângă geam / mai înăuntru']::text[], ARRAY['Arătați geamul: „Afară — rece.”', 'Arătați camera: „Înăuntru — cald. Alegem unul.”', 'Dacă vrea: comparați cu unde ați stat ieri.']::text[], 'A ales un loc cald sau a privit alegerea.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z1-social', 'Descrie vremea adultului', ARRAY['fereastră']::text[], ARRAY['Stați umăr la umăr: „Geam.”', 'Modelați: „Rece.” sau „Ploaie.” — „Spune-i mamei / tatei.”', 'Dacă vrea: el arată ieri / azi cu gest.']::text[], 'A împărtășit ceva despre vreme cu adultul.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z2-fizic', 'Mâna pe geam — rece pe scurt', ARRAY['fereastră curată']::text[], ARRAY['Atingeți sticla pe scurt: „Geam. Rece.”', 'Luați mâna: „Gata. Cald în palmă.”', 'Dacă vrea: „Ieri tot rece pe geam?” — gest da / nu.']::text[], 'A atins geamul rece sau a privit.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z2-mental', 'Rece — zăpadă sau doar rece?', ARRAY['fereastră']::text[], ARRAY['Arătați afară: „Rece.”', '„Zăpadă? Sau fără zăpadă?” — arătați / mimați.', 'Dacă vrea: comparație cu ieri — același rece sau altul.']::text[], 'A legat rece de ce e afară azi.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z2-social', 'Arată-i altcuiva geam', ARRAY['fereastră']::text[], ARRAY['Mergeți cu el la geam lângă o persoană dragă.', 'Modelați: „Geam. Rece.” sau „Ploaie.”', 'Dacă vrea: el arată singur și compară cu ieri.']::text[], 'A arătat geamul cuiva din casă.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z3-fizic', 'Ploaie pe geam — degetul urmărește', ARRAY['fereastră (ploaie, zăpadă sau mimă)']::text[], ARRAY['Dacă plouă / ningă (sau mimați): „Ploaie.” Degetul pe sticlă.', 'Câteva linii blânde, apoi oprire: „Gata.”', 'Dacă vrea: „Ieri a plouat? Sau zăpadă?” — gest.']::text[], 'A urmărit ploaie / zăpadă pe geam sau a mimat.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z3-mental', 'Ploaie sau rece — care e azi?', ARRAY['fereastră']::text[], ARRAY['Întrebați: „Azi ploaie?” — arătați afară.', '„Azi rece?” — gest pe brațe.', 'Dacă vrea: „Ieri care era?” — așteptați alegerea.']::text[], 'A ales sau auziți ploaie / rece pentru azi.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z3-social', 'Rândul la arătat ploaie / zăpadă', ARRAY['fereastră']::text[], ARRAY['Voi arătați: „Acum eu. Ploaie.” (sau zăpadă).', 'Apoi: „Acum tu” — așteptați gestul spre geam.', 'Dacă vrea: încă un schimb, apoi comparați cu ieri.']::text[], 'Ați schimbat rândul la arătat vremea.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z4-fizic', 'Întindere la geam — brațe și genunchi', ARRAY['spațiu lângă geam']::text[], ARRAY['La geam: brațele sus — „Geam.” — apoi genunchi ușor îndoiți.', '2–3 repetări: „Sus… jos.”', 'Dacă vrea: „Ieri am făcut la fel?” — da / nu cu capul.']::text[], 'A făcut întindere scurtă lângă geam.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z4-mental', 'Rece, ploaie, geam — pe obiecte', ARRAY['fereastră', 'opțional: imagine ploaie / zăpadă']::text[], ARRAY['Arătați geamul: „Geam.”', '„Rece.” pe sticlă; „Ploaie” dacă e / pe imagine.', 'Dacă vrea: el alege un cuvânt și îl spune pe geam.']::text[], 'A legat cele trei cuvinte de geam / vreme.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z4-social', 'Eu spun rece, tu arăți geam', ARRAY['fereastră']::text[], ARRAY['Voi: „Rece.” El arată geamul: „Geam.”', 'Schimbați o dată: el spune / voi arătați.', 'Dacă vrea: adăugați ploaie dacă e vizibil; comparați cu ieri.']::text[], 'Ați legat rece de geam împreună.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z5-fizic', 'Traseu: cameră → geam → întindere → gata', ARRAY['cale scurtă până la geam']::text[], ARRAY['Din cameră: „Mergem la geam.”', 'La geam întindere scurtă, apoi: „Gata. Înapoi.”', 'Dacă vrea: „Ieri tot acest traseu?” — gest.']::text[], 'A făcut traseul scurt până la geam.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z5-mental', 'Ce e diferit azi la geam?', ARRAY['fereastră']::text[], ARRAY['Priviți: „Azi… rece? Ploaie? Zăpadă?”', 'Numiți un lucru diferit față de altă zi.', 'Dacă vrea: „Ieri ce era?” — așteptați.']::text[], 'A observat un detaliu de azi la geam.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z5-social', 'Ajutor: vino la geam', ARRAY['fereastră']::text[], ARRAY['Cereți: „Vino la geam, te rog.”', 'Mulțumiți când vine: „Mulțumesc.”', 'Dacă vrea: el vă cheamă la geam; comparați cu ieri.']::text[], 'A venit la geam la cerere (sau a privit).', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z6-fizic', 'Privit liber scurt la geam', ARRAY['fereastră']::text[], ARRAY['Stați liber 30–60 de secunde: „Geam.”', 'Fără întrebări; doar privit.', 'Dacă vrea: „Ieri am privit la fel?” — un da / nu blând.']::text[], 'A privit liber la geam pe scurt.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z6-mental', 'Ce am văzut la geam?', ARRAY['fereastră']::text[], ARRAY['Întoarceți-vă din geam: „Am văzut…” — numiți 1 lucru.', 'El adaugă gest: rece / ploaie / zăpadă.', 'Dacă vrea: „Ieri am văzut altceva?”']::text[], 'Ați numit ceva văzut la geam.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z6-social', 'Joacă paralel: eu la un geam, tu la altul', ARRAY['1–2 ferestre / locuri de privit']::text[], ARRAY['Fiecare privește o clipă din locul lui: „Geam.”', 'Apoi vă întâlniți: „Rece / ploaie?”', 'Dacă vrea: comparați ce a văzut fiecare; și cu ieri.']::text[], 'Ați privit paralel pe scurt.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z7-fizic', 'Mișcare liberă — geam sau întindere', ARRAY['fereastră / spațiu liber']::text[], ARRAY['El alege: privit la geam sau întindere; voi urmăriți blând.', 'Fără forțare.', 'Dacă vrea: spuneți cuvântul ales — „Geam” sau „Rece”.']::text[], 'A ales și a făcut o mișcare blândă.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z7-mental', 'Favoritul: rece, ploaie sau geam?', ARRAY['fereastră']::text[], ARRAY['Întrebați: „Îți place rece, ploaie sau geam?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: „Ieri tot ăsta?” — un da / nu blând.']::text[], 'A ales un cuvânt favorit de vreme.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['perdea / jucării de la geam']::text[], ARRAY['„La loc.” După privitul de seară.', '„Acum e liniște.”', 'Dacă vrea: o ultimă privire geam, apoi închideți.']::text[], 'Geamul e închis ritual; calm.', 'Zăpadă sau ploaie la geam'),
  ('s27-b23-z7-social', 'Ritual: bună seara, geam blând', ARRAY['fereastră']::text[], ARRAY['Șoptiți: „Bună seara.” O privire scurtă: „Geam.”', '„Noapte bună.”', 'Dacă vrea: un ultim ploaie / rece pe amintire, apoi odihnă.']::text[], 'Ați închis seara la geam blând.', 'Zăpadă sau ploaie la geam'),
  ('s28-b23-z1-mental', 'Noroi și pământ — ce e afară?', ARRAY['fereastră / ușă spre curte', 'opțional: imagine noroi']::text[], ARRAY['Arătați afară sau imagine: „Noroi.”', '„Pământ.” — gest pe sol.', 'Dacă vrea: întrebați „Unde e noroi?” — el arată.']::text[], 'A legat noroi / pământ de afară.', 'Dezgheț și noroi'),
  ('s28-b23-z2-fizic', 'Deget pe noroi uscat sau ud', ARRAY['noroi uscat / pământ în ghiveci sau curte (sigur)', 'șervețel']::text[], ARRAY['Atingeți blând: „Noroi.” sau „Pământ.”', 'Dacă e ud: „Ud.” — apoi ștergeți: „Gata.”', 'Dacă vrea: comparați uscat și ud pe două locuri.']::text[], 'A atins noroi / pământ pe scurt.', 'Dezgheț și noroi'),
  ('s28-b23-z2-mental', 'Noroi: moale sau tare?', ARRAY['noroi / pământ sigur']::text[], ARRAY['Apăsați blând: „Moale? Tare?”', 'Spuneți: „Noroi ud e moale.” sau „Pământ uscat e tare.”', 'Dacă vrea: el alege care îi place — moale sau tare.']::text[], 'A simțit textura noroi / pământ.', 'Dezgheț și noroi'),
  ('s28-b23-z2-social', 'Privim noroi împreună', ARRAY['curte / ghiveci / geam spre curte']::text[], ARRAY['Stați împreună: „Noroi. Uite.”', 'El arată sau spune ud / pământ.', 'Dacă vrea: întrebați „Ce face noroi?” — așteptați gest.']::text[], 'A privit noroiul cu adultul.', 'Dezgheț și noroi'),
  ('s28-b23-z3-fizic', 'Pași scurți în curte cu cizme', ARRAY['cizme', 'curte / zonă sigură (sau mimă pe preș)']::text[], ARRAY['Cu cizme: 5–8 pași: „Pământ.”', 'Înapoi la ușă: „Gata.”', 'Dacă vrea: alegeți traseul scurt — stânga sau dreapta.']::text[], 'A făcut pași scurți pe pământ / mimă.', 'Dezgheț și noroi'),
  ('s28-b23-z3-mental', 'Curte ud sau uscată?', ARRAY['curte / geam']::text[], ARRAY['Arătați: „Afară ud? Sau uscat?”', '„Noroi e ud.” — gest.', 'Dacă vrea: comparați cu ieri dacă își amintește.']::text[], 'A ales ud sau uscat pentru afară.', 'Dezgheț și noroi'),
  ('s28-b23-z3-social', 'Pași în curte cu adultul', ARRAY['cizme', 'curte / preș']::text[], ARRAY['Mergeți umăr la umăr: „Pământ.”', 'O rundă scurtă, apoi: „Înapoi.”', 'Dacă vrea: pe rând — tu 3 pași, eu 3 pași.']::text[], 'Ați mers împreună pe scurt.', 'Dezgheț și noroi'),
  ('s28-b23-z4-fizic', 'Apă pe pământ: dezgheț', ARRAY['pahar mic cu apă', 'pământ / ghiveci / tavă (adult)']::text[], ARRAY['Turnați puțin: „Ud. Apă pe pământ.”', 'Priviți: „Noroi?” — o clipă.', 'Dacă vrea: el toarnă o picătură cu ajutor (sau alege să nu).']::text[], 'A văzut apă pe pământ (dezgheț / noroi).', 'Dezgheț și noroi'),
  ('s28-b23-z4-mental', 'Dezgheț: apă face noroi', ARRAY['pământ + apă (controlat)']::text[], ARRAY['„Uscat… pământ.” Apoi: „Ud… noroi.”', '„Ce s-a schimbat?”', 'Dacă vrea: întrebați „De ce e noroi?” — gest spre apă.']::text[], 'A legat apa de noroi.', 'Dezgheț și noroi'),
  ('s28-b23-z4-social', 'Turnăm apa pe rând', ARRAY['pahar', 'pământ controlat']::text[], ARRAY['„Acum eu” — o picătură.', '„Acum tu” — dacă vrea; altfel voi închideți.', 'Dacă vrea: comparați unde e mai ud.']::text[], 'Ați turnat pe rând (sau a privit).', 'Dezgheț și noroi'),
  ('s28-b23-z5-fizic', 'Ștergem cizmele pe preș', ARRAY['cizme', 'preș']::text[], ARRAY['Pe preș: „Curat.” — frecați blând talpa.', '„Gata. Fără noroi pe jos.”', 'Dacă vrea: alegeți preșul sau cârpa (1 din 2).']::text[], 'A șters cizmele pe preș pe scurt.', 'Dezgheț și noroi'),
  ('s28-b23-z5-mental', 'Murdar și curat — noroi pe cizmă', ARRAY['cizmă', 'preș']::text[], ARRAY['Arătați talpa: „Noroi? Murdar?”', 'După șters: „Curat.”', 'Dacă vrea: el arată care cizmă e mai curată.']::text[], 'A deosebit murdar / curat pe cizmă.', 'Dezgheț și noroi'),
  ('s28-b23-z6-fizic', 'Mâini la chiuvetă după curte', ARRAY['chiuvetă', 'săpun (adult)', 'prosop']::text[], ARRAY['„Ud pe mâini.” — apă scurtă.', 'Ștergeți: „Curat. Gata.”', 'Dacă vrea: alegeți săpunul sau doar apa (1 din 2).']::text[], 'S-a spălat pe mâini pe scurt după curte / joc.', 'Dezgheț și noroi'),
  ('s28-b23-z6-mental', 'Texturi: noroi, apoi ud curat', ARRAY['amintire noroi', 'chiuvetă']::text[], ARRAY['„Înainte — noroi.” Gest pe palmă.', '„Acum — ud, curat.” la chiuvetă.', 'Dacă vrea: întrebați „Unde e pământ acum?” — pe preș / afară.']::text[], 'A legat noroi de înainte și curat de acum.', 'Dezgheț și noroi'),
  ('s28-b23-z6-social', 'Spălăm după curte împreună', ARRAY['chiuvetă']::text[], ARRAY['Umăr la umăr: „Ud. Curat.”', 'Pe rând la robinet, scurt.', 'Dacă vrea: el spune „gata” primul.']::text[], 'Ați spălat împreună pe scurt.', 'Dezgheț și noroi'),
  ('s28-b23-z7-fizic', 'Plimbare liberă — curte sau preș', ARRAY['curte / preș', 'cizme opțional']::text[], ARRAY['El alege zona; voi urmăriți blând.', 'Fără grabă: „Pământ… gata.”', 'Dacă vrea: alegeți noroi (privit) sau doar pași uscați.']::text[], 'A plimbat liber pe scurt.', 'Dezgheț și noroi'),
  ('s28-b23-z7-mental', 'Favoritul: noroi, ud sau pământ?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place noroi, ud sau pământ?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: comparați cu ce a ales ieri (dacă își amintește).']::text[], 'A ales un cuvânt favorit din temă.', 'Dezgheț și noroi'),
  ('s28-b23-z7-social', 'Ritual: bună seara după curte', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara.” Gest: mâini curate.', '„Noapte bună.”', 'Dacă vrea: un ultim „Noroi… gata” pe amintire, apoi odihnă.']::text[], 'Ați închis seara blând după tema de curte.', 'Dezgheț și noroi'),
  ('s29-b23-z1-fizic', 'Afară: pași pe iarbă nouă', ARRAY['curte / iarbă', 'încălțăminte de afară']::text[], ARRAY['Ieșiți scurt: „Verde. Iarbă.” — 3–5 pași pe iarbă.', 'Atingeți iarba cu mâna: „Plantă. Verde.”', 'Dacă vrea: spuneți „Udăm ca să crește — să crească.” — gest pe iarbă.']::text[], 'A făcut pași pe iarbă și a atins verdele.', 'Muguri și iarbă nouă'),
  ('s29-b23-z1-mental', 'Verde nou și verde vechi', ARRAY['iarbă / plantă pe pervaz', 'opțional: frunză uscată']::text[], ARRAY['Arătați iarba nouă: „Verde. Nou.”', 'Arătați o frunză mai veche / uscată: „Vechi.” — „Ce e diferit?”', 'Dacă vrea: el arată care e verde și spune (sau gest) de ce udăm.']::text[], 'A deosebit verde nou de vechi pe scurt.', 'Muguri și iarbă nouă'),
  ('s29-b23-z1-resurse', 'Apă pentru plantă — ajunge', ARRAY['pahar mic cu apă', 'plantă / ghiveci']::text[], ARRAY['Turnați puțin: „Apă. Plantă.”', '„Ajunge.” — opriți; paharul deoparte.', 'Dacă vrea: întrebați „De ce udăm?” — „Ca să crește.”']::text[], 'Planta a primit puțină apă; ajunge e clar.', 'Muguri și iarbă nouă'),
  ('s29-b23-z1-social', 'Grijă împreună de plantă', ARRAY['plantă / ghiveci']::text[], ARRAY['Stați umăr la umăr: „Plantă. Verde.”', 'Atingeți blând frunza împreună: „Crește.”', 'Dacă vrea: el spune (sau arată) de ce udăm — voi completați blând.']::text[], 'Ați îngrijit planta împreună pe scurt.', 'Muguri și iarbă nouă'),
  ('s29-b23-z2-fizic', 'Deget pe mugure', ARRAY['ramură cu muguri / plantă']::text[], ARRAY['Atingeți un mugure: „Mugure. Crește.”', '10–15 secunde, fără apăsare: „Verde.”', 'Dacă vrea: spuneți „Udăm ca mugurii să crește.”']::text[], 'A atins mugurele blând.', 'Muguri și iarbă nouă'),
  ('s29-b23-z2-mental', 'Mugure și frunză — care e care?', ARRAY['ramură / plantă']::text[], ARRAY['Arătați mugurele: „Mugure.”', 'Arătați o frunză: „Verde. Frunză.”', 'Dacă vrea: „De ce udăm plantă?” — gest spre apă / sol.']::text[], 'A legat mugure și frunză de plantă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z2-social', 'Arată mugurele adultului', ARRAY['ramură / plantă']::text[], ARRAY['El arată (sau voi ghidați): „Uite. Crește.”', 'Voi: „Da. Verde.” — o clipă împreună.', 'Dacă vrea: spuneți împreună de ce udăm — o frază scurtă.']::text[], 'A arătat mugurele adultului.', 'Muguri și iarbă nouă'),
  ('s29-b23-z3-fizic', 'Îngenunchem lângă iarbă', ARRAY['iarbă / curte']::text[], ARRAY['Îngenuncheați (sau așezați-vă): „Verde.”', 'Mâna pe iarbă 5–8 secunde: „Plantă.”', 'Dacă vrea: „Udăm ca să crește.” — gest pe sol.']::text[], 'A stat scurt lângă iarbă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z3-mental', 'Unde e verde pe plantă?', ARRAY['plantă / iarbă']::text[], ARRAY['„Unde e verde?” — el arată frunză / iarbă.', '„Da. Plantă.”', 'Dacă vrea: întrebați „De ce e verde?” — legați de udat / crește.']::text[], 'A găsit verde pe plantă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z3-resurse', 'Alege: udăm azi sau mâine', ARRAY['plantă', 'pahar (opțional)']::text[], ARRAY['Arătați 2: „Azi — apă. Mâine — așteptăm.”', 'Alegeți împreună: „Ajunge așa.”', 'Dacă vrea: spuneți de ce ați ales — „Ca să crește / ca să nu fie prea mult.”']::text[], 'Ați ales când udați; fără forțare.', 'Muguri și iarbă nouă'),
  ('s29-b23-z3-social', 'Rândul la atins iarba', ARRAY['iarbă']::text[], ARRAY['„Acum eu” — mână pe verde.', '„Acum tu.”', 'Dacă vrea: pe rând spuneți „crește” după fiecare atingere.']::text[], 'Ați schimbat rândul la atins iarba.', 'Muguri și iarbă nouă'),
  ('s29-b23-z4-fizic', 'Cărăm paharul cu apă spre plantă', ARRAY['pahar mic cu puțină apă', 'plantă']::text[], ARRAY['Cărați împreună paharul: „Apă… plantă.”', 'Turnați puțin: „Crește.” — apoi gata.', 'Dacă vrea: el spune de ce ați udat — „Ca să crește.”']::text[], 'A cărat apa și a udat pe scurt.', 'Muguri și iarbă nouă'),
  ('s29-b23-z4-mental', 'De ce udăm? — o frază', ARRAY['plantă', 'pahar']::text[], ARRAY['Arătați planta: „Plantă. Verde.”', '„De ce udăm?” — răspundeți: „Ca să crește.”', 'Dacă vrea: el repetă gestul / cuvântul crește.']::text[], 'A auzit de ce udăm legat de crește.', 'Muguri și iarbă nouă'),
  ('s29-b23-z4-social', 'Udăm pe rând — o picătură', ARRAY['pahar', 'plantă']::text[], ARRAY['„Acum eu” — o picătură.', '„Acum tu” — dacă vrea; altfel voi închideți.', 'Dacă vrea: „De ce?” — „Ca plantă să crește.”']::text[], 'Ați udat pe rând pe scurt.', 'Muguri și iarbă nouă'),
  ('s29-b23-z5-fizic', 'Întindem scurt lângă plantă', ARRAY['plantă / pervaz', 'spațiu liber']::text[], ARRAY['Brațele sus: „Crește. Sus.” — 3–5 secunde.', 'Mâinile pe genunchi: „Verde. Jos.”', 'Dacă vrea: arătați planta — „Și ea crește.”']::text[], 'A făcut întindem scurt lângă plantă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z5-mental', 'Trei cuvinte: plantă, verde, crește', ARRAY['plantă']::text[], ARRAY['Arătați planta: „Plantă.”', 'Frunza: „Verde.” — gest sus: „Crește.”', 'Dacă vrea: el arată care cuvânt vrea să-l audă iar.']::text[], 'A auzit cele trei cuvinte pe plantă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z5-resurse', 'Ghiveciul pe pervaz — la loc', ARRAY['ghiveci / plantă']::text[], ARRAY['Așezați ghiveciul: „Plantă. La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți pervazul sau masa (1 din 2).']::text[], 'Ghiveciul e așezat la loc.', 'Muguri și iarbă nouă'),
  ('s29-b23-z5-social', 'Arată verde altcuiva', ARRAY['plantă', 'persoană dragă (sau foto)']::text[], ARRAY['Mergeți împreună: „Verde. Uite.”', 'El arată frunza / iarba.', 'Dacă vrea: spuneți celeilalte persoane de ce udăm.']::text[], 'A arătat verdele altcuiva.', 'Muguri și iarbă nouă'),
  ('s29-b23-z6-fizic', 'Plimbare scurtă: iarbă → plantă pe pervaz', ARRAY['curte / iarbă', 'plantă pe pervaz']::text[], ARRAY['Pași pe iarbă: „Verde.”', 'Înapoi la plantă: „Plantă. Crește.”', 'Dacă vrea: pe traseu spuneți de ce udăm — o frază.']::text[], 'A legat iarba de planta din casă pe scurt.', 'Muguri și iarbă nouă'),
  ('s29-b23-z6-mental', 'Aceeași plantă — afară și pe pervaz?', ARRAY['iarbă', 'plantă pe pervaz']::text[], ARRAY['„Afară — verde.” Gest pe iarbă.', '„Aici — plantă.” pe pervaz. „Amândouă crește?”', 'Dacă vrea: el alege pe care o udăm azi.']::text[], 'A legat verdele din afară de planta din casă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z6-resurse', 'Udatul de azi — gata', ARRAY['pahar', 'plantă']::text[], ARRAY['Dacă ați udat: „Ajunge. Gata.”', 'Paharul la loc.', 'Dacă vrea: un ultim „Crește” pe plantă, apoi opriți.']::text[], 'Udatul e închis; gata e clar.', 'Muguri și iarbă nouă'),
  ('s29-b23-z6-social', 'Împreună: verde pe iarbă și pe plantă', ARRAY['iarbă / plantă']::text[], ARRAY['Umăr la umăr: „Verde… plantă.”', 'O rundă scurtă de arătat.', 'Dacă vrea: inventați o frază scurtă — „Udăm ca să crește.”']::text[], 'Ați arătat verdele împreună.', 'Muguri și iarbă nouă'),
  ('s29-b23-z7-fizic', 'Mișcare liberă lângă plantă sau iarbă', ARRAY['plantă / iarbă', 'spațiu liber']::text[], ARRAY['El alege zona; voi urmăriți blând.', 'Fără grabă: „Verde… gata.”', 'Dacă vrea: alegeți întindem „crește” sau doar privit.']::text[], 'A mișcat liber pe scurt lângă verde.', 'Muguri și iarbă nouă'),
  ('s29-b23-z7-mental', 'Favoritul: plantă, verde sau crește?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place plantă, verde sau crește?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: spuneți de ce udăm legat de alegerea lui.']::text[], 'A ales un cuvânt favorit din temă.', 'Muguri și iarbă nouă'),
  ('s29-b23-z7-resurse', 'Planta și paharul la loc — seara', ARRAY['plantă', 'pahar']::text[], ARRAY['„La loc.” — plantă / pahar.', '„Ajunge. Acum e liniște.”', 'Dacă vrea: o ultimă privire verde, apoi calm.']::text[], 'Totul e la loc înainte de calm.', 'Muguri și iarbă nouă'),
  ('s29-b23-z7-social', 'Ritual: bună seara, plantă blândă', ARRAY['plantă / pervaz']::text[], ARRAY['Șoptiți: „Bună seara.” Gest pe plantă: „Plantă.”', '„Noapte bună. Crește.”', 'Dacă vrea: un ultim „De ce udăm?” — răspuns șoptit, apoi odihnă.']::text[], 'Ați închis seara blând la plantă.', 'Muguri și iarbă nouă'),
  ('s30-b23-z1-fizic', 'Afară dimineața: urechi și ochi 2–3 min', ARRAY['curte / fereastră deschisă', 'încălțăminte dacă ieșiți']::text[], ARRAY['Stați liniștiți: „Uite. Privim.” — 30–60 secunde.', 'Dacă auziți: „Pasăre.” — arătați direcția.', 'Dacă vrea: întrebați „Ce face pasărea?” — zboară / cântă (gest).']::text[], 'A ascultat / privit afară pe scurt.', 'Păsări dimineața'),
  ('s30-b23-z1-mental', 'Sunet → pasăre — unde?', ARRAY['fereastră / curte']::text[], ARRAY['Auziți un sunet: „Pasăre?” — arătați sus / copac.', '„Uite. Acolo.”', 'Dacă vrea: „Ce face?” — el gesticulează sau voi modelați.']::text[], 'A legat sunetul de pasăre și direcție.', 'Păsări dimineața'),
  ('s30-b23-z1-resurse', 'Observăm — fără a prinde', ARRAY['fereastră / curte']::text[], ARRAY['„Uite. Doar privim.” — mâinile jos.', '„Ajunge. Gata.” — închideți jocul de prins (nu există).', 'Dacă vrea: alegeți uite de la geam sau 3 pași afară (1 din 2).']::text[], 'A observat fără a alerga după animal.', 'Păsări dimineața'),
  ('s30-b23-z1-social', 'Arată adultului ce aude', ARRAY['fereastră / curte']::text[], ARRAY['El arată (sau voi ghidați): „Uite. Pasăre.”', 'Voi: „Da. Aud.” — o clipă împreună.', 'Dacă vrea: „Ce face pasărea?” — o întrebare blândă.']::text[], 'A arătat adultului ce aude / vede.', 'Păsări dimineața'),
  ('s30-b23-z2-fizic', 'Pași scurți spre fereastră — uite', ARRAY['fereastră']::text[], ARRAY['3–5 pași spre geam: „Uite.”', 'Stați: „Pasăre?” — 20–30 secunde.', 'Dacă vrea: „Ce face?” — priviți încă o clipă.']::text[], 'A mers la geam și a privit.', 'Păsări dimineața'),
  ('s30-b23-z2-mental', 'Pasăre sau câine — care sunet?', ARRAY['fereastră / curte', 'opțional: înregistrare scurtă adult']::text[], ARRAY['„Pasăre — cirip.” Gest sus.', '„Câine — ham.” Gest jos / curte. „Care e?”', 'Dacă vrea: „Ce face câine?” / „Ce face pasărea?” — o întrebare.']::text[], 'A deosebit pasăre de câine pe scurt.', 'Păsări dimineața'),
  ('s30-b23-z2-resurse', 'Geamul — rămâne așa, gata', ARRAY['fereastră']::text[], ARRAY['După uite: „Ajunge.”', '„Gata.” — nu mai deschideți / închideți degeaba.', 'Dacă vrea: alegeți geam deschis puțin sau închis (1 din 2, adult).']::text[], 'Geamul e lăsat; gata e clar.', 'Păsări dimineața'),
  ('s30-b23-z2-social', 'Rândul la uite pe geam', ARRAY['fereastră']::text[], ARRAY['„Acum eu — uite.”', '„Acum tu — uite.”', 'Dacă vrea: pe rând „Ce face pasărea?” — un gest.']::text[], 'Ați schimbat rândul la privit.', 'Păsări dimineața'),
  ('s30-b23-z3-fizic', 'Corp liniștit: uite pe loc', ARRAY['curte / geam', 'spațiu liber']::text[], ARRAY['Pe loc: „Uite.” — corp calm 20–40 secunde.', 'Dacă auziți pasăre: arătați fără a alerga.', 'Dacă vrea: „Ce face?” — zbura / stă (gest).']::text[], 'A stat calm și a privit / ascultat.', 'Păsări dimineața'),
  ('s30-b23-z3-mental', 'Direcție: pasăre sus sau câine jos?', ARRAY['curte / geam']::text[], ARRAY['„Pasăre — uite sus.”', '„Câine — uite jos / curte.”', 'Dacă vrea: el arată unde uite — apoi „Ce face?”']::text[], 'A legat pasăre/câine de direcție.', 'Păsări dimineața'),
  ('s30-b23-z3-resurse', 'Limită: doar uite, nu alergăm', ARRAY['curte / geam']::text[], ARRAY['„Uite. Ajunge.” — fără goană.', '„Gata.” dacă începe alergarea după animal.', 'Dacă vrea: alegeți 10 secunde uite sau 30 (1 din 2).']::text[], 'Limita de observare e respectată.', 'Păsări dimineața'),
  ('s30-b23-z3-social', 'Uite împreună — umăr la umăr', ARRAY['fereastră']::text[], ARRAY['Stați împreună: „Uite. Pasăre.”', 'Șoptiți: „Aud.”', 'Dacă vrea: „Ce face pasărea?” — răspundeți împreună cu gest.']::text[], 'Ați privit împreună pe scurt.', 'Păsări dimineața'),
  ('s30-b23-z4-fizic', 'Deget pe geam — uite pasăre', ARRAY['fereastră curată']::text[], ARRAY['Deget pe geam: „Uite.”', 'Urmăriți o pasăre (sau nor): „Pasăre.”', 'Dacă vrea: „Ce face?” — zboară / stă.']::text[], 'A urmărit pe geam pe scurt.', 'Păsări dimineața'),
  ('s30-b23-z4-mental', 'Trei cuvinte: pasăre, câine, uite', ARRAY['fereastră / curte']::text[], ARRAY['„Uite.” pe geam; „Pasăre.” sus; „Câine.” (dacă e / mimă).', 'Repetați o dată, blând.', 'Dacă vrea: el alege un cuvânt — voi întrebați „Ce face?”']::text[], 'A auzit cele trei cuvinte pe temă.', 'Păsări dimineața'),
  ('s30-b23-z4-resurse', 'După uite — ne întoarcem în casă', ARRAY['ușă / pantofi']::text[], ARRAY['„Ajunge. Înapoi.”', 'Pantofii / ușa: „La loc / gata.”', 'Dacă vrea: un ultim uite de 5 secunde, apoi închideți.']::text[], 'V-ați întors; jocul de uite e închis.', 'Păsări dimineața'),
  ('s30-b23-z4-social', 'Arată pasăre unei persoane dragi', ARRAY['fereastră', 'persoană dragă']::text[], ARRAY['„Uite. Pasăre.” — arătați împreună.', 'El trage de mână / arată.', 'Dacă vrea: întrebați persoana „Ce face pasărea?” — el ascultă.']::text[], 'A arătat pasăre altcuiva.', 'Păsări dimineața'),
  ('s30-b23-z5-fizic', 'Urechi afară, apoi pași în casă', ARRAY['curte / geam', 'ușă']::text[], ARRAY['Afară: „Uite. Pasăre.” — 20–40 secunde.', 'Înapoi: 3–5 pași în casă: „Gata.”', 'Dacă vrea: pe prag „Ce face pasărea acum?” — gest.']::text[], 'A ascultat afară și s-a întors.', 'Păsări dimineața'),
  ('s30-b23-z5-mental', 'Ce face pasărea? — zboară / cântă', ARRAY['fereastră']::text[], ARRAY['„Pasăre. Ce face?” — voi: „Zboară.” sau „Cântă.”', 'Gest cu brațele / deget pe ureche.', 'Dacă vrea: el alege gestul — zbura sau cântă.']::text[], 'A legat pasăre de o acțiune.', 'Păsări dimineața'),
  ('s30-b23-z5-resurse', 'Alege: uite de la geam sau din curte', ARRAY['geam', 'ușă']::text[], ARRAY['Arătați 2: „Geam — uite. Curte — uite.”', 'Alegeți una: „Ajunge așa.”', 'Dacă vrea: după alegere, o întrebare „Ce face?”']::text[], 'Ați ales locul de uite; fără forțare.', 'Păsări dimineața'),
  ('s30-b23-z5-social', 'Rândul: eu uite, tu uite', ARRAY['fereastră']::text[], ARRAY['„Acum eu — uite.”', '„Acum tu.”', 'Dacă vrea: pe rând „Ce face câine / pasăre?” — o rundă.']::text[], 'Ați schimbat rândul la uite.', 'Păsări dimineața'),
  ('s30-b23-z6-fizic', 'Întindem scurt înainte de uite', ARRAY['spațiu liber', 'fereastră']::text[], ARRAY['Brațele sus: „Uite sus — pasăre.”', 'Mâinile pe genunchi: „Uite jos — câine?”', 'Dacă vrea: „Ce face?” pe fiecare gest.']::text[], 'A legat întindem de uite sus/jos.', 'Păsări dimineața'),
  ('s30-b23-z6-mental', 'Pasăre dimineața — amintim sunetul', ARRAY['fereastră']::text[], ARRAY['„Dimineața — pasăre.” Mimă cirip.', '„Uite.” pe geam acum.', 'Dacă vrea: „Ce face pasărea dimineața?” — cântă (gest).']::text[], 'A legat pasăre de dimineață.', 'Păsări dimineața'),
  ('s30-b23-z6-resurse', 'Uite de azi — gata', ARRAY['fereastră']::text[], ARRAY['„Ajunge. Uite gata.”', '„La loc” — dacă ați mutat un scaun la geam.', 'Dacă vrea: un ultim uite 5 secunde, apoi opriți.']::text[], 'Uite-ul zilei e închis.', 'Păsări dimineața'),
  ('s30-b23-z6-social', 'Joacă paralel: eu uite pasăre, tu uite', ARRAY['fereastră']::text[], ARRAY['Voi: „Eu — pasăre.”', 'El: „Tu — uite.” — fără forțare să vadă același lucru.', 'Dacă vrea: schimbați — „Ce face?” pe ce vede fiecare.']::text[], 'Ați privit în paralel pe scurt.', 'Păsări dimineața'),
  ('s30-b23-z7-fizic', 'Uite liber la geam — el alege', ARRAY['fereastră']::text[], ARRAY['El alege cât stă; voi urmăriți blând.', 'Fără grabă: „Uite… gata.”', 'Dacă vrea: o întrebare blândă „Ce face pasărea?” — refuz e în regulă.']::text[], 'A privit liber pe scurt.', 'Păsări dimineața'),
  ('s30-b23-z7-mental', 'Favoritul: pasăre, câine sau uite?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place pasăre, câine sau uite?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: „Ce face [alegerea]?” — un gest scurt.']::text[], 'A ales un cuvânt favorit din temă.', 'Păsări dimineața'),
  ('s30-b23-z7-resurse', 'Geamul și scaunul la loc — seara', ARRAY['fereastră', 'scaun (dacă e)']::text[], ARRAY['„La loc.” — scaun / perdea cum vreți.', '„Ajunge. Acum e liniște.”', 'Dacă vrea: un ultim uite blând, apoi calm.']::text[], 'Totul e la loc înainte de calm.', 'Păsări dimineața'),
  ('s30-b23-z7-social', 'Ritual: bună seara, uite blând', ARRAY['fereastră']::text[], ARRAY['Șoptiți: „Bună seara.” O privire: „Uite.”', '„Noapte bună. Pasăre… gata.”', 'Dacă vrea: „Ce face pasărea noaptea?” — „Doarme.” — apoi odihnă.']::text[], 'Ați închis seara la geam blând.', 'Păsări dimineața'),
  ('s31-b23-z1-fizic', 'Mâini pe semințe — atins pe scurt', ARRAY['semințe mari sigure (fasole / floarea-soarelui)', 'farfurie / tavă']::text[], ARRAY['Atingeți o sămânță: „Sămânță. Plantă.”', 'Mutați 2–3 pe tavă: „Crește.” — blând.', 'Dacă vrea: spuneți „Udăm ca să crește.” — gest pe sămânță.']::text[], 'A atins semințele pe scurt.', 'Semințe și udat'),
  ('s31-b23-z1-mental', 'Sămânță și verde — ce urmează?', ARRAY['sămânță', 'plantă mică / imagine frunză']::text[], ARRAY['„Sămânță.” Apoi: „Verde. Frunză.”', '„Întâi sămânță… apoi crește.”', 'Dacă vrea: „De ce udăm?” — „Ca să crește.”']::text[], 'A legat sămânța de crește / verde.', 'Semințe și udat'),
  ('s31-b23-z1-resurse', 'Apă pe sămânță / pământ — ajunge', ARRAY['pahar mic', 'ghiveci cu pământ / sămânță']::text[], ARRAY['Turnați puțin: „Apă. Plantă.”', '„Ajunge.” — opriți.', 'Dacă vrea: întrebați „De ce udăm?” — „Ca să crește.”']::text[], 'A udat puțin; ajunge e clar.', 'Semințe și udat'),
  ('s31-b23-z1-social', 'Punem sămânța împreună', ARRAY['sămânță', 'ghiveci / pământ']::text[], ARRAY['Umăr la umăr: „Plantă. Sămânță.”', 'Apăsați blând în pământ: „Crește.”', 'Dacă vrea: el spune de ce urmați cu apă.']::text[], 'Ați pus sămânța împreună.', 'Semințe și udat'),
  ('s31-b23-z2-fizic', 'Cărăm paharul spre semințe', ARRAY['pahar mic cu apă', 'ghiveci']::text[], ARRAY['Cărați paharul: „Apă… plantă.”', 'Turnați o picătură: „Crește.”', 'Dacă vrea: „De ce?” — „Ca sămânța să crește.”']::text[], 'A cărat apa și a udat pe scurt.', 'Semințe și udat'),
  ('s31-b23-z2-mental', 'Uscat și ud — pământul seminței', ARRAY['pământ uscat', 'picătură apă']::text[], ARRAY['„Uscat.” pe pământ. Apoi: „Ud. Apă.”', '„Plantă vrea ud ca să crește.”', 'Dacă vrea: el arată unde e ud acum.']::text[], 'A deosebit uscat de ud pe pământ.', 'Semințe și udat'),
  ('s31-b23-z2-social', 'Rândul la turnat o picătură', ARRAY['pahar', 'ghiveci']::text[], ARRAY['„Acum eu” — o picătură.', '„Acum tu” — dacă vrea.', 'Dacă vrea: pe rând „Crește” după fiecare picătură.']::text[], 'Ați turnat pe rând pe scurt.', 'Semințe și udat'),
  ('s31-b23-z3-fizic', 'Deget în pământ lângă sămânță', ARRAY['ghiveci cu pământ', 'șervețel']::text[], ARRAY['Deget blând în pământ: „Plantă.”', 'Scoateți: „Verde vine… crește.” — fără a dezgropa forțat.', 'Dacă vrea: spuneți de ce nu scoatem sămânța — „Ca să crește.”']::text[], 'A atins pământul lângă sămânță.', 'Semințe și udat'),
  ('s31-b23-z3-mental', 'Unde e sămânța acum?', ARRAY['ghiveci']::text[], ARRAY['„Sămânța e în plantă / pământ.” — gest.', '„Nu o vedem. Crește înăuntru.”', 'Dacă vrea: „De ce udăm dacă nu o vedem?” — „Ca să crește.”']::text[], 'A înțeles că sămânța e ascunsă în pământ.', 'Semințe și udat'),
  ('s31-b23-z3-resurse', 'Alege: udăm puțin sau mai puțin', ARRAY['pahar', 'ghiveci']::text[], ARRAY['Arătați 2: „Puțin. Și mai puțin.”', 'Alegeți: „Ajunge așa.”', 'Dacă vrea: spuneți de ce puțin — „Ca plantă să crește bine.”']::text[], 'Ați ales cantitatea; fără risipă.', 'Semințe și udat'),
  ('s31-b23-z3-social', 'Grijă împreună — sămânța noastră', ARRAY['ghiveci']::text[], ARRAY['„Plantă a noastră.” — mână pe ghiveci.', '„Verde… crește.”', 'Dacă vrea: inventați o frază — „Udăm ca să crește.”']::text[], 'Ați îngrijit sămânța împreună.', 'Semințe și udat'),
  ('s31-b23-z4-fizic', 'Pași: chiuvetă → ghiveci cu apă', ARRAY['chiuvetă', 'pahar', 'ghiveci']::text[], ARRAY['Umpleți puțin la chiuvetă: „Apă.”', 'Pași spre plantă: „Crește.” — turnați puțin.', 'Dacă vrea: el spune de ce ați adus apa.']::text[], 'A făcut traseul apă → plantă.', 'Semințe și udat'),
  ('s31-b23-z4-mental', 'De ce udăm semințele? — o frază', ARRAY['ghiveci', 'pahar']::text[], ARRAY['„Plantă. Sămânță.”', '„De ce udăm?” — „Ca să crește. Verde.”', 'Dacă vrea: el repetă „crește” sau arată apa.']::text[], 'A auzit motivul udatului.', 'Semințe și udat'),
  ('s31-b23-z4-social', 'Arată sămânța / ghiveciul altcuiva', ARRAY['ghiveci', 'persoană dragă']::text[], ARRAY['„Plantă. Crește.” — arătați împreună.', 'El trage de mână / arată.', 'Dacă vrea: spuneți celeilalte persoane de ce udăm.']::text[], 'A arătat ghiveciul altcuiva.', 'Semințe și udat'),
  ('s31-b23-z5-fizic', 'Întindem „crește” lângă ghiveci', ARRAY['ghiveci', 'spațiu liber']::text[], ARRAY['Din ghemuit: ridicați-vă încet: „Crește.”', 'Brațele ca frunze: „Verde.”', 'Dacă vrea: legați de udat — „Apă… apoi crește.”']::text[], 'A mimă crește cu corpul.', 'Semințe și udat'),
  ('s31-b23-z5-mental', 'Trei cuvinte: plantă, verde, crește pe semințe', ARRAY['ghiveci / semințe']::text[], ARRAY['„Plantă” pe ghiveci; „Crește” gest sus; „Verde” pe frunză (dacă e).', 'O rundă blândă.', 'Dacă vrea: el alege ordinea celor trei cuvinte.']::text[], 'A auzit cele trei cuvinte pe semințe.', 'Semințe și udat'),
  ('s31-b23-z6-fizic', 'Plimbare scurtă: ghiveci → lumină (pervaz)', ARRAY['ghiveci ușor', 'pervaz']::text[], ARRAY['Cărați ghiveciul împreună: „Plantă.”', 'Pe pervaz: „Verde. Crește — lumină.”', 'Dacă vrea: spuneți de ce e la lumină + de ce udăm.']::text[], 'A mutat planta spre lumină pe scurt.', 'Semințe și udat'),
  ('s31-b23-z6-mental', 'Lumină și apă — plantă are nevoie', ARRAY['ghiveci pe pervaz']::text[], ARRAY['„Lumină.” pe geam. „Apă.” pe pahar.', '„Plantă: verde… crește.”', 'Dacă vrea: el alege ce dăm azi — lumină (mutat) sau apă.']::text[], 'A legat lumină și apă de crește.', 'Semințe și udat'),
  ('s31-b23-z6-resurse', 'Udatul de azi la semințe — gata', ARRAY['pahar', 'ghiveci']::text[], ARRAY['„Ajunge. Gata.”', 'Paharul la loc.', 'Dacă vrea: un ultim „Crește” pe ghiveci, apoi opriți.']::text[], 'Udatul e închis; gata e clar.', 'Semințe și udat'),
  ('s31-b23-z6-social', 'Împreună verificăm: e ud?', ARRAY['ghiveci']::text[], ARRAY['Deget blând pe pământ: „Ud? Uscat?”', '„Plantă… crește.”', 'Dacă vrea: decideți împreună dacă mai udați — „De ce da / nu.”']::text[], 'Ați verificat pământul împreună.', 'Semințe și udat'),
  ('s31-b23-z7-fizic', 'Mișcare liberă lângă ghiveci', ARRAY['ghiveci', 'spațiu liber']::text[], ARRAY['El alege zona; voi urmăriți blând.', 'Fără grabă: „Plantă… gata.”', 'Dacă vrea: alegeți întindem crește sau doar privit.']::text[], 'A mișcat liber pe scurt lângă plantă.', 'Semințe și udat'),
  ('s31-b23-z7-mental', 'Favoritul: plantă, verde sau crește?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place plantă, verde sau crește?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: legați alegerea de „De ce udăm?”']::text[], 'A ales un cuvânt favorit din temă.', 'Semințe și udat'),
  ('s31-b23-z7-resurse', 'Ghiveciul și paharul la loc — seara', ARRAY['ghiveci', 'pahar']::text[], ARRAY['„La loc.”', '„Ajunge. Acum e liniște.”', 'Dacă vrea: o ultimă privire verde, apoi calm.']::text[], 'Totul e la loc înainte de calm.', 'Semințe și udat'),
  ('s31-b23-z7-social', 'Ritual: bună seara, sămânță blândă', ARRAY['ghiveci']::text[], ARRAY['Șoptiți: „Bună seara.” Gest pe ghiveci: „Plantă.”', '„Noapte bună. Crește.”', 'Dacă vrea: un ultim „De ce udăm?” — răspuns șoptit, apoi odihnă.']::text[], 'Ați închis seara blând la semințe.', 'Semințe și udat'),
  ('s32-b23-z1-fizic', 'Mingea afară — aruncat scurt', ARRAY['minge moale', 'curte / spațiu liber']::text[], ARRAY['Țineți mingea: „Minge.”', 'Aruncați blând 1–2 m: „Rând.” — el prinde / aleargă.', 'Dacă vrea: inventați o regulă — „Mingea pe iarbă, nu pe trepte.”']::text[], 'A aruncat / alergat după minge pe scurt.', 'Mingea afară'),
  ('s32-b23-z1-mental', 'Rândul tău — trei schimburi', ARRAY['minge']::text[], ARRAY['„Rândul meu.” — aruncați voi.', '„Rândul tău.” — așteptați; apoi iar „Rândul meu.” — 3 schimburi.', 'Dacă vrea: regula — „Numărăm până la trei, apoi gata.”']::text[], 'A făcut aproximativ 3 schimburi de rând.', 'Mingea afară'),
  ('s32-b23-z1-resurse', 'Mingea la loc după joacă', ARRAY['minge', 'coș / loc cunoscut']::text[], ARRAY['După joacă: „Minge. La loc.”', '„Ajunge. Gata.”', 'Dacă vrea: regula — „Mingea în coș = gata jocul.”']::text[], 'Mingea e la loc; jocul e închis.', 'Mingea afară'),
  ('s32-b23-z1-social', 'Trei schimburi sociale cu minge', ARRAY['minge']::text[], ARRAY['„Rândul meu” — voi. „Rând” — el. Încă o dată — 3 schimburi.', 'Zâmbiți / gest „gata” după trei.', 'Dacă vrea: regula scurtă — „După trei, pauză.”']::text[], 'Ați făcut 3 schimburi cu mingea.', 'Mingea afară'),
  ('s32-b23-z2-fizic', 'Rulare pe iarbă — minge', ARRAY['minge', 'iarbă / preș afară']::text[], ARRAY['Rulați mingea: „Minge.”', 'El o oprește cu mâna / piciorul: „Rând.”', 'Dacă vrea: regula — „Mingea doar pe iarbă.”']::text[], 'A rulat / oprit mingea pe scurt.', 'Mingea afară'),
  ('s32-b23-z2-mental', 'Rândul meu și rând — care e acum?', ARRAY['minge']::text[], ARRAY['Țineți mingea: „Rândul meu.”', 'O dați: „Rândul tău.” — „Care e acum?”', 'Dacă vrea: regula — „Cine ține mingea are rândul.”']::text[], 'A legat cine ține mingea de rând.', 'Mingea afară'),
  ('s32-b23-z2-resurse', 'Alege: minge mare sau mică', ARRAY['2 mingi (sau 1 minge + alternativă)']::text[], ARRAY['Arătați 2: „Minge mare. Minge mică.”', 'Alegeți una: „Ajunge așa.”', 'Dacă vrea: regula — „Azi doar mingea aleasă.”']::text[], 'Ați ales o minge; cealaltă la loc.', 'Mingea afară'),
  ('s32-b23-z2-social', 'Rândul: eu minge, tu minge', ARRAY['minge']::text[], ARRAY['„Rândul meu.” — o rulare.', '„Rând.” — așteptați.', 'Dacă vrea: regula — „Spunem rândul meu înainte.”']::text[], 'Ați schimbat rândul la minge.', 'Mingea afară'),
  ('s32-b23-z3-fizic', 'Pase scurte pe loc', ARRAY['minge moale']::text[], ARRAY['Pasă la 1 m: „Minge.”', 'Înapoi: „Rând.” — 3–4 pase.', 'Dacă vrea: regula — „Mingea pe jos, nu pe cap.”']::text[], 'A făcut pase scurte pe loc.', 'Mingea afară'),
  ('s32-b23-z3-mental', 'Numără rândul: unu, doi, trei', ARRAY['minge']::text[], ARRAY['„Rând unu… rând doi… rând trei.”', '„Gata. Trei.”', 'Dacă vrea: regula — „Doar trei rânduri, apoi mingea la loc.”']::text[], 'A legat trei schimburi de gata.', 'Mingea afară'),
  ('s32-b23-z3-resurse', 'După trei — mingea la loc', ARRAY['minge', 'coș']::text[], ARRAY['„Trei. Ajunge.”', '„Minge. La loc.”', 'Dacă vrea: el duce mingea — regula „Eu / tu cărați pe rând.”']::text[], 'După trei, mingea e la loc.', 'Mingea afară'),
  ('s32-b23-z3-social', 'Așteaptă rând — fără grabă', ARRAY['minge']::text[], ARRAY['Voi țineți: „Rândul meu.” — el așteaptă.', '„Rând.” — îi dați mingea.', 'Dacă vrea: regula — „Mâinile pe genunchi când aștepți.”']::text[], 'A așteptat rândul pe scurt.', 'Mingea afară'),
  ('s32-b23-z4-fizic', 'Alergare scurtă după minge', ARRAY['minge', 'curte liberă']::text[], ARRAY['Rulați mingea: „Minge — aleargă.”', 'El aduce mingea: „Rândul tău.”', 'Dacă vrea: regula — „O alergare, apoi pauză.”']::text[], 'A alergat scurt după minge.', 'Mingea afară'),
  ('s32-b23-z4-mental', 'Mingea afară — unde e locul ei?', ARRAY['minge', 'coș / colț']::text[], ARRAY['„Mingea joacă afară.” Gest pe curte.', '„Mingea doarme aici.” Gest pe coș.', 'Dacă vrea: regula — „După joacă, mingea la loc.”']::text[], 'A legat mingea de locul de joacă și de la loc.', 'Mingea afară'),
  ('s32-b23-z4-resurse', 'Mingea rămâne în zonă — limită', ARRAY['minge', 'zonă de joacă']::text[], ARRAY['„Minge aici.” — arătați zona.', '„Ajunge afară din zonă — oprim.”', 'Dacă vrea: regula inventată — „Minge nu trece de… (reper).”']::text[], 'Limita de zonă e clară.', 'Mingea afară'),
  ('s32-b23-z4-social', 'Trei schimburi — apoi gata împreună', ARRAY['minge']::text[], ARRAY['Trei schimburi: „Rândul meu… rând… rândul meu.”', 'Împreună: „Gata.”', 'Dacă vrea: regula — „După gata, batem din palme o dată.”']::text[], 'Ați închis cele 3 schimburi împreună.', 'Mingea afară'),
  ('s32-b23-z5-fizic', 'Picior pe minge — atingere blândă', ARRAY['minge moale']::text[], ARRAY['Picior pe minge: „Minge.”', 'Împingeți blând: „Rând.” — o rundă.', 'Dacă vrea: regula — „Picior ușor, nu lovitură tare.”']::text[], 'A atins mingea cu piciorul pe scurt.', 'Mingea afară'),
  ('s32-b23-z5-mental', 'Trei cuvinte: minge, rând, rândul meu', ARRAY['minge']::text[], ARRAY['„Minge.” pe minge; „Rând.” când o dați; „Rândul meu.” când o luați.', 'O rundă de etichete.', 'Dacă vrea: el inventează ordinea — regula lui de azi.']::text[], 'A auzit cele trei etichete pe minge.', 'Mingea afară'),
  ('s32-b23-z5-resurse', 'Alege: încă un rând sau la loc', ARRAY['minge']::text[], ARRAY['Arătați 2: „Încă un rând. Sau mingea la loc.”', 'Alegeți: „Ajunge așa.”', 'Dacă vrea: regula — „Alegerea e gata, nu schimbăm.”']::text[], 'Ați ales continuare sau închidere.', 'Mingea afară'),
  ('s32-b23-z5-social', 'Rândul meu spus înainte de a lua mingea', ARRAY['minge']::text[], ARRAY['Modelați: „Rândul meu.” — apoi luați mingea.', 'El: „Rând / rândul meu” — apoi primește.', 'Dacă vrea: regula — „Spui, apoi iei mingea.”']::text[], 'A legat cuvântul de a lua mingea.', 'Mingea afară'),
  ('s32-b23-z6-fizic', 'Traseu: ușa → iarbă cu minge', ARRAY['minge', 'ușă', 'iarbă']::text[], ARRAY['Din casă / prag: „Mingea afară.”', 'Pe iarbă: 1–2 aruncări: „Rând.”', 'Dacă vrea: regula — „Mingea joacă doar pe iarbă azi.”']::text[], 'A dus mingea pe iarbă și a jucat scurt.', 'Mingea afară'),
  ('s32-b23-z6-mental', 'Regula zilei — una singură', ARRAY['minge']::text[], ARRAY['Alegeți o regulă scurtă: „Mingea pe iarbă.” sau „Trei rânduri.”', 'Spuneți-o o dată: „Regula.”', 'Dacă vrea: el alege care regulă (1 din 2).']::text[], 'A auzit / ales o regulă scurtă.', 'Mingea afară'),
  ('s32-b23-z6-resurse', 'Joaca cu minge de azi — gata', ARRAY['minge', 'coș']::text[], ARRAY['„Ajunge. Mingea la loc.”', '„Gata.”', 'Dacă vrea: regula de închidere — „Mingea în coș = gata jocul.”']::text[], 'Joaca e închisă; mingea la loc.', 'Mingea afară'),
  ('s32-b23-z6-social', 'Joacă paralel: eu cu minge, tu lângă', ARRAY['minge (sau 2)']::text[], ARRAY['Voi rulați: „Rândul meu — minge.”', 'El poate rula lângă sau privi: „Rând.”', 'Dacă vrea: regula — „Fiecare are minge / spațiu.”']::text[], 'Ați jucat în paralel pe scurt.', 'Mingea afară'),
  ('s32-b23-z7-fizic', 'Joacă liberă cu minge — el alege', ARRAY['minge', 'curte / preș']::text[], ARRAY['El alege aruncat / rulat / pe loc; voi urmăriți blând.', 'Fără grabă: „Minge… gata.”', 'Dacă vrea: o regulă blândă aleasă de el — sau zero regulă.']::text[], 'A jucat liber cu mingea pe scurt.', 'Mingea afară'),
  ('s32-b23-z7-mental', 'Favoritul: minge, rând sau rândul meu?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place minge, rând sau rândul meu?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: inventați o regulă de seară legată de alegere.']::text[], 'A ales un cuvânt favorit din temă.', 'Mingea afară'),
  ('s32-b23-z7-resurse', 'Mingea la loc — seara', ARRAY['minge', 'coș']::text[], ARRAY['„Minge. La loc.”', '„Ajunge. Acum e liniște.”', 'Dacă vrea: un ultim rând mimă fără minge, apoi calm.']::text[], 'Mingea e la loc înainte de calm.', 'Mingea afară'),
  ('s32-b23-z7-social', 'Ritual: bună seara după minge', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara.” Gest: mâini fără minge.', '„Noapte bună. Minge… gata.”', 'Dacă vrea: regula de noapte — „Mingea doarme; noi dormim.”']::text[], 'Ați închis seara blând după mingea afară.', 'Mingea afară'),
  ('s33-b23-z1-fizic', 'Umplem găleata cu nisip pe scurt', ARRAY['nisip (cutie / curte)', 'găleată mică']::text[], ARRAY['Mâna în nisip: „Nisip.” — puneți puțin în găleată.', '„Plin.” — arătați găleata când e plină pe jumătate.', 'Dacă vrea: umpleți cu scop — „Nisip în găleată, nu pe jos.”']::text[], 'A umplut găleata puțin cu nisip.', 'Nisip și găleată'),
  ('s33-b23-z1-mental', 'Plin și gol pe găleată', ARRAY['găleată', 'nisip']::text[], ARRAY['Arătați găleata cu nisip: „Plin.”', 'Goliți pe o zonă de nisip: „Gol.”', 'Dacă vrea: el arată care e plin și care e gol.']::text[], 'A deosebit plin de gol pe scurt.', 'Nisip și găleată'),
  ('s33-b23-z1-resurse', 'Nisipul rămâne în zonă', ARRAY['zonă de nisip / cutie', 'găleată']::text[], ARRAY['Arătați zona: „Nisip aici.”', '„Ajunge.” — nisipul rămâne în zonă, nu pe trepte.', 'Dacă vrea: umpleți cu scop — doar în cutie / pe preș.']::text[], 'Nisipul a rămas în zona de joacă.', 'Nisip și găleată'),
  ('s33-b23-z1-social', 'Schimb găleata pe rând', ARRAY['găleată', 'nisip']::text[], ARRAY['„Acum eu” — găleată cu nisip.', '„Acum tu.” — schimb blând.', 'Dacă vrea: umpleți pe rând cu scop — fiecare o mână de nisip.']::text[], 'Ați schimbat găleata pe rând.', 'Nisip și găleată'),
  ('s33-b23-z2-fizic', 'Golește găleata — gol', ARRAY['găleată cu nisip', 'zonă de nisip']::text[], ARRAY['Răsturnați blând: „Gol.”', 'Atingeți nisipul golit: „Nisip.”', 'Dacă vrea: umpleți din nou cu scop — „Plin pentru golire.”']::text[], 'A golit găleata pe scurt.', 'Nisip și găleată'),
  ('s33-b23-z2-mental', 'Nisip: unde e? — în găleată sau pe jos', ARRAY['găleată', 'nisip']::text[], ARRAY['„Unde e nisip?” — arătați găleata: „Aici — plin.”', 'Arătați pe jos / cutie: „Aici — gol găleata.”', 'Dacă vrea: el spune (sau arată) unde e nisip acum.']::text[], 'A localizat nisipul în găleată sau pe jos.', 'Nisip și găleată'),
  ('s33-b23-z2-resurse', 'Găleata la loc după joacă', ARRAY['găleată']::text[], ARRAY['După joacă: „La loc.”', '„Gol. Ajunge.”', 'Dacă vrea: alegeți locul găleții (1 din 2 rafturi / colțuri).']::text[], 'Găleata e la loc.', 'Nisip și găleată'),
  ('s33-b23-z2-social', 'Arată adultului găleata plin', ARRAY['găleată cu nisip']::text[], ARRAY['El arată (sau voi ghidați): „Uite. Plin.”', 'Voi: „Da. Nisip.” — o clipă împreună.', 'Dacă vrea: umpleți împreună cu scop — încă o mână.']::text[], 'A arătat găleata plină adultului.', 'Nisip și găleată'),
  ('s33-b23-z3-fizic', 'Lopată mică: nisip în găleată', ARRAY['lopată mică (sau mână)', 'găleată', 'nisip']::text[], ARRAY['O lopată / mână: „Nisip… plin.”', '2–3 mișcări, fără grabă.', 'Dacă vrea: umpleți cu scop — „Până la linie / până aici.”']::text[], 'A pus nisip în găleată cu unealtă sau mână.', 'Nisip și găleată'),
  ('s33-b23-z3-mental', 'Trei cuvinte: nisip, plin, gol', ARRAY['găleată', 'nisip']::text[], ARRAY['„Nisip.” pe nisip; „Plin.” pe găleata plină; „Gol.” pe goală.', 'O rundă de etichete.', 'Dacă vrea: el alege ordinea cuvintelor — scopul lui de azi.']::text[], 'A auzit cele trei etichete pe nisip.', 'Nisip și găleată'),
  ('s33-b23-z3-resurse', 'Alege: încă o umplere sau ajunge', ARRAY['găleată', 'nisip']::text[], ARRAY['Arătați 2: „Încă nisip — plin. Sau ajunge — gol la loc.”', 'Alegeți: „Ajunge așa.”', 'Dacă vrea: umpleți o dată cu scop, apoi gata.']::text[], 'Ați ales continuare sau închidere.', 'Nisip și găleată'),
  ('s33-b23-z3-social', 'Rândul la lopată / mână', ARRAY['lopată sau mână', 'găleată']::text[], ARRAY['„Acum eu — nisip.”', '„Acum tu.”', 'Dacă vrea: pe rând umpleți cu scop — „Fiecare o lopată.”']::text[], 'Ați schimbat rândul la umplut.', 'Nisip și găleată'),
  ('s33-b23-z4-fizic', 'Cărăm găleata plin pe scurt', ARRAY['găleată cu puțin nisip']::text[], ARRAY['Cărați împreună: „Plin… nisip.” — 3–5 pași.', 'Așezați: „Aici.”', 'Dacă vrea: umpleți la destinație cu scop — o mână în plus.']::text[], 'A cărat găleata pe scurt.', 'Nisip și găleată'),
  ('s33-b23-z4-mental', 'De ce umplem? — o frază', ARRAY['găleată', 'nisip']::text[], ARRAY['Arătați găleata: „Nisip. Plin.”', '„De ce umplem?” — „Ca să căram / ca să turnăm.”', 'Dacă vrea: el repetă scopul — gest spre gol / turnat.']::text[], 'A auzit un scop pentru umplere.', 'Nisip și găleată'),
  ('s33-b23-z4-resurse', 'După joacă — nisipul în cutie, găleata la loc', ARRAY['cutie de nisip', 'găleată']::text[], ARRAY['„Nisip în cutie.” — „La loc.”', '„Ajunge.”', 'Dacă vrea: gol găleata în cutie cu scop, apoi raft.']::text[], 'Zona e strânsă; găleata la loc.', 'Nisip și găleată'),
  ('s33-b23-z4-social', 'Turnăm nisip împreună — gol', ARRAY['găleată cu nisip', 'zonă']::text[], ARRAY['Țineți împreună: „Gol.”', 'Nisip pe zonă: „Nisip.”', 'Dacă vrea: umpleți din nou cu scop — „Plin pentru gol împreună.”']::text[], 'Ați golit găleata împreună.', 'Nisip și găleată'),
  ('s33-b23-z5-fizic', 'Degete în nisip — textură', ARRAY['nisip']::text[], ARRAY['Degete în nisip: „Nisip.” — 10–15 secunde.', 'Strângeți puțin: „Plin mână.” — deschideți: „Gol.”', 'Dacă vrea: umpleți găleata cu scop doar cu degetele.']::text[], 'A simțit textura nisipului.', 'Nisip și găleată'),
  ('s33-b23-z5-mental', 'Plin mână și gol mână', ARRAY['nisip']::text[], ARRAY['Mână cu nisip: „Plin.”', 'Mână deschisă: „Gol.”', 'Dacă vrea: el arată plin / gol pe mâinile lui.']::text[], 'A legat plin/gol de mână.', 'Nisip și găleată'),
  ('s33-b23-z5-resurse', 'Limită: nisip doar în zonă', ARRAY['zonă de nisip']::text[], ARRAY['„Nisip aici. Ajunge.”', 'Dacă a căzut afară: „Înapoi în zonă.”', 'Dacă vrea: umpleți cutia cu scop — „Plin cutie, gol afară.”']::text[], 'Limita zonei e clară.', 'Nisip și găleată'),
  ('s33-b23-z5-social', 'Arată nisip unei persoane dragi', ARRAY['găleată / nisip']::text[], ARRAY['„Uite. Nisip.” — arătați împreună.', '„Plin.” pe găleată dacă e plină.', 'Dacă vrea: umpleți cu scop ca să arătați — o lopată.']::text[], 'A împărtășit nisipul cu cineva.', 'Nisip și găleată'),
  ('s33-b23-z6-fizic', 'Traseu: cutie → găleată plin → gol pe zonă', ARRAY['cutie de nisip', 'găleată']::text[], ARRAY['Din cutie: „Nisip… plin.”', 'Pe zonă: „Gol.” — 1–2 ture.', 'Dacă vrea: umpleți cu scop — „Plin pentru golire pe preș.”']::text[], 'A făcut traseul umple–golește pe scurt.', 'Nisip și găleată'),
  ('s33-b23-z6-mental', 'Scopul zilei — una singură', ARRAY['găleată', 'nisip']::text[], ARRAY['Alegeți un scop: „Plin găleată.” sau „Gol pe cutie.”', 'Spuneți-l o dată: „Scop.”', 'Dacă vrea: el alege scopul (1 din 2).']::text[], 'A auzit / ales un scop scurt.', 'Nisip și găleată'),
  ('s33-b23-z6-resurse', 'Joaca cu nisip de azi — gata', ARRAY['găleată', 'cutie']::text[], ARRAY['„Ajunge. Nisip în cutie. Găleată la loc.”', '„Gol. Gata.”', 'Dacă vrea: un ultim plin cu scop, apoi strâns.']::text[], 'Joaca e închisă; nisipul la loc.', 'Nisip și găleată'),
  ('s33-b23-z6-social', 'Joacă paralel: eu plin, tu gol', ARRAY['2 găleți sau rând clar']::text[], ARRAY['Voi: „Plin — nisip.”', 'El: „Gol” sau privește — fără forțare.', 'Dacă vrea: schimbați rolurile cu scop — „Acum tu plin.”']::text[], 'Ați jucat în paralel pe scurt.', 'Nisip și găleată'),
  ('s33-b23-z7-fizic', 'Joacă liberă la nisip — el alege', ARRAY['nisip', 'găleată (opțional)']::text[], ARRAY['El alege umplut / golit / doar mână; voi urmăriți blând.', 'Fără grabă: „Nisip… gata.”', 'Dacă vrea: un scop blând ales de el — sau zero scop.']::text[], 'A jucat liber cu nisipul pe scurt.', 'Nisip și găleată'),
  ('s33-b23-z7-mental', 'Favoritul: nisip, plin sau gol?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place nisip, plin sau gol?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: un mic scop de seară legat de alegere.']::text[], 'A ales un cuvânt favorit din temă.', 'Nisip și găleată'),
  ('s33-b23-z7-resurse', 'Găleata și nisip la loc — seara', ARRAY['găleată', 'cutie de nisip']::text[], ARRAY['„Nisip. La loc.”', '„Ajunge. Acum e liniște.”', 'Dacă vrea: gol găleata o dată, apoi raft.']::text[], 'Totul e la loc înainte de calm.', 'Nisip și găleată'),
  ('s33-b23-z7-social', 'Ritual: bună seara după nisip', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara.” Gest: mâini fără nisip.', '„Noapte bună. Nisip… gata.”', 'Dacă vrea: „Găleata doarme gol; noi dormim.”']::text[], 'Ați închis seara blând după nisip.', 'Nisip și găleată'),
  ('s34-b23-z1-fizic', 'Strângem frunză de pe pământ pe scurt', ARRAY['curte / pământ', '2–3 frunze']::text[], ARRAY['Aplecați-vă: „Frunză.” — ridicați una de pe pământ.', '„Toamnă.” — arătați unde a căzut / umbra pe pământ.', 'Dacă vrea: „De ce e diferit?” — frunză uscată față de pământ.']::text[], 'A strâns o frunză de pe pământ.', 'Umbre pe pământ'),
  ('s34-b23-z1-mental', 'Frunză și pământ — două tipuri', ARRAY['frunză', 'pământ / noroi uscat']::text[], ARRAY['Arătați: „Frunză.” — apoi „Pământ.”', '„Ce e diferit?” — textură / culoare pe scurt.', 'Dacă vrea: el spune (sau arată) de ce e diferit.']::text[], 'A deosebit frunză de pământ pe scurt.', 'Umbre pe pământ'),
  ('s34-b23-z1-resurse', 'Colectăm 3 — în cutie — gata', ARRAY['cutie mică', 'frunze / pietricele de pe pământ']::text[], ARRAY['„Unu… doi… trei.” — în cutie.', '„Ajunge. Gata.”', 'Dacă vrea: „De ce e diferit?” pe obiectul 2 față de 1.']::text[], 'Ați colectat 3 și ați închis cutia.', 'Umbre pe pământ'),
  ('s34-b23-z1-social', 'Împarte frunză cu adultul', ARRAY['frunză']::text[], ARRAY['Oferiți frunză: „Pentru tine.”', 'El poate da înapoi: „Frunză.”', 'Dacă vrea: „De ce e diferit?” — leafa lui față de a voastră.']::text[], 'Ați împărțit o frunză pe scurt.', 'Umbre pe pământ'),
  ('s34-b23-z2-fizic', 'Urmărim umbra pe pământ — toamnă', ARRAY['soare / lumină afară', 'pământ']::text[], ARRAY['Arătați umbra pe pământ: „Toamnă. Umbră pe pământ.”', 'Mutați corpul: umbra se mută — 10–20 secunde.', 'Dacă vrea: „De ce e diferit?” — umbră față de frunză pe pământ.']::text[], 'A văzut umbra pe pământ.', 'Umbre pe pământ'),
  ('s34-b23-z2-mental', 'Sortăm: frunză uscată și frunză verde', ARRAY['2 frunze diferite']::text[], ARRAY['„Frunză uscată.” — „Frunză verde.”', 'Sortați în 2 grămăjoare pe pământ.', 'Dacă vrea: „De ce e diferit?” — o frază scurtă.']::text[], 'A sortat două tipuri de frunze.', 'Umbre pe pământ'),
  ('s34-b23-z2-resurse', 'Cutia cu frunză — la loc', ARRAY['cutie']::text[], ARRAY['După colectat: „La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți unde stă cutia (1 din 2).']::text[], 'Cutia e la loc.', 'Umbre pe pământ'),
  ('s34-b23-z2-social', 'Arată umbra pe pământ adultului', ARRAY['lumină / soare', 'pământ']::text[], ARRAY['El arată (sau voi ghidați): „Uite. Toamnă pe pământ.”', 'Voi: „Da. Umbră.”', 'Dacă vrea: „De ce e diferit?” — umbra lui față de a voastră.']::text[], 'A arătat umbra adultului.', 'Umbre pe pământ'),
  ('s34-b23-z3-fizic', 'Mână pe pământ lângă frunză', ARRAY['pământ', 'frunză']::text[], ARRAY['Mână pe pământ: „Pământ.”', 'Mână pe frunză: „Frunză.” — 5–8 secunde fiecare.', 'Dacă vrea: „De ce e diferit?” — moale / aspru.']::text[], 'A atins pământul și frunza.', 'Umbre pe pământ'),
  ('s34-b23-z3-mental', 'Trei cuvinte: frunză, pământ, toamnă', ARRAY['frunză', 'pământ', 'umbră (opțional)']::text[], ARRAY['„Frunză.” pe frunză; „Pământ.” pe pământ; „Toamnă.” pe umbră / cădere.', 'O rundă de etichete.', 'Dacă vrea: el arată de ce e diferit frunză de pământ.']::text[], 'A auzit cele trei etichete afară.', 'Umbre pe pământ'),
  ('s34-b23-z3-resurse', 'Alege: încă un frunză sau gata cutia', ARRAY['cutie', 'frunză']::text[], ARRAY['Arătați 2: „Încă un frunză. Sau ajunge — cutia gata.”', 'Alegeți: „Ajunge așa.”', 'Dacă vrea: „De ce?” — motiv scurt pe alegere.']::text[], 'Ați ales continuare sau închidere.', 'Umbre pe pământ'),
  ('s34-b23-z3-social', 'Rândul la strâns frunză de pe pământ', ARRAY['frunze', 'pământ']::text[], ARRAY['„Acum eu — frunză.”', '„Acum tu.”', 'Dacă vrea: pe rând spuneți de ce e diferit leaful vostru.']::text[], 'Ați schimbat rândul la strâns.', 'Umbre pe pământ'),
  ('s34-b23-z4-fizic', 'Cărăm cutia cu 3 pe pământ', ARRAY['cutie cu 3 obiecte']::text[], ARRAY['Cărați împreună pe pământ: „Frunză… pământ.”', 'Așezați: „Aici. Gata.”', 'Dacă vrea: „De ce e diferit?” locul nou față de locul vechi.']::text[], 'A cărat cutia pe scurt.', 'Umbre pe pământ'),
  ('s34-b23-z4-mental', 'Texturi: frunză aspră și pământ fin', ARRAY['frunză', 'pământ']::text[], ARRAY['Atingeți: „Frunză — aspră.”', '„Pământ — altfel.”', 'Dacă vrea: el spune de ce e diferit — un cuvânt / gest.']::text[], 'A comparat două texturi.', 'Umbre pe pământ'),
  ('s34-b23-z4-resurse', 'După colectat — totul în cutie la loc', ARRAY['cutie', 'frunze']::text[], ARRAY['„În cutie. La loc.”', '„Ajunge.”', 'Dacă vrea: sortați frunză / pământ înainte de închis.']::text[], 'Totul e strâns în cutie.', 'Umbre pe pământ'),
  ('s34-b23-z4-social', 'Oferă frunză — mulțumesc pe scurt', ARRAY['frunză']::text[], ARRAY['El oferă frunză: „Pentru tine.”', 'Voi: „Mulțumesc.” — fără forțare pe el.', 'Dacă vrea: „De ce e diferit?” leafa dată față de cea păstrată.']::text[], 'Ați făcut un schimb blând cu frunza.', 'Umbre pe pământ'),
  ('s34-b23-z5-fizic', 'Pași pe pământ — umbră cade după noi', ARRAY['pământ / potecă', 'soare']::text[], ARRAY['3–5 pași pe pământ: „Pământ.”', 'Priviți umbra: „Toamnă.” — umbra vine după.', 'Dacă vrea: „De ce e diferit?” umbra față de frunză pe jos.']::text[], 'A mers pe pământ și a văzut umbra.', 'Umbre pe pământ'),
  ('s34-b23-z5-mental', 'Unde cade umbra — pe frunză sau pe pământ?', ARRAY['lumină', 'frunză pe pământ']::text[], ARRAY['Puneți frunză pe pământ: „Unde cade umbra?”', 'Arătați: pe frunză / pe pământ.', 'Dacă vrea: „De ce e diferit?” locul umbrei când mutați frunză.']::text[], 'A observat unde cade umbra.', 'Umbre pe pământ'),
  ('s34-b23-z5-social', 'Privim umbra pe pământ împreună', ARRAY['soare / lumină']::text[], ARRAY['Umăr la umăr: „Toamnă pe pământ.”', 'Arătați frunză dacă e lângă: „Frunză.”', 'Dacă vrea: „De ce e diferit?” umbra voastră față de a lui.']::text[], 'Ați privit umbra împreună.', 'Umbre pe pământ'),
  ('s34-b23-z6-fizic', 'Traseu: frunză pe pământ → cutie → gata', ARRAY['frunză', 'cutie', 'pământ']::text[], ARRAY['Ridicați frunză de pe pământ: „Frunză.”', 'În cutie: „Gata.”', 'Dacă vrea: „De ce e diferit?” frunză în cutie față de pe pământ.']::text[], 'A dus frunza din pământ în cutie.', 'Umbre pe pământ'),
  ('s34-b23-z6-mental', 'De ce e diferit? — o frază', ARRAY['2 obiecte: frunză și pământ / pietricică']::text[], ARRAY['Arătați ambele: „Frunză. Pământ.”', '„De ce e diferit?” — răspundeți scurt: „Unul e frunză, unul e pământ.”', 'Dacă vrea: el repetă gestul / cuvântul.']::text[], 'A auzit de ce sunt diferite.', 'Umbre pe pământ'),
  ('s34-b23-z6-resurse', 'Colectatul de azi — gata', ARRAY['cutie']::text[], ARRAY['„Ajunge. Cutia la loc.”', '„Gata.”', 'Dacă vrea: un frunză în plus doar dacă alege — apoi gata.']::text[], 'Colectatul e închis.', 'Umbre pe pământ'),
  ('s34-b23-z6-social', 'Sortăm împreună pe pământ', ARRAY['frunze / pietricele', 'pământ']::text[], ARRAY['„Frunză aici. Pământ / piatră acolo.”', 'Rândul: „Acum eu… acum tu.”', 'Dacă vrea: pe rând spuneți de ce e diferit.']::text[], 'Ați sortat împreună pe scurt.', 'Umbre pe pământ'),
  ('s34-b23-z7-fizic', 'Mișcare liberă pe pământ — el alege', ARRAY['curte / pământ']::text[], ARRAY['El alege pași / aplecat / umbră; voi urmăriți blând.', 'Fără grabă: „Pământ… gata.”', 'Dacă vrea: o frunză favorită ridicată — sau zero.']::text[], 'A explorat liber pe pământ pe scurt.', 'Umbre pe pământ'),
  ('s34-b23-z7-mental', 'Favoritul: frunză, pământ sau toamnă?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place frunză, pământ sau toamnă?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: „De ce e diferit?” favoritul față de celelalte.']::text[], 'A ales un cuvânt favorit din temă.', 'Umbre pe pământ'),
  ('s34-b23-z7-resurse', 'Cutia și frunză la loc — seara', ARRAY['cutie']::text[], ARRAY['„Frunză. La loc.”', '„Ajunge. Acum e liniște.”', 'Dacă vrea: o privire pe pământ pe geam — fără a colecta.']::text[], 'Cutia e la loc înainte de calm.', 'Umbre pe pământ'),
  ('s34-b23-z7-social', 'Ritual: bună seara după frunză și pământ', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara.” Gest: mâini goale.', '„Noapte bună. Frunză… pământ… gata.”', 'Dacă vrea: „Umbrele dorm; noi dormim.”']::text[], 'Ați închis seara blând după umbre pe pământ.', 'Umbre pe pământ'),
  ('s35-b23-z1-fizic', 'Turnat scurt afară — toarnă apă', ARRAY['vas mic cu apă', 'curte / iarbă']::text[], ARRAY['Afară: „Apă.” — țineți vasul împreună.', '„Toarnă.” — turnați puțin pe iarbă / în vas gol.', 'Dacă vrea: toarnă cu scop — pe plantă, nu pe pantofi.']::text[], 'A turnat puțină apă afară.', 'Apă afară (joc scurt)'),
  ('s35-b23-z1-mental', 'Ud și uscat afară', ARRAY['iarbă / pământ', 'apă']::text[], ARRAY['Arătați locul ud: „Apă. Ud.”', 'Arătați loc uscat: „Uscat.”', 'Dacă vrea: toarnă pe uscat cu scop — „Ca plantă să bea.”']::text[], 'A deosebit ud de uscat afară.', 'Apă afară (joc scurt)'),
  ('s35-b23-z1-resurse', 'Limită vas — fără risipă forțată', ARRAY['vas mic cu puțină apă']::text[], ARRAY['Arătați vasul: „Apă. Atât.”', '„Ajunge.” — când e gol / aproape gol.', 'Dacă vrea: toarnă ultimul strop pe plantă cu scop.']::text[], 'Limita vasului e clară.', 'Apă afară (joc scurt)'),
  ('s35-b23-z1-social', 'Udăm plantă împreună', ARRAY['plantă / ghiveci afară sau pe treaptă', 'vas']::text[], ARRAY['Umăr la umăr: „Plantă. Apă.”', '„Toarnă.” — puțin împreună.', 'Dacă vrea: toarnă cu scop — „Doar pe pământul plantă.”']::text[], 'Ați udat planta împreună pe scurt.', 'Apă afară (joc scurt)'),
  ('s35-b23-z2-fizic', 'Cărăm vasul cu apă afară', ARRAY['vas mic cu puțină apă']::text[], ARRAY['Cărați: „Apă… afară.” — 3–5 pași.', 'Așezați lângă plantă: „Aici.”', 'Dacă vrea: toarnă cu scop imediat după așezat.']::text[], 'A cărat vasul afară.', 'Apă afară (joc scurt)'),
  ('s35-b23-z2-mental', 'Toarnă pe plantă sau pe iarbă?', ARRAY['vas', 'plantă', 'iarbă']::text[], ARRAY['Arătați 2: „Plantă — apă. Iarbă — apă.”', 'Alegeți unde toarnă — o dată.', 'Dacă vrea: el alege scopul toarnă (plantă sau iarbă).']::text[], 'A legat turnatul de un loc.', 'Apă afară (joc scurt)'),
  ('s35-b23-z2-resurse', 'Vasul la loc după toarnă', ARRAY['vas']::text[], ARRAY['După toarnă: „La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți unde stă vasul (1 din 2).']::text[], 'Vasul e la loc.', 'Apă afară (joc scurt)'),
  ('s35-b23-z2-social', 'Rândul la toarnă pe plantă', ARRAY['vas', 'plantă']::text[], ARRAY['„Acum eu — toarnă.”', '„Acum tu.” — dacă vrea; altfel voi închideți.', 'Dacă vrea: fiecare toarnă cu scop — o picătură pe plantă.']::text[], 'Ați schimbat rândul la turnat.', 'Apă afară (joc scurt)'),
  ('s35-b23-z3-fizic', 'Degete pe apă — apoi pe uscat', ARRAY['vas / iarbă udă', 'loc uscat']::text[], ARRAY['Deget pe apă: „Apă. Ud.”', 'Deget pe uscat: „Uscat.”', 'Dacă vrea: toarnă puțin pe uscat cu scop — vedeți schimbarea.']::text[], 'A simțit ud și uscat.', 'Apă afară (joc scurt)'),
  ('s35-b23-z3-mental', 'Trei cuvinte: toarnă, apă, plantă', ARRAY['vas', 'plantă']::text[], ARRAY['„Apă.” pe vas; „Toarnă.” când turnați; „Plantă.” pe plantă.', 'O rundă de etichete.', 'Dacă vrea: el ordonează — toarnă pe plantă cu apă.']::text[], 'A auzit cele trei etichete pe apă.', 'Apă afară (joc scurt)'),
  ('s35-b23-z3-resurse', 'Alege: încă un toarnă sau ajunge', ARRAY['vas']::text[], ARRAY['Arătați 2: „Încă toarnă. Sau ajunge — vas la loc.”', 'Alegeți: „Ajunge așa.”', 'Dacă vrea: un toarnă cu scop pe plantă, apoi gata.']::text[], 'Ați ales continuare sau închidere.', 'Apă afară (joc scurt)'),
  ('s35-b23-z3-social', 'Arată adultului unde e plantă udată', ARRAY['plantă']::text[], ARRAY['El arată (sau voi ghidați): „Uite. Plantă. Apă.”', 'Voi: „Da. Toarnă.”', 'Dacă vrea: spuneți scopul — „Ca plantă să bea.”']::text[], 'A arătat planta udată.', 'Apă afară (joc scurt)'),
  ('s35-b23-z4-fizic', 'Toarnă din vas în vas — afară', ARRAY['2 vase mici', 'apă puțină']::text[], ARRAY['„Apă.” — „Toarnă.” din vasul A în B.', 'O singură rundă, fără risipă pe jos dacă se poate.', 'Dacă vrea: toarnă cu scop — umpleți vasul plantă.']::text[], 'A turnat din vas în vas pe scurt.', 'Apă afară (joc scurt)'),
  ('s35-b23-z4-mental', 'De ce toarnă pe plantă? — o frază', ARRAY['plantă', 'vas']::text[], ARRAY['Arătați plantă: „Plantă.”', '„De ce toarnă apă?” — „Ca să bea / să crească.”', 'Dacă vrea: el repetă gestul toarnă pe plantă.']::text[], 'A auzit de ce turnăm pe plantă.', 'Apă afară (joc scurt)'),
  ('s35-b23-z4-resurse', 'După joc — vasele goale la loc', ARRAY['2 vase']::text[], ARRAY['„La loc.” — vasele.', '„Ajunge. Gata.”', 'Dacă vrea: alegeți care vas e pentru plantă (1 din 2).']::text[], 'Vasele sunt la loc.', 'Apă afară (joc scurt)'),
  ('s35-b23-z4-social', 'Ținem vasul împreună la toarnă', ARRAY['vas', 'plantă']::text[], ARRAY['Ambele mâini pe vas: „Apă… toarnă.”', 'Pe plantă: „Plantă.”', 'Dacă vrea: toarnă cu scop — opriți la „ajunge”.']::text[], 'Ați turnat ținând vasul împreună.', 'Apă afară (joc scurt)'),
  ('s35-b23-z5-fizic', 'Pași spre plantă cu apă', ARRAY['vas', 'plantă afară / pe treaptă']::text[], ARRAY['Pași: „Apă… plantă.”', 'La plantă: „Toarnă.” — puțin.', 'Dacă vrea: toarnă cu scop doar pe pământ, nu pe frunze.']::text[], 'A dus apa la plantă și a turnat.', 'Apă afară (joc scurt)'),
  ('s35-b23-z5-mental', 'Unde e apă acum — vas sau plantă?', ARRAY['vas', 'plantă']::text[], ARRAY['Înainte de toarnă: „Apă în vas.”', 'După: „Apă la plantă.”', 'Dacă vrea: el arată unde a mers apă.']::text[], 'A urmărit unde a mers apa.', 'Apă afară (joc scurt)'),
  ('s35-b23-z5-resurse', 'Fără risipă — vasul e limita', ARRAY['vas mic']::text[], ARRAY['„Atât apă. Ajunge.”', 'Nu reumpleți forțat.', 'Dacă vrea: toarnă ultimul strop pe plantă cu scop, apoi gata jocul.']::text[], 'Nu s-a forțat risipa; vasul e limita.', 'Apă afară (joc scurt)'),
  ('s35-b23-z5-social', 'Oferă apă plantă — grijă împreună', ARRAY['vas', 'plantă']::text[], ARRAY['„Pentru plantă.” — toarnă mic.', 'Stați o clipă: „Apă. Plantă.”', 'Dacă vrea: el spune scopul — „Ca să bea.”']::text[], 'Ați oferit apă plantei împreună.', 'Apă afară (joc scurt)'),
  ('s35-b23-z6-fizic', 'Traseu: casă → afară → toarnă pe plantă', ARRAY['vas', 'ușă', 'plantă']::text[], ARRAY['Din casă: „Apă afară.”', 'La plantă: „Toarnă.” — 1 rundă.', 'Dacă vrea: toarnă cu scop — „Doar pe plantă azi.”']::text[], 'A dus apa afară și a turnat pe plantă.', 'Apă afară (joc scurt)'),
  ('s35-b23-z6-mental', 'Scopul toarnă de azi — unul', ARRAY['vas', 'plantă / iarbă']::text[], ARRAY['Alegeți: „Toarnă pe plantă.” sau „Toarnă pe iarbă.”', 'Spuneți scopul o dată.', 'Dacă vrea: el alege scopul (1 din 2).']::text[], 'A auzit / ales un scop de turnat.', 'Apă afară (joc scurt)'),
  ('s35-b23-z6-resurse', 'Jocul cu apă de azi — gata', ARRAY['vas']::text[], ARRAY['„Ajunge. Vas la loc.”', '„Gata.”', 'Dacă vrea: un toarnă mimă fără apă, apoi calm.']::text[], 'Jocul e închis; vasul la loc.', 'Apă afară (joc scurt)'),
  ('s35-b23-z6-social', 'Toarnă paralel: eu pe plantă, tu privești', ARRAY['vas', 'plantă']::text[], ARRAY['Voi: „Toarnă — plantă.”', 'El poate turna după sau doar privi: „Apă.”', 'Dacă vrea: schimbați — el toarnă cu scop, voi urmăriți.']::text[], 'Ați împărțit rolurile la turnat.', 'Apă afară (joc scurt)'),
  ('s35-b23-z7-fizic', 'Joacă liberă cu apă afară — el alege', ARRAY['vas mic (opțional)', 'curte']::text[], ARRAY['El alege toarnă / doar privire / degete pe ud; voi urmăriți blând.', 'Fără grabă: „Apă… gata.”', 'Dacă vrea: un toarnă pe plantă cu scop — sau zero.']::text[], 'A explorat liber apa afară pe scurt.', 'Apă afară (joc scurt)'),
  ('s35-b23-z7-mental', 'Favoritul: toarnă, apă sau plantă?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place toarnă, apă sau plantă?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: un scop de seară legat de alegere.']::text[], 'A ales un cuvânt favorit din temă.', 'Apă afară (joc scurt)'),
  ('s35-b23-z7-resurse', 'Vasul la loc — seara', ARRAY['vas']::text[], ARRAY['„Apă. La loc.”', '„Ajunge. Acum e liniște.”', 'Dacă vrea: vasul gol pe raft — ritual scurt.']::text[], 'Vasul e la loc înainte de calm.', 'Apă afară (joc scurt)'),
  ('s35-b23-z7-social', 'Ritual: bună seara după apă afară', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara.” Gest: mâini uscate.', '„Noapte bună. Plantă… apă… gata.”', 'Dacă vrea: „Plantă doarme; noi dormim.”']::text[], 'Ați închis seara blând după apa afară.', 'Apă afară (joc scurt)'),
  ('s36-b23-z1-fizic', 'Afară: uite pe insecte de departe 2–3 min', ARRAY['curte / grădină', 'încălțăminte de afară']::text[], ARRAY['Stați liniștiți: „Uite.” — 30–60 secunde, de departe.', 'Dacă vedeți insectă: „Uite. Departe.” — fără a prinde.', 'Dacă vrea: „Ce face?” — o întrebare blândă (zboară / merge).']::text[], 'A privit afară de departe pe scurt.', 'Insecte de departe'),
  ('s36-b23-z1-mental', 'Sunet sau uite — pasăre, câine sau insectă?', ARRAY['urechi / ochi afară']::text[], ARRAY['Auziți / vedeți: „Pasăre?” — gest sus; „Câine?” — gest jos / gard.', 'Insectă: „Uite. Departe.” — fără etichetă forțată.', 'Dacă vrea: „Ce face?” pe ce ați observat.']::text[], 'A legat sunet/privire de o direcție.', 'Insecte de departe'),
  ('s36-b23-z1-resurse', 'Observăm — fără a prinde', ARRAY['mâini vizibile']::text[], ARRAY['„Uite. Doar privim.” — mâinile jos.', '„Ajunge.” — fără goană după insectă.', 'Dacă vrea: „Ce face?” — răspundeți voi dacă el tace.']::text[], 'A observat fără a prinde.', 'Insecte de departe'),
  ('s36-b23-z1-social', 'Arată adultului ce uite vede', ARRAY['curte']::text[], ARRAY['El arată (sau voi ghidați): „Uite.”', 'Voi: „Da. Departe.”', 'Dacă vrea: „Ce face?” — o frază scurtă împreună.']::text[], 'A arătat adultului ceva văzut.', 'Insecte de departe'),
  ('s36-b23-z2-fizic', 'Pași scurți — apoi uite pe loc', ARRAY['curte']::text[], ARRAY['3–5 pași: „Uite.”', 'Opriți-vă: corp calm 20–40 secunde — insecte de departe.', 'Dacă vrea: „Ce face?” pe o insectă / pasăre dacă apare.']::text[], 'A mers scurt și a privit pe loc.', 'Insecte de departe'),
  ('s36-b23-z2-mental', 'Pasăre sus, câine jos, insectă pe iarbă — uite', ARRAY['curte']::text[], ARRAY['„Pasăre — uite sus.”', '„Câine — uite” (dacă e / mimă); insectă: „Uite pe iarbă.”', 'Dacă vrea: „Ce face?” — alegeți unul din trei.']::text[], 'A orientat privirea pe direcții.', 'Insecte de departe'),
  ('s36-b23-z2-resurse', 'Limită: doar uite, nu alergăm', ARRAY['curte']::text[], ARRAY['„Uite. Ajunge.” — fără goană.', 'Mâinile rămân jos.', 'Dacă vrea: „Ce face?” fără a ne apropia mai mult.']::text[], 'Limita de observare e clară.', 'Insecte de departe'),
  ('s36-b23-z2-social', 'Rândul la uite pe iarbă', ARRAY['iarbă / curte']::text[], ARRAY['„Acum eu — uite.”', '„Acum tu.”', 'Dacă vrea: pe rând „Ce face?” pe ce vedeți.']::text[], 'Ați schimbat rândul la privire.', 'Insecte de departe'),
  ('s36-b23-z3-fizic', 'Corp liniștit: uite de pe treaptă', ARRAY['treaptă / bancă / loc ridicat']::text[], ARRAY['Pe loc ridicat: „Uite.” — de departe.', '20–40 secunde calm.', 'Dacă vrea: „Ce face?” pe insectă / pasăre văzută.']::text[], 'A privit calm de pe un loc ridicat.', 'Insecte de departe'),
  ('s36-b23-z3-mental', 'Trei cuvinte: pasăre, câine, uite', ARRAY['curte / geam']::text[], ARRAY['„Uite.” pe ce vedeți; „Pasăre.” sus; „Câine.” (dacă e / mimă).', 'Insectă rămâne „uite departe” în RO.', 'Dacă vrea: „Ce face pasărea / câine?” — o întrebare.']::text[], 'A auzit cele trei etichete pe observare.', 'Insecte de departe'),
  ('s36-b23-z3-resurse', 'Alege: uite de la geam sau din curte', ARRAY['geam', 'curte']::text[], ARRAY['Arătați 2: „Geam — uite. Curte — uite.”', 'Alegeți: „Ajunge așa.”', 'Dacă vrea: „Ce face?” din locul ales.']::text[], 'Ați ales locul de observare.', 'Insecte de departe'),
  ('s36-b23-z3-social', 'Uite împreună — umăr la umăr', ARRAY['curte']::text[], ARRAY['Stați împreună: „Uite.”', 'Arătați departe: insectă / pasăre dacă e.', 'Dacă vrea: „Ce face?” — răspundeți pe rând.']::text[], 'Ați privit împreună de departe.', 'Insecte de departe'),
  ('s36-b23-z4-fizic', 'Deget pe aer — uite, nu atingere', ARRAY['curte']::text[], ARRAY['Degetul arată: „Uite.” — fără a atinge insecta.', 'Mâna jos după 5–10 secunde.', 'Dacă vrea: „Ce face?” — fără a ne apropia.']::text[], 'A arătat fără a prinde.', 'Insecte de departe'),
  ('s36-b23-z4-mental', 'Ce face? — zboară / merge / stă', ARRAY['insectă sau pasăre văzută / mimă']::text[], ARRAY['„Uite. Ce face?”', 'Voi: „Zboară.” / „Merge.” / „Stă.” — un răspuns.', 'Dacă vrea: el alege gestul care potrivește.']::text[], 'A legat observația de o acțiune.', 'Insecte de departe'),
  ('s36-b23-z4-resurse', 'După uite — ne întoarcem în casă', ARRAY['ușă']::text[], ARRAY['„Ajunge. Înapoi.”', '„Uite gata.”', 'Dacă vrea: o ultimă întrebare „ce face?” pe prag.']::text[], 'V-ați întors după observare.', 'Insecte de departe'),
  ('s36-b23-z4-social', 'Arată uite unei persoane dragi', ARRAY['curte / geam']::text[], ARRAY['„Uite.” — arătați împreună de departe.', 'Pasăre / câine / insectă — ce e.', 'Dacă vrea: „Ce face?” spus persoanei dragi.']::text[], 'A împărtășit privirea cu cineva.', 'Insecte de departe'),
  ('s36-b23-z5-fizic', 'Urechi afară, apoi uite', ARRAY['curte']::text[], ARRAY['Urechi: 15–20 secunde — pasăre / câine / liniște.', 'Apoi ochi: „Uite.” pe iarbă de departe.', 'Dacă vrea: „Ce face?” pe ce ați auzit sau văzut.']::text[], 'A ascultat și a privit pe scurt.', 'Insecte de departe'),
  ('s36-b23-z5-mental', 'Direcție: pasăre sus sau uite pe iarbă?', ARRAY['curte']::text[], ARRAY['„Pasăre — uite sus.”', '„Insectă — uite pe iarbă.”', 'Dacă vrea: „Ce face?” pe direcția aleasă.']::text[], 'A ales o direcție de privire.', 'Insecte de departe'),
  ('s36-b23-z5-resurse', 'Mâinile jos — regula uite', '{}'::text[], ARRAY['„Uite. Mâinile jos. Ajunge.”', 'Fără prindere.', 'Dacă vrea: „Ce face?” doar cu ochii, nu cu mâinile.']::text[], 'Regula mâinilor jos e clară.', 'Insecte de departe'),
  ('s36-b23-z5-social', 'Rândul: eu uite, tu uite', ARRAY['curte']::text[], ARRAY['„Acum eu — uite.”', '„Acum tu — uite.”', 'Dacă vrea: pe rând „Ce face pasărea / câine / insecta?”']::text[], 'Ați schimbat rândul la uite.', 'Insecte de departe'),
  ('s36-b23-z6-fizic', 'Întindem scurt înainte de uite', ARRAY['curte']::text[], ARRAY['Brațele sus: „Uite sus — pasăre.”', 'Apoi brațele jos: „Uite pe iarbă.” — insecte de departe.', 'Dacă vrea: „Ce face?” după întindem.']::text[], 'A făcut întindem și a privit.', 'Insecte de departe'),
  ('s36-b23-z6-mental', 'Întrebarea zilei — ce face?', ARRAY['curte / geam']::text[], ARRAY['Alegeți un țintă: insectă / pasăre / câine (sau mimă).', '„Ce face?” — un răspuns scurt.', 'Dacă vrea: el pune întrebarea „ce face?” către voi.']::text[], 'Ați folosit întrebarea „ce face?” o dată.', 'Insecte de departe'),
  ('s36-b23-z6-resurse', 'Uite de azi — gata', ARRAY['ușă / prag']::text[], ARRAY['„Ajunge. Uite gata.”', 'Înapoi în casă fără forțare.', 'Dacă vrea: un uite mimă pe geam, apoi gata.']::text[], 'Observarea e închisă.', 'Insecte de departe'),
  ('s36-b23-z6-social', 'Uite paralel: eu pasăre, tu iarbă', ARRAY['curte']::text[], ARRAY['Voi: „Uite — pasăre.”', 'El: „Uite” pe iarbă / insectă — sau privește liber.', 'Dacă vrea: schimbați ținta și „Ce face?” pe fiecare.']::text[], 'Ați privit în paralel pe scurt.', 'Insecte de departe'),
  ('s36-b23-z7-fizic', 'Uite liber afară — el alege', ARRAY['curte / geam']::text[], ARRAY['El alege geam / curte / treaptă; voi urmăriți blând.', 'Fără grabă: „Uite… gata.”', 'Dacă vrea: o întrebare „ce face?” — sau zero.']::text[], 'A privit liber pe scurt.', 'Insecte de departe'),
  ('s36-b23-z7-mental', 'Favoritul: pasăre, câine sau uite?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place pasăre, câine sau uite?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: „Ce face?” legat de favorit.']::text[], 'A ales un cuvânt favorit din temă.', 'Insecte de departe'),
  ('s36-b23-z7-resurse', 'La loc în casă după uite — seara', ARRAY['încălțăminte / ușă']::text[], ARRAY['„Înapoi. La loc.” — pantofi / prag.', '„Ajunge. Acum e liniște.”', 'Dacă vrea: un uite pe geam seara, fără a ieși.']::text[], 'Ați închis afară; liniște în casă.', 'Insecte de departe'),
  ('s36-b23-z7-social', 'Ritual: bună seara după uite', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara.” Gest: ochi închiși o clipă.', '„Noapte bună. Uite… gata.”', 'Dacă vrea: „Insectele dorm departe; noi dormim.”']::text[], 'Ați închis seara blând după insecte de departe.', 'Insecte de departe'),
  ('s37-b23-z1-fizic', 'Din lumină în umbră — loc răcoros', ARRAY['zonă cu soare / lumină', 'loc umbrit (copac / perete / umbrelă)']::text[], ARRAY['Stați scurt în lumină: „Lumină. Cald.”', 'Mutați corpul în umbră: „Umbră. Răcoare.” — 10–15 secunde.', 'Dacă vrea: mutați un obiect (minge / pălărie) din lumină în umbră.']::text[], 'A mutat corpul din lumină în umbră răcoroasă.', 'Umbră și loc răcoros'),
  ('s37-b23-z1-mental', 'Ce s-a schimbat? — lumină și umbră', ARRAY['loc luminos și umbros']::text[], ARRAY['Mâna în lumină: „Lumină.” — apoi în umbră: „Umbră.”', '„Ce s-a schimbat?” — „Aici cald; aici răcoare.”', 'Dacă vrea: mutați un obiect mic lumină↔umbră și întrebați iar.']::text[], 'A observat diferența lumină / umbră pe corp.', 'Umbră și loc răcoros'),
  ('s37-b23-z1-resurse', 'Stinge / aprinde — gata (adult)', ARRAY['lampă sau întrerupător (doar adultul)']::text[], ARRAY['Adultul stinge blând: „Întuneric.”', 'Aprinde: „Lumină. Gata.” — o dată e destul.', 'Dacă vrea: mutați un obiect lângă lampă — lumină — apoi deoparte — umbră.']::text[], 'Ați stins și aprins o dată; jocul e închis.', 'Umbră și loc răcoros'),
  ('s37-b23-z1-social', 'Arătăm umbră celuilalt la loc răcoros', ARRAY['perete luminat sau pământ cu umbră']::text[], ARRAY['La umbră / pe perete: „Uite umbră — a mea.”', 'Ajutați-l: „Uite umbră — a ta.”', 'Dacă vrea: mutați un obiect între voi — umbra obiectului pe rând.']::text[], 'Ați arătat umbra unul altuia la loc răcoros.', 'Umbră și loc răcoros'),
  ('s37-b23-z2-fizic', 'Pași din umbră în lumină și înapoi', ARRAY['zonă umbră → zonă lumină']::text[], ARRAY['Din umbră: „Umbră. Răcoare.” — 3 pași.', 'În lumină: „Lumină.” — apoi înapoi în umbră.', 'Dacă vrea: el mută o jucărie pe același traseu lumină↔umbră.']::text[], 'A mers umbră–lumină–umbră pe scurt.', 'Umbră și loc răcoros'),
  ('s37-b23-z2-mental', 'Lumină, întuneric, umbră — trei etichete', ARRAY['lampă (adult) / fereastră / umbră']::text[], ARRAY['Aprindeți sau arătați fereastra: „Lumină.”', 'Stingeți puțin / colț: „Întuneric.” — pe umbră: „Umbră.”', 'Dacă vrea: mutați un obiect din lumină în întuneric / umbră.']::text[], 'A auzit lumină, întuneric și umbră pe locuri reale.', 'Umbră și loc răcoros'),
  ('s37-b23-z2-resurse', 'Lampa — ajunge, nu mai stingem', ARRAY['lampă']::text[], ARRAY['După joc: „Ajunge. Lampa rămâne așa.”', '„Gata.” — fără alte comutări.', 'Dacă vrea: alegeți împreună unde stă un obiect — lumină sau umbră.']::text[], 'Jocul cu lampa e închis.', 'Umbră și loc răcoros'),
  ('s37-b23-z2-social', 'Rândul la locul răcoros', ARRAY['bancă / scaun la umbră', 'zonă lumină']::text[], ARRAY['„Acum eu” — stați în umbră.', '„Acum tu” — el la loc răcoros (sau invers).', 'Dacă vrea: pe rând mutați un obiect din lumină în umbră.']::text[], 'Ați schimbat rândul la locul răcoros.', 'Umbră și loc răcoros'),
  ('s37-b23-z3-fizic', 'Așezăm la umbră — umbră răcoros', ARRAY['scaun / bancă / preș la umbră']::text[], ARRAY['Așezați-vă: „Umbră. Jos. Răcoare.” — 15–20 secunde.', 'Atingeți podeaua / pământul umbrit: „Răcoare.”', 'Dacă vrea: mutați scaunul / preșul puțin spre lumină, apoi înapoi în umbră.']::text[], 'S-a așezat scurt la loc răcoros.', 'Umbră și loc răcoros'),
  ('s37-b23-z3-mental', 'Unde e mai răcoare — lumină sau umbră?', ARRAY['două zone clare']::text[], ARRAY['Arătați lumină: „Lumină. Cald.”', 'Arătați umbră: „Umbră. Răcoare.” — „Unde stăm?”', 'Dacă vrea: mutați un obiect în zona aleasă — lumină↔umbră.']::text[], 'A comparat cald în lumină cu răcoare în umbră.', 'Umbră și loc răcoros'),
  ('s37-b23-z3-resurse', 'Pălăria / obiectul la umbră — la loc', ARRAY['pălărie sau jucărie', 'loc umbrit']::text[], ARRAY['Puneți obiectul în umbră: „Aici. Răcoare.”', 'După: „La loc. Ajunge.”', 'Dacă vrea: mutați obiectul lumină↔umbră o dată, apoi la loc.']::text[], 'Obiectul e așezat; jocul e gata.', 'Umbră și loc răcoros'),
  ('s37-b23-z3-social', 'Umbrele se întâlnesc pe perete', ARRAY['perete luminat']::text[], ARRAY['Apropiați umbră pe perete: „Uite — umbrele.”', '„Lumină pe noi; umbră pe perete.”', 'Dacă vrea: mutați o mână / un obiect — umbră se mișcă.']::text[], 'Ați întâlnit umbrele pe perete.', 'Umbră și loc răcoros'),
  ('s37-b23-z4-fizic', 'Traseu: lumină → umbră → lumină', ARRAY['două zone clare afară sau în casă']::text[], ARRAY['Parcurgeți: lumină, apoi umbră (răcoare), apoi lumină.', 'Numiți: „Lumină. Umbră. Lumină.”', 'Dacă vrea: el poartă un obiect pe traseu — mută lumină↔umbră.']::text[], 'A parcurs traseul lumină–umbră–lumină.', 'Umbră și loc răcoros'),
  ('s37-b23-z4-mental', 'Obiect în lumină, obiect în umbră', ARRAY['2 obiecte mici', 'zonă lumină și umbră']::text[], ARRAY['Unul în lumină: „Lumină.”', 'Celălalt în umbră: „Umbră.” — „Care e în umbră?”', 'Dacă vrea: schimbați locurile — mutați obiectele lumină↔umbră.']::text[], 'A văzut obiecte în lumină și în umbră.', 'Umbră și loc răcoros'),
  ('s37-b23-z4-resurse', 'Stins o dată — întuneric — apoi ajunge', ARRAY['lampă (adult)']::text[], ARRAY['Stingeți: „Întuneric.”', 'Aprindeți: „Lumină. Ajunge. Gata.”', 'Dacă vrea: mutați un obiect lângă lampă (lumină) și departe (umbră).']::text[], 'Ciclu stins/aprins închis cu ajunge.', 'Umbră și loc răcoros'),
  ('s37-b23-z4-social', 'Arată umbră unei persoane dragi', ARRAY['perete / pământ luminat']::text[], ARRAY['„Uite. Umbră.” — arătați împreună.', 'Persoana (sau voi): „Da. Lumină pe tine.”', 'Dacă vrea: el mută un obiect ca să vadă umbră pe pământ.']::text[], 'A împărtășit umbra cu cineva.', 'Umbră și loc răcoros'),
  ('s37-b23-z5-fizic', 'Mișcare în lumină, calm în umbră', ARRAY['zonă lumină / umbră']::text[], ARRAY['În lumină: 2–3 pași / sărituri mici: „Lumină.”', 'În umbră: stați liniștiți: „Umbră. Răcoare.”', 'Dacă vrea: mutați o minge din lumină în umbră — apoi calm.']::text[], 'A legat mișcarea de lumină și calmul de umbră.', 'Umbră și loc răcoros'),
  ('s37-b23-z5-mental', 'Unde e întuneric — colț sau cameră?', ARRAY['2 colțuri / lampă']::text[], ARRAY['Arătați un colț mai luminos: „Lumină.”', 'Altul: „Întuneric. Mai întuneric.” — pe umbră: „Umbră.”', 'Dacă vrea: mutați un obiect în colțul întuneric / umbră.']::text[], 'A comparat lumină și întuneric pe două locuri.', 'Umbră și loc răcoros'),
  ('s37-b23-z5-resurse', 'Alege: stăm în lumină sau în umbră', ARRAY['2 locuri clare']::text[], ARRAY['„Lumină (cald) sau umbră (răcoare)?”', 'El alege; mergeți acolo: „Alegerea ta. Ajunge.”', 'Dacă vrea: mutați un obiect în locul ales.']::text[], 'A ales unde stați; alegerea e respectată.', 'Umbră și loc răcoros'),
  ('s37-b23-z5-social', 'Umbră a mea, umbră a ta', ARRAY['perete luminat / pământ']::text[], ARRAY['„A mea — umbră.” Apoi: „A ta.”', 'Mișcați pe rând o mână în lumină.', 'Dacă vrea: mutați un obiect pe rând — fiecare își vede umbră.']::text[], 'Ați numit umbra mea / umbra ta.', 'Umbră și loc răcoros'),
  ('s37-b23-z6-fizic', 'De la fereastră lumină spre umbră în cameră', ARRAY['fereastră', 'colț umbrit']::text[], ARRAY['La fereastră: „Lumină.”', '5 pași spre umbră: „Umbră. Răcoare.”', 'Dacă vrea: cărați un obiect pe același drum lumină↔umbră.']::text[], 'A mers de la lumină de fereastră spre umbră.', 'Umbră și loc răcoros'),
  ('s37-b23-z6-mental', 'Trei cuvinte: lumină, întuneric, umbră', ARRAY['lampă / perete / umbră']::text[], ARRAY['„Lumină.” pe lumină; „Întuneric.” pe stins / colț; „Umbră.” pe umbră.', 'O rundă de etichete cu gest.', 'Dacă vrea: el alege ordinea — apoi mutați un obiect pe cuvântul lui.']::text[], 'A auzit cele trei etichete pe locuri reale.', 'Umbră și loc răcoros'),
  ('s37-b23-z6-resurse', 'Lampa și locul răcoros — gata', ARRAY['lampă', 'scaun / preș la umbră']::text[], ARRAY['Lampa la loc: „La loc.”', 'Locul răcoros lăsat: „Ajunge. Gata.”', 'Dacă vrea: un ultim obiect mutat lumină↔umbră, apoi gata.']::text[], 'Spațiul e lăsat în ordine.', 'Umbră și loc răcoros'),
  ('s37-b23-z6-social', 'Joacă paralel: eu lumină, tu umbră', ARRAY['două zone']::text[], ARRAY['Voi în lumină; el în umbră (sau invers).', '„Eu lumină. Tu umbră — răcoare.”', 'Dacă vrea: schimbați zonele; mutați un obiect odată cu voi.']::text[], 'Ați jucat paralel pe lumină și umbră.', 'Umbră și loc răcoros'),
  ('s37-b23-z7-fizic', 'Loc răcoros liber — el alege', ARRAY['cameră / curte cu lumină și umbră']::text[], ARRAY['El alege lumină sau umbră; voi urmăriți blând.', 'Fără grabă, fără test: „Răcoare… gata.”', 'Dacă vrea: mutați împreună un obiect în zona favorită.']::text[], 'A ales liber zona de azi.', 'Umbră și loc răcoros'),
  ('s37-b23-z7-mental', 'Favoritul: lumină, întuneric sau umbră?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place lumină, întuneric sau umbră?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: mutați un obiect legat de cuvântul favorit.']::text[], 'A ales un cuvânt favorit din temă.', 'Umbră și loc răcoros'),
  ('s37-b23-z7-resurse', 'Lumina de seară — ajunge', ARRAY['lampă de seară']::text[], ARRAY['Alegeți o lumină blândă: „Lumină. Ajunge așa.”', '„Gata. Acum e liniște.” — întuneric blând în cameră.', 'Dacă vrea: un obiect pe noptieră — lumină mică lângă el.']::text[], 'Lumina de seară e setată; jocul e gata.', 'Umbră și loc răcoros'),
  ('s37-b23-z7-social', 'Ritual: bună seara la loc răcoros', ARRAY['lampă slabă opțională', 'colț umbrit']::text[], ARRAY['Șoptiți: „Bună seara.” Gest pe umbră mică.', '„Noapte bună. Întuneric… odihnă.”', 'Dacă vrea: un ultim obiect mutat în umbră, apoi liniște.']::text[], 'Ați închis seara blând la umbră și răcoare.', 'Umbră și loc răcoros'),
  ('s38-b23-z1-fizic', 'Piciorul pe verde — iarbă pe scurt', ARRAY['curte / iarbă', 'încălțăminte de afară (sau desculț dacă e sigur)']::text[], ARRAY['Ieșiți: „Verde. Iarbă.” — 3–5 pași cu piciorul pe iarbă.', 'Atingeți iarba cu mâna: „Plantă. Verde.”', 'Dacă vrea: spuneți „Udăm ca să crește — să crească.” — gest pe iarbă.']::text[], 'A pus piciorul pe iarbă și a atins verdele.', 'Piciorul pe iarbă'),
  ('s38-b23-z1-mental', 'Verde nou și verde vechi pe iarbă', ARRAY['iarbă', 'opțional: fir uscat / frunză veche']::text[], ARRAY['Arătați iarba proaspătă: „Verde. Nou.”', 'Arătați un fir mai vechi / uscat: „Vechi.” — „Ce e diferit?”', 'Dacă vrea: el arată care e verde și spune (sau gest) de ce udăm.']::text[], 'A deosebit verde nou de vechi pe iarbă.', 'Piciorul pe iarbă'),
  ('s38-b23-z1-resurse', 'Apă pentru plantă — ajunge', ARRAY['pahar mic cu apă', 'plantă / ghiveci sau pat de iarbă']::text[], ARRAY['Turnați puțin: „Apă. Plantă.”', '„Ajunge.” — opriți; paharul deoparte.', 'Dacă vrea: „De ce udăm?” — „Ca să crește.”']::text[], 'Planta / iarba a primit puțină apă; ajunge e clar.', 'Piciorul pe iarbă'),
  ('s38-b23-z1-social', 'Grijă împreună — picior lângă plantă', ARRAY['iarbă / plantă']::text[], ARRAY['Stați umăr la umăr, picioare pe verde: „Plantă. Verde.”', 'Atingeți blând: „Crește.”', 'Dacă vrea: el spune (sau arată) de ce udăm — voi completați blând.']::text[], 'Ați îngrijit iarba / planta împreună pe scurt.', 'Piciorul pe iarbă'),
  ('s38-b23-z2-fizic', 'Desculț pe verde — dacă e bine', ARRAY['iarbă uscată / sigură', 'sau încălțăminte subțire']::text[], ARRAY['Dacă e sigur: un picior pe verde: „Verde.” — 10 secunde.', 'Altfel: talpa încălțămintei pe iarbă: „Plantă.”', 'Dacă vrea: „Udăm ca iarba să crește.” — gest pe sol.']::text[], 'A simțit iarba sub picior (sau talpă).', 'Piciorul pe iarbă'),
  ('s38-b23-z2-mental', 'Iarbă și plantă — care e care?', ARRAY['iarbă', 'plantă în ghiveci (opțional)']::text[], ARRAY['Arătați iarba: „Verde. Iarbă.”', 'Arătați planta: „Plantă.”', 'Dacă vrea: „De ce udăm plantă?” — gest spre apă / sol.']::text[], 'A legat iarba de planta din ghiveci.', 'Piciorul pe iarbă'),
  ('s38-b23-z2-social', 'Arată verde de sub picior adultului', ARRAY['iarbă']::text[], ARRAY['El arată (sau voi ghidați): „Uite. Verde.”', 'Voi: „Da. Plantă sub picior.” — o clipă împreună.', 'Dacă vrea: spuneți împreună de ce udăm — o frază scurtă.']::text[], 'A arătat iarba de sub picior adultului.', 'Piciorul pe iarbă'),
  ('s38-b23-z3-fizic', 'Îngenunchem — mână și picior pe verde', ARRAY['iarbă / curte']::text[], ARRAY['Îngenuncheați: „Verde.” — mână pe iarbă.', 'Un picior pe iarbă: „Plantă.” — 5–8 secunde.', 'Dacă vrea: „Udăm ca să crește.” — gest pe sol.']::text[], 'A stat scurt cu mână și picior pe iarbă.', 'Piciorul pe iarbă'),
  ('s38-b23-z3-mental', 'Unde e verde sub picior?', ARRAY['iarbă / plantă']::text[], ARRAY['„Unde e verde?” — el arată iarba sub picior.', '„Da. Plantă.”', 'Dacă vrea: „De ce e verde?” — legați de udat / crește.']::text[], 'A găsit verdele sub picior.', 'Piciorul pe iarbă'),
  ('s38-b23-z3-resurse', 'Alege: udăm azi sau mâine', ARRAY['plantă / iarbă', 'pahar (opțional)']::text[], ARRAY['Arătați 2: „Azi — apă. Mâine — așteptăm.”', 'Alegeți împreună: „Ajunge așa.”', 'Dacă vrea: spuneți de ce — „Ca să crește / ca să nu fie prea mult.”']::text[], 'Ați ales când udați; fără forțare.', 'Piciorul pe iarbă'),
  ('s38-b23-z3-social', 'Rândul la picior pe verde', ARRAY['iarbă']::text[], ARRAY['„Acum eu” — un picior pe verde.', '„Acum tu.”', 'Dacă vrea: pe rând spuneți „crește” după fiecare pas pe iarbă.']::text[], 'Ați schimbat rândul la picior pe iarbă.', 'Piciorul pe iarbă'),
  ('s38-b23-z4-fizic', 'Cărăm paharul spre plantă — pe lângă iarbă', ARRAY['pahar mic cu puțină apă', 'plantă / zonă de udat']::text[], ARRAY['Cărați paharul: pași pe verde: „Apă… plantă.”', 'Turnați puțin: „Crește.” — apoi gata.', 'Dacă vrea: el spune de ce ați udat — „Ca să crește.”']::text[], 'A cărat apa pe lângă iarbă și a udat pe scurt.', 'Piciorul pe iarbă'),
  ('s38-b23-z4-mental', 'De ce udăm? — o frază', ARRAY['plantă / iarbă', 'pahar']::text[], ARRAY['Arătați: „Plantă. Verde.” — piciorul pe iarbă.', '„De ce udăm?” — „Ca să crește.”', 'Dacă vrea: el repetă gestul / cuvântul crește.']::text[], 'A auzit de ce udăm legat de crește.', 'Piciorul pe iarbă'),
  ('s38-b23-z4-social', 'Udăm pe rând — o picătură lângă verde', ARRAY['pahar', 'plantă / iarbă']::text[], ARRAY['„Acum eu” — o picătură.', '„Acum tu” — dacă vrea; altfel voi închideți.', 'Dacă vrea: „De ce?” — „Ca plantă să crește.”']::text[], 'Ați udat pe rând pe scurt.', 'Piciorul pe iarbă'),
  ('s38-b23-z5-fizic', 'Întindem pe verde — crește sus', ARRAY['iarbă / curte', 'spațiu liber']::text[], ARRAY['Picior pe verde; brațele sus: „Crește. Sus.” — 3–5 secunde.', 'Mâinile pe genunchi: „Verde. Jos.”', 'Dacă vrea: arătați iarba — „Și ea crește.”']::text[], 'A făcut întindem scurt cu piciorul pe iarbă.', 'Piciorul pe iarbă'),
  ('s38-b23-z5-mental', 'Trei cuvinte: plantă, verde, crește', ARRAY['iarbă / plantă']::text[], ARRAY['Picior pe iarbă: „Verde.”', 'Pe plantă: „Plantă.” — gest sus: „Crește.”', 'Dacă vrea: el arată care cuvânt vrea să-l audă iar.']::text[], 'A auzit cele trei cuvinte pe iarbă / plantă.', 'Piciorul pe iarbă'),
  ('s38-b23-z5-resurse', 'Ghiveciul / zona — la loc după joacă pe verde', ARRAY['ghiveci opțional', 'încălțăminte']::text[], ARRAY['Dacă ați mutat ghiveciul: „Plantă. La loc.”', 'Pantofii la prag: „Ajunge.”', 'Dacă vrea: alegeți pervazul sau masa pentru plantă (1 din 2).']::text[], 'Zona e lăsată în ordine după iarba de azi.', 'Piciorul pe iarbă'),
  ('s38-b23-z5-social', 'Arată verde de sub picior altcuiva', ARRAY['iarbă', 'persoană dragă (sau foto)']::text[], ARRAY['Mergeți împreună: „Verde. Uite — sub picior.”', 'El arată iarba.', 'Dacă vrea: spuneți celeilalte persoane de ce udăm.']::text[], 'A arătat iarba altcuiva.', 'Piciorul pe iarbă'),
  ('s38-b23-z6-fizic', 'Traseu: verde afară → plantă pe pervaz', ARRAY['curte / iarbă', 'plantă pe pervaz']::text[], ARRAY['Pași pe verde: „Verde.” — picior pe iarbă.', 'Înapoi la plantă: „Plantă. Crește.”', 'Dacă vrea: pe traseu spuneți de ce udăm — o frază.']::text[], 'A legat iarba de planta din casă pe scurt.', 'Piciorul pe iarbă'),
  ('s38-b23-z6-mental', 'Aceeași verde — afară și pe pervaz?', ARRAY['iarbă', 'plantă pe pervaz']::text[], ARRAY['„Afară — verde sub picior.” Gest pe iarbă.', '„Aici — plantă.” pe pervaz. „Amândouă crește?”', 'Dacă vrea: el alege pe care o udăm azi.']::text[], 'A legat verdele din afară de planta din casă.', 'Piciorul pe iarbă'),
  ('s38-b23-z6-resurse', 'Udatul de azi — gata', ARRAY['pahar', 'plantă']::text[], ARRAY['Dacă ați udat: „Ajunge. Gata.”', 'Paharul la loc.', 'Dacă vrea: un ultim „Crește” pe plantă, apoi opriți.']::text[], 'Udatul e închis; gata e clar.', 'Piciorul pe iarbă'),
  ('s38-b23-z6-social', 'Împreună: picior pe verde, mână pe plantă', ARRAY['iarbă / plantă']::text[], ARRAY['Umăr la umăr: „Verde… plantă.”', 'O rundă scurtă — picior și mână.', 'Dacă vrea: inventați o frază — „Udăm ca să crește.”']::text[], 'Ați legat piciorul pe iarbă de planta din casă.', 'Piciorul pe iarbă'),
  ('s38-b23-z7-fizic', 'Picior pe verde liber — el alege', ARRAY['iarbă / plantă', 'spațiu liber']::text[], ARRAY['El alege: pași pe verde, doar privit, sau întindem; voi urmăriți blând.', 'Fără grabă: „Verde… gata.”', 'Dacă vrea: alegeți întindem „crește” sau doar picior pe iarbă.']::text[], 'A mișcat liber pe scurt pe iarbă.', 'Piciorul pe iarbă'),
  ('s38-b23-z7-mental', 'Favoritul: plantă, verde sau crește?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place plantă, verde sau crește?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: spuneți de ce udăm legat de alegerea lui.']::text[], 'A ales un cuvânt favorit din temă.', 'Piciorul pe iarbă'),
  ('s38-b23-z7-resurse', 'Înapoi în casă — pantofi la loc', ARRAY['încălțăminte', 'prag']::text[], ARRAY['„Înapoi. La loc.” — pantofi / prag.', '„Ajunge. Acum e liniște.”', 'Dacă vrea: o ultimă privire verde pe geam, fără a ieși.']::text[], 'Ați închis afară; pantofii la loc.', 'Piciorul pe iarbă'),
  ('s38-b23-z7-social', 'Ritual: bună seara după verde', ARRAY['plantă / pervaz']::text[], ARRAY['Șoptiți: „Bună seara.” Gest pe plantă: „Plantă.”', '„Noapte bună. Crește.”', 'Dacă vrea: un ultim „De ce udăm?” — răspuns șoptit, apoi odihnă.']::text[], 'Ați închis seara blând după piciorul pe iarbă.', 'Piciorul pe iarbă'),
  ('s39-b23-z1-fizic', 'Gustare: stai, vezi fruct, mestecă', ARRAY['fruct mic sigur (sau bucată)', 'scaun / masă']::text[], ARRAY['Stați la masă: „Uite. Fruct.” — arătați fructul.', 'O bucată: „Mâncăm.” — mestecați fără grabă.', 'Dacă vrea: rol — voi oferiți, el: „Mulțumesc.” (sau invers).']::text[], 'A văzut fructul, a stat și a mestecat pe scurt.', 'Fructe pe care le vedem'),
  ('s39-b23-z1-mental', 'Numește fruct — miros și gust mic', ARRAY['1 fruct cunoscut']::text[], ARRAY['Arătați: „Fruct.” — mirosiți: „Miros.”', 'O mușcătură mică: „Gust. Mâncăm.”', 'Dacă vrea: rol — el oferă, voi mulțumiți: „Mulțumesc.”']::text[], 'A numit, mirosit și gustat fructul pe scurt.', 'Fructe pe care le vedem'),
  ('s39-b23-z1-resurse', 'Ajunge — farfuria cu fruct la loc', ARRAY['farfurie / castron mic']::text[], ARRAY['După gustare: „Ajunge. Încă? Nu acum.”', 'Farfuria la chiuvetă sau pe blat: „La loc.”', 'Dacă vrea: el oferă farfuria goală adultului — voi: „Mulțumesc.”']::text[], 'Farfuria e la loc; porția e închisă.', 'Fructe pe care le vedem'),
  ('s39-b23-z1-social', 'Oferă o bucată de fruct — mulțumesc', ARRAY['2 bucăți mici de fruct']::text[], ARRAY['Oferiți-i una: „Pentru tine. Fruct.”', 'El poate oferi una: voi: „Mulțumesc.”', 'Dacă vrea: schimbați rolurile — el oferă primul.']::text[], 'Ați oferit și ați mulțumit pe o bucată de fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z2-fizic', 'Mestecăm fruct încet — același ritm', ARRAY['bucată moale de fruct']::text[], ARRAY['Luați o bucată: „Fruct. Mâncăm. Încet.”', 'Mestecați de câteva ori împreună, pe ritm blând.', 'Dacă vrea: el oferă următoarea bucată; voi: „Mulțumesc.”']::text[], 'A mestecat fructul încet alături de adult.', 'Fructe pe care le vedem'),
  ('s39-b23-z2-mental', 'Ce fruct e pe farfurie?', ARRAY['1–2 fructe vizibile']::text[], ARRAY['Arătați: „Ce e asta?” — „Fruct.” + numele (măr / banană…).', 'Miros scurt: „Miros de fruct.”', 'Dacă vrea: el arată fruct-ul și îl oferă — voi mulțumiți.']::text[], 'A numit sau a privit fructul de pe farfurie.', 'Fructe pe care le vedem'),
  ('s39-b23-z2-resurse', 'Încă un fruct? — ajunge', ARRAY['farfurie cu 2 bucăți']::text[], ARRAY['Întrebați: „Încă?” — arătați o bucată de fruct.', 'Dacă da, una; apoi: „Ajunge. Gata.”', 'Dacă vrea: el spune „ajunge” sau împinge farfuria blând.']::text[], 'Porția de fruct s-a închis cu ajunge.', 'Fructe pe care le vedem'),
  ('s39-b23-z2-social', 'Rândul la oferit fruct', ARRAY['bol cu bucăți mici de fruct']::text[], ARRAY['Voi oferiți: „Acum eu. Fruct.”', 'Apoi: „Acum tu” — așteptați gestul lui.', 'Dacă vrea: „Mulțumesc” după fiecare oferire.']::text[], 'Ați schimbat rândul la oferit fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z3-fizic', 'Stăm pe scaun — vedem fruct, terminăm gura', ARRAY['scaun', 'o bucată de fruct']::text[], ARRAY['Stați: „Pe scaun. Uite fruct.”', 'Terminați gura: „Mâncăm. Gata gura.”', 'Dacă vrea: apoi el oferă restul / sâmburele la loc — voi: „Mulțumesc.”']::text[], 'A rămas pe scaun până a terminat gura cu fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z3-mental', 'Dulce sau acru? — două fruct', ARRAY['2 gusturi sigure de fruct (sau fruct / alt aliment)']::text[], ARRAY['Gustați primul: „Fruct. Așa.”', 'Al doilea: „Altul. Care îți place?”', 'Dacă vrea: el oferă favoritul adultului — „Mulțumesc” la schimb.']::text[], 'A comparat două gusturi de fruct pe scurt.', 'Fructe pe care le vedem'),
  ('s39-b23-z3-resurse', 'Farfuria goală după fruct — la loc', ARRAY['farfurie']::text[], ARRAY['Arătați: „Goală. Ajunge.”', 'La loc: „La chiuvetă / pe blat.”', 'Dacă vrea: alegeți chiuveta sau blatul.']::text[], 'Farfuria goală e la loc.', 'Fructe pe care le vedem'),
  ('s39-b23-z3-social', 'Oferă fruct altcuiva', ARRAY['1 bucată de fruct', 'persoană dragă']::text[], ARRAY['Mergeți împreună și oferiți: „Pentru tine. Fruct.”', 'Modelați: „Mulțumesc.” când primesc.', 'Dacă vrea: el ține bucata și o oferă singur.']::text[], 'A oferit o bucată de fruct cuiva.', 'Fructe pe care le vedem'),
  ('s39-b23-z4-fizic', 'Bea o înghițitură, apoi mâncăm fruct', ARRAY['pahar cu apă', 'bucată de fruct']::text[], ARRAY['Înghițitură: „Apă.”', 'Apoi: „Fruct. Mâncăm.”', 'Dacă vrea: el alege ordinea — și oferă apa sau fruct-ul — voi: „Mulțumesc.”']::text[], 'A legat o înghițitură de apă de o mestecare de fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z4-mental', 'Fruct — unde e fructul?', ARRAY['1 fruct', '1 alt aliment']::text[], ARRAY['Arătați: „Fruct.” pe fruct.', 'Arătați celălalt: „Nu e fruct.” — „Unde e fructul?”', 'Dacă vrea: el aduce fruct-ul și îl oferă — voi mulțumiți.']::text[], 'A găsit fructul dintre două.', 'Fructe pe care le vedem'),
  ('s39-b23-z4-resurse', 'Alege: încă fruct sau ajunge', ARRAY['farfurie cu rest', 'gest „gata”']::text[], ARRAY['„Încă fruct sau ajunge?” — arătați ambele gesturi.', 'El alege; respectați: „Bine. Așa facem.”', 'Dacă vrea: farfuria la loc imediat după alegere.']::text[], 'A ales încă sau ajunge; alegerea e respectată.', 'Fructe pe care le vedem'),
  ('s39-b23-z4-social', 'Eu mulțumesc, tu oferi fruct', ARRAY['1 bucată de fruct']::text[], ARRAY['El oferă (asistat); voi: „Mulțumesc.”', 'Schimbați: voi oferiți fruct; așteptați mulțumirea lui.', 'Dacă vrea: încă un schimb scurt pe rol.']::text[], 'Ați jucat rolul ofer / mulțumesc pe fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z5-fizic', 'Masă scurtă cu fruct: stai, mâncăm, gata', ARRAY['masă / scaun', 'porție mică de fruct']::text[], ARRAY['Secvență: „Stăm. Fruct. Mâncăm. Gata.”', 'O porție mică, fără grabă.', 'Dacă vrea: el anunță „gata” și oferă farfuria — voi: „Mulțumesc.”']::text[], 'A parcurs stai–mănâncă–gata cu fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z5-mental', 'Mâncăm, fruct, mulțumesc — la masă', ARRAY['fruct', 'bucată de oferit']::text[], ARRAY['„Mâncăm” pe mestecare. „Fruct” pe fruct.', 'Oferiți: „Mulțumesc” când primește.', 'Dacă vrea: el spune unul din cele trei (sau gest) pe rol.']::text[], 'A auzit mâncăm / fruct / mulțumesc la masă.', 'Fructe pe care le vedem'),
  ('s39-b23-z5-resurse', 'Totul de masă cu fruct — la loc', ARRAY['farfurie', 'pahar', 'șervet']::text[], ARRAY['Strângeți: „La loc.”', '„Ajunge. Masa e gata.”', 'Dacă vrea: el alege ce duce primul — paharul sau farfuria.']::text[], 'Obiectele de masă sunt la loc.', 'Fructe pe care le vedem'),
  ('s39-b23-z5-social', 'Masă împreună — mulțumesc pentru fruct', ARRAY['masă']::text[], ARRAY['La final: „Mulțumesc pentru fruct.” împreună.', '„Mulțumesc.” pe rând, blând.', 'Dacă vrea: el mulțumește primului adult — rol ofer / mulțumesc.']::text[], 'Ați mulțumit împreună la final de masă cu fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z6-fizic', 'Alege fruct — gustare liberă', ARRAY['2 fructe / 2 bucăți diferite']::text[], ARRAY['Arătați două: „Fruct… fruct.” — el alege una.', 'Stați și mestecați: „Mâncăm.” — fără presiune.', 'Dacă vrea: după, oferă o bucată mică adultului — „Mulțumesc.”']::text[], 'A ales și a gustat un fruct liber.', 'Fructe pe care le vedem'),
  ('s39-b23-z6-mental', 'De ce ne place acest fruct?', ARRAY['fructul ales']::text[], ARRAY['Arătați: „Îți place. Fruct.”', '„De ce?” — oferiți: „Pentru că e dulce / moale.”', 'Dacă vrea: el oferă favoritul — voi: „Mulțumesc” + motivul lui.']::text[], 'A legat plăcerea de un motiv simplu pe fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z6-resurse', 'Restul de fruct — la loc sau la frigider', ARRAY['recipient / farfurie']::text[], ARRAY['„Ajunge. Restul la loc.”', 'Închideți: „Gata.”', 'Dacă vrea: alegeți blat sau frigider (cu adult).']::text[], 'Restul de fruct e pus la loc.', 'Fructe pe care le vedem'),
  ('s39-b23-z6-social', 'Joacă de rol: eu ofer fruct, tu mulțumesc', ARRAY['1–2 fructe sau jucării-fruct']::text[], ARRAY['Voi oferiți: „Fruct?” — el ia.', '„Mulțumesc!” la schimb — apoi inversați rolurile.', 'Dacă vrea: încă un schimb pe rolul ales de el.']::text[], 'Ați jucat rolul ofer / mulțumesc pe fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z7-fizic', 'Masă blândă cu fruct — ritmul lui', ARRAY['gustare mică de fruct opțională']::text[], ARRAY['El dictează: mestecă, bea, sau doar privește fruct-ul.', 'Fără forțare.', 'Dacă vrea: voi oferiți o bucată și așteptați „mulțumesc” / gest.']::text[], 'A ales liber ritmul la masă cu fruct.', 'Fructe pe care le vedem'),
  ('s39-b23-z7-mental', 'Favoritul: ce fruct am văzut?', ARRAY['2 fructe / 2 amintiri arătate']::text[], ARRAY['Întrebați: „Ce fruct ți-a plăcut?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Fruct” sau „Mâncăm” pe favorită — apoi rol ofer / mulțumesc.']::text[], 'A ales sau a privit fructul favorit al săptămânii.', 'Fructe pe care le vedem'),
  ('s39-b23-z7-resurse', 'Masa cu fruct strânsă înainte de calm', ARRAY['farfurie / pahar']::text[], ARRAY['Strângeți: „La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: paharul favorit rămâne la vedere.']::text[], 'Masa e strânsă înainte de calm.', 'Fructe pe care le vedem'),
  ('s39-b23-z7-social', 'Ritual: bună seara — mulțumesc pentru fruct', '{}'::text[], ARRAY['Șoptiți: „Bună seara. Mulțumesc pentru fruct.”', '„Noapte bună.”', 'Dacă vrea: un ultim rol — el oferă un sărut pe obraz / gest; voi mulțumiți.']::text[], 'Ați închis seara blând după fructele văzute.', 'Fructe pe care le vedem'),
  ('s40-b23-z1-fizic', 'Cărăm 1 obiect pe treabă reală', ARRAY['1 obiect ușor de cărat (prosop / jucărie / cutie goală)']::text[], ARRAY['Alegeți treaba: „Ajutor.” — luați obiectul împreună.', 'Cărați 3–5 pași: „Cărăm.” — așezați: „Gata.”', 'Dacă vrea: alegeți ce cărăm din 2 obiecte — apoi încă o tură.']::text[], 'A cărat un obiect pe o treabă scurtă reală.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z1-mental', 'Plan: întâi… apoi…', ARRAY['1 obiect de cărat', 'loc de destinație']::text[], ARRAY['Spuneți: „Întâi cărăm — luăm.” Gest pe obiect.', '„Apoi gata — punem aici.” Gest pe loc.', 'Dacă vrea: el alege ce cărăm — voi spuneți planul pe obiectul lui.']::text[], 'A auzit un plan în doi pași pe treabă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z1-resurse', 'Termină — obiectul la loc', ARRAY['obiect cărat']::text[], ARRAY['După treabă: „Gata. La loc.”', '„Ajunge. Ajutor e gata.”', 'Dacă vrea: alegeți raftul sau cutia (1 din 2) pentru la loc.']::text[], 'Obiectul e la loc; treaba e închisă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z1-social', 'Ajutor: cer și ofer pe scurt', ARRAY['1 obiect ușor']::text[], ARRAY['Voi: „Ajutor, te rog?” — el ține / cărați împreună.', 'La final: „Gata. Mulțumesc.”', 'Dacă vrea: el alege ce cărăm și cere „ajutor” primul.']::text[], 'Ați cerut și oferit ajutor pe o treabă scurtă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z2-fizic', 'Cărăm două obiecte — pe rând', ARRAY['2 obiecte ușoare']::text[], ARRAY['Primul: „Cărăm.” — 3 pași — „Gata.”', 'Al doilea: „Ajutor… cărăm.” — așezați.', 'Dacă vrea: el alege ordinea — ce cărăm întâi.']::text[], 'A cărat două obiecte pe rând pe scurt.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z2-mental', 'Întâi ajutor, apoi cărăm, apoi gata', ARRAY['1 obiect']::text[], ARRAY['Trei etichete: „Ajutor.” (ne uităm împreună) — „Cărăm.” — „Gata.”', 'O rundă pe treaba reală.', 'Dacă vrea: el alege ce cărăm și spune (sau arată) pasul următor.']::text[], 'A legat ajutor–cărăm–gata pe o treabă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z2-resurse', 'După cărăm — totul la loc', ARRAY['cele 2 obiecte']::text[], ARRAY['„Gata. La loc.” — ambele.', '„Ajunge.”', 'Dacă vrea: alegeți care obiect merge primul la loc.']::text[], 'Ambele obiecte sunt la loc.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z2-social', 'Rândul la cărăm', ARRAY['1 obiect']::text[], ARRAY['„Acum eu — cărăm.”', '„Acum tu — ajutor.”', 'Dacă vrea: el alege ce cărăm pentru următorul rând.']::text[], 'Ați schimbat rândul la cărat.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z3-fizic', 'Treabă reală: cărăm rufele / jucăriile', ARRAY['coș mic / 2–3 jucării / un prosop']::text[], ARRAY['Arătați treaba: „Ajutor. Cărăm.” — luați 1–2 piese.', 'Duceți la locul lor: „Gata.”', 'Dacă vrea: alegeți ce cărăm — rufă sau jucărie (1 din 2).']::text[], 'A ajutat la o treabă reală cu cărat scurt.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z3-mental', 'De ce ajutor? — o frază', ARRAY['obiect de cărat']::text[], ARRAY['Arătați: „Ajutor — pentru că e greu / departe.”', '„Cărăm… gata.”', 'Dacă vrea: el alege ce cărăm și spune de ce (sau gest).']::text[], 'A auzit un motiv simplu pentru ajutor.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z3-resurse', 'Gata — coșul / cutia la loc', ARRAY['coș / cutie']::text[], ARRAY['După treabă: „Gata. La loc.”', '„Ajunge. Ajutor e gata.”', 'Dacă vrea: alegeți colțul coșului (1 din 2).']::text[], 'Coșul / cutia e la loc.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z3-social', 'Ofer ajutor adultului', ARRAY['1 obiect pe care adultul îl „are nevoie”']::text[], ARRAY['Voi: „Ajutor, te rog?” — el aduce / cărăm.', '„Gata. Mulțumesc.”', 'Dacă vrea: el alege ce cărăm ca ajutor pentru voi.']::text[], 'A oferit ajutor adultului pe scurt.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z4-fizic', 'Cărăm împreună — greutate blândă', ARRAY['1 obiect pe care îl țineți amândoi (cutie ușoară)']::text[], ARRAY['Țineți împreună: „Ajutor. Cărăm.” — 3–5 pași.', 'Așezați: „Gata.”', 'Dacă vrea: alegeți ce cărăm împreună din 2 cutii / obiecte.']::text[], 'A cărat împreună cu adultul pe scurt.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z4-mental', 'Plan pe 2 pași — el repetă', ARRAY['obiect', 'destinație']::text[], ARRAY['„Întâi cărăm.” — gest.', '„Apoi gata aici.” — gest. El arată sau repetă.', 'Dacă vrea: el alege ce cărăm — planul pe alegerea lui.']::text[], 'A repetat sau arătat planul în doi pași.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z4-resurse', 'Alege: încă un cărăm sau ajunge', ARRAY['obiect', 'gest gata']::text[], ARRAY['„Încă ajutor / cărăm — sau ajunge?”', 'El alege; respectați: „Gata așa.”', 'Dacă vrea: dacă alege încă, alegeți și ce cărăm.']::text[], 'A ales continuare sau închidere pe treabă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z4-social', 'Ajutor pe rând — eu, tu', ARRAY['2 obiecte mici']::text[], ARRAY['„Acum eu — cărăm. Gata.”', '„Acum tu — ajutor.”', 'Dacă vrea: el alege ce cărăm la rândul lui.']::text[], 'Ați făcut ajutor pe rând.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z5-fizic', 'Traseu scurt: luăm → cărăm → gata', ARRAY['1–2 obiecte', 'loc de pornim și loc de sosire']::text[], ARRAY['De la pornim: „Ajutor.” — luați.', 'Pe drum: „Cărăm.” — la sosire: „Gata.”', 'Dacă vrea: alegeți ce cărăm pe traseu (1 din 2).']::text[], 'A parcurs traseul luăm–cărăm–gata.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z5-mental', 'Trei cuvinte: ajutor, cărăm, gata', ARRAY['1 obiect pe treabă']::text[], ARRAY['„Ajutor.” pe cerere; „Cărăm.” pe cărat; „Gata.” pe așezat.', 'O rundă de etichete pe treaba reală.', 'Dacă vrea: el alege ce cărăm și ordinea cuvintelor.']::text[], 'A auzit ajutor / cărăm / gata pe treabă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z5-resurse', 'Tot ce am cărat — la loc', ARRAY['obiectele zilei']::text[], ARRAY['„Gata. La loc.”', '„Ajunge. Ajutor e gata pentru azi.”', 'Dacă vrea: alegeți ce duceți voi și ce duce el.']::text[], 'Tot ce ați cărat e la loc.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z5-social', 'Arată gata unei persoane dragi', ARRAY['obiect așezat la loc', 'persoană dragă']::text[], ARRAY['„Uite. Gata. Ajutor.” — arătați treaba terminată.', 'Persoana (sau voi): „Da. Cărăm bine.”', 'Dacă vrea: el alege ce cărăm ca să arate iar gata.']::text[], 'A arătat treaba terminată cuiva.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z6-fizic', 'Ajutor liber — treabă aleasă de el', ARRAY['2–3 obiecte posibile de cărat']::text[], ARRAY['Arătați 2–3: „Ce cărăm?” — el alege.', 'Cărați pe scurt: „Ajutor… gata.”', 'Dacă vrea: încă o alegere — ce cărăm a doua oară.']::text[], 'A ales și a cărat pe o treabă liberă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z6-mental', 'Unde e gata? — locul final', ARRAY['obiect', '2 locuri posibile']::text[], ARRAY['„Cărăm… unde gata?” — arătați 2 locuri.', 'El alege; așezați: „Gata.”', 'Dacă vrea: alegeți și ce cărăm înainte de unde.']::text[], 'A ales locul final al treburii.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z6-resurse', 'Treaba de azi — gata', ARRAY['zona de treabă']::text[], ARRAY['„Gata. Ajunge.”', 'Privire pe zonă: „La loc. Ajutor e gata.”', 'Dacă vrea: un ultim obiect — el alege ce cărăm la loc.']::text[], 'Treaba zilei e închisă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z6-social', 'Joacă paralel: eu cărăm, tu ajutor', ARRAY['2 obiecte']::text[], ARRAY['Voi cărați unul: „Cărăm.”', 'El pe al lui: „Ajutor… gata.” — sau doar privește.', 'Dacă vrea: schimbați obiectele — el alege ce cărăm.']::text[], 'Ați cărat în paralel pe scurt.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z7-fizic', 'Treabă blândă — ritmul lui', ARRAY['1 obiect ușor opțional']::text[], ARRAY['El dictează: cărăm, doar arată, sau stă lângă treabă.', 'Fără forțare: „Ajutor… gata.”', 'Dacă vrea: alegeți împreună ce cărăm — o singură tură.']::text[], 'A ales liber ritmul pe treaba de duminică.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z7-mental', 'Favoritul: ajutor, cărăm sau gata?', ARRAY['amintiri din săptămână']::text[], ARRAY['Întrebați: „Îți place ajutor, cărăm sau gata?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: legați de „ce cărăm” — un obiect favorit la loc.']::text[], 'A ales un cuvânt favorit din temă.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['obiectele zilei / săptămânii']::text[], ARRAY['„Gata. La loc.”', '„Ajunge. Acum e liniște.”', 'Dacă vrea: el alege un singur obiect de cărăm la loc.']::text[], 'Totul e la loc înainte de calm.', 'Ajutor la treabă scurtă'),
  ('s40-b23-z7-social', 'Ritual: bună seara după ajutor', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara. Gata. Ajutor e gata.”', '„Noapte bună.”', 'Dacă vrea: un ultim „cărăm” — o jucărie la pat / raft, apoi odihnă.']::text[], 'Ați închis seara blând după ajutorul de treabă.', 'Ajutor la treabă scurtă'),
  ('s41-b23-z1-fizic', 'Plimbare scurtă până la poartă', ARRAY['curte / potecă / hol spre poartă sau ușă-gard']::text[], ARRAY['Alegeți poarta (sau un reper de „poartă”): „Mergem până la poartă.”', 'Mergeți împreună: „Mergem.”', 'Dacă vrea: denumiți un reper pe drum — „Pomul. / Pietroiul.”']::text[], 'A ajuns la poartă (sau la reperul de poartă) pe jos.', 'Drumul până la poartă'),
  ('s41-b23-z1-resurse', 'Întoarcere acasă — gata', ARRAY['poartă → casă / punct de pornim']::text[], ARRAY['Spuneți: „Ne întoarcem. Gata drumul până la poartă.”', 'Ajungeți la pornim: „Acasă. Ajunge.”', 'Dacă vrea: el alege dacă vă întoarceți pe același traseu.']::text[], 'V-ați întors; drumul până la poartă e închis.', 'Drumul până la poartă'),
  ('s41-b23-z1-social', 'Mergeți împreună — așteaptă la poartă', '{}'::text[], ARRAY['Luați-l de mână sau mergeți umăr la umăr: „Împreună.”', 'Opriți-vă o clipă: „Așteptăm.” apoi: „Hai. Mergem.”', 'Dacă vrea: el dă semnalul de plecare (gest sau cuvânt).']::text[], 'A mers împreună și a așteptat o oprire.', 'Drumul până la poartă'),
  ('s41-b23-z2-fizic', 'Mergem și oprim pe drumul spre poartă', ARRAY['potecă / hol / curte']::text[], ARRAY['Mergeți: „Mergem.”', 'Opriți-vă: „Oprim. Stăm.” — 2–3 runde pe drum.', 'Dacă vrea: el alege când oprim (bătăi din palme sau gest).']::text[], 'A alternat mers și oprire pe drum.', 'Drumul până la poartă'),
  ('s41-b23-z2-resurse', 'Drumul se oprește la poartă', ARRAY['poartă ca punct de oprire']::text[], ARRAY['La poartă: „Oprim. Gata.”', '„Ajunge pentru azi pe drum.”', 'Dacă vrea: alegeți un obiect mic de „închis” (cheie / pantof la loc).']::text[], 'Drumul e închis la poartă.', 'Drumul până la poartă'),
  ('s41-b23-z2-social', 'Rândul la mers spre poartă', '{}'::text[], ARRAY['Voi faceți 2 pași: „Acum eu. Hai.”', 'Apoi: „Acum tu” — așteptați pașii lui.', 'Dacă vrea: încă un schimb, apoi oprim împreună.']::text[], 'Ați schimbat rândul la pași spre poartă.', 'Drumul până la poartă'),
  ('s41-b23-z3-fizic', 'Dus-întors: casă → poartă → casă', ARRAY['poartă la 5–10 pași']::text[], ARRAY['Mergeți la poartă: „Hai. Mergem.”', 'Întoarceți-vă: „Înapoi. Acasă.”', 'Dacă vrea: denumiți un reper la dus și unul la întors.']::text[], 'A făcut un dus-întors până la poartă.', 'Drumul până la poartă'),
  ('s41-b23-z4-fizic', 'Pași mari, pași mici spre poartă', ARRAY['spațiu liber pe drum']::text[], ARRAY['Faceți 3 pași mari: „Mari.”', 'Apoi 3 pași mici: „Mici. Mergem.”', 'Dacă vrea: el alege următorul tip — mari sau mici.']::text[], 'A făcut pași mari și pași mici pe drum.', 'Drumul până la poartă'),
  ('s41-b23-z4-mental', 'Unde ne oprim? — Oprim la poartă sau înainte', ARRAY['2 repere pe drum, inclusiv poarta']::text[], ARRAY['Arătați: „Oprim aici? Sau la poartă?”', 'Alegeți unul și opriți-vă: „Oprim. Stăm.”', 'Dacă vrea: el motivează de ce acel reper (aproape / departe).']::text[], 'A ales un loc de oprire pe drumul spre poartă.', 'Drumul până la poartă'),
  ('s41-b23-z4-resurse', 'Alege drumul — unul din două spre poartă', ARRAY['2 direcții / 2 poteci scurte']::text[], ARRAY['„Astăzi: pe aici sau pe aici până la poartă?”', 'El alege; mergeți scurt: „Hai. Ajunge la poartă.”', 'Dacă vrea: spuneți de ce ați alege voi celălalt drum, scurt.']::text[], 'A ales un drum din două până la poartă.', 'Drumul până la poartă'),
  ('s41-b23-z4-social', 'Eu merg, tu aștepți — pe drumul porții', '{}'::text[], ARRAY['Voi mergeți 3 pași; el așteaptă.', 'Schimbați: „Acum tu. Hai.”', 'Dacă vrea: la final spuneți împreună „Oprim!”']::text[], 'Ați alternat mers și așteptare pe drum.', 'Drumul până la poartă'),
  ('s41-b23-z5-fizic', 'Traseu cu trei repere până la poartă', ARRAY['3 repere pe drumul scurt, ultimul = poarta']::text[], ARRAY['Parcurgeți: reper 1 → 2 → poartă, denumind fiecare.', '„Mergem… Oprim” la fiecare reper o clipă.', 'Dacă vrea: el denumește unul dintre repere singur.']::text[], 'A trecut pe la trei repere până la poartă.', 'Drumul până la poartă'),
  ('s41-b23-z5-mental', 'Pași, oprim, hai — pe drumul porții', '{}'::text[], ARRAY['Spuneți: „Mergem” și mergeți.', '„Oprim” — stați. „Hai” — plecați din nou.', 'Dacă vrea: el dă unul din cele trei cuvinte (sau gest).']::text[], 'A auzit pași / oprim / hai pe drumul până la poartă.', 'Drumul până la poartă'),
  ('s41-b23-z5-resurse', 'Întoarcerea de la poartă — ajunge', ARRAY['poartă → punct de pornim']::text[], ARRAY['Înapoi de la poartă: „Acasă. Gata.”', '„Ajunge drumul de azi.”', 'Dacă vrea: un obiect de pe drum la loc înainte de pauză.']::text[], 'Întoarcerea de la poartă a închis drumul.', 'Drumul până la poartă'),
  ('s41-b23-z5-social', 'Drumul meu, drumul tău — paralel spre poartă', ARRAY['2 linii / 2 părți de potecă']::text[], ARRAY['Voi pe o parte; el pe cealaltă: „Mergem împreună.”', 'La poartă: „Oprim. Împreună.”', 'Dacă vrea: schimbați părțile o dată.']::text[], 'Ați mers paralel pe drumul scurt spre poartă.', 'Drumul până la poartă'),
  ('s41-b23-z6-fizic', 'Plimbare liberă scurtă până aproape de poartă', ARRAY['curte / balcon / potecă']::text[], ARRAY['Mergeți liber 30–60 de secunde: „Mergem.”', 'Alegeți un reper spre poartă și opriți: „Oprim.”', 'Dacă vrea: denumiți două lucruri văzute pe drum.']::text[], 'A făcut o plimbare liberă scurtă cu o oprire spre poartă.', 'Drumul până la poartă'),
  ('s41-b23-z7-mental', 'Favoritul: mergem sau oprim pe drumul porții?', '{}'::text[], ARRAY['Întrebați: „Îți place să mergi sau să stai?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: „Mergem” sau „Oprim” pe favorită — și un „de ce” blând.']::text[], 'A ales sau a privit favorita săptămânii.', 'Drumul până la poartă'),
  ('s41-b23-z7-social', 'Ritual: bună seara, poarta e departe — oprim', '{}'::text[], ARRAY['Șoptiți: „Bună seara. Oprim. Drumul până la poartă e gata.”', '„Noapte bună.”', 'Dacă vrea: un ultim „Hai” pe degete (mers pe genunchi), apoi calm.']::text[], 'Ați închis săptămâna drumului până la poartă cu ritual blând.', 'Drumul până la poartă'),
  ('s42-b23-z1-fizic', 'Strângem frunze din nou — blând', ARRAY['frunze afară sau aduse', 'mâini sau găleată mică']::text[], ARRAY['Strângeți 2–3 frunze împreună, fără grabă: „Din nou. Frunze.”', '„Frunză.” pe una pe rest.', 'Dacă vrea: întrebați: „De ce e diferită?” pe două frunze.']::text[], 'A strâns frunze din nou pe scurt cu adultul.', 'Vânt și frunze din nou'),
  ('s42-b23-z1-mental', 'Două tipuri din nou: frunză și pământ', ARRAY['frunză', 'puțin pământ/nisip într-un vas']::text[], ARRAY['Atingeți: „Frunză.” Apoi: „Pământ.”', '„Uscat / moale” — ce simțiți, pe scurt.', 'Dacă vrea: sortați încă o frunză lângă frunze.']::text[], 'A atins și a auzit frunză / pământ din nou.', 'Vânt și frunze din nou'),
  ('s42-b23-z2-fizic', 'Pământ controlat — degete pe vas', ARRAY['vas cu puțin pământ/nisip', 'prosop']::text[], ARRAY['Lăsați-l să atingă pământul din vas (nu împrăștia).', '„Pământ.” Ștergeți degetele: „Gata.”', 'Dacă vrea: comparați cu o frunză uscată pe lângă.']::text[], 'A atins pământul controlat din vas.', 'Vânt și frunze din nou'),
  ('s42-b23-z2-mental', 'Sortăm: frunză mare, frunză mică', ARRAY['2–4 frunze de mărimi diferite']::text[], ARRAY['Arătați: „Mare.” „Mică.”', 'Puneți-le în două grupe.', 'Dacă vrea: „De ce e diferit?” — o frază scurtă de la voi.']::text[], 'A văzut sortarea mare / mică pe frunze.', 'Vânt și frunze din nou'),
  ('s42-b23-z2-social', 'Arătăm frunza adultului', ARRAY['1 frunză']::text[], ARRAY['Invitați-l să arate frunza cuiva drag.', '„Uite frunza!”', 'Dacă vrea: spuneți: „Frunză.” când arată.']::text[], 'A arătat frunza cuiva.', 'Vânt și frunze din nou'),
  ('s42-b23-z4-fizic', 'Frunza cade — toamnă din nou', ARRAY['1–2 frunze', 'vânt ușor sau suflat blând']::text[], ARRAY['Lăsați o frunză să cadă de la înălțimea pieptului: „Toamnă. Cade.”', 'Ridicați-o: „Jos pe jos. Frunză.”', 'Dacă vrea: el dă drumul frunzei (voi prindeți sau lăsați pe jos).']::text[], 'A urmărit frunza care cade din nou.', 'Vânt și frunze din nou'),
  ('s42-b23-z4-resurse', 'Pământul rămâne în vas', ARRAY['vas cu pământ', 'prosop']::text[], ARRAY['Arătați: „Pământul stă aici. Pământ.”', 'Dacă a căzut puțin pe prosop, ștergeți: „La loc. Gata.”', 'Dacă vrea: el ajută cu o mișcare de șters.']::text[], 'Pământul e în vas; zona e strânsă.', 'Vânt și frunze din nou'),
  ('s42-b23-z5-mental', 'Unde e frunza, unde e pământul?', ARRAY['frunză', 'vas cu pământ']::text[], ARRAY['„Unde e frunza?” Așteptați arătarea.', '„Unde e pământul?”', 'Dacă vrea: „Frunză” / „Pământ” pe fiecare, o dată.']::text[], 'A arătat sau a privit frunza și pământul.', 'Vânt și frunze din nou'),
  ('s42-b23-z5-social', 'Privim împreună frunza pe jos', ARRAY['frunză']::text[], ARRAY['Stați umăr lângă umăr: „Uite — frunză.”', '„Frunză.” o dată.', 'Dacă vrea: el alege unde o puneți să o priviți.']::text[], 'Ați privit împreună frunza.', 'Vânt și frunze din nou'),
  ('s42-b23-z6-fizic', 'Afară: strâns scurt pe pământ — din nou', ARRAY['curte sau ghiveci', '2–3 frunze/pietre']::text[], ARRAY['Strângeți controlat 2–3 lucruri de pe pământ.', '„Pământ. Frunză.”', 'Dacă vrea: duceți-le în cutie înăuntru.']::text[], 'A strâns pe scurt afară din nou.', 'Vânt și frunze din nou'),
  ('s42-b23-z7-fizic', 'Strâns liber — frunza favorită din nou', ARRAY['frunze']::text[], ARRAY['El alege ritmul: strânge sau doar ține o frunză.', 'Voi numiți, fără grabă.', 'Dacă vrea: lăsați frunza să cadă o dată: „Toamnă. Cade.”']::text[], 'A manipulat frunza liber, pe scurt.', 'Vânt și frunze din nou'),
  ('s42-b23-z7-mental', 'Favorita: frunză, pământ sau toamnă?', ARRAY['frunză', 'vas cu pământ']::text[], ARRAY['„Ce ți-a plăcut?” — arătați frunză, pământ, sau căderea.', 'Stați un moment la alegere.', 'Dacă vrea: spuneți de ce e frumos, o frază — sau doar tăcere împreună.']::text[], 'A ales sau a privit favorita.', 'Vânt și frunze din nou'),
  ('s42-b23-z7-social', 'Ritual: bună seara, frunză din nou', ARRAY['1 frunză opțională']::text[], ARRAY['Șoptiți: „Bună seara.” Atingeți frunza sau cutia.', '„Noapte bună.”', 'Dacă vrea: „Frunză — la revedere până mâine.”']::text[], 'Ați închis săptămâna frunzelor din nou cu ritual blând.', 'Vânt și frunze din nou'),
  ('s43-b23-z1-fizic', 'Cărăm două–trei obiecte în coș', ARRAY['2–3 obiecte ușoare', 'coș sau cutie']::text[], ARRAY['Luați împreună primul obiect: „Unul. Cărăm. Alege.”', 'Puneți-l în coș; apoi al doilea: „Două.”', 'Dacă vrea: al treilea obiect — sau opriți-vă la două.']::text[], 'A cărat 2–3 obiecte până la coș.', 'Coșul și strânsul'),
  ('s43-b23-z1-mental', 'Sortăm pe un criteriu — în coș', ARRAY['4 obiecte: 2 de un tip, 2 de alt tip', 'coș']::text[], ARRAY['Arătați: „La fel aici.” — grămadă 1.', '„Altul aici.” — grămadă 2. Spuneți: „Sortăm.”', 'Dacă vrea: el mută un obiect în grămada potrivită.']::text[], 'A văzut două grămezi sortate pe un criteriu.', 'Coșul și strânsul'),
  ('s43-b23-z1-resurse', 'Coș / cutie: plin și gol', ARRAY['coș sau cutie', '2–3 obiecte']::text[], ARRAY['Puneți obiectele: „Plin puțin. Cutie.”', 'Goliți pe masă: „Gol.” Apoi: „La loc în coș.”', 'Dacă vrea: alegeți dacă lăsați coșul plin sau gol la final.']::text[], 'A văzut coșul plin și gol; obiectele sunt la loc.', 'Coșul și strânsul'),
  ('s43-b23-z1-social', 'Rândul la pus în coș', ARRAY['coș', '2 obiecte']::text[], ARRAY['Voi puneți unul: „Acum eu. În coș.”', 'Apoi: „Acum tu” — așteptați gestul lui.', 'Dacă vrea: adăugați: „Cutie. Coș.” când puneți.']::text[], 'Ați făcut un schimb de rând la pus în coș.', 'Coșul și strânsul'),
  ('s43-b23-z2-fizic', 'Alege de pe jos — în coș', ARRAY['2 obiecte pe jos', 'coș']::text[], ARRAY['Ridicați de pe jos: „Alege. Luăm.”', 'Cărați în coș: „Aici. Coș.”', 'Dacă vrea: el alege care obiect intră primul.']::text[], 'A strâns obiecte de pe jos în coș.', 'Coșul și strânsul'),
  ('s43-b23-z2-mental', 'Două grămezi: culoare — sortăm', ARRAY['2 obiecte de o culoare', '2 de altă culoare']::text[], ARRAY['Sortați: „Roșu aici. Albastru aici.”', 'Spuneți: „Sortăm după culoare.”', 'Dacă vrea: el alege unde merge un obiect nou.']::text[], 'A sortat (sau a privit sortarea) pe culoare.', 'Coșul și strânsul'),
  ('s43-b23-z3-fizic', 'Traseu scurt cu coșul', ARRAY['2 obiecte', 'coș la 5–8 pași']::text[], ARRAY['Cărați primul obiect până la coș.', 'Întoarceți-vă după al doilea: „Încă unul. Alege.”', 'Dacă vrea: el alege ordinea obiectelor.']::text[], 'A făcut un traseu scurt de strâns în coș.', 'Coșul și strânsul'),
  ('s43-b23-z3-mental', 'Mare și mic — sortăm în coș', ARRAY['2 obiecte mari', '2 mici', 'coș']::text[], ARRAY['Arătați: „Mare aici. Mic aici.”', '„Sortăm după mărime.”', 'Dacă vrea: combinați: un obiect „mare și roșu” — arătați ambele criterii.']::text[], 'A văzut sortarea pe mărime.', 'Coșul și strânsul'),
  ('s43-b23-z4-fizic', 'Strângem de pe jos — trei în coș', ARRAY['3 obiecte pe jos', 'coș']::text[], ARRAY['Strângeți: „Unu. Doi. Trei.” în coș.', '„Gata. Am strâns. Alege.”', 'Dacă vrea: numărați din nou pe degete.']::text[], 'A strâns trei obiecte de pe jos în coș.', 'Coșul și strânsul'),
  ('s43-b23-z4-resurse', 'Alege ce intră în coș — unul din două', ARRAY['2 obiecte', 'coș']::text[], ARRAY['„Acesta sau acesta în coș?”', 'El alege; celălalt la loc pe masă: „La loc.”', 'Dacă vrea: spuneți: „Alege. Alegem.” pe obiectul ales.']::text[], 'Un obiect e în coș; celălalt e la loc.', 'Coșul și strânsul'),
  ('s43-b23-z5-mental', 'Sortăm culoare și mărime — lângă coș', ARRAY['obiecte pe 2 culori și 2 mărimi', 'coș']::text[], ARRAY['Faceți o grămadă: „Roșu și mic.”', 'Arătați alta: „Albastru și mare.” Spuneți: „Sortăm.”', 'Dacă vrea: el alege unde merge un obiect după ambele criterii.']::text[], 'A văzut sortarea pe culoare și mărime (extensie schiță).', 'Coșul și strânsul'),
  ('s43-b23-z5-resurse', 'Plin destul — restul la loc', ARRAY['coș / cutie', '4 obiecte']::text[], ARRAY['Puneți două: „Plin destul. Ajunge. Cutie.”', 'Celelalte: „La loc pe raft.”', 'Dacă vrea: alegeți raftul sau masa pentru rest.']::text[], 'Coșul are destul; restul e la loc.', 'Coșul și strânsul'),
  ('s43-b23-z6-fizic', 'Colectăm afară — strâns în coș', ARRAY['curte / balcon sau cameră', '2–3 obiecte sigure', 'coș']::text[], ARRAY['Colectați 2–3 lucruri sigure (frunză, piatră mică, jucărie).', 'Cărați-le la coș: „În cutie. În coș.”', 'Dacă vrea: încă un obiect, sau opriți-vă.']::text[], 'A colectat și a cărat 2–3 obiecte în coș.', 'Coșul și strânsul'),
  ('s43-b23-z6-mental', 'Trei grămezi pe masă — sortăm', ARRAY['6 obiecte pe 3 tipuri']::text[], ARRAY['Așezați: „Una. Două. Trei.” — trei grămezi.', 'Numiți criteriul: „Culoare” sau „Mărime.”', 'Dacă vrea: el arată grămada pe care o numiți.']::text[], 'A privit trei grămezi sortate.', 'Coșul și strânsul'),
  ('s43-b23-z7-mental', 'Favoritul: sortăm, alege sau coș?', ARRAY['coș', 'câteva obiecte']::text[], ARRAY['Întrebați: „Îți place să sortezi, să iei sau coșul?” — arătați.', 'Stați un moment pe alegerea lui.', 'Dacă vrea: spuneți: „Sortăm” sau „Alege” pe favorită.']::text[], 'A ales sau a privit favorita săptămânii.', 'Coșul și strânsul'),
  ('s43-b23-z7-social', 'Ritual: bună seara, coș', ARRAY['coș']::text[], ARRAY['Șoptiți: „Bună seara.” Atingeți coșul blând.', '„Noapte bună.”', 'Dacă vrea: „Cutie. Coș — la revedere până mâine.”']::text[], 'Ați închis săptămâna coșului și strânsului cu ritual blând.', 'Coșul și strânsul'),
  ('s44-b23-z1-fizic', 'Pregătim spațiul — un obiect pentru familie', ARRAY['1 pernă / scaun / jucărie']::text[], ARRAY['Alegeți un obiect: „Pentru oaspete / prieten / familie.”', 'Cărați-l împreună la locul pregătit.', 'Dacă vrea: o întrebare blândă — „Vrei să pui tu perna?” — poate refuza.']::text[], 'A cărat un obiect pentru spațiul de familie / oaspete.', 'Prieteni și familie'),
  ('s44-b23-z1-mental', 'Salut + un cuvânt blând', '{}'::text[], ARRAY['Modelați: „Bună.” — undă cu mâna.', 'Adăugați un cuvânt: „Prieten” sau „Familie.”', 'Dacă vrea: „Vrei să spui bună?” — poate refuza, fără presiune.']::text[], 'A auzit / încercat salutul blând.', 'Prieteni și familie'),
  ('s44-b23-z1-resurse', 'Loc pentru oaspete / familie — scaunul', ARRAY['scaun / pernă']::text[], ARRAY['Arătați: „Aici stă oaspetele / prieten / familia.”', '„Ajunge. Locul e gata.”', 'Dacă vrea: alegeți scaunul sau perna (1 din 2).']::text[], 'Locul pentru oaspete / familie e marcat.', 'Prieteni și familie'),
  ('s44-b23-z1-social', 'Bună fără forțare — familiei', '{}'::text[], ARRAY['Voi spuneți: „Bună.” — undă.', 'El poate undă, spune sau doar privi — tot e bine.', 'Dacă vrea: o întrebare — „Vrei bună sau doar mâna?” — poate refuza.']::text[], 'Ați practicat salutul fără forțare.', 'Prieteni și familie'),
  ('s44-b23-z2-fizic', 'Mână ridicată — bună pe scurt', '{}'::text[], ARRAY['Ridicați mâna: „Bună.” — 2–3 unde.', 'Jos: „Gata.”', 'Dacă vrea: „Vrei încă un bună?” — poate refuza.']::text[], 'A unduit sau a privit salutul.', 'Prieteni și familie'),
  ('s44-b23-z2-mental', 'Bună — ce înseamnă pentru familie?', '{}'::text[], ARRAY['„Bună înseamnă bună.” — undă.', '„La revedere înseamnă la revedere.” — undă de plecare.', 'Dacă vrea: el alege pe care îl arată acum.']::text[], 'A legat bună / la revedere de gest.', 'Prieteni și familie'),
  ('s44-b23-z2-resurse', 'Jucăria prieten pe raft', ARRAY['o jucărie „prieten / familie”', 'raft']::text[], ARRAY['După joacă: „Prieten la loc.”', '„Ajunge. Gata.”', 'Dacă vrea: alegeți raftul sau scaunul pentru jucărie.']::text[], 'Jucăria prieten e la loc.', 'Prieteni și familie'),
  ('s44-b23-z2-social', 'Spunem bună familiei din casă', '{}'::text[], ARRAY['Mergeți la o persoană dragă din familie.', 'Modelați: „Bună!” — undă.', 'Dacă vrea: „Vrei să spui tu?” — poate refuza.']::text[], 'A împărtășit un bună în familie.', 'Prieteni și familie'),
  ('s44-b23-z3-fizic', 'Așezăm scaunul pentru prieten / familie', ARRAY['scaun ușor / pernă']::text[], ARRAY['Mutați împreună scaunul: „Pentru prieten. Pentru familie.”', '„Aici.” — arătați locul.', 'Dacă vrea: „Vrei tu să împingi?” — poate refuza.']::text[], 'A mutat scaunul / perna pe scurt.', 'Prieteni și familie'),
  ('s44-b23-z3-mental', 'Prieten — cine e din familie?', ARRAY['jucărie sau poză persoană dragă']::text[], ARRAY['Arătați: „Prieten / familie.”', 'Numiți pe cineva drag din casă.', 'Dacă vrea: „Cine e prieten-ul tău?” — poate refuza dacă nu răspunde.']::text[], 'A legat prieten de o persoană din familie / jucărie.', 'Prieteni și familie'),
  ('s44-b23-z3-resurse', 'Scaunul rămâne locul familiei — gata', ARRAY['scaun']::text[], ARRAY['„Locul e gata. Ajunge.”', 'Nu mai mutați: „Gata.”', 'Dacă vrea: alegeți dacă prieten stă pe scaun sau pe pernă.']::text[], 'Locul familiei / oaspetelui e stabilit.', 'Prieteni și familie'),
  ('s44-b23-z3-social', 'Rândul la bună în familie', '{}'::text[], ARRAY['Voi: „Acum eu. Bună.”', '„Acum tu” — așteptați undă sau cuvânt.', 'Dacă vrea: „Vrei încă un rând?” — poate refuza.']::text[], 'Ați schimbat rândul la salut.', 'Prieteni și familie'),
  ('s44-b23-z4-fizic', 'La revedere cu mâna — pași spre ușă pe scurt', ARRAY['ușă / prag']::text[], ARRAY['La ușă: „La revedere.” — undă.', '2–3 pași înapoi în casă: „Rămânem. Familie.”', 'Dacă vrea: „Vrei la revedere încă o dată?” — poate refuza.']::text[], 'A practicat la revedere la ușă pe scurt.', 'Prieteni și familie'),
  ('s44-b23-z4-mental', 'Bună, prieten, la revedere — pe gesturi', '{}'::text[], ARRAY['„Bună” — undă venire. „Prieten” — arătați pe cineva din familie.', '„La revedere” — undă plecare.', 'Dacă vrea: el alege un gest de arătat.']::text[], 'A legat cele trei cuvinte de gesturi.', 'Prieteni și familie'),
  ('s44-b23-z4-resurse', 'După la revedere — jucăria prieten la loc', ARRAY['jucărie oaspete', 'raft']::text[], ARRAY['„La revedere, prieten. La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți raftul sau patul jucăriei.']::text[], 'Jucăria prieten e la loc după la revedere.', 'Prieteni și familie'),
  ('s44-b23-z4-social', 'Eu bună, tu la revedere — apoi invers', '{}'::text[], ARRAY['Voi: „Bună.” El: „La revedere” (sau undă).', 'Schimbați o dată.', 'Dacă vrea: o întrebare — „Care îți place?” — poate refuza.']::text[], 'Ați schimbat rolurile bună / la revedere.', 'Prieteni și familie'),
  ('s44-b23-z5-fizic', 'Traseu: pregătim → bună → scaun → la revedere', ARRAY['1 obiect', 'scaun']::text[], ARRAY['Cărați obiectul, spuneți bună, arătați scaunul, apoi la revedere.', 'Traseu scurt, o dată — temă familie.', 'Dacă vrea: el alege unde e bună pe traseu.']::text[], 'A făcut traseul de prieteni / familie pe scurt.', 'Prieteni și familie'),
  ('s44-b23-z5-mental', 'Cine vine? — prieten din familie', ARRAY['jucărie / poză']::text[], ARRAY['„Vine prieten.” — arătați.', '„Bună, prieten.”', 'Dacă vrea: „Cum îl cheamă?” — poate refuza dacă nu spune.']::text[], 'A legat venirea de prieten / bună.', 'Prieteni și familie'),
  ('s44-b23-z5-social', 'Ajutor: adu scaunul / perna pentru prieten', ARRAY['scaun ușor / pernă']::text[], ARRAY['Cereți: „Adu perna pentru prieten, te rog.”', 'Mulțumiți: „Bună pe locul ăsta.”', 'Dacă vrea: el cere ajutorul vostru — poate refuza pe roluri.']::text[], 'A ajutat la pregătirea locului.', 'Prieteni și familie'),
  ('s44-b23-z6-fizic', 'Joacă liberă — bună / la revedere pe scurt', ARRAY['jucărie oaspete opțional']::text[], ARRAY['30–60 de secunde: undă bună sau la revedere când vrea.', 'Voi urmăriți, fără a corecta.', 'Dacă vrea: o întrebare blândă la final — poate refuza.']::text[], 'A jucat liber salutul pe scurt.', 'Prieteni și familie'),
  ('s44-b23-z6-mental', 'Ce am spus familiei / oaspetelui?', '{}'::text[], ARRAY['„Am spus bună? La revedere?”', 'El arată gestul.', 'Dacă vrea: „Și prieten?” — arătați jucăria / persoana.']::text[], 'A denumit un salut din joacă.', 'Prieteni și familie'),
  ('s44-b23-z6-resurse', 'Scaunul / jucăria la loc după joacă', ARRAY['scaun sau jucărie']::text[], ARRAY['„La loc.” după joaca de prieteni / familie.', '„Ajunge. Gata.”', 'Dacă vrea: prieten rămâne pe scaun până seara (apoi la loc).']::text[], 'Spațiul e strâns după joacă.', 'Prieteni și familie'),
  ('s44-b23-z6-social', 'Joacă paralel: eu bună, tu cu prieten', ARRAY['jucărie']::text[], ARRAY['Voi unduiți bună; el ține prieten (sau invers).', 'Fără a lua obiectul celuilalt.', 'Dacă vrea: schimbați, apoi la revedere împreună.']::text[], 'Ați jucat paralel pe tema prietenilor / familiei.', 'Prieteni și familie'),
  ('s44-b23-z7-fizic', 'Mișcare liberă — bună sau la revedere la final', ARRAY['spațiu liber']::text[], ARRAY['El alege mișcare liberă; la final undă bună sau la revedere.', 'Fără forțare.', 'Dacă vrea: „Vrei bună sau la revedere?” — poate refuza pe ambele.']::text[], 'A mișcat liber și a închis cu un salut.', 'Prieteni și familie'),
  ('s44-b23-z7-mental', 'Favoritul: bună, prieten sau la revedere?', '{}'::text[], ARRAY['Întrebați: „Îți place bună, prieten sau la revedere?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: o singură rundă doar pe favorit — poate refuza.']::text[], 'A ales sau a privit salutul / cuvântul favorit.', 'Prieteni și familie'),
  ('s44-b23-z7-resurse', 'Locul familiei strâns înainte de calm', ARRAY['scaun / jucărie / pernă']::text[], ARRAY['„La loc. La revedere, prieten.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un ultim bună șoptit, apoi totul la loc.']::text[], 'Spațiul e gata înainte de calm.', 'Prieteni și familie'),
  ('s44-b23-z7-social', 'Ritual: bună seara, la revedere blând — familie', '{}'::text[], ARRAY['Șoptiți: „Bună seara. La revedere.” — undă mică.', '„Noapte bună, prieten. Familie.”', 'Dacă vrea: un bună de noapte bună, apoi odihnă — poate refuza.']::text[], 'Ați închis săptămâna prietenilor și familiei cu ritual blând.', 'Prieteni și familie'),
  ('s45-b23-z1-fizic', 'Pași mulți pe drumul scurt', ARRAY['hol / curte / potecă liberă']::text[], ARRAY['Alegeți un reper la 6–10 pași: „Mergem acolo. Mergem.”', 'Mergeți împreună, pași clari, fără grabă: „Corp puternic. Pași.”', 'Dacă vrea: denumiți un reper pe drum — „Ușa. / Pomul.”']::text[], 'A făcut pașii până la reper pe jos.', 'Corp puternic, pași mulți'),
  ('s45-b23-z1-mental', 'Numărăm pașii până la reper', ARRAY['reper la 4–8 pași']::text[], ARRAY['Mergeți încet și numărați: „Unu. Doi. Trei…”', 'La reper: „Gata. Atâția pași. Oprim.”', 'Dacă vrea: încă o dată, el spune un număr cu voi.']::text[], 'A auzit numărarea pașilor până la reper.', 'Corp puternic, pași mulți'),
  ('s45-b23-z1-resurse', 'Întoarcere acasă — gata pașii', ARRAY['reper → casă / punct de pornim']::text[], ARRAY['Spuneți: „Ne întoarcem. Gata pașii mulți.”', 'Ajungeți la pornim: „Acasă. Ajunge.”', 'Dacă vrea: el alege dacă vă întoarceți pe același traseu.']::text[], 'V-ați întors; pașii mulți sunt închiși.', 'Corp puternic, pași mulți'),
  ('s45-b23-z1-social', 'Mergeți împreună — așteaptă la reper', '{}'::text[], ARRAY['Luați-l de mână sau umăr la umăr: „Împreună. Mergem.”', 'Opriți-vă o clipă: „Așteptăm. Oprim.” apoi: „Hai. Mergem.”', 'Dacă vrea: el dă semnalul de plecare (gest sau cuvânt).']::text[], 'A mers împreună și a așteptat o oprire.', 'Corp puternic, pași mulți'),
  ('s45-b23-z2-fizic', 'Mergem și oprim — corp puternic', ARRAY['spațiu liber pe hol / curte']::text[], ARRAY['Mergeți: „Mergem. Pași.”', 'Opriți-vă: „Oprim. Stăm.” — 2–3 runde.', 'Dacă vrea: el alege când oprim (bătăi din palme sau gest).']::text[], 'A alternat mers și oprire cu corpul.', 'Corp puternic, pași mulți'),
  ('s45-b23-z2-resurse', 'Pașii se opresc — gata', ARRAY['reper ca punct de oprire']::text[], ARRAY['La reper: „Oprim. Gata.”', '„Ajunge pentru azi cu pașii mulți.”', 'Dacă vrea: alegeți un obiect mic de „închis” (pantof / jucărie la loc).']::text[], 'Pașii mulți sunt închiși la reper.', 'Corp puternic, pași mulți'),
  ('s45-b23-z2-social', 'Rândul la pași puternici', '{}'::text[], ARRAY['Voi faceți 2 pași: „Acum eu. Hai.”', 'Apoi: „Acum tu” — așteptați pașii lui.', 'Dacă vrea: încă un schimb, apoi oprim împreună.']::text[], 'Ați schimbat rândul la pași.', 'Corp puternic, pași mulți'),
  ('s45-b23-z3-fizic', 'Dus-întors: pornim → reper → pornim', ARRAY['reper la 5–10 pași']::text[], ARRAY['Mergeți la reper: „Hai. Mergem.”', 'Întoarceți-vă: „Înapoi. Acasă.”', 'Dacă vrea: denumiți un reper la dus și unul la întors.']::text[], 'A făcut un dus-întors pe pași.', 'Corp puternic, pași mulți'),
  ('s45-b23-z3-social', 'Așteaptă-mă la reper', ARRAY['reper clar']::text[], ARRAY['El stă la reper (sau voi); celălalt vine: „Te aștept.”', 'Când ajungeți: „Împreună! Hai.”', 'Dacă vrea: schimbați rolurile o dată.']::text[], 'Ați exersat așteptarea la reper.', 'Corp puternic, pași mulți'),
  ('s45-b23-z4-fizic', 'Pași mari, pași mici — corp puternic', ARRAY['spațiu liber']::text[], ARRAY['Faceți 3 pași mari: „Mari. Puternic.”', 'Apoi 3 pași mici: „Mici. Mergem.”', 'Dacă vrea: el alege următorul tip — mari sau mici.']::text[], 'A făcut pași mari și pași mici.', 'Corp puternic, pași mulți'),
  ('s45-b23-z4-mental', 'Unde ne oprim? — Oprim la reper', ARRAY['2 repere pe drum']::text[], ARRAY['Arătați: „Oprim aici? Sau mai departe?”', 'Alegeți unul și opriți-vă: „Oprim. Stăm.”', 'Dacă vrea: el motivează de ce acel reper (aproape / departe).']::text[], 'A ales un loc de oprire pe drum.', 'Corp puternic, pași mulți'),
  ('s45-b23-z4-resurse', 'Alege drumul — unul din două', ARRAY['2 direcții / 2 poteci scurte']::text[], ARRAY['„Astăzi: pe aici sau pe aici?”', 'El alege; mergeți scurt: „Hai. Mergem. Ajunge.”', 'Dacă vrea: spuneți de ce ați alege voi celălalt drum, scurt.']::text[], 'A ales un drum din două.', 'Corp puternic, pași mulți'),
  ('s45-b23-z4-social', 'Eu merg, tu aștepți — pe pași', '{}'::text[], ARRAY['Voi mergeți 3 pași; el așteaptă.', 'Schimbați: „Acum tu. Hai.”', 'Dacă vrea: la final spuneți împreună „Oprim!”']::text[], 'Ați schimbat mersul și așteptarea.', 'Corp puternic, pași mulți'),
  ('s45-b23-z5-fizic', 'Traseu cu trei repere — pași mulți', ARRAY['3 repere pe hol / curte']::text[], ARRAY['Parcurgeți: reper 1 → 2 → 3, denumind fiecare.', '„Mergem. Unu. Doi. Trei.”', 'Dacă vrea: el alege ordinea celor trei repere.']::text[], 'A trecut pe trei repere denumite.', 'Corp puternic, pași mulți'),
  ('s45-b23-z5-mental', 'Pași, oprim, hai — pe corpul puternic', '{}'::text[], ARRAY['Spuneți: „Mergem” și mergeți.', '„Oprim” — stați; „Hai” — porniți din nou.', 'Dacă vrea: el spune unul din cele trei cuvinte (sau arată).']::text[], 'A legat pași / oprim / hai de mișcare.', 'Corp puternic, pași mulți'),
  ('s45-b23-z5-resurse', 'Întoarcerea de la reper — ajunge', ARRAY['reper → pornim']::text[], ARRAY['Înapoi de la reper: „Acasă. Gata.”', '„Ajunge. Pașii mulți s-au terminat.”', 'Dacă vrea: el alege când e „ajunge” (gest).']::text[], 'V-ați întors; pașii sunt gata.', 'Corp puternic, pași mulți'),
  ('s45-b23-z5-social', 'Drumul meu, drumul tău — paralel', ARRAY['spațiu pentru două linii scurte']::text[], ARRAY['Voi pe o parte; el pe cealaltă: „Mergem împreună.”', 'La reper: „Oprim. Împreună!”', 'Dacă vrea: schimbați laturile o dată.']::text[], 'Ați mers paralel și v-ați întâlnit la reper.', 'Corp puternic, pași mulți'),
  ('s45-b23-z6-fizic', 'Plimbare liberă scurtă — pași mulți', ARRAY['curte / hol']::text[], ARRAY['Mergeți liber 30–60 de secunde: „Mergem. Puternic.”', 'Alegeți un reper mic și opriți-vă: „Oprim.”', 'Dacă vrea: denumiți ce ați trecut pe drum.']::text[], 'A mers liber scurt și s-a oprit la un reper.', 'Corp puternic, pași mulți'),
  ('s45-b23-z6-social', 'Arată-i altcuiva pașii mulți', ARRAY['o persoană dragă (sau jucărie-personaj)']::text[], ARRAY['Mergeți cu o persoană dragă (sau jucărie) pe traseul scurt.', '„Mergem. Uite pașii noștri.”', 'Dacă vrea: el arată reperul favorit.']::text[], 'A împărtășit drumul cu cineva / ceva drag.', 'Corp puternic, pași mulți'),
  ('s45-b23-z7-fizic', 'Pași liberi — cum vrea el', ARRAY['spațiu liber']::text[], ARRAY['El dictează ritmul: pași, oprire, sau doar stă.', 'Voi urmați: „Mergem” sau „Oprim”, după el.', 'Dacă vrea: un singur „Hai” blând, apoi gata.']::text[], 'A ales ritmul pașilor (sau a refuzat — e bine).', 'Corp puternic, pași mulți'),
  ('s45-b23-z7-mental', 'Favoritul: mergem sau oprim?', '{}'::text[], ARRAY['Întrebați: „Îți place să mergi sau să stai?” — arătați ambele.', 'Stați pe alegerea lui.', 'Dacă vrea: o rundă scurtă doar pe favorit.']::text[], 'A ales sau a privit favoritul mergem / oprim.', 'Corp puternic, pași mulți'),
  ('s45-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['1–2 obiecte pe jos']::text[], ARRAY['Strângeți: „La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un ultim mergem scurt până la raft, apoi oprim.']::text[], 'Spațiul e gata înainte de calm.', 'Corp puternic, pași mulți'),
  ('s45-b23-z7-social', 'Ritual: bună seara — oprim, pașii gata', '{}'::text[], ARRAY['Șoptiți: „Bună seara. Oprim. Pașii mulți sunt gata.”', '„Corp puternic. Noapte bună.”', 'Dacă vrea: un mergem de 2 pași spre pat, apoi odihnă.']::text[], 'Ați închis săptămâna corpului puternic cu ritual blând.', 'Corp puternic, pași mulți'),
  ('s46-b23-z1-fizic', 'Vânătoare scurtă — unde e?', ARRAY['1 obiect cunoscut ascuns la vedere']::text[], ARRAY['Ascundeți ușor un obiect: „Unde? Unde e?”', 'Căutați împreună 20–40 de secunde, arătând: „Aici? Acolo?”', 'Dacă vrea: el inventează întrebarea — „Unde?” cu gest.']::text[], 'A căutat și a găsit (sau a arătat) obiectul.', 'Întrebări cu arătatul'),
  ('s46-b23-z1-mental', 'El pune o întrebare arătând', ARRAY['2 obiecte vizibile']::text[], ARRAY['Modelați: arătați un obiect — „Asta? Acesta?”', 'Invitați-l: „Tu întreabă.” — așteptați gest sau sunet.', 'Dacă vrea: el inventează întrebarea pe al doilea obiect.']::text[], 'A arătat și a întrebat (sau a văzut modelul).', 'Întrebări cu arătatul'),
  ('s46-b23-z1-social', 'Întrebare ↔ răspuns cu adult', '{}'::text[], ARRAY['Voi: „Unde?” — el arată sau voi modelați răspunsul.', 'Schimbați: el întreabă (gest), voi răspundeți arătând.', 'Dacă vrea: încă un schimb pe un obiect nou.']::text[], 'Ați făcut un schimb întrebare–răspuns.', 'Întrebări cu arătatul'),
  ('s46-b23-z2-fizic', 'Căutăm asta — arătăm cu degetul', ARRAY['3 obiecte pe masă / pe jos']::text[], ARRAY['Spuneți: „Asta. Acesta.” și arătați unul.', 'El caută același tip sau același obiect pe scurt.', 'Dacă vrea: el alege care e „asta” următorul.']::text[], 'A legat arătatul de căutare.', 'Întrebări cu arătatul'),
  ('s46-b23-z2-mental', 'Asta sau aia — două pe masă', ARRAY['2 obiecte diferite']::text[], ARRAY['Arătați aproape: „Asta.” Apoi departe: „Aia.”', 'Întrebați: „Unde? Unde e asta?”', 'Dacă vrea: el inventează — arată și spune (sau gest) asta / aia.']::text[], 'A diferențiat asta și aia pe două obiecte.', 'Întrebări cu arătatul'),
  ('s46-b23-z2-social', 'Rândul la întrebarea cu arătatul', '{}'::text[], ARRAY['Voi întrebați arătând: „Unde?”', 'Apoi: „Acum tu” — așteptați arătarea lui.', 'Dacă vrea: încă un rând pe „aia”.']::text[], 'Ați schimbat rândul la întrebare.', 'Întrebări cu arătatul'),
  ('s46-b23-z3-fizic', 'Unde e pe corp? — arătăm', '{}'::text[], ARRAY['Întrebați: „Unde? Unde e nasul?” — arătați pe voi.', 'El arată pe el sau pe voi (orice e bine).', 'Dacă vrea: el inventează — „Unde?” pe o altă parte a corpului.']::text[], 'A arătat o parte a corpului la întrebare.', 'Întrebări cu arătatul'),
  ('s46-b23-z3-mental', 'Unde pe cameră — două locuri', ARRAY['2 locuri cunoscute (ușă / fereastră)']::text[], ARRAY['„Unde e ușa?” — așteptați arătarea.', '„Unde e fereastra?”', 'Dacă vrea: el alege ce întreabă următorul.']::text[], 'A arătat două locuri din cameră.', 'Întrebări cu arătatul'),
  ('s46-b23-z3-social', 'Arată-mi — eu arăt ție', '{}'::text[], ARRAY['El arată un obiect: voi numiți „Asta.”', 'Voi arătați altul: „Aia.” — el privește.', 'Dacă vrea: el inventează o întrebare doar cu gest.']::text[], 'Ați schimbat arătatul unul altuia.', 'Întrebări cu arătatul'),
  ('s46-b23-z4-fizic', 'Vânătoare: aia departe', ARRAY['1 obiect mai departe în cameră']::text[], ARRAY['Arătați departe: „Aia. Acela.”', 'Mergeți împreună să-l „găsiți” pe scurt.', 'Dacă vrea: el alege următorul „aia” din cameră.']::text[], 'A legat aia de un obiect mai departe.', 'Întrebări cu arătatul'),
  ('s46-b23-z4-mental', 'Alege: asta sau aia?', ARRAY['2 obiecte — unul aproape, unul mai departe']::text[], ARRAY['„Asta sau aia?” — arătați ambele.', 'El alege arătând sau atingând.', 'Dacă vrea: el inventează întrebarea pe cele două.']::text[], 'A ales între asta și aia.', 'Întrebări cu arătatul'),
  ('s46-b23-z4-resurse', 'Alege 1 din 2 — apoi gata', ARRAY['2 obiecte']::text[], ARRAY['„Acesta sau acesta? Asta sau aia?”', 'După alegere: „Gata. Ajunge.”', 'Dacă vrea: celălalt obiect merge tot la loc.']::text[], 'A ales unul; jocul e închis.', 'Întrebări cu arătatul'),
  ('s46-b23-z4-social', 'Întrebăm împreună pe rând', ARRAY['1 obiect drag']::text[], ARRAY['Împreună: „Unde?” — căutați cu ochii.', 'Când e găsit: „Asta! Gata.”', 'Dacă vrea: încă o rundă, el conduce întrebarea.']::text[], 'Ați întrebat și răspuns împreună.', 'Întrebări cu arătatul'),
  ('s46-b23-z5-fizic', 'Traseu unde-e: trei opriri', ARRAY['3 obiecte / 3 locuri']::text[], ARRAY['La fiecare oprire: „Unde?” — arătați obiectul.', 'Treceți la următorul: „Asta. Aia.”', 'Dacă vrea: el alege ordinea celor trei.']::text[], 'A făcut trei opriri cu arătatul.', 'Întrebări cu arătatul'),
  ('s46-b23-z5-mental', 'Unde, asta, aia — pe scurt', ARRAY['2–3 obiecte']::text[], ARRAY['Spuneți pe rând: „Unde?” „Asta.” „Aia.” cu gest.', 'El repetă un cuvânt sau doar arată.', 'Dacă vrea: el inventează ordinea cuvintelor.']::text[], 'A auzit și legat cele trei cuvinte de gest.', 'Întrebări cu arătatul'),
  ('s46-b23-z5-social', 'Arată adultului — unde e?', ARRAY['o persoană dragă sau jucărie-personaj']::text[], ARRAY['Invitați-l să arate cuiva: „Unde? Uite.”', 'Adultul răspunde: „Asta! Mulțumesc.”', 'Dacă vrea: el inventează o întrebare nouă pentru adult.']::text[], 'A arătat și a primit răspuns de la adult.', 'Întrebări cu arătatul'),
  ('s46-b23-z6-fizic', 'Vânătoare liberă scurtă în cameră', ARRAY['cameră cunoscută']::text[], ARRAY['„Unde e [jucăria]?” — căutați liber 30–40 de secunde.', 'Când e găsit: „Asta. Gata.”', 'Dacă vrea: el alege ce căutați următorul.']::text[], 'A căutat liber și a închis cu găsitul.', 'Întrebări cu arătatul'),
  ('s46-b23-z6-mental', 'Ce am întrebat azi?', '{}'::text[], ARRAY['Reamintiți: „Am zis unde? Asta?” — arătați gesturile.', 'El alege gestul favorit.', 'Dacă vrea: inventează o întrebare nouă doar cu arătatul.']::text[], 'A recunoscut un gest de întrebare.', 'Întrebări cu arătatul'),
  ('s46-b23-z6-social', 'Arată-i altcuiva asta și aia', ARRAY['persoană dragă / jucărie']::text[], ARRAY['Arătați împreună: „Asta.” apoi „Aia.”', 'Persoana dragă confirmă: „Da. Uite.”', 'Dacă vrea: el conduce arătatul singur o rundă.']::text[], 'A împărtășit asta / aia cu cineva.', 'Întrebări cu arătatul'),
  ('s46-b23-z7-fizic', 'Arătat liber — cum vrea el', ARRAY['2 obiecte la îndemână']::text[], ARRAY['El arată ce vrea; voi spuneți blând „Asta” sau „Aia”.', 'Fără vânătoare forțată — doar arătat.', 'Dacă vrea: un singur „Unde?” șoptit, apoi gata.']::text[], 'A arătat liber (sau a refuzat — e bine).', 'Întrebări cu arătatul'),
  ('s46-b23-z7-mental', 'Favoritul: unde, asta sau aia?', '{}'::text[], ARRAY['Întrebați: „Îți place unde, asta sau aia?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: o rundă scurtă doar pe favorit.']::text[], 'A ales sau a privit cuvântul / gestul favorit.', 'Întrebări cu arătatul'),
  ('s46-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['1–2 obiecte']::text[], ARRAY['„La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un ultim asta pe raft, apoi calm.']::text[], 'Spațiul e gata înainte de calm.', 'Întrebări cu arătatul'),
  ('s46-b23-z7-social', 'Ritual: bună seara — unde e liniștea?', '{}'::text[], ARRAY['Șoptiți: „Bună seara. Unde? Aici — liniște.”', '„Asta. Noapte bună.”', 'Dacă vrea: un aia spre fereastră / lampă, apoi odihnă.']::text[], 'Ați închis săptămâna întrebărilor cu ritual blând.', 'Întrebări cu arătatul'),
  ('s47-b23-z1-fizic', 'Trei lucruri cărate la loc', ARRAY['3 obiecte pe jos', 'raft / cutie']::text[], ARRAY['Alegeți trei: „Unu. Doi. Trei. La loc.”', 'Cărați-le pe rând la loc, fără grabă.', 'Dacă vrea: pe două obiecte — „Al meu. Al meu.” „Al tău. Al tău.”']::text[], 'A cărat sau a văzut cărate trei lucruri la loc.', 'Grijă de lucruri'),
  ('s47-b23-z1-resurse', 'Al meu — la loc', ARRAY['1 obiect al lui', 'locul lui']::text[], ARRAY['„Al meu. Al meu.” — arătați obiectul.', '„La loc. La loc. Gata.”', 'Dacă vrea: comparați cu al vostru — „Al tău. Al tău.”']::text[], 'Obiectul lui e la loc.', 'Grijă de lucruri'),
  ('s47-b23-z1-social', 'Ajutor la strâns împreună', ARRAY['2–3 obiecte']::text[], ARRAY['„Împreună. La loc.” — fiecare ia câte unul.', 'La raft: „Gata. Mulțumesc.”', 'Dacă vrea: pe două — al meu / al tău înainte de pus.']::text[], 'Ați strâns împreună pe scurt.', 'Grijă de lucruri'),
  ('s47-b23-z2-fizic', 'Cărăm cutia de grijă — scurt', ARRAY['cutie ușoară cu 2–3 lucruri']::text[], ARRAY['Ridicați cutia împreună: „La loc. Cărăm.”', 'Duceți 4–6 pași până la locul ei.', 'Dacă vrea: el alege ce rămâne în cutie.']::text[], 'A cărat cutia (sau a ținut o mână).', 'Grijă de lucruri'),
  ('s47-b23-z2-mental', 'Același tip la un loc', ARRAY['4 obiecte — 2 tipuri']::text[], ARRAY['Sortați: „Astea aici. Astea aici.”', '„De ce aici? — La fel.”', 'Dacă vrea: al meu pe un tip, al tău pe celălalt.']::text[], 'A sortat pe tipuri pe scurt.', 'Grijă de lucruri'),
  ('s47-b23-z2-resurse', 'Al tău — la locul lui', ARRAY['1 obiect al adultului']::text[], ARRAY['„Al tău. Al tău.” — arătați.', 'Puneți la loc: „La loc. Ajunge.”', 'Dacă vrea: el duce obiectul vostru (ajutor).']::text[], 'Obiectul adultului e la loc.', 'Grijă de lucruri'),
  ('s47-b23-z2-social', 'Rândul la pus în cutie', ARRAY['cutie', '3 obiecte']::text[], ARRAY['Voi: „Acum eu. La loc.” — puneți unul.', '„Acum tu” — așteptați.', 'Dacă vrea: încă un schimb al meu / al tău pe două obiecte.']::text[], 'Ați schimbat rândul la strâns.', 'Grijă de lucruri'),
  ('s47-b23-z3-fizic', 'Traseu: pe jos → raft', ARRAY['2 obiecte pe jos', 'raft']::text[], ARRAY['Luați un obiect: „La loc.”', 'Duceți la raft: „La loc. Gata.”', 'Dacă vrea: al doilea obiect — „Al meu sau al tău?”']::text[], 'A dus cel puțin un obiect pe traseul la raft.', 'Grijă de lucruri'),
  ('s47-b23-z3-resurse', 'Ajunge — grijă terminată', '{}'::text[], ARRAY['După 2–3 lucruri: „Ajunge. Gata.”', '„La loc e gata pentru acum.”', 'Dacă vrea: un ultim obiect — al meu sau al tău.']::text[], 'Grija de lucruri e închisă.', 'Grijă de lucruri'),
  ('s47-b23-z3-social', 'Oferă ajutor — strângem', ARRAY['1 obiect greu pentru el, ușor împreună']::text[], ARRAY['„Ajutor? Împreună.”', 'Duceți la loc: „La loc. Mulțumesc.”', 'Dacă vrea: el oferă ajutor pe un obiect al vostru (al tău).']::text[], 'Ați cerut / oferit ajutor la strâns.', 'Grijă de lucruri'),
  ('s47-b23-z4-fizic', 'Trei în coș — apoi la loc', ARRAY['coș / cutie', '3 obiecte']::text[], ARRAY['Puneți trei în coș: „Unu. Doi. Trei.”', 'Duceți coșul la locul lui: „La loc.”', 'Dacă vrea: scoateți două — „Al meu. Al tău.”']::text[], 'A umplut și dus coșul pe scurt.', 'Grijă de lucruri'),
  ('s47-b23-z4-mental', 'Al meu, al tău — pe două', ARRAY['2 obiecte clare']::text[], ARRAY['Arătați: „Al meu. Al meu.”', '„Al tău. Al tău.”', 'Dacă vrea: el pune fiecare la locul lui după etichetă.']::text[], 'A auzit al meu / al tău pe două obiecte.', 'Grijă de lucruri'),
  ('s47-b23-z4-resurse', 'Alege 1 din 2 de strâns', ARRAY['2 obiecte pe jos']::text[], ARRAY['„Pe care îl strângem? Acesta sau acesta?”', 'După: „La loc. Ajunge.”', 'Dacă vrea: și pe al doilea — la loc scurt.']::text[], 'A ales ce strânge; restul poate rămâne.', 'Grijă de lucruri'),
  ('s47-b23-z4-social', 'Strângem pe rând — al meu / al tău', ARRAY['2 obiecte']::text[], ARRAY['Voi strângeți „al tău”; el „al meu” (sau invers).', 'La final: „Împreună. La loc. Gata.”', 'Dacă vrea: schimbați obiectele o dată.']::text[], 'Ați strâns pe rând cu etichete al meu / al tău.', 'Grijă de lucruri'),
  ('s47-b23-z5-fizic', 'Grijă pe traseu: trei opriri', ARRAY['3 obiecte în 3 locuri']::text[], ARRAY['La fiecare: ridicați → duceți la loc → „La loc.”', 'Trei opriri, fără grabă.', 'Dacă vrea: la două spuneți al meu / al tău.']::text[], 'A făcut trei opriri de grijă.', 'Grijă de lucruri'),
  ('s47-b23-z5-resurse', 'La loc — ajunge grija', ARRAY['ultimele 1–2 obiecte']::text[], ARRAY['„La loc.”', '„Ajunge. Gata la loc.”', 'Dacă vrea: verifică raftul — „Totul e bine?”']::text[], 'Grija e închisă cu la loc.', 'Grijă de lucruri'),
  ('s47-b23-z5-social', 'Arată adultului: am strâns', ARRAY['spațiu strâns']::text[], ARRAY['Invitați-l să arate raftul: „Uite. La loc.”', 'Adultul: „Bravo. Mulțumesc.”', 'Dacă vrea: arată care e al meu și care e al tău.']::text[], 'A împărtășit rezultatul strânsului.', 'Grijă de lucruri'),
  ('s47-b23-z6-fizic', 'Strâns liber scurt în cameră', ARRAY['cameră cu 2–4 obiecte pe jos']::text[], ARRAY['Strângeți liber 30–40 de secunde: „La loc.”', 'Opriți-vă: „Gata. Ajunge.”', 'Dacă vrea: denumiți al meu / al tău pe două rămase.']::text[], 'A strâns liber pe scurt.', 'Grijă de lucruri'),
  ('s47-b23-z6-resurse', 'Cutia plină / goală — la loc', ARRAY['cutie']::text[], ARRAY['Arătați: „Plină” sau „Goală.”', '„La loc. La loc. Ajunge.”', 'Dacă vrea: el alege dacă mai pune un obiect.']::text[], 'Cutia e la loc; grija e gata.', 'Grijă de lucruri'),
  ('s47-b23-z6-social', 'Strângem cu cineva drag', ARRAY['persoană dragă / jucărie-personaj']::text[], ARRAY['Împreună: „La loc. Împreună.”', 'La final: „Mulțumesc.”', 'Dacă vrea: al meu pentru el, al tău pentru adult.']::text[], 'A strâns cu cineva drag pe scurt.', 'Grijă de lucruri'),
  ('s47-b23-z7-fizic', 'Un singur lucru la loc — cum vrea el', ARRAY['1 obiect']::text[], ARRAY['El alege un obiect (sau refuză).', 'Duceți-l blând: „La loc. La loc.”', 'Dacă vrea: al meu sau al tău pe acel obiect.']::text[], 'A pus un lucru la loc (sau a refuzat — e bine).', 'Grijă de lucruri'),
  ('s47-b23-z7-mental', 'Favoritul: la loc, al meu sau al tău?', '{}'::text[], ARRAY['Întrebați: „Îți place la loc, al meu sau al tău?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: o rundă scurtă doar pe favorit.']::text[], 'A ales sau a privit cuvântul favorit.', 'Grijă de lucruri'),
  ('s47-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['1–2 obiecte']::text[], ARRAY['„La loc.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un ultim la loc șoptit, apoi calm.']::text[], 'Spațiul e gata înainte de calm.', 'Grijă de lucruri'),
  ('s47-b23-z7-social', 'Ritual: bună seara — lucrurile dorm', '{}'::text[], ARRAY['Șoptiți: „Bună seara. La loc. Lucrurile sunt la loc.”', '„Al meu. Al tău. Noapte bună.”', 'Dacă vrea: un salut blând raftului, apoi odihnă.']::text[], 'Ați închis săptămâna grijii cu ritual blând.', 'Grijă de lucruri'),
  ('s48-b23-z1-fizic', 'Gest de salut — undă bună', '{}'::text[], ARRAY['Modelați unda: „Bună.” — mâna se mișcă.', 'El încearcă unda (sau privește) — fără forțare.', 'Dacă vrea: alege formula — bună sau salut (cu același gest).']::text[], 'A făcut sau a văzut gestul de salut.', 'Salut și la revedere'),
  ('s48-b23-z1-mental', 'Două formule: bună și la revedere', '{}'::text[], ARRAY['Arătați: „Bună” + undă. Apoi: „La revedere” + undă de plecare.', '„Alege una.” — așteptați gest sau privire.', 'Dacă vrea: el alege formula și o repetă (sau doar gest).']::text[], 'A auzit și ales între bună și la revedere.', 'Salut și la revedere'),
  ('s48-b23-z1-resurse', 'Ritual plecare — gata', ARRAY['ușă / pantofi / geantă mică']::text[], ARRAY['La ușă: „La revedere. Gata.”', '„Ajunge. Plecarea e gata pentru joc.”', 'Dacă vrea: el alege dacă undă bună sau la revedere.']::text[], 'Ritualul de plecare e închis.', 'Salut și la revedere'),
  ('s48-b23-z1-social', 'Salut și la revedere pe rând', '{}'::text[], ARRAY['Voi: „Bună!” — undă.', 'Apoi: „Acum tu” — așteptați; apoi „La revedere” pe rând.', 'Dacă vrea: alege formula preferată pentru runda următoare.']::text[], 'Ați schimbat salutul și la revederea pe rând.', 'Salut și la revedere'),
  ('s48-b23-z2-fizic', 'Bună scurt — undă mică', '{}'::text[], ARRAY['Undă mică: „Bună.”', 'Repetați 2–3 ori, blând, pe loc.', 'Dacă vrea: el alege salut sau bună pentru următoarea undă.']::text[], 'A exersat unda bună pe scurt.', 'Salut și la revedere'),
  ('s48-b23-z2-mental', 'Bună la venire, la revedere la plecare', ARRAY['ușă sau prag']::text[], ARRAY['La „venire”: „Bună.”', 'La „plecare”: „La revedere.” — 1 rundă fiecare.', 'Dacă vrea: el alege care face primul.']::text[], 'A legat bună de venire și la revedere de plecare.', 'Salut și la revedere'),
  ('s48-b23-z2-resurse', 'Geanta / pantofii — gata plecarea', ARRAY['pantofi sau geantă jucărie']::text[], ARRAY['Așezați: „La loc lângă ușă. Gata.”', '„Ajunge. Ritualul e gata.”', 'Dacă vrea: un la revedere pantofilor, apoi oprim joc.']::text[], 'Obiectele de plecare sunt gata.', 'Salut și la revedere'),
  ('s48-b23-z2-social', 'Salutăm jucăria — bună / la revedere', ARRAY['1 jucărie-personaj']::text[], ARRAY['„Bună, [jucărie]!” — undă.', '„La revedere!” — undă de plecare.', 'Dacă vrea: el alege formula pentru jucărie.']::text[], 'A salutat și a spus la revedere jucăriei.', 'Salut și la revedere'),
  ('s48-b23-z3-fizic', 'Undă mare, undă mică — salut', '{}'::text[], ARRAY['Undă mare: „Bună!”', 'Undă mică: „Bună.”', 'Dacă vrea: el alege mărimea undei și formula.']::text[], 'A încercat undă mare și undă mică.', 'Salut și la revedere'),
  ('s48-b23-z3-mental', 'Alege formula — bună, bună sau la revedere', '{}'::text[], ARRAY['Arătați trei gesturi scurte cu cele trei cuvinte.', '„Tu alegi.” — stați pe alegerea lui.', 'Dacă vrea: repetă formula aleasă o dată.']::text[], 'A ales o formulă din trei.', 'Salut și la revedere'),
  ('s48-b23-z3-resurse', 'După la revedere — totul la loc', ARRAY['1 obiect de „plecare”']::text[], ARRAY['„La revedere. Gata.”', 'Obiectul la loc: „La loc. Ajunge.”', 'Dacă vrea: un bună de „ne-am întors”, apoi la loc.']::text[], 'După la revedere, obiectul e la loc.', 'Salut și la revedere'),
  ('s48-b23-z3-social', 'Rândul: eu bună, tu la revedere', '{}'::text[], ARRAY['Voi: „Bună!”', 'El (sau model): „La revedere!” — apoi schimbați.', 'Dacă vrea: alege cine începe cu bună.']::text[], 'Ați alternat bună și la revedere pe rând.', 'Salut și la revedere'),
  ('s48-b23-z4-fizic', 'Salut pe traseu: ușă → hol → ușă', ARRAY['ușă / prag']::text[], ARRAY['La ușă: „Bună.” — undă.', 'Mergeți 4–6 pași și înapoi: „La revedere” la ușă.', 'Dacă vrea: pe drum alege bună în loc de bună.']::text[], 'A legat salutul de un traseu scurt la ușă.', 'Salut și la revedere'),
  ('s48-b23-z4-mental', 'Când zicem bună? Când la revedere?', '{}'::text[], ARRAY['„Când venim — bună. Când plecăm — la revedere.”', 'Jucați 1 venire + 1 plecare pe prag.', 'Dacă vrea: el alege formula pentru venire.']::text[], 'A legat formulele de venire / plecare.', 'Salut și la revedere'),
  ('s48-b23-z4-resurse', 'Alege 1 din 2: bună sau la revedere acum', '{}'::text[], ARRAY['„Acum: bună sau la revedere?”', 'După alegere: „Gata. Ajunge.”', 'Dacă vrea: și pe cealaltă, scurt, apoi gata.']::text[], 'A ales o formulă; ritualul e închis.', 'Salut și la revedere'),
  ('s48-b23-z4-social', 'Salutăm pe cineva drag', ARRAY['persoană dragă / poză / jucărie']::text[], ARRAY['„Bună!” spre persoana dragă — undă.', 'La final: „La revedere!” — fără forțare.', 'Dacă vrea: el alege bună pentru salutul scurt.']::text[], 'A salutat pe cineva drag (sau jucăria).', 'Salut și la revedere'),
  ('s48-b23-z5-fizic', 'Trei unde: bună, bună, la revedere', '{}'::text[], ARRAY['Trei unde pe rând, denumind fiecare.', 'Pauză scurtă între ele — fără grabă.', 'Dacă vrea: el alege ordinea celor trei.']::text[], 'A făcut sau a văzut trei unde denumite.', 'Salut și la revedere'),
  ('s48-b23-z5-mental', 'Bună / bună / la revedere — pe scurt', '{}'::text[], ARRAY['Spuneți cele trei cu gest; el arată favoritul.', 'Confirmați: „Da. Acesta.”', 'Dacă vrea: inventează o rundă doar pe favorit.']::text[], 'A ales un favorit dintre cele trei.', 'Salut și la revedere'),
  ('s48-b23-z5-resurse', 'Ritual plecare de trei ori — apoi ajunge', ARRAY['ușă']::text[], ARRAY['Trei la revedere scurte la ușă (sau bună + la revedere + bună).', '„Ajunge. Gata.”', 'Dacă vrea: el spune când e ajunge (gest).']::text[], 'Ritualul e gata după trei.', 'Salut și la revedere'),
  ('s48-b23-z5-social', 'Pe rând cu adultul — formule', '{}'::text[], ARRAY['Schimbați: adult bună → copil bună → adult la revedere.', 'Sau orice ordine vrea el.', 'Dacă vrea: el alege formula pentru adult.']::text[], 'Ați schimbat formulele pe rând.', 'Salut și la revedere'),
  ('s48-b23-z6-fizic', 'Salut liber scurt — undă cum vrea', '{}'::text[], ARRAY['El face unda cum vrea 20–30 de secunde.', 'Voi numiți blând: „Bună” sau „Bună” sau „La revedere”.', 'Dacă vrea: alege el cuvântul pentru unda lui.']::text[], 'A unduit liber pe scurt.', 'Salut și la revedere'),
  ('s48-b23-z6-mental', 'Ce formulă am folosit azi?', '{}'::text[], ARRAY['Reamintiți cu gesturi: bună / bună / la revedere.', 'El alege pe care o ține minte.', 'Dacă vrea: o repetă o dată.']::text[], 'A recunoscut o formulă de azi.', 'Salut și la revedere'),
  ('s48-b23-z6-resurse', 'La loc după jocul de salut', ARRAY['jucărie / pantofi de joc']::text[], ARRAY['„La revedere, joc. La loc.”', '„Ajunge. Gata.”', 'Dacă vrea: un bună de „ne vedem mâine” șoptit.']::text[], 'Obiectele de joc sunt la loc.', 'Salut și la revedere'),
  ('s48-b23-z6-social', 'Arată-i altcuiva salutul', ARRAY['persoană dragă']::text[], ARRAY['Mergeți / arătați: „Bună!” spre persoana dragă.', '„La revedere!” la final — poate refuza.', 'Dacă vrea: el alege bună ca formulă scurtă.']::text[], 'A împărtășit un salut cu cineva.', 'Salut și la revedere'),
  ('s48-b23-z7-fizic', 'Undă blândă — cum vrea el', '{}'::text[], ARRAY['El dictează: undă, sau doar stă.', 'Voi urmați cu un bună sau la revedere șoptit.', 'Dacă vrea: un bună mic, apoi gata.']::text[], 'A ales ritmul undei (sau a refuzat — e bine).', 'Salut și la revedere'),
  ('s48-b23-z7-mental', 'Favoritul: bună, bună sau la revedere?', '{}'::text[], ARRAY['Întrebați: „Îți place bună, bună sau la revedere?” — gesturi.', 'Stați pe alegerea lui.', 'Dacă vrea: o rundă scurtă doar pe favorit.']::text[], 'A ales sau a privit formula favorită.', 'Salut și la revedere'),
  ('s48-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['1–2 obiecte']::text[], ARRAY['„La loc. La revedere, jucării.”', '„Gata. Acum e liniște.”', 'Dacă vrea: un bună de noapte bună șoptit raftului.']::text[], 'Spațiul e gata înainte de calm.', 'Salut și la revedere'),
  ('s48-b23-z7-social', 'Ritual: bună seara — la revedere blând', '{}'::text[], ARRAY['Șoptiți: „Bună seara. La revedere.” — undă mică.', '„Bună, noapte bună.” — fără forțare.', 'Dacă vrea: alege formula de închidere, apoi odihnă.']::text[], 'Ați închis săptămâna salutului cu ritual blând.', 'Salut și la revedere'),
  ('s49-b23-z1-fizic', 'Reluăm jocul fizic favorita', ARRAY['spațiu liber']::text[], ARRAY['Alegeți un joc pe care l-a iubit anul ăsta (pași / minge / geam): „Favorita.”', 'Faceți o rundă scurtă: „Din nou.”', 'Dacă vrea: ordonați 2 favorita — întâi… apoi…']::text[], 'A reluat un joc fizic favorit pe scurt.', 'Repetăm 3 favorita'),
  ('s49-b23-z1-mental', 'Alege favorita — de ce?', ARRAY['2–3 amintiri / gesturi de jocuri din an']::text[], ARRAY['Arătați 2–3: „Care e favorita?”', '„De ce?” — așteptați gest sau 1 cuvânt; fără notare.', 'Dacă vrea: ordonați 2 — asta întâi, asta apoi.']::text[], 'A ales o favorită (gest e destul).', 'Repetăm 3 favorita'),
  ('s49-b23-z1-resurse', 'Alege 1 din 3 favorita', ARRAY['3 obiecte / zone din jocuri iubite']::text[], ARRAY['Arătați trei: „Una. Favorita.”', 'El alege una: „Gata. Ajunge.”', 'Dacă vrea: puneți cele 3 în ordine — 1, 2, 3.']::text[], 'A ales una din trei favorita.', 'Repetăm 3 favorita'),
  ('s49-b23-z1-social', 'Joacă favorita cu adultul', ARRAY['jocul ales']::text[], ARRAY['„Favorita împreună.” — o rundă scurtă.', '„Gata.” — oprire blândă.', 'Dacă vrea: din nou o dată, apoi gata.']::text[], 'A jucat favorita cu adultul pe scurt.', 'Repetăm 3 favorita'),
  ('s49-b23-z2-fizic', 'Din nou — aceeași mișcare de două ori', ARRAY['spațiu liber']::text[], ARRAY['O mișcare pe care o știe: „Una.”', '„Din nou.” — a doua oară, la fel.', 'Dacă vrea: alegeți a doua mișcare favorita și ordonați-le.']::text[], 'A repetat mișcarea cu din nou.', 'Repetăm 3 favorita'),
  ('s49-b23-z2-mental', 'Trei favorita — care e unu?', ARRAY['3 gesturi / obiecte din an']::text[], ARRAY['Arătați trei: „Favorita… favorita… favorita.”', '„Care e unu?” — așteptați alegerea, fără test.', 'Dacă vrea: puneți 1–2–3 în ordine cu el.']::text[], 'A ales prima dintre trei favorita.', 'Repetăm 3 favorita'),
  ('s49-b23-z2-resurse', 'Jucăria favorita — la loc după', ARRAY['1 jucărie favorită']::text[], ARRAY['Joacă scurtă: „Favorita.”', '„Gata. La loc.”', 'Dacă vrea: alegeți între 2 jucării favorita unde stau.']::text[], 'Jucăria favorită e la loc.', 'Repetăm 3 favorita'),
  ('s49-b23-z2-social', 'Arată-i altcuiva favorita', ARRAY['persoană dragă', 'joc / obiect']::text[], ARRAY['Mergeți la cineva drag: „Favorita. Uite.”', 'El arată sau joacă o clipă.', 'Dacă vrea: din nou pe scurt, apoi gata.']::text[], 'A arătat favorita cuiva din casă.', 'Repetăm 3 favorita'),
  ('s49-b23-z3-fizic', 'Traseu scurt al celor 3 favorita', ARRAY['2–3 locuri din jocuri iubite']::text[], ARRAY['„Întâi aici… apoi acolo.” — traseu scurt al favoritelor.', '„Gata.” la final.', 'Dacă vrea: el ordonează cele 2–3 locuri — care primul.']::text[], 'A mers pe traseul favoritelor.', 'Repetăm 3 favorita'),
  ('s49-b23-z3-mental', 'Favorita de vară sau de casă?', ARRAY['2 zone / amintiri']::text[], ARRAY['Arătați două: „Care e favorita?”', 'Stați pe alegerea lui o clipă.', 'Dacă vrea: ordonați — întâi asta, apoi cealaltă.']::text[], 'A ales între două amintiri favorita.', 'Repetăm 3 favorita'),
  ('s49-b23-z3-resurse', 'Ajunge — o favorită azi', ARRAY['2–3 opțiuni']::text[], ARRAY['„Azi una. Favorita.” — alegeți împreună.', '„Gata. Ajunge.”', 'Dacă vrea: ordonați restul pentru mâine (gest).']::text[], 'O singură favorită e aleasă pentru azi.', 'Repetăm 3 favorita'),
  ('s49-b23-z3-social', 'Rândul la favorita', ARRAY['joc scurt']::text[], ARRAY['„Acum eu — favorita.” O rundă.', '„Acum tu.” — așteptați.', 'Dacă vrea: din nou pe rând, apoi gata.']::text[], 'Ați schimbat rândul la jocul favorit.', 'Repetăm 3 favorita'),
  ('s49-b23-z4-fizic', 'Corp favorit: sărit / pași / pe loc', ARRAY['spațiu liber']::text[], ARRAY['El alege: sărituri, pași sau pe loc: „Favorita.”', 'O rundă: „Gata.”', 'Dacă vrea: din nou + a doua alegere, în ordine.']::text[], 'A făcut mișcarea corporală aleasă.', 'Repetăm 3 favorita'),
  ('s49-b23-z4-mental', 'De ce e favorita? — 1 frază / gest', ARRAY['obiectul / jocul ales']::text[], ARRAY['Țineți alegerea: „De ce e favorita?”', 'Modelați o frază scurtă sau acceptați gestul — fără evaluare.', 'Dacă vrea: comparați cu a doua favorită — care întâi.']::text[], 'A motivat (gest/cuvânt) favorita.', 'Repetăm 3 favorita'),
  ('s49-b23-z4-resurse', 'Trei pe masă — alege una', ARRAY['3 obiecte favorita pe masă / jos']::text[], ARRAY['„Trei. Alege favorita.”', 'Celelalte: „La loc. Gata.”', 'Dacă vrea: ordonați cele 3 înainte de a alege.']::text[], 'A ales una; restul la loc.', 'Repetăm 3 favorita'),
  ('s49-b23-z4-social', 'Eu gata, tu din nou', ARRAY['joc scurt']::text[], ARRAY['Voi: „Gata.” — opriți.', 'El: „Din nou?” — dacă vrea, o rundă; dacă nu, gata.', 'Dacă vrea: el spune gata primul.']::text[], 'Ați folosit gata / din nou împreună.', 'Repetăm 3 favorita'),
  ('s49-b23-z5-fizic', 'Din nou pe traseul cunoscut', ARRAY['traseu scurt în casă (2–3 puncte)']::text[], ARRAY['Faceți traseul o dată: „Una.”', '„Din nou.” — a doua oară.', 'Dacă vrea: el schimbă ordinea punctelor.']::text[], 'A repetat traseul cu din nou.', 'Repetăm 3 favorita'),
  ('s49-b23-z5-mental', 'Trei favorita din an — care?', ARRAY['3 amintiri: drum / curte / casă']::text[], ARRAY['Arătați trei amintiri din săptămânile trecute.', '„Care e favorita?”', 'Dacă vrea: ordonați 2–3 favorita din an.']::text[], 'A ales o amintire favorită din an.', 'Repetăm 3 favorita'),
  ('s49-b23-z5-resurse', 'Gata — totul la loc după favorita', ARRAY['obiectele din joc']::text[], ARRAY['După joc: „Gata. La loc.”', '„Ajunge.”', 'Dacă vrea: alegeți ce rămâne la vedere (1 din 2).']::text[], 'După favorita, lucrurile sunt la loc.', 'Repetăm 3 favorita'),
  ('s49-b23-z5-social', 'Împreună: favorita, apoi gata', ARRAY['joc ales']::text[], ARRAY['„Favorita împreună.” — scurt.', 'Împreună: „Gata.”', 'Dacă vrea: din nou o dată dacă amândoi vreți.']::text[], 'Ați închis favorita cu gata împreună.', 'Repetăm 3 favorita'),
  ('s49-b23-z6-fizic', 'Mișcare liberă — ce e favorita azi', ARRAY['spațiu liber']::text[], ARRAY['El alege mișcarea: „Favorita.”', 'Voi urmăriți blând: „Gata” când se oprește.', 'Dacă vrea: din nou sau treceți la a doua favorită.']::text[], 'A mișcat liber pe alegerea lui.', 'Repetăm 3 favorita'),
  ('s49-b23-z6-mental', 'Ce am iubit anul ăsta?', ARRAY['spațiu calm']::text[], ARRAY['„Anul ăsta. Favorita…” — numiți 1–2 amintiri blând.', 'El adaugă gest sau cuvânt — fără întrebări.', 'Dacă vrea: ordonați 2–3 pe degete.']::text[], 'Ați numit cel puțin o favorită din an.', 'Repetăm 3 favorita'),
  ('s49-b23-z6-resurse', 'Alege 1 din 3 — apoi gata', ARRAY['3 zone / obiecte']::text[], ARRAY['„Una din trei. Favorita.”', '„Gata. Ajunge pentru azi.”', 'Dacă vrea: celelalte două în ordine pe loc.']::text[], 'A ales una din trei; gata.', 'Repetăm 3 favorita'),
  ('s49-b23-z6-social', 'Arătăm favoritele adultului', ARRAY['1–2 obiecte / gesturi']::text[], ARRAY['„Favorita. Uite.” — arătați împreună.', 'Adultul mulțumește blând: „Frumos.”', 'Dacă vrea: din nou pe scurt, apoi gata.']::text[], 'A împărtășit favoritele cu adultul.', 'Repetăm 3 favorita'),
  ('s49-b23-z7-fizic', 'Mișcare liberă — favorita blândă', ARRAY['spațiu liber']::text[], ARRAY['El alege; voi urmăriți blând.', 'Fără grabă: „Favorita… gata.”', 'Dacă vrea: din nou o dată foarte scurt.']::text[], 'A mișcat liber pe favorita zilei.', 'Repetăm 3 favorita'),
  ('s49-b23-z7-mental', 'Favoritul săptămânii — din nou sau gata?', ARRAY['amintirea săptămânii']::text[], ARRAY['„Azi favorita e…” — arătați alegerea lui.', '„Din nou sau gata?” — respectați.', 'Dacă vrea: ordonați 2 favorita ale săptămânii.']::text[], 'A închis mental săptămâna pe o favorită.', 'Repetăm 3 favorita'),
  ('s49-b23-z7-resurse', 'Totul la loc — gata înainte de calm', ARRAY['jucării folosite']::text[], ARRAY['„Gata. La loc.”', '„Acum e liniște.”', 'Dacă vrea: un obiect favorita rămâne la vedere.']::text[], 'Lucrurile sunt la loc; calm.', 'Repetăm 3 favorita'),
  ('s49-b23-z7-social', 'Ritual: bună seara, favorita blândă', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara. Favorita…” — un gest scurt.', '„Gata. Noapte bună.”', 'Dacă vrea: din nou pe un salut mic, apoi odihnă.']::text[], 'Ați închis seara cu ritual de favorita.', 'Repetăm 3 favorita'),
  ('s50-b23-z1-fizic', '30 de secunde mișcare, 30 de calm', ARRAY['spațiu liber în casă']::text[], ARRAY['Mișcați-vă ușor ~30 de secunde: „Mișcare.”', 'Opriți-vă: „Calm. Liniște.” — ~30 de secunde pe loc.', 'Dacă vrea: încă o rundă scurtă de 30s liniște.']::text[], 'Ați făcut mișcare scurtă, apoi calm.', 'Casă liniștită'),
  ('s50-b23-z1-mental', 'Ce ați auzit în liniște?', ARRAY['cameră liniștită']::text[], ARRAY['Stați liniște ~20 de secunde: „Liniște. Ascultăm.”', '„Ce ați auzit?” — un sunet sau „liniște”.', 'Dacă vrea: creați încă 30s de liniște împreună.']::text[], 'A auzit ceva (sau liniștea) pe scurt.', 'Casă liniștită'),
  ('s50-b23-z1-resurse', 'Jucăriile la loc înainte de calm', ARRAY['2–3 jucării pe jos', 'cutie / raft']::text[], ARRAY['Strângeți: „La loc.”', '„Acum calm. Moale.”', 'Dacă vrea: alegeți ce rămâne afară (1 din 2).']::text[], 'Jucăriile sunt la loc; casa e pregătită de calm.', 'Casă liniștită'),
  ('s50-b23-z1-social', 'Liniște împreună', '{}'::text[], ARRAY['Stați umăr la umăr: „Liniște împreună.”', '10–20 de secunde fără vorbă tare — moale.', 'Dacă vrea: el ține degetul la buze ca semnal de calm.']::text[], 'Ați împărtășit o clipă de liniște.', 'Casă liniștită'),
  ('s50-b23-z2-fizic', 'Pași moale prin casă', ARRAY['hol / cameră']::text[], ARRAY['Mergeți pe vârfuri sau pași ușori: „Moale. Pași.”', 'Opriți-vă: „Calm.”', 'Dacă vrea: el alege unde e cel mai liniște colț.']::text[], 'A făcut pași blânzi și s-a oprit calm.', 'Casă liniștită'),
  ('s50-b23-z2-mental', 'Liniște sau sunet? — două clipe', '{}'::text[], ARRAY['5 secunde liniște: „Liniște.”', 'O bătaie din palme: „Sunet.” Apoi iar liniște.', 'Dacă vrea: creați 30s de liniște după sunet.']::text[], 'A simțit diferența liniște / sunet.', 'Casă liniștită'),
  ('s50-b23-z2-resurse', 'Oprim jucăria sonoră — gata', ARRAY['jucărie sonoră', 'cutie']::text[], ARRAY['După un sunet scurt: „Gata. Liniște.”', '„La loc. Ajunge.”', 'Dacă vrea: el alege cutia sau raftul.']::text[], 'Jucăria sonoră e oprită și la loc.', 'Casă liniștită'),
  ('s50-b23-z2-social', 'Rândul la liniște', '{}'::text[], ARRAY['Voi: „Acum eu — liniște.” 5 secunde.', '„Acum tu” — așteptați liniștea lui.', 'Dacă vrea: încă un schimb, apoi moale împreună.']::text[], 'Ați schimbat rândul la o clipă de liniște.', 'Casă liniștită'),
  ('s50-b23-z3-fizic', 'Dans scurt, apoi calm', ARRAY['spațiu liber']::text[], ARRAY['Mișcare ~30 de secunde: „Mișcare.”', 'Mâinile pe genunchi: „Calm. Moale.”', 'Dacă vrea: încă 30s de liniște pe loc.']::text[], 'A trecut de la mișcare la calm.', 'Casă liniștită'),
  ('s50-b23-z3-mental', 'Unde e casa liniștită?', ARRAY['2 locuri: hol / colț de cameră']::text[], ARRAY['Arătați două locuri: „Unde e liniște?”', 'Stați în locul ales: „Calm aici.”', 'Dacă vrea: creați 30s de liniște în acel loc.']::text[], 'A ales un loc liniștit din casă.', 'Casă liniștită'),
  ('s50-b23-z3-resurse', 'Totul la loc — apoi moale', ARRAY['obiecte pe jos']::text[], ARRAY['„La loc.” — 2–3 lucruri.', '„Moale. Liniște. Ajunge.”', 'Dacă vrea: alegeți un obiect moale de ținut pe genunchi.']::text[], 'Casa e strânsă; urmează moale.', 'Casă liniștită'),
  ('s50-b23-z3-social', 'Liniște pe genunchi împreună', ARRAY['canapea / covor']::text[], ARRAY['Stați aproape: „Liniște. Calm.”', 'Respirați o dată vizibil, moale.', 'Dacă vrea: el spune când e gata calm (gest).']::text[], 'Ați stat liniștiți aproape unul de altul.', 'Casă liniștită'),
  ('s50-b23-z4-fizic', 'Întindere moale, apoi pe loc', '{}'::text[], ARRAY['Brațele sus blând: „Moale.”', 'Jos pe loc: „Calm. Liniște.”', 'Dacă vrea: încă 30s pe loc, fără mișcare mare.']::text[], 'A făcut o întindere moale și calm.', 'Casă liniștită'),
  ('s50-b23-z4-mental', 'Voce moale — un cuvânt', '{}'::text[], ARRAY['Spuneți un cuvânt tare, apoi moale: „Moale. Liniște.”', 'El poate doar asculta.', 'Dacă vrea: el alege un cuvânt pe care îl spuneți moale.']::text[], 'A auzit voce moale pe scurt.', 'Casă liniștită'),
  ('s50-b23-z4-resurse', 'Alege 1 din 2 — jucăria liniște', ARRAY['2 jucării: una sonoră, una fără sunet']::text[], ARRAY['„Care e liniște?” — arătați ambele.', 'Alegeți una: „Ajunge. La loc pe cealaltă.”', 'Dacă vrea: 30s de joacă moale cu cea liniște.']::text[], 'A ales jucăria liniștită; cealaltă la loc.', 'Casă liniștită'),
  ('s50-b23-z4-social', 'Arată-i adultului liniște', '{}'::text[], ARRAY['Invitați-l să arate colțul liniștit: „Liniște. Uite.”', 'Adultul șoptește: „Calm. Moale.”', 'Dacă vrea: stați 30s acolo împreună.']::text[], 'A arătat un loc liniște adultului.', 'Casă liniștită'),
  ('s50-b23-z5-fizic', 'Trei opriri calm pe traseu', ARRAY['hol: 3 puncte']::text[], ARRAY['La fiecare oprire: „Calm.” — 5 secunde.', 'Între opriri: pași moale.', 'Dacă vrea: la ultima oprire, 30s de liniște.']::text[], 'A făcut trei opriri calme pe traseu.', 'Casă liniștită'),
  ('s50-b23-z5-mental', 'Liniște, calm, moale — pe scurt', '{}'::text[], ARRAY['Spuneți pe rând cu gest: „Liniște.” „Calm.” „Moale.”', 'Repetați o dată, șoptit.', 'Dacă vrea: el arată care îi place — liniște / calm / moale.']::text[], 'A auzit cele trei cuvinte pe liniște.', 'Casă liniștită'),
  ('s50-b23-z5-resurse', 'Lumina sau jucăria — la loc pentru calm', ARRAY['întrerupător sau jucărie', 'locul lor']::text[], ARRAY['Pregătiți casa: „La loc.”', '„Acum liniște. Ajunge.”', 'Dacă vrea: alegeți lumină mică sau stins (cu adult).']::text[], 'Casa e pregătită pentru calm.', 'Casă liniștită'),
  ('s50-b23-z5-social', 'Liniște pe rând — eu, tu', '{}'::text[], ARRAY['Voi liniște 5 secunde: „Acum eu.”', 'El: „Acum tu” — așteptați.', 'Dacă vrea: la final 30s liniște împreună.']::text[], 'Ați făcut liniște pe rând.', 'Casă liniștită'),
  ('s50-b23-z6-fizic', 'Mișcare liberă, apoi calm liber', ARRAY['spațiu liber']::text[], ARRAY['El dictează ~30s mișcare.', 'Apoi: „Calm. Moale.” — cât vrea el pe loc.', 'Dacă vrea: încă 30s de liniște în locul ales.']::text[], 'A mișcat liber, apoi s-a calm pe loc.', 'Casă liniștită'),
  ('s50-b23-z6-mental', 'Ce ați auzit azi în casă?', ARRAY['cameră']::text[], ARRAY['Stați liniște 15–20 de secunde.', '„Ce ați auzit?” — oferiți 2 opțiuni arătate.', 'Dacă vrea: creați 30s de liniște „goală” (fără comentariu).']::text[], 'A reflectat blând la ce a auzit.', 'Casă liniștită'),
  ('s50-b23-z6-resurse', 'Totul la loc înainte de liniște', ARRAY['jucării folosite']::text[], ARRAY['„La loc.”', '„Liniște. Ajunge pentru azi.”', 'Dacă vrea: un obiect moale rămâne pe canapea.']::text[], 'Spațiul e strâns înainte de liniște.', 'Casă liniștită'),
  ('s50-b23-z6-social', 'Arătăm liniștea altcuiva', ARRAY['persoană dragă sau jucărie']::text[], ARRAY['Mergeți la cineva: „Liniște. Uite.” — gest de liniște.', 'Stați moale o clipă.', 'Dacă vrea: 30s liniște în trei (sau cu jucăria).']::text[], 'A împărtășit gestul de liniște.', 'Casă liniștită'),
  ('s50-b23-z7-fizic', 'Corp liber — calm cum vrea el', ARRAY['spațiu liber']::text[], ARRAY['El alege: mișcare scurtă sau doar calm pe loc.', 'Voi urmăriți blând: „Moale… calm.”', 'Dacă vrea: 30s liniște la final.']::text[], 'A ales ritmul calm al duminicii.', 'Casă liniștită'),
  ('s50-b23-z7-mental', 'Favoritul: liniște sau moale?', '{}'::text[], ARRAY['Întrebați: „Îți place liniște sau moale?” — arătați ambele gesturi.', 'Respectați alegerea; fără test.', 'Dacă vrea: creați 30s pe alegerea lui.']::text[], 'A ales un tip de liniște a săptămânii.', 'Casă liniștită'),
  ('s50-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['jucării']::text[], ARRAY['Strângeți: „La loc.”', '„Calm. Gata pentru azi.”', 'Dacă vrea: un ultim moale pe genunchi, apoi odihnă.']::text[], 'Spațiul e gata înainte de calm.', 'Casă liniștită'),
  ('s50-b23-z7-social', 'Ritual: bună seara — liniște, calm', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara. Liniște. Moale.”', '„Calm. Noapte bună.”', 'Dacă vrea: 30s de liniște înainte de somn.']::text[], 'Ați închis seara cu ritual de liniște.', 'Casă liniștită'),
  ('s51-b23-z1-fizic', 'Traseu cunoscut în curte', ARRAY['curte / balcon / potecă']::text[], ARRAY['Mergeți pe drum-ul pe care îl știți: „Drum.”', 'Opriți-vă la un loc cunoscut: „Curte.”', 'Dacă vrea: denumiți 3 locuri pe traseu — poartă / copac / iarbă.']::text[], 'A mers pe traseul cunoscut din curte.', 'Curtea cunoscută'),
  ('s51-b23-z1-mental', 'Hartă verbală: trei locuri', ARRAY['3 locuri vizibile în curte']::text[], ARRAY['Arătați: „Curte. Copac. Drum.” — sau echivalentele RO.', '„Unde e copac?” — așteptați arătarea.', 'Dacă vrea: el denumește cele 3 locuri (gest e destul).']::text[], 'A asociat cel puțin un loc din cele trei.', 'Curtea cunoscută'),
  ('s51-b23-z1-resurse', 'Întoarcere = gata curtea', ARRAY['ușă / punct de pornim']::text[], ARRAY['Spuneți: „Ne întoarcem. Gata curte.”', 'Ajungeți: „Acasă. Ajunge.”', 'Dacă vrea: alegeți pe unde vă întoarceți pe drum.']::text[], 'V-ați întors; curtea e închisă pentru acum.', 'Curtea cunoscută'),
  ('s51-b23-z1-social', 'Arată locul preferat din curte', '{}'::text[], ARRAY['„Unde îți place în curte?” — el arată.', 'Denumiți locul: „Copac” sau „Drum” sau altul.', 'Dacă vrea: denumiți 3 locuri împreună.']::text[], 'A arătat locul preferat din curte.', 'Curtea cunoscută'),
  ('s51-b23-z2-fizic', 'Pași până la copac și înapoi', ARRAY['pom / stâlp / reper „copac”']::text[], ARRAY['Mergeți la copac: „Copac. Pom.”', 'Înapoi pe drum: „Drum. Înapoi.”', 'Dacă vrea: denumiți 3 opriri — pornim / copac / poartă.']::text[], 'A mers până la copac și înapoi.', 'Curtea cunoscută'),
  ('s51-b23-z2-mental', 'Curte, copac, drum — pe rând', ARRAY['curte']::text[], ARRAY['Arătați fiecare: „Curte.” „Copac.” „Drum.”', 'Repetați o dată, arătând.', 'Dacă vrea: el arată drum-ul singur.']::text[], 'A auzit și a văzut cele trei cuvinte pe locuri.', 'Curtea cunoscută'),
  ('s51-b23-z2-resurse', 'Pantofii / jucăria de curte — la loc', ARRAY['pantofi sau jucărie luată afară', 'locul lor']::text[], ARRAY['După curte: „La loc.”', '„Gata. Ajunge.”', 'Dacă vrea: alegeți raftul sau cutia.']::text[], 'Obiectul de curte e la loc.', 'Curtea cunoscută'),
  ('s51-b23-z2-social', 'Mergeți pe drum împreună', ARRAY['drum scurt']::text[], ARRAY['Luați-l de mână: „Drum împreună.”', 'La copac: „Aici.” — o clipă.', 'Dacă vrea: el alege ritmul pe drum.']::text[], 'A mers pe drum cu adultul.', 'Curtea cunoscută'),
  ('s51-b23-z3-fizic', 'Aceleași locuri — traseu cunoscut', ARRAY['2–3 locuri din curte pe care le știți']::text[], ARRAY['Parcurgeți aceleași locuri ca ieri: „Curte cunoscut.”', 'La fiecare: numiți scurt.', 'Dacă vrea: denumiți toate cele 3 locuri pe rând.']::text[], 'A vizitat din nou locurile cunoscute.', 'Curtea cunoscută'),
  ('s51-b23-z3-mental', 'Unde e drum? Unde e copac?', ARRAY['curte']::text[], ARRAY['„Unde e drum?” — așteptați gestul.', '„Unde e copac?” — la fel.', 'Dacă vrea: adăugați „Unde e curte?” ca al treilea.']::text[], 'A arătat drum sau copac.', 'Curtea cunoscută'),
  ('s51-b23-z3-resurse', 'Gata curte — întoarcere acasă', ARRAY['ușă']::text[], ARRAY['„Gata curte. Mergem.”', '„Acasă. Ajunge.”', 'Dacă vrea: el alege când e gata (gest).']::text[], 'Curtea e închisă; sunteți acasă.', 'Curtea cunoscută'),
  ('s51-b23-z3-social', 'Rândul pe drum', ARRAY['drum scurt']::text[], ARRAY['Voi faceți 3 pași pe drum: „Acum eu.”', '„Acum tu” — așteptați.', 'Dacă vrea: la copac schimbați din nou rândul.']::text[], 'Ați schimbat rândul pe drum.', 'Curtea cunoscută'),
  ('s51-b23-z4-fizic', 'Drum lung sau drum scurt?', ARRAY['2 trasee scurte în curte']::text[], ARRAY['Arătați două drum-uri: „Scurt? Lung?”', 'Mergeți pe cel ales: „Drum.”', 'Dacă vrea: denumiți 3 locuri pe drum-ul ales.']::text[], 'A ales și a mers pe un drum.', 'Curtea cunoscută'),
  ('s51-b23-z4-mental', 'Copac aproape sau departe?', ARRAY['copac / reper']::text[], ARRAY['Arătați: „Copac aproape? Sau departe?”', 'Mergeți până acolo sau doar arătați.', 'Dacă vrea: comparați cu un al doilea copac / stâlp.']::text[], 'A legat copac de aproape / departe.', 'Curtea cunoscută'),
  ('s51-b23-z4-resurse', 'Alege 1 din 2 — unde stăm în curte', ARRAY['2 locuri: lângă copac / pe drum']::text[], ARRAY['„Aici sau aici?”', 'Stați scurt: „Ajunge.”', 'Dacă vrea: denumiți locul ales + încă 2 din jur.']::text[], 'A ales unde stați în curte.', 'Curtea cunoscută'),
  ('s51-b23-z4-social', 'Arată curte-ul altcuiva', ARRAY['persoană dragă']::text[], ARRAY['Mergeți cu cineva: „Curte. Uite.”', 'El arată copac sau drum.', 'Dacă vrea: denumiți 3 locuri pentru oaspete.']::text[], 'A arătat curtea cuiva drag.', 'Curtea cunoscută'),
  ('s51-b23-z5-fizic', 'Trei opriri pe drum cunoscut', ARRAY['drum cu 3 repere']::text[], ARRAY['Oprire 1, 2, 3 — denumiți fiecare.', '„Drum. Curte. Copac.” pe ce se potrivește.', 'Dacă vrea: el alege ordinea celor 3 opriri.']::text[], 'A făcut trei opriri pe drum.', 'Curtea cunoscută'),
  ('s51-b23-z5-mental', 'Hartă: curte → copac → drum', '{}'::text[], ARRAY['Spuneți harta: „Curte. Copac. Drum.” arătând.', 'Cereți: „Arată drum.”', 'Dacă vrea: el spune harta cu gesturi pe cele 3.']::text[], 'A folosit harta verbală pe scurt.', 'Curtea cunoscută'),
  ('s51-b23-z5-resurse', 'Întoarcerea de pe drum — ajunge', ARRAY['drum → ușă']::text[], ARRAY['Înapoi pe drum: „Acasă.”', '„Gata. Ajunge.”', 'Dacă vrea: un obiect mic de curte la loc.']::text[], 'V-ați întors de pe drum; gata.', 'Curtea cunoscută'),
  ('s51-b23-z5-social', 'Așteaptă-mă la copac', ARRAY['copac / reper']::text[], ARRAY['El stă la copac (sau voi); celălalt vine: „Te aștept.”', 'Când ajungeți: „Împreună pe drum!”', 'Dacă vrea: schimbați rolurile o dată.']::text[], 'Ați exersat așteptarea la copac.', 'Curtea cunoscută'),
  ('s51-b23-z6-fizic', 'Plimbare liberă pe curte cunoscut', ARRAY['curte']::text[], ARRAY['Mergeți liber pe locurile știute: „Curte.”', 'Voi numiți drum / copac dacă apar.', 'Dacă vrea: el alege 3 locuri de vizitat.']::text[], 'A explorat liber curtea cunoscută.', 'Curtea cunoscută'),
  ('s51-b23-z6-mental', 'Ce locuri știm în curte?', ARRAY['curte']::text[], ARRAY['„Ce știm?” — oferiți 2–3 locuri arătate.', '„Copac? Drum?” — așteptați gest.', 'Dacă vrea: denumiți cele 3 locuri preferate din curte.']::text[], 'Ați numit locuri cunoscute din curte.', 'Curtea cunoscută'),
  ('s51-b23-z6-resurse', 'La loc după curte', ARRAY['pantofi / jucărie / frunză']::text[], ARRAY['„La loc.”', '„Gata curte. Ajunge.”', 'Dacă vrea: alegeți ce rămâne afară (1 din 2).']::text[], 'După curte, lucrurile sunt la loc.', 'Curtea cunoscută'),
  ('s51-b23-z6-social', 'Locul preferat — arată-mi', '{}'::text[], ARRAY['„Arată-mi.” — el duce la locul preferat din curte.', 'Denumiți: „Copac” sau „Drum” sau altul.', 'Dacă vrea: denumiți 3 locuri din jurul lui.']::text[], 'A dus adultul la locul preferat.', 'Curtea cunoscută'),
  ('s51-b23-z7-fizic', 'Pași liberi pe drum — cum vrea el', ARRAY['drum / curte']::text[], ARRAY['El dictează ritmul pe drum sau stă la copac.', 'Fără grabă: „Curte cunoscut.”', 'Dacă vrea: treceți pe 3 locuri denumite, blând.']::text[], 'A mers liber pe curtea cunoscută.', 'Curtea cunoscută'),
  ('s51-b23-z7-mental', 'Favoritul din curte: copac sau drum?', '{}'::text[], ARRAY['„Copac sau drum?” — arătați ambele.', 'Respectați alegerea.', 'Dacă vrea: adăugați curte ca a treia opțiune denumită.']::text[], 'A ales un loc favorit din curte.', 'Curtea cunoscută'),
  ('s51-b23-z7-resurse', 'Totul la loc înainte de calm', ARRAY['obiecte de curte']::text[], ARRAY['„La loc.”', '„Gata curte pentru azi.”', 'Dacă vrea: un ultim privit spre copac, apoi calm.']::text[], 'Spațiul e gata după curte.', 'Curtea cunoscută'),
  ('s51-b23-z7-social', 'Ritual: bună seara — curte e gata', ARRAY['ușă / fereastră spre curte']::text[], ARRAY['Șoptiți: „Bună seara. Curte… drum… copac — gata.”', '„Noapte bună.”', 'Dacă vrea: un salut mic spre curte pe fereastră.']::text[], 'Ați închis seara cu ritual de curte cunoscută.', 'Curtea cunoscută'),
  ('s52-b23-z1-fizic', 'Ultimul joc fizic favorita — blând', ARRAY['spațiu liber']::text[], ARRAY['Alegeți un joc iubit din an: „Favorita.”', 'O rundă scurtă: „Din nou… gata.” — fără grabă.', 'Dacă vrea: ordonați 2 favorita — întâi… apoi…']::text[], 'A reluat blând un joc fizic favorit.', 'Anul se închide blând'),
  ('s52-b23-z1-mental', 'Anul se închide — care e favorita?', ARRAY['2–3 amintiri din an']::text[], ARRAY['Arătați 2–3: „Care e favorita?”', '„De ce?” — gest e destul; fără notare, fără test.', 'Dacă vrea: ordonați 2–3 favorita ale anului.']::text[], 'A ales o favorită a anului (gest e destul).', 'Anul se închide blând'),
  ('s52-b23-z1-resurse', 'Alege 1 din 3 — apoi gata pe an', ARRAY['3 obiecte / zone favorita']::text[], ARRAY['Arătați trei: „Una. Favorita.”', '„Gata. Ajunge pentru an.”', 'Dacă vrea: puneți cele 3 în ordine — 1, 2, 3.']::text[], 'A ales una din trei; anul se închide pe alegere.', 'Anul se închide blând'),
  ('s52-b23-z1-social', 'Joacă favorita — închidere împreună', ARRAY['jocul ales']::text[], ARRAY['„Favorita împreună.” — o rundă blândă.', '„Gata. Anul se închide.”', 'Dacă vrea: din nou o dată, apoi gata.']::text[], 'Ați închis o favorită împreună.', 'Anul se închide blând'),
  ('s52-b23-z2-fizic', 'Din nou blând — aceeași mișcare', ARRAY['spațiu liber']::text[], ARRAY['O mișcare cunoscută: „Una.”', '„Din nou.” — a doua oară, mai blând.', 'Dacă vrea: alegeți a doua mișcare și ordonați-le.']::text[], 'A repetat mișcarea blând cu din nou.', 'Anul se închide blând'),
  ('s52-b23-z2-mental', 'Ce am iubit anul ăsta — fără test', ARRAY['spațiu calm']::text[], ARRAY['„Anul… favorita…” — numiți 1–2 amintiri.', 'El adaugă gest sau cuvânt — acceptați orice.', 'Dacă vrea: ordonați 2–3 pe degete.']::text[], 'Ați numit blând o favorită a anului.', 'Anul se închide blând'),
  ('s52-b23-z2-resurse', 'Jucăria favorita — la loc, gata', ARRAY['1 jucărie favorită']::text[], ARRAY['Joacă scurtă: „Favorita.”', '„Gata. La loc.”', 'Dacă vrea: alegeți între 2 unde stă.']::text[], 'Jucăria favorită e la loc; gata.', 'Anul se închide blând'),
  ('s52-b23-z2-social', 'Arată favoritele anului', ARRAY['persoană dragă', '1–2 obiecte']::text[], ARRAY['„Favorita. Uite.” — arătați împreună.', 'Adultul: „Frumos. Gata pentru azi.”', 'Dacă vrea: din nou pe scurt, apoi gata.']::text[], 'A împărtășit favoritele anului.', 'Anul se închide blând'),
  ('s52-b23-z3-fizic', 'Traseu blând al anului', ARRAY['2–3 locuri din jocuri ale anului']::text[], ARRAY['„Întâi aici… apoi acolo.” — traseu scurt de amintiri.', '„Gata.” la final — închidere blândă.', 'Dacă vrea: el ordonează cele 2–3 locuri.']::text[], 'A mers pe traseul blând al amintirilor.', 'Anul se închide blând'),
  ('s52-b23-z3-mental', 'Trei favorita — care închide anul?', ARRAY['3 gesturi / obiecte']::text[], ARRAY['Arătați trei: „Favorita… favorita… favorita.”', '„Care e unu pentru închidere?” — fără presiune.', 'Dacă vrea: puneți 1–2–3 în ordine cu el.']::text[], 'A ales una dintre trei pentru închidere.', 'Anul se închide blând'),
  ('s52-b23-z3-resurse', 'Ajunge — o favorită, apoi gata', ARRAY['2–3 opțiuni']::text[], ARRAY['„Azi una. Favorita.”', '„Gata. Ajunge.”', 'Dacă vrea: ordonați restul pe loc (gest).']::text[], 'O favorită e aleasă; gata.', 'Anul se închide blând'),
  ('s52-b23-z3-social', 'Rândul la favorita — apoi gata', ARRAY['joc scurt']::text[], ARRAY['„Acum eu — favorita.” O rundă.', '„Acum tu.” — așteptați.', 'Dacă vrea: din nou pe rând, apoi gata împreună.']::text[], 'Ați schimbat rândul și ați închis cu gata.', 'Anul se închide blând'),
  ('s52-b23-z4-fizic', 'Corp blând: favorita de închidere', ARRAY['spațiu liber']::text[], ARRAY['El alege: sărituri mici, pași sau pe loc: „Favorita.”', 'O rundă: „Gata.”', 'Dacă vrea: din nou + a doua alegere, în ordine.']::text[], 'A făcut mișcarea blândă aleasă.', 'Anul se închide blând'),
  ('s52-b23-z4-mental', 'De ce e favorita? — blând, fără notă', ARRAY['obiectul / jocul ales']::text[], ARRAY['„De ce e favorita?”', 'Modelați o frază scurtă sau acceptați gestul — zero evaluare.', 'Dacă vrea: comparați cu a doua — care întâi.']::text[], 'A motivat blând favorita.', 'Anul se închide blând'),
  ('s52-b23-z4-resurse', 'Trei pe masă — alege, gata', ARRAY['3 obiecte favorita']::text[], ARRAY['„Trei. Alege favorita.”', 'Celelalte: „La loc. Gata.”', 'Dacă vrea: ordonați cele 3 înainte de a alege.']::text[], 'A ales una; restul la loc.', 'Anul se închide blând'),
  ('s52-b23-z4-social', 'Eu gata, tu din nou — închidere', ARRAY['joc scurt']::text[], ARRAY['Voi: „Gata.” — opriți blând.', 'El: „Din nou?” — dacă vrea; dacă nu, gata anul pe azi.', 'Dacă vrea: el spune gata primul.']::text[], 'Ați folosit gata / din nou la închidere.', 'Anul se închide blând'),
  ('s52-b23-z5-fizic', 'Din nou pe traseul anului', ARRAY['traseu scurt cunoscut (2–3 puncte)']::text[], ARRAY['Faceți traseul o dată: „Una.”', '„Din nou.” — a doua oară, blând.', 'Dacă vrea: el schimbă ordinea punctelor.']::text[], 'A repetat traseul anului cu din nou.', 'Anul se închide blând'),
  ('s52-b23-z5-mental', 'Favorita din an: casă, curte, drum?', ARRAY['3 amintiri: casă / curte / drum']::text[], ARRAY['Arătați trei amintiri din an.', '„Care e favorita?”', 'Dacă vrea: ordonați 2–3 favorita ale anului.']::text[], 'A ales o amintire favorită a anului.', 'Anul se închide blând'),
  ('s52-b23-z5-resurse', 'Gata — totul la loc după an', ARRAY['obiectele din joc']::text[], ARRAY['După joc: „Gata. La loc.”', '„Ajunge. Anul se strânge blând.”', 'Dacă vrea: alegeți ce rămâne la vedere (1 din 2).']::text[], 'După favorita, lucrurile sunt la loc.', 'Anul se închide blând'),
  ('s52-b23-z5-social', 'Împreună: favorita, apoi gata pe an', ARRAY['joc ales']::text[], ARRAY['„Favorita împreună.” — scurt.', 'Împreună: „Gata.”', 'Dacă vrea: din nou o dată dacă amândoi vreți.']::text[], 'Ați închis favorita anului cu gata.', 'Anul se închide blând'),
  ('s52-b23-z6-fizic', 'Mișcare liberă — favorita de închidere', ARRAY['spațiu liber']::text[], ARRAY['El alege mișcarea: „Favorita.”', 'Voi urmăriți blând: „Gata” când se oprește.', 'Dacă vrea: din nou sau a doua favorită, în ordine.']::text[], 'A mișcat liber pe alegerea de închidere.', 'Anul se închide blând'),
  ('s52-b23-z6-mental', 'Anul e plin — ce rămâne favorita?', ARRAY['spațiu calm']::text[], ARRAY['„Anul se închide. Favorita…” — 1–2 amintiri.', 'El adaugă ce vrea — fără întrebări.', 'Dacă vrea: ordonați 2–3 pe degete.']::text[], 'Ați numit blând ce rămâne favorita.', 'Anul se închide blând'),
  ('s52-b23-z6-resurse', 'Alege 1 din 3 — gata pe an', ARRAY['3 zone / obiecte']::text[], ARRAY['„Una din trei. Favorita.”', '„Gata. Ajunge pentru an.”', 'Dacă vrea: celelalte două în ordine pe loc.']::text[], 'A ales una din trei; gata pe an.', 'Anul se închide blând'),
  ('s52-b23-z6-social', 'Mulțumim anului — favorita împreună', ARRAY['1–2 obiecte / gesturi']::text[], ARRAY['„Favorita. Mulțumim.” — gest blând spre an.', 'Adultul: „Frumos. Gata.”', 'Dacă vrea: din nou pe un salut mic, apoi gata.']::text[], 'Ați mulțumit blând anului cu favorita.', 'Anul se închide blând'),
  ('s52-b23-z7-fizic', 'Mișcare liberă — anul se închide blând', ARRAY['spațiu liber']::text[], ARRAY['El alege; voi urmăriți blând.', 'Fără grabă: „Favorita… gata. Anul e gata.”', 'Dacă vrea: din nou o dată foarte scurt.']::text[], 'A mișcat liber; anul se închide pe corp.', 'Anul se închide blând'),
  ('s52-b23-z7-mental', 'Favoritul anului — din nou sau gata?', ARRAY['amintirea anului']::text[], ARRAY['„Favorita e…” — arătați alegerea lui.', '„Din nou sau gata?” — respectați; zero evaluare.', 'Dacă vrea: ordonați 2 favorita ale anului.']::text[], 'A închis mental anul pe o favorită.', 'Anul se închide blând'),
  ('s52-b23-z7-resurse', 'Totul la loc — gata înainte de calm', ARRAY['jucării folosite']::text[], ARRAY['„Gata. La loc.”', '„Anul e strâns. Liniște.”', 'Dacă vrea: un obiect favorita rămâne la vedere.']::text[], 'Lucrurile sunt la loc; anul e strâns blând.', 'Anul se închide blând'),
  ('s52-b23-z7-social', 'Ritual: bună seara — anul e gata', ARRAY['spațiu de seară']::text[], ARRAY['Șoptiți: „Bună seara. Favorita… gata. Anul se închide blând.”', '„Noapte bună.”', 'Dacă vrea: din nou pe un salut mic, apoi odihnă.']::text[], 'Ați închis anul cu ritual blând de seară.', 'Anul se închide blând')
) as v(id, titlu, materiale, pasi, gata_cand, tema_saptamana)
where a.id = v.id
  and a.banda = '2-3';
